  'がっこう': VocabUsage('はちじ に がっこう へ いきます', 'hachiji ni gakkou e ikimasu', 'Saya pergi ke sekolah jam delapan.', 'I go to school at eight.', 'Kata benda tempat. Pola: がっこう へ/に いく; がっこう で べんきょう する.', 'Place noun. Patterns: がっこう へ/に いく; がっこう で べんきょう する.'),
  'えき': VocabUsage('えき で ともだち を まちます', 'eki de tomodachi o machimasu', 'Saya menunggu teman di stasiun.', 'I wait for my friend at the station.', 'Kata benda tempat. Pola: えき で (di stasiun), えき まで (sampai stasiun).', 'Place noun. Patterns: えき で (at the station), えき まで (to the station).'),
  'みせ': VocabUsage('この みせ は やすい です', 'kono mise wa yasui desu', 'Toko ini murah.', 'This shop is cheap.', 'Kata benda tempat. Pola: みせ で かう (beli di toko). Toko khusus sering ~や (ほんや).', 'Place noun. Pattern: みせ で かう (buy at a shop). Specific shops often ~や (ほんや).'),
  'びょういん': VocabUsage('かぜ で びょういん へ いきました', 'kaze de byouin e ikimashita', 'Saya pergi ke rumah sakit karena flu.', 'I went to the hospital because of a cold.', 'Kata benda tempat. Jangan tertukar dengan びよういん (salon kecantikan).', 'Place noun. Don\'t confuse with びよういん (beauty salon).'),
  'ぎんこう': VocabUsage('ぎんこう で おかね を おろします', 'ginkou de okane o oroshimasu', 'Saya menarik uang di bank.', 'I withdraw money at the bank.', 'Kata benda tempat. Kolokasi: ぎんこう で おかね を おろす/あずける (tarik/setor).', 'Place noun. Collocations: ぎんこう で おかね を おろす/あずける (withdraw/deposit).'),
