  'よむ': VocabUsage('でんしゃ で ほん を よみます', 'densha de hon o yomimasu', 'Saya membaca buku di kereta.', 'I read a book on the train.', 'Kata kerja gol. I. Bentuk sopan: よみます. Pola: [bacaan] を よむ.', 'Group 1 verb. Polite: よみます. Pattern: [text] を よむ.'),
  'かく': VocabUsage('ともだち に てがみ を かきます', 'tomodachi ni tegami o kakimasu', 'Saya menulis surat untuk teman.', 'I write a letter to my friend.', 'Kata kerja gol. I. Bentuk sopan: かきます. Pola: [orang] に [hal] を かく. Juga \'menggambar\'.', 'Group 1 verb. Polite: かきます. Pattern: [person] に [thing] を かく. Also \'to draw\'.'),
  'いく': VocabUsage('あした がっこう へ いきます', 'ashita gakkou e ikimasu', 'Besok saya pergi ke sekolah.', 'I will go to school tomorrow.', 'Kata kerja gol. I (bentuk て tak beraturan: いって). Sopan: いきます. Pola: [tempat] へ/に いく.', 'Group 1 verb (irregular て-form: いって). Polite: いきます. Pattern: [place] へ/に いく.'),
  'くる': VocabUsage('ともだち が うち に きます', 'tomodachi ga uchi ni kimasu', 'Teman datang ke rumah saya.', 'My friend comes to my house.', 'Kata kerja gol. III (tak beraturan). Sopan: きます. Pola: [tempat] へ/に くる.', 'Group 3 verb (irregular). Polite: きます. Pattern: [place] へ/に くる.'),
  'かえる': VocabUsage('ろくじ に うち へ かえります', 'rokuji ni uchi e kaerimasu', 'Saya pulang ke rumah jam enam.', 'I go home at six.', 'Kata kerja gol. I (walau berakhir ~える). Sopan: かえります. Pola: [tempat] へ かえる.', 'Group 1 verb (despite ending in ~える). Polite: かえります. Pattern: [place] へ かえる.'),
  'ねる': VocabUsage('まいばん じゅういちじ に ねます', 'maiban juuichiji ni nemasu', 'Setiap malam saya tidur jam sebelas.', 'I go to bed at eleven every night.', 'Kata kerja gol. II. Bentuk sopan: ねます. Lawan: おきる. Pola: [jam] に ねる.', 'Group 2 verb. Polite: ねます. Opposite: おきる. Pattern: [time] に ねる.'),
  'おきる': VocabUsage('あさ ろくじ に おきます', 'asa rokuji ni okimasu', 'Saya bangun jam enam pagi.', 'I get up at six in the morning.', 'Kata kerja gol. II. Bentuk sopan: おきます. Pola: [jam] に おきる.', 'Group 2 verb. Polite: おきます. Pattern: [time] に おきる.'),
  'あるく': VocabUsage('えき まで あるきます', 'eki made arukimasu', 'Saya berjalan kaki sampai stasiun.', 'I walk to the station.', 'Kata kerja gol. I. Sopan: あるきます. Pola: [tempat] まで あるく; [jalan] を あるく.', 'Group 1 verb. Polite: あるきます. Patterns: [place] まで あるく; [road] を あるく.'),
  'はしる': VocabUsage('こうえん を はしります', 'kouen o hashirimasu', 'Saya berlari di taman.', 'I run in the park.', 'Kata kerja gol. I (walau berakhir ~いる). Sopan: はしります. Rute memakai を.', 'Group 1 verb (despite ~いる ending). Polite: はしります. Route takes を.'),
  'かう': VocabUsage('スーパー で やさい を かいます', 'suupaa de yasai o kaimasu', 'Saya membeli sayur di supermarket.', 'I buy vegetables at the supermarket.', 'Kata kerja gol. I. Sopan: かいます. Pola: [tempat] で [barang] を かう.', 'Group 1 verb. Polite: かいます. Pattern: [place] で [item] を かう.'),
  'うる': VocabUsage('この みせ は くだもの を うります', 'kono mise wa kudamono o urimasu', 'Toko ini menjual buah.', 'This shop sells fruit.', 'Kata kerja gol. I. Sopan: うります. Lawan: かう. Sering: うって いる (dijual).', 'Group 1 verb. Polite: うります. Opposite: かう. Often: うって いる (on sale).'),
  'する': VocabUsage('にちようび に テニス を します', 'nichiyoubi ni tenisu o shimasu', 'Hari Minggu saya bermain tenis.', 'I play tennis on Sunday.', 'Kata kerja gol. III (tak beraturan). Sopan: します. Pola: [kegiatan] を する.', 'Group 3 verb (irregular). Polite: します. Pattern: [activity] を する.'),
  'なる': VocabUsage('らいねん はたち に なります', 'rainen hatachi ni narimasu', 'Tahun depan saya berumur dua puluh tahun.', 'I will turn twenty next year.', 'Kata kerja gol. I. Sopan: なります. Pola: [benda/な-adj] に なる; [い-adj ~く] なる.', 'Group 1 verb. Polite: なります. Patterns: [noun/な-adj] に なる; [い-adj ~く] なる.'),
  'わかる': VocabUsage('にほんご が すこし わかります', 'nihongo ga sukoshi wakarimasu', 'Saya sedikit mengerti bahasa Jepang.', 'I understand a little Japanese.', 'Kata kerja gol. I. Sopan: わかります. Objek memakai が, bukan を: [hal] が わかる.', 'Group 1 verb. Polite: わかります. Object takes が, not を: [thing] が わかる.'),
  'しる': VocabUsage('かれ の でんわ ばんごう を しって います か', 'kare no denwa bangou o shitte imasu ka', 'Apakah kamu tahu nomor telepon dia?', 'Do you know his phone number?', 'Kata kerja gol. I. Biasanya しって います (tahu); negatifnya しりません, bukan しって いません.', 'Group 1 verb. Usually しって います (know); negative is しりません, not しって いません.'),
  'あう': VocabUsage('えき で ともだち に あいます', 'eki de tomodachi ni aimasu', 'Saya bertemu teman di stasiun.', 'I meet my friend at the station.', 'Kata kerja gol. I. Sopan: あいます. Orang yang ditemui memakai に (bukan を).', 'Group 1 verb. Polite: あいます. The person met takes に (not を).'),
  'まつ': VocabUsage('ここ で バス を まちます', 'koko de basu o machimasu', 'Saya menunggu bus di sini.', 'I wait for the bus here.', 'Kata kerja gol. I. Sopan: まちます. Pola: [orang/benda] を まつ. ちょっと まって = tunggu sebentar.', 'Group 1 verb. Polite: まちます. Pattern: [person/thing] を まつ. ちょっと まって = wait a moment.'),
  'つくる': VocabUsage('はは が ケーキ を つくります', 'haha ga keeki o tsukurimasu', 'Ibu membuat kue.', 'My mother makes a cake.', 'Kata kerja gol. I. Sopan: つくります. Pola: [benda/masakan] を つくる.', 'Group 1 verb. Polite: つくります. Pattern: [thing/dish] を つくる.'),
  'つかう': VocabUsage('この パソコン を つかって も いい です か', 'kono pasokon o tsukatte mo ii desu ka', 'Bolehkah saya memakai komputer ini?', 'May I use this computer?', 'Kata kerja gol. I. Sopan: つかいます. Pola: [alat] を つかう. Izin: ~て も いい です か.', 'Group 1 verb. Polite: つかいます. Pattern: [tool] を つかう. Permission: ~て も いい です か.'),
  'あける': VocabUsage('まど を あけます', 'mado o akemasu', 'Saya membuka jendela.', 'I open the window.', 'Kata kerja gol. II (transitif). Sopan: あけます. Pola: [benda] を あける. Intransitif: あく.', 'Group 2 verb (transitive). Polite: あけます. Pattern: [thing] を あける. Intransitive: あく.'),
  'しめる': VocabUsage('さむい です から ドア を しめます', 'samui desu kara doa o shimemasu', 'Karena dingin, saya menutup pintu.', 'It\'s cold, so I close the door.', 'Kata kerja gol. II (transitif). Sopan: しめます. Intransitif: しまる.', 'Group 2 verb (transitive). Polite: しめます. Intransitive: しまる.'),
  'おしえる': VocabUsage('せんせい は えいご を おしえます', 'sensei wa eigo o oshiemasu', 'Guru mengajar bahasa Inggris.', 'The teacher teaches English.', 'Kata kerja gol. II. Sopan: おしえます. Pola: [orang] に [hal] を おしえる. Juga \'memberi tahu\'.', 'Group 2 verb. Polite: おしえます. Pattern: [person] に [thing] を おしえる. Also \'to tell\'.'),
  'ならう': VocabUsage('ともだち に ピアノ を ならいます', 'tomodachi ni piano o naraimasu', 'Saya belajar piano dari teman.', 'I learn piano from a friend.', 'Kata kerja gol. I. Sopan: ならいます. Belajar dari guru: [orang] に [hal] を ならう.', 'Group 1 verb. Polite: ならいます. Learn from someone: [person] に [thing] を ならう.'),
  'べんきょうする': VocabUsage('としょかん で べんきょう します', 'toshokan de benkyou shimasu', 'Saya belajar di perpustakaan.', 'I study at the library.', 'Kata kerja gol. III (benda + する). Sopan: べんきょう します. Belajar mandiri; ならう = diajari orang.', 'Group 3 verb (noun + する). Polite: べんきょう します. Self-study; ならう = learn from someone.'),
  'はたらく': VocabUsage('あに は ぎんこう で はたらきます', 'ani wa ginkou de hatarakimasu', 'Kakak laki-laki saya bekerja di bank.', 'My older brother works at a bank.', 'Kata kerja gol. I. Sopan: はたらきます. Tempat kerja memakai で. Sering: はたらいて います.', 'Group 1 verb. Polite: はたらきます. Workplace takes で. Often: はたらいて います.'),
  'あそぶ': VocabUsage('こども が こうえん で あそびます', 'kodomo ga kouen de asobimasu', 'Anak-anak bermain di taman.', 'Children play in the park.', 'Kata kerja gol. I. Sopan: あそびます. Tempat memakai で. Juga \'jalan-jalan/main ke rumah\'.', 'Group 1 verb. Polite: あそびます. Place takes で. Also \'hang out/visit\'.'),
  'やすむ': VocabUsage('きょう は かいしゃ を やすみます', 'kyou wa kaisha o yasumimasu', 'Hari ini saya tidak masuk kerja.', 'I\'m taking the day off work today.', 'Kata kerja gol. I. Sopan: やすみます. [tempat] を やすむ = absen/libur dari; juga \'beristirahat\'.', 'Group 1 verb. Polite: やすみます. [place] を やすむ = be absent from; also \'to rest\'.'),
  'とても': VocabUsage('この ケーキ は とても おいしい です', 'kono keeki wa totemo oishii desu', 'Kue ini sangat enak.', 'This cake is very delicious.', 'Kata keterangan derajat; diletakkan sebelum kata sifat. Untuk kalimat negatif lebih umum あまり.', 'Degree adverb; placed before adjectives. For negatives あまり is more common.'),
  'すこし': VocabUsage('にほんご が すこし わかります', 'nihongo ga sukoshi wakarimasu', 'Saya sedikit mengerti bahasa Jepang.', 'I understand a little Japanese.', 'Kata keterangan jumlah/derajat. Lebih santai: ちょっと. Lawan: たくさん.', 'Adverb of amount/degree. Casual: ちょっと. Opposite: たくさん.'),
  'たくさん': VocabUsage('こうえん に ひと が たくさん います', 'kouen ni hito ga takusan imasu', 'Di taman ada banyak orang.', 'There are many people in the park.', 'Kata keterangan jumlah; biasanya sebelum kata kerja. Bisa juga たくさん の [benda].', 'Adverb of quantity; usually before the verb. Also たくさん の [noun].'),
  'いつも': VocabUsage('わたし は いつも バス で かえります', 'watashi wa itsumo basu de kaerimasu', 'Saya selalu pulang naik bus.', 'I always go home by bus.', 'Kata keterangan frekuensi (paling tinggi). Urutan: いつも > よく > ときどき.', 'Frequency adverb (highest). Scale: いつも > よく > ときどき.'),
  'ときどき': VocabUsage('ときどき ともだち と カラオケ に いきます', 'tokidoki tomodachi to karaoke ni ikimasu', 'Kadang-kadang saya pergi karaoke dengan teman.', 'I sometimes go to karaoke with friends.', 'Kata keterangan frekuensi; tanpa partikel. Lebih jarang dari よく.', 'Frequency adverb; no particle. Less often than よく.'),
  'よく': VocabUsage('ちち は よく ゴルフ を します', 'chichi wa yoku gorufu o shimasu', 'Ayah sering bermain golf.', 'My father often plays golf.', 'Kata keterangan: \'sering\' atau \'dengan baik\' (よく わかる). Bentuk keterangan dari いい.', 'Adverb: \'often\' or \'well\' (よく わかる). Adverbial form of いい.'),
  'もう': VocabUsage('もう ひるごはん を たべました', 'mou hirugohan o tabemashita', 'Saya sudah makan siang.', 'I have already eaten lunch.', 'Kata keterangan; dengan bentuk lampau = \'sudah\'. もう + jumlah = \'lagi\' (もう いっぱい).', 'Adverb; with past tense = \'already\'. もう + amount = \'more\' (もう いっぱい).'),
  'まだ': VocabUsage('しゅくだい は まだ です', 'shukudai wa mada desu', 'PR-nya belum selesai.', 'I haven\'t done my homework yet.', 'Kata keterangan. まだ です / まだ ~て いません = belum. Dengan bentuk positif = \'masih\'.', 'Adverb. まだ です / まだ ~て いません = not yet. With positive verbs = \'still\'.'),
  'ちょっと': VocabUsage('ちょっと まって ください', 'chotto matte kudasai', 'Tolong tunggu sebentar.', 'Please wait a moment.', 'Kata keterangan santai: \'sebentar/sedikit\'. ちょっと... juga cara halus menolak.', 'Casual adverb: \'a moment/a little\'. ちょっと... is also a soft refusal.'),
  'だいたい': VocabUsage('しごと は だいたい ごじ に おわります', 'shigoto wa daitai goji ni owarimasu', 'Pekerjaan biasanya selesai kira-kira jam lima.', 'Work usually ends around five.', 'Kata keterangan: \'kira-kira/umumnya\'. Mirip ぐらい/ごろ, tapi diletakkan sebelum jumlah.', 'Adverb: \'roughly/mostly\'. Like ぐらい/ごろ but placed before the amount.'),
  'なに': VocabUsage('あさ なに を たべます か', 'asa nani o tabemasu ka', 'Pagi hari kamu makan apa?', 'What do you eat in the morning?', 'Kata tanya \'apa\'. Menjadi なん sebelum で/の/です/satuan: なん です か, なんじ.', 'Question word \'what\'. Becomes なん before で/の/です/counters: なん です か, なんじ.'),
  'だれ': VocabUsage('あの ひと は だれ です か', 'ano hito wa dare desu ka', 'Orang itu siapa?', 'Who is that person?', 'Kata tanya \'siapa\'. Lebih sopan: どなた. Sebagai subjek pakai が: だれ が きます か.', 'Question word \'who\'. Politer: どなた. As subject use が: だれ が きます か.'),
  'どこ': VocabUsage('トイレ は どこ です か', 'toire wa doko desu ka', 'Toilet di mana?', 'Where is the toilet?', 'Kata tanya tempat. Pola: [benda] は どこ です か; どこ へ いきます か. Sopan: どちら.', 'Question word for place. Patterns: [thing] は どこ です か; どこ へ いきます か. Polite: どちら.'),
  'いつ': VocabUsage('たんじょうび は いつ です か', 'tanjoubi wa itsu desu ka', 'Ulang tahunmu kapan?', 'When is your birthday?', 'Kata tanya waktu; tidak memakai に. Pola: [hal] は いつ です か.', 'Question word for time; takes no に. Pattern: [thing] は いつ です か.'),
  'なぜ': VocabUsage('なぜ がっこう を やすみました か', 'naze gakkou o yasumimashita ka', 'Mengapa kamu tidak masuk sekolah?', 'Why were you absent from school?', 'Kata tanya alasan, agak formal. Santai: どうして. Jawaban sering diakhiri ~から.', 'Question word for reason, a bit formal. Casual: どうして. Answers often end in ~から.'),
  'どう': VocabUsage('にほん の せいかつ は どう です か', 'nihon no seikatsu wa dou desu ka', 'Bagaimana kehidupan di Jepang?', 'How is life in Japan?', 'Kata tanya keadaan/pendapat. Pola: [hal] は どう です か. Sopan: いかが.', 'Question word for state/opinion. Pattern: [thing] は どう です か. Polite: いかが.'),
  'いくら': VocabUsage('この りんご は いくら です か', 'kono ringo wa ikura desu ka', 'Apel ini berapa harganya?', 'How much is this apple?', 'Kata tanya harga. Pola: [barang] は いくら です か. Untuk jumlah pakai いくつ.', 'Question word for price. Pattern: [item] は いくら です か. For quantity use いくつ.'),
  'これ': VocabUsage('これ は わたし の ほん です', 'kore wa watashi no hon desu', 'Ini buku saya.', 'This is my book.', 'Kata tunjuk benda dekat pembicara; berdiri sendiri. Sebelum benda pakai この.', 'Demonstrative for things near the speaker; stands alone. Before nouns use この.'),
  'それ': VocabUsage('それ は なん です か', 'sore wa nan desu ka', 'Itu apa?', 'What is that?', 'Kata tunjuk benda dekat lawan bicara. Sebelum benda pakai その.', 'Demonstrative for things near the listener. Before nouns use その.'),
  'あれ': VocabUsage('あれ は ふじさん です', 'are wa fujisan desu', 'Itu Gunung Fuji.', 'That is Mount Fuji.', 'Kata tunjuk benda jauh dari keduanya. Sebelum benda pakai あの.', 'Demonstrative for things far from both. Before nouns use あの.'),
  'こんにちは': VocabUsage('こんにちは きょう は あつい です ね', 'konnichiwa kyou wa atsui desu ne', 'Halo, hari ini panas, ya.', 'Hello, it\'s hot today, isn\'t it?', 'Salam siang hari. Ditulis dengan は tapi dibaca \'wa\'. Jarang dipakai ke keluarga sendiri.', 'Daytime greeting. Written with は but read \'wa\'. Rarely used with one\'s own family.'),
  'おはよう': VocabUsage('おはよう きょう も がんばろう', 'ohayou kyou mo ganbarou', 'Selamat pagi, hari ini juga semangat ya.', 'Morning! Let\'s do our best today too.', 'Salam pagi santai (teman/keluarga). Sopan: おはよう ございます.', 'Casual morning greeting (friends/family). Polite: おはよう ございます.'),
  'こんばんは': VocabUsage('こんばんは いい よる です ね', 'konbanwa ii yoru desu ne', 'Selamat malam, malam yang indah, ya.', 'Good evening, it\'s a nice night, isn\'t it?', 'Salam saat bertemu di malam hari; ditulis は dibaca \'wa\'. Saat berpisah malam: おやすみなさい.', 'Evening greeting when meeting; written は read \'wa\'. When parting at night: おやすみなさい.'),
  'さようなら': VocabUsage('せんせい さようなら', 'sensei sayounara', 'Selamat tinggal, Pak/Bu Guru.', 'Goodbye, teacher.', 'Salam perpisahan, terdengar agak final. Antar teman lebih umum じゃ ね / また ね.', 'Farewell, sounds somewhat final. Among friends じゃ ね / また ね is more common.'),
  'ありがとう': VocabUsage('てつだって くれて ありがとう', 'tetsudatte kurete arigatou', 'Terima kasih sudah membantu.', 'Thanks for helping me.', 'Ungkapan terima kasih santai. Sopan: ありがとう ございます; lampau: ありがとう ございました.', 'Casual thanks. Polite: ありがとう ございます; for past help: ありがとう ございました.'),
  'すみません': VocabUsage('すみません えき は どこ です か', 'sumimasen eki wa doko desu ka', 'Permisi, stasiun di mana?', 'Excuse me, where is the station?', 'Ungkapan serbaguna: permisi, maaf (ringan), atau terima kasih atas repotnya.', 'Versatile phrase: excuse me, (light) sorry, or thanks for the trouble.'),
  'はい': VocabUsage('はい わたし は がくせい です', 'hai watashi wa gakusei desu', 'Ya, saya pelajar.', 'Yes, I am a student.', 'Jawaban \'ya\' yang sopan; juga berarti \'baik/saya dengar\'. Santai: うん.', 'Polite \'yes\'; also \'okay/I hear you\'. Casual: うん.'),
  'いいえ': VocabUsage('いいえ わたし は せんせい じゃ ありません', 'iie watashi wa sensei ja arimasen', 'Bukan, saya bukan guru.', 'No, I\'m not a teacher.', 'Jawaban \'tidak/bukan\'. Juga membalas terima kasih: いいえ = sama-sama. Santai: ううん.', 'Answer \'no\'. Also replies to thanks: いいえ = you\'re welcome. Casual: ううん.'),
  'かいしゃ': VocabUsage('ちち は かいしゃ で はたらいて います', 'chichi wa kaisha de hataraite imasu', 'Ayah bekerja di perusahaan.', 'My father works at a company.', 'Kata benda. Pola: かいしゃ で はたらく; かいしゃ に いく (ke kantor). かいしゃいん = karyawan.', 'Noun. Patterns: かいしゃ で はたらく; かいしゃ に いく (go to work). かいしゃいん = employee.'),
  'ねこ': VocabUsage('うち に ねこ が にひき います', 'uchi ni neko ga nihiki imasu', 'Di rumah ada dua ekor kucing.', 'There are two cats at home.', 'Kata benda makhluk hidup, pakai います. Hitungan: ~ひき (いっぴき, にひき).', 'Animate noun, use います. Counter: ~ひき (いっぴき, にひき).'),
  'いぬ': VocabUsage('まいあさ いぬ と さんぽ します', 'maiasa inu to sanpo shimasu', 'Setiap pagi saya jalan-jalan dengan anjing.', 'I walk with my dog every morning.', 'Kata benda makhluk hidup, pakai います. Hitungan: ~ひき. Pola: いぬ を かう (memelihara).', 'Animate noun, use います. Counter: ~ひき. Pattern: いぬ を かう (keep a dog).'),
  'くるま': VocabUsage('くるま で かいしゃ へ いきます', 'kuruma de kaisha e ikimasu', 'Saya pergi ke kantor naik mobil.', 'I go to the office by car.', 'Kata benda. Sarana memakai で: くるま で いく. Hitungan: ~だい.', 'Noun. Means of transport takes で: くるま で いく. Counter: ~だい.'),
  'でんしゃ': VocabUsage('でんしゃ で がっこう へ いきます', 'densha de gakkou e ikimasu', 'Saya pergi ke sekolah naik kereta.', 'I go to school by train.', 'Kata benda. Kolokasi: でんしゃ で いく; でんしゃ に のる (naik); でんしゃ を おりる (turun).', 'Noun. Collocations: でんしゃ で いく; でんしゃ に のる (board); でんしゃ を おりる (get off).'),
  'ある': VocabUsage('つくえ の うえ に ほん が あります', 'tsukue no ue ni hon ga arimasu', 'Di atas meja ada buku.', 'There is a book on the desk.', 'Kata kerja gol. I untuk benda mati/tumbuhan. Sopan: あります; negatif biasa: ない.', 'Group 1 verb for inanimate things/plants. Polite: あります; plain negative: ない.'),
  'いる': VocabUsage('きょうしつ に せんせい が います', 'kyoushitsu ni sensei ga imasu', 'Di kelas ada guru.', 'The teacher is in the classroom.', 'Kata kerja gol. II untuk orang/hewan. Sopan: います. Pola: [tempat] に [makhluk] が いる.', 'Group 2 verb for people/animals. Polite: います. Pattern: [place] に [being] が いる.'),
  'し': VocabUsage('しがつ に がっこう が はじまります', 'shigatsu ni gakkou ga hajimarimasu', 'Sekolah dimulai bulan April.', 'School starts in April.', 'Bacaan lain angka 4, dipakai pada しがつ (April). Sering dihindari karena mirip \'mati\'.', 'Alternate reading of 4, used in しがつ (April). Often avoided as it sounds like \'death\'.'),
  'しち': VocabUsage('しちじ に あさごはん を たべます', 'shichiji ni asagohan o tabemasu', 'Saya sarapan jam tujuh.', 'I eat breakfast at seven.', 'Bacaan lain angka 7; dipakai pada しちじ (jam 7) dan しちがつ (Juli).', 'Alternate reading of 7; used in しちじ (7 o\'clock) and しちがつ (July).'),
  'く': VocabUsage('くじ に じゅぎょう が はじまります', 'kuji ni jugyou ga hajimarimasu', 'Pelajaran dimulai jam sembilan.', 'Class starts at nine.', 'Bacaan lain angka 9; wajib pada くじ (jam 9) dan くがつ (September).', 'Alternate reading of 9; required in くじ (9 o\'clock) and くがつ (September).'),
  'れい': VocabUsage('きょう は れいど です', 'kyou wa reido desu', 'Hari ini suhunya nol derajat.', 'It is zero degrees today.', 'Angka 0 bacaan Sino-Jepang, formal; dipakai untuk suhu (れいど) dan skor. Lisan: ゼロ.', 'Sino-Japanese 0, formal; used for temperature (れいど) and scores. Spoken: ゼロ.'),
  'ひとつ': VocabUsage('りんご を ひとつ ください', 'ringo o hitotsu kudasai', 'Tolong satu buah apel.', 'One apple, please.', 'Hitungan umum asli Jepang (1–10) untuk benda tanpa satuan khusus; tanpa partikel.', 'Native general counter (1–10) for things without a specific counter; no particle.'),
  'ふたつ': VocabUsage('ケーキ を ふたつ かいました', 'keeki o futatsu kaimashita', 'Saya membeli dua potong kue.', 'I bought two pieces of cake.', 'Hitungan umum: 2 buah. Pola: [benda] を ふたつ + kata kerja.', 'General counter: two items. Pattern: [thing] を ふたつ + verb.'),
  'みっつ': VocabUsage('たまご を みっつ つかいます', 'tamago o mittsu tsukaimasu', 'Saya memakai tiga butir telur.', 'I use three eggs.', 'Hitungan umum: 3 buah. Letakkan setelah objek + partikel, sebelum kata kerja.', 'General counter: three items. Place after object + particle, before the verb.'),
  'よっつ': VocabUsage('いす が よっつ あります', 'isu ga yottsu arimasu', 'Ada empat kursi.', 'There are four chairs.', 'Hitungan umum: 4 buah. Pola: [benda] が よっつ ある.', 'General counter: four items. Pattern: [thing] が よっつ ある.'),
  'いつつ': VocabUsage('みかん を いつつ たべました', 'mikan o itsutsu tabemashita', 'Saya makan lima buah jeruk.', 'I ate five mandarins.', 'Hitungan umum: 5 buah. Jangan tertukar dengan いつ (kapan).', 'General counter: five items. Don\'t confuse with いつ (when).'),
  'むっつ': VocabUsage('はこ が むっつ あります', 'hako ga muttsu arimasu', 'Ada enam kotak.', 'There are six boxes.', 'Hitungan umum: 6 buah. Pola: [benda] が むっつ ある.', 'General counter: six items. Pattern: [thing] が むっつ ある.'),
  'ななつ': VocabUsage('にじ の いろ は ななつ です', 'niji no iro wa nanatsu desu', 'Warna pelangi ada tujuh.', 'A rainbow has seven colors.', 'Hitungan umum: 7 buah. Pola: [benda] は ななつ です.', 'General counter: seven items. Pattern: [thing] は ななつ です.'),
  'やっつ': VocabUsage('おかし を やっつ もらいました', 'okashi o yattsu moraimashita', 'Saya menerima delapan kudapan.', 'I received eight sweets.', 'Hitungan umum: 8 buah. Pola: [benda] を やっつ + kata kerja.', 'General counter: eight items. Pattern: [thing] を やっつ + verb.'),
  'ここのつ': VocabUsage('あめ が ここのつ あります', 'ame ga kokonotsu arimasu', 'Ada sembilan permen.', 'There are nine candies.', 'Hitungan umum: 9 buah. Juga bisa untuk umur anak (ここのつ = 9 tahun).', 'General counter: nine items. Also for a child\'s age (ここのつ = 9 years old).'),
  'とお': VocabUsage('おにぎり を とお つくりました', 'onigiri o too tsukurimashita', 'Saya membuat sepuluh onigiri.', 'I made ten rice balls.', 'Hitungan umum: 10 buah (tanpa ~つ). Di atas 10 pakai angka + こ: じゅういっこ.', 'General counter: ten items (no ~つ). Above 10 use number + こ: じゅういっこ.'),
  'いくつ': VocabUsage('りんご は いくつ あります か', 'ringo wa ikutsu arimasu ka', 'Ada berapa buah apel?', 'How many apples are there?', 'Kata tanya jumlah (hitungan ~つ). Juga umur: おいくつ です か (sopan).', 'Question word for quantity (~つ count). Also age: おいくつ です か (polite).'),
  'ひとり': VocabUsage('ひとり で にほん へ いきました', 'hitori de nihon e ikimashita', 'Saya pergi ke Jepang sendirian.', 'I went to Japan alone.', 'Hitungan orang: 1 orang. ひとり で = sendirian. Mulai 3 orang pakai ~にん.', 'Counter for people: one. ひとり で = alone. From three use ~にん.'),
  'ふたり': VocabUsage('ふたり で しょくじ を しました', 'futari de shokuji o shimashita', 'Kami berdua makan bersama.', 'The two of us had a meal.', 'Hitungan orang: 2 orang. ふたり で = berdua. 3 orang ke atas: さんにん, よにん.', 'Counter for people: two. ふたり で = as a pair. Three and up: さんにん, よにん.'),
  'なんにん': VocabUsage('かぞく は なんにん です か', 'kazoku wa nannin desu ka', 'Keluargamu berapa orang?', 'How many people are in your family?', 'Kata tanya jumlah orang. Pola: [kelompok] は なんにん です か. Jawab: [n]にん です.', 'Question for number of people. Pattern: [group] は なんにん です か. Answer: [n]にん です.'),
  'おおぜい': VocabUsage('えき に ひと が おおぜい います', 'eki ni hito ga oozei imasu', 'Di stasiun ada banyak orang.', 'There are lots of people at the station.', 'Kata keterangan/benda khusus orang banyak. Untuk benda pakai たくさん.', 'Adverb/noun only for many people. For things use たくさん.'),
  'いちまい': VocabUsage('かみ を いちまい ください', 'kami o ichimai kudasai', 'Tolong beri selembar kertas.', 'One sheet of paper, please.', 'Hitungan benda tipis/datar (kertas, kaus, piring, tiket): いちまい, にまい, さんまい.', 'Counter for flat things (paper, shirts, plates, tickets): いちまい, にまい, さんまい.'),
  'なんまい': VocabUsage('きって は なんまい いります か', 'kitte wa nanmai irimasu ka', 'Perlu berapa lembar prangko?', 'How many stamps do you need?', 'Kata tanya jumlah benda tipis. Jawab: [n]まい です.', 'Question for number of flat things. Answer: [n]まい です.'),
  'いっぽん': VocabUsage('ビール を いっぽん ください', 'biiru o ippon kudasai', 'Tolong satu botol bir.', 'One bottle of beer, please.', 'Hitungan benda panjang (pena, botol, pohon). Bunyi: いっぽん, にほん, さんぼん, ろっぽん.', 'Counter for long objects (pens, bottles, trees). Sounds: いっぽん, にほん, さんぼん, ろっぽん.'),
  'なんぼん': VocabUsage('ペン は なんぼん あります か', 'pen wa nanbon arimasu ka', 'Ada berapa batang pena?', 'How many pens are there?', 'Kata tanya jumlah benda panjang (bunyi ~ぼん). Jawab: [n]ほん/ぼん/ぽん.', 'Question for number of long objects (~ぼん sound). Answer: [n]ほん/ぼん/ぽん.'),
  'いっぴき': VocabUsage('にわ に ねこ が いっぴき います', 'niwa ni neko ga ippiki imasu', 'Di halaman ada seekor kucing.', 'There is one cat in the garden.', 'Hitungan hewan kecil (kucing, ikan, serangga). Bunyi: いっぴき, にひき, さんびき.', 'Counter for small animals (cats, fish, insects). Sounds: いっぴき, にひき, さんびき.'),
  'なんびき': VocabUsage('いぬ は なんびき います か', 'inu wa nanbiki imasu ka', 'Ada berapa ekor anjing?', 'How many dogs are there?', 'Kata tanya jumlah hewan kecil. Pakai います karena makhluk hidup.', 'Question for number of small animals. Use います since they are animate.'),
  'いっさつ': VocabUsage('まいつき ほん を いっさつ よみます', 'maitsuki hon o issatsu yomimasu', 'Setiap bulan saya membaca satu buku.', 'I read one book every month.', 'Hitungan buku/majalah/buku catatan: いっさつ, にさつ, はっさつ. Tanya: なんさつ.', 'Counter for books/magazines/notebooks: いっさつ, にさつ, はっさつ. Ask: なんさつ.'),
  'いちだい': VocabUsage('うち に くるま が いちだい あります', 'uchi ni kuruma ga ichidai arimasu', 'Di rumah ada satu unit mobil.', 'We have one car at home.', 'Hitungan mesin/kendaraan (mobil, sepeda, komputer, TV): いちだい, にだい. Tanya: なんだい.', 'Counter for machines/vehicles (cars, bikes, PCs, TVs): いちだい, にだい. Ask: なんだい.'),
  'いっこ': VocabUsage('あめ を いっこ あげます', 'ame o ikko agemasu', 'Saya beri kamu satu permen.', 'I\'ll give you one candy.', 'Hitungan benda kecil/bulat: いっこ, にこ, さんこ. Alternatif umum: ひとつ.', 'Counter for small/round items: いっこ, にこ, さんこ. General alternative: ひとつ.'),
  'いっぱい': VocabUsage('おなか が いっぱい です', 'onaka ga ippai desu', 'Perut saya sudah kenyang.', 'I\'m full.', 'Arti \'penuh\' (おなか が いっぱい) atau \'satu gelas/mangkuk\' (みず を いっぱい). Bunyi: にはい, さんばい.', '\'Full\' (おなか が いっぱい) or \'one cup/bowl\' (みず を いっぱい). Sounds: にはい, さんばい.'),
  'いっかい': VocabUsage('トイレ は いっかい に あります', 'toire wa ikkai ni arimasu', 'Toilet ada di lantai satu.', 'The toilet is on the first floor.', 'Hitungan kali (いっかい, にかい) atau lantai (いっかい, さんがい). Tanya: なんかい.', 'Counter for times (いっかい, にかい) or floors (いっかい, さんがい). Ask: なんかい.'),
  'なんかい': VocabUsage('にほん へ なんかい いきました か', 'nihon e nankai ikimashita ka', 'Sudah berapa kali kamu pergi ke Jepang?', 'How many times have you been to Japan?', 'Kata tanya + pembilang かい. 回 = berapa kali; 階 = lantai berapa. Contoh: なんかい です か.', 'Question word + counter かい. 回 = how many times; 階 = which floor. E.g. なんかい です か.'),
  'なんさい': VocabUsage('おとうと さん は なんさい です か', 'otouto san wa nansai desu ka', 'Adik laki-lakimu umur berapa?', 'How old is your younger brother?', 'Kata tanya umur. Pola: [orang] は なんさい です か. Lebih sopan: おいくつ です か.', 'Question word for age. Pattern: [person] は なんさい です か. More polite: おいくつ です か.'),
  'はたち': VocabUsage('あね は らいねん はたち に なります', 'ane wa rainen hatachi ni narimasu', 'Kakak perempuan saya tahun depan berumur 20 tahun.', 'My older sister will turn 20 next year.', 'Bacaan khusus untuk umur 20 (bukan にじゅっさい). Pola: はたち に なります = menjadi 20 tahun.', 'Special reading for age 20 (not にじゅっさい). Pattern: はたち に なります = turn 20.'),
  'なんばん': VocabUsage('でんわ ばんごう は なんばん です か', 'denwa bangou wa nanban desu ka', 'Nomor teleponnya berapa?', 'What is the phone number?', 'Kata tanya nomor/urutan. Pola: ～は なんばん です か. Juga untuk nomor jalur/peron.', 'Question word for a number/order. Pattern: ～は なんばん です か. Also used for platform/line numbers.'),
  'ばんごう': VocabUsage('へや の ばんごう を おしえて ください', 'heya no bangou o oshiete kudasai', 'Tolong beri tahu nomor kamarnya.', 'Please tell me the room number.', 'Kata benda. Sering: でんわ ばんごう (nomor telepon), [benda] の ばんごう.', 'Noun. Common: でんわ ばんごう (phone number), [thing] の ばんごう.'),
  'いちがつ': VocabUsage('いちがつ は とても さむい です', 'ichigatsu wa totemo samui desu', 'Bulan Januari sangat dingin.', 'January is very cold.', 'Nama bulan = angka + がつ. Pakai に untuk \'pada bulan\': いちがつ に.', 'Month name = number + がつ. Use に for \'in\': いちがつ に.'),
  'にがつ': VocabUsage('にがつ に テスト が あります', 'nigatsu ni tesuto ga arimasu', 'Ada ujian di bulan Februari.', 'There is a test in February.', 'Bulan ke-2. Pola: にがつ に + kegiatan. Jangan tertukar dengan にかげつ (dua bulan lamanya).', '2nd month. Pattern: にがつ に + activity. Don\'t confuse with にかげつ (two months long).'),
  'さんがつ': VocabUsage('さんがつ に だいがく を でます', 'sangatsu ni daigaku o demasu', 'Saya lulus dari universitas bulan Maret.', 'I will graduate from university in March.', 'Bulan ke-3; di Jepang akhir tahun ajaran. Pola: さんがつ に ～.', '3rd month; end of the school year in Japan. Pattern: さんがつ に ～.'),
  'しがつ': VocabUsage('しがつ から にほんご を べんきょう します', 'shigatsu kara nihongo o benkyou shimasu', 'Mulai April saya akan belajar bahasa Jepang.', 'I will study Japanese from April.', 'Bulan ke-4 dibaca しがつ, bukan よんがつ. Awal tahun ajaran di Jepang.', '4th month is read しがつ, not よんがつ. Start of the Japanese school year.'),
  'ごがつ': VocabUsage('ごがつ は いい てんき です', 'gogatsu wa ii tenki desu', 'Bulan Mei cuacanya bagus.', 'The weather is nice in May.', 'Bulan ke-5. Pakai は untuk topik, に untuk waktu kejadian: ごがつ に.', '5th month. Use は as topic, に for time of an event: ごがつ に.'),
  'ろくがつ': VocabUsage('ろくがつ は あめ が おおい です', 'rokugatsu wa ame ga ooi desu', 'Bulan Juni banyak hujan.', 'There is a lot of rain in June.', 'Bulan ke-6; musim hujan (つゆ) di Jepang. Pola: ろくがつ に ～.', '6th month; rainy season (つゆ) in Japan. Pattern: ろくがつ に ～.'),
  'しちがつ': VocabUsage('しちがつ に うみ へ いきます', 'shichigatsu ni umi e ikimasu', 'Bulan Juli saya pergi ke laut.', 'I will go to the sea in July.', 'Bulan ke-7 dibaca しちがつ, bukan なながつ.', '7th month is read しちがつ, not なながつ.'),
  'はちがつ': VocabUsage('はちがつ は とても あつい です', 'hachigatsu wa totemo atsui desu', 'Bulan Agustus sangat panas.', 'August is very hot.', 'Bulan ke-8. Pola: はちがつ に + kegiatan; はちがつ は + keadaan.', '8th month. Pattern: はちがつ に + activity; はちがつ は + description.'),
  'くがつ': VocabUsage('くがつ に にほん へ かえります', 'kugatsu ni nihon e kaerimasu', 'Bulan September saya pulang ke Jepang.', 'I will return to Japan in September.', 'Bulan ke-9 dibaca くがつ, bukan きゅうがつ.', '9th month is read くがつ, not きゅうがつ.'),
  'じゅうがつ': VocabUsage('じゅうがつ に りょこう を します', 'juugatsu ni ryokou o shimasu', 'Bulan Oktober saya akan berwisata.', 'I will travel in October.', 'Bulan ke-10. Pola: じゅうがつ に ～. Bandingkan とおか (tanggal 10).', '10th month. Pattern: じゅうがつ に ～. Compare とおか (the 10th day).'),
  'じゅういちがつ': VocabUsage('たんじょうび は じゅういちがつ です', 'tanjoubi wa juuichigatsu desu', 'Ulang tahun saya bulan November.', 'My birthday is in November.', 'Bulan ke-11 = じゅう + いち + がつ. Pola: ～は じゅういちがつ です.', '11th month = じゅう + いち + がつ. Pattern: ～は じゅういちがつ です.'),
  'じゅうにがつ': VocabUsage('じゅうにがつ に ゆき が ふります', 'juunigatsu ni yuki ga furimasu', 'Bulan Desember turun salju.', 'It snows in December.', 'Bulan ke-12. Pola: じゅうにがつ に ～.', '12th month. Pattern: じゅうにがつ に ～.'),
  'なんがつ': VocabUsage('なつやすみ は なんがつ から です か', 'natsuyasumi wa nangatsu kara desu ka', 'Libur musim panas mulai bulan apa?', 'Which month does summer vacation start?', 'Kata tanya bulan. Pola: なんがつ に ～か / ～は なんがつ です か.', 'Question word for month. Pattern: なんがつ に ～か / ～は なんがつ です か.'),
  'ついたち': VocabUsage('しがつ ついたち に にゅうがく します', 'shigatsu tsuitachi ni nyuugaku shimasu', 'Saya masuk sekolah tanggal 1 April.', 'I enter school on April 1st.', 'Tanggal 1 dibaca ついたち (bukan いちにち = satu hari). Pola: [bulan] ついたち に.', 'The 1st is ついたち (not いちにち = one day). Pattern: [month] ついたち に.'),
  'ふつか': VocabUsage('ふつか に ともだち が きます', 'futsuka ni tomodachi ga kimasu', 'Teman saya datang tanggal 2.', 'My friend is coming on the 2nd.', 'Tanggal 2 atau durasi dua hari. Durasi: ふつか かん / ふつか やすみます.', 'The 2nd or two days. As duration: ふつか かん / ふつか やすみます.'),
  'みっか': VocabUsage('みっか は にちようび です', 'mikka wa nichiyoubi desu', 'Tanggal 3 hari Minggu.', 'The 3rd is a Sunday.', 'Tanggal 3 atau tiga hari. Durasi tanpa に: みっか やすみました.', 'The 3rd or three days. Duration takes no に: みっか やすみました.'),
  'よっか': VocabUsage('よっか に テスト が あります', 'yokka ni tesuto ga arimasu', 'Ada ujian tanggal 4.', 'There is a test on the 4th.', 'Tanggal 4 atau empat hari. Jangan tertukar dengan ようか (tanggal 8).', 'The 4th or four days. Don\'t confuse with ようか (the 8th).'),
  'いつか': VocabUsage('いつか に パーティー を します', 'itsuka ni paatii o shimasu', 'Kami mengadakan pesta tanggal 5.', 'We are having a party on the 5th.', 'Tanggal 5 atau lima hari. Juga bisa berarti \'suatu hari nanti\' tergantung konteks.', 'The 5th or five days. Can also mean \'someday\' depending on context.'),
  'むいか': VocabUsage('むいか から りょこう に いきます', 'muika kara ryokou ni ikimasu', 'Mulai tanggal 6 saya pergi berwisata.', 'I am going on a trip from the 6th.', 'Tanggal 6 atau enam hari. Pola: むいか に / むいか から / むいか かん.', 'The 6th or six days. Patterns: むいか に / むいか から / むいか かん.'),
  'なのか': VocabUsage('しちがつ なのか は たなばた です', 'shichigatsu nanoka wa tanabata desu', 'Tanggal 7 Juli adalah Tanabata.', 'July 7th is Tanabata.', 'Tanggal 7 atau tujuh hari. Kadang dibaca なぬか. Pola: [bulan] なのか.', 'The 7th or seven days. Sometimes read なぬか. Pattern: [month] なのか.'),
  'ようか': VocabUsage('ようか に びょういん へ いきます', 'youka ni byouin e ikimasu', 'Tanggal 8 saya pergi ke rumah sakit.', 'I am going to the hospital on the 8th.', 'Tanggal 8 atau delapan hari. Beda dengan よっか (tanggal 4).', 'The 8th or eight days. Different from よっか (the 4th).'),
  'ここのか': VocabUsage('ここのか まで に しゅくだい を だします', 'kokonoka made ni shukudai o dashimasu', 'Saya kumpulkan PR paling lambat tanggal 9.', 'I will hand in my homework by the 9th.', 'Tanggal 9 atau sembilan hari. Pola batas waktu: ここのか まで に.', 'The 9th or nine days. Deadline pattern: ここのか まで に.'),
  'とおか': VocabUsage('とおか かん にほん に いました', 'tooka kan nihon ni imashita', 'Saya berada di Jepang selama sepuluh hari.', 'I was in Japan for ten days.', 'Tanggal 10 atau sepuluh hari. Durasi: とおか かん. Ingat vokal panjang とお.', 'The 10th or ten days. Duration: とおか かん. Note the long vowel とお.'),
  'はつか': VocabUsage('はつか は はは の たんじょうび です', 'hatsuka wa haha no tanjoubi desu', 'Tanggal 20 adalah ulang tahun ibu saya.', 'The 20th is my mother\'s birthday.', 'Tanggal 20 dibaca khusus はつか (bukan にじゅうにち).', 'The 20th has the special reading はつか (not にじゅうにち).'),
  'なんにち': VocabUsage('きょう は なんにち です か', 'kyou wa nannichi desu ka', 'Hari ini tanggal berapa?', 'What is the date today?', 'Kata tanya tanggal; juga \'berapa hari\' (durasi). Pola: ～は なんにち です か.', 'Question word for the date; also \'how many days\'. Pattern: ～は なんにち です か.'),
  'なんようび': VocabUsage('あした は なんようび です か', 'ashita wa nanyoubi desu ka', 'Besok hari apa?', 'What day of the week is tomorrow?', 'Kata tanya hari dalam minggu. Jawab dengan ～ようび です.', 'Question word for the day of the week. Answer with ～ようび です.'),
  'なんじ': VocabUsage('いま なんじ です か', 'ima nanji desu ka', 'Sekarang jam berapa?', 'What time is it now?', 'Kata tanya jam. Pola: なんじ に ～ます か (jam berapa melakukan sesuatu).', 'Question word for the time. Pattern: なんじ に ～ます か (at what time).'),
  'よじ': VocabUsage('よじ に うち へ かえります', 'yoji ni uchi e kaerimasu', 'Saya pulang ke rumah jam empat.', 'I go home at four o\'clock.', 'Jam empat dibaca よじ, bukan よんじ. Waktu tertentu pakai に.', 'Four o\'clock is よじ, not よんじ. Specific times take に.'),
  'しちじ': VocabUsage('まいあさ しちじ に おきます', 'maiasa shichiji ni okimasu', 'Setiap pagi saya bangun jam tujuh.', 'I get up at seven every morning.', 'Jam tujuh dibaca しちじ (bukan ななじ). Pola: しちじ に ～ます.', 'Seven o\'clock is しちじ (not ななじ). Pattern: しちじ に ～ます.'),
  'くじ': VocabUsage('ぎんこう は くじ から です', 'ginkou wa kuji kara desu', 'Bank buka mulai jam sembilan.', 'The bank opens from nine o\'clock.', 'Jam sembilan dibaca くじ, bukan きゅうじ. Pola: くじ から ～ まで.', 'Nine o\'clock is くじ, not きゅうじ. Pattern: くじ から ～ まで.'),
  'はん': VocabUsage('じゅうにじ はん に ひるごはん を たべます', 'juuniji han ni hirugohan o tabemasu', 'Saya makan siang jam setengah satu.', 'I eat lunch at twelve thirty.', 'Diletakkan setelah jam: [jam] はん = lewat 30 menit. Contoh: さんじ はん = 3.30.', 'Placed after the hour: [hour] はん = half past. E.g. さんじ はん = 3:30.'),
  'ごろ': VocabUsage('じゅういちじ ごろ ねます', 'juuichiji goro nemasu', 'Saya tidur sekitar jam sebelas.', 'I go to bed around eleven.', 'Akhiran untuk titik waktu: [jam/tanggal] ごろ. Untuk jumlah pakai ぐらい.', 'Suffix for points in time: [time/date] ごろ. For amounts use ぐらい.'),
  'すぎ': VocabUsage('いま くじ すぎ です', 'ima kuji sugi desu', 'Sekarang sudah lewat jam sembilan.', 'It is now past nine.', 'Akhiran: [jam] すぎ = lewat dari jam itu. Lawannya: [jam] まえ.', 'Suffix: [time] すぎ = past that time. Opposite: [time] まえ.'),
  'いっぷん': VocabUsage('えき まで あるいて いっぷん です', 'eki made aruite ippun desu', 'Ke stasiun satu menit jalan kaki.', 'It is a one-minute walk to the station.', 'Pembilang menit ふん/ぷん berubah bunyi: いっぷん, さんぷん, ろっぷん.', 'Minute counter ふん/ぷん changes sound: いっぷん, さんぷん, ろっぷん.'),
  'じっぷん': VocabUsage('じっぷん まって ください', 'jippun matte kudasai', 'Tolong tunggu sepuluh menit.', 'Please wait ten minutes.', 'Sepuluh menit: じっぷん atau じゅっぷん (keduanya umum).', 'Ten minutes: じっぷん or じゅっぷん (both common).'),
  'いっしゅうかん': VocabUsage('いっしゅうかん に にかい プール へ いきます', 'isshuukan ni nikai puuru e ikimasu', 'Saya ke kolam renang dua kali seminggu.', 'I go to the pool twice a week.', 'Durasi satu minggu. Pola frekuensi: いっしゅうかん に [n]かい.', 'Duration of one week. Frequency pattern: いっしゅうかん に [n]かい.'),
  'ひとつき': VocabUsage('ひとつき に いちど かいもの に いきます', 'hitotsuki ni ichido kaimono ni ikimasu', 'Saya belanja sebulan sekali.', 'I go shopping once a month.', 'Satu bulan (lamanya), nuansa lisan. Versi formal: いっかげつ.', 'One month (duration), conversational. Formal version: いっかげつ.'),
  'いっかげつ': VocabUsage('いっかげつ にほん に いました', 'ikkagetsu nihon ni imashita', 'Saya tinggal di Jepang selama satu bulan.', 'I stayed in Japan for one month.', 'Pembilang durasi bulan: [n]かげつ. Beda dengan いちがつ (Januari).', 'Counter for months of duration: [n]かげつ. Different from いちがつ (January).'),
  'おととい': VocabUsage('おととい デパート へ いきました', 'ototoi depaato e ikimashita', 'Kemarin lusa saya pergi ke mal.', 'I went to the department store the day before yesterday.', 'Kata keterangan waktu relatif, tanpa partikel に. Urutan: おととい → きのう → きょう.', 'Relative time word, no に. Order: おととい → きのう → きょう.'),
  'あさって': VocabUsage('あさって ともだち に あいます', 'asatte tomodachi ni aimasu', 'Lusa saya bertemu teman.', 'I will meet my friend the day after tomorrow.', 'Waktu relatif, tanpa に. Urutan: きょう → あした → あさって.', 'Relative time word, no に. Order: きょう → あした → あさって.'),
  'けさ': VocabUsage('けさ パン を たべました', 'kesa pan o tabemashita', 'Tadi pagi saya makan roti.', 'I ate bread this morning.', 'Pagi ini/tadi pagi, tanpa に. Biasanya dipakai dengan bentuk lampau.', 'This morning, no に. Usually used with past tense.'),
  'こんばん': VocabUsage('こんばん テレビ を みます', 'konban terebi o mimasu', 'Malam ini saya menonton TV.', 'I will watch TV tonight.', 'Waktu relatif, tanpa に. Juga dalam salam こんばんは.', 'Relative time word, no に. Also in the greeting こんばんは.'),
  'ゆうべ': VocabUsage('ゆうべ おそく ねました', 'yuube osoku nemashita', 'Tadi malam saya tidur larut.', 'I went to bed late last night.', 'Tadi malam (lisan), tanpa に. Lebih formal: さくや / きのう の よる.', 'Last night (spoken), no に. More formal: さくや / きのう の よる.'),
  'ゆうがた': VocabUsage('ゆうがた こうえん を さんぽ します', 'yuugata kouen o sanpo shimasu', 'Sore hari saya jalan-jalan di taman.', 'I take a walk in the park in the evening.', 'Waktu menjelang malam (sekitar 4–7 sore). Bisa tanpa に.', 'Late afternoon/early evening (about 4–7 pm). Can be used without に.'),
  'まいしゅう': VocabUsage('まいしゅう にちようび に テニス を します', 'maishuu nichiyoubi ni tenisu o shimasu', 'Setiap minggu hari Minggu saya bermain tenis.', 'I play tennis every Sunday.', 'まい + しゅう = setiap minggu, tanpa に. Pola: まいしゅう [hari] に.', 'まい + しゅう = every week, no に. Pattern: まいしゅう [day] に.'),
  'まいつき': VocabUsage('まいつき ほん を にさつ かいます', 'maitsuki hon o nisatsu kaimasu', 'Setiap bulan saya membeli dua buku.', 'I buy two books every month.', 'Setiap bulan, tanpa に. Bacaan lain: まいげつ (lebih formal).', 'Every month, no に. Alternate reading: まいげつ (more formal).'),
  'まいとし': VocabUsage('まいとし ふゆ に スキー を します', 'maitoshi fuyu ni sukii o shimasu', 'Setiap tahun saya bermain ski di musim dingin.', 'I go skiing every winter.', 'Setiap tahun, tanpa に. Bacaan lain: まいねん.', 'Every year, no に. Alternate reading: まいねん.'),
  'せんげつ': VocabUsage('せんげつ ひっこし しました', 'sengetsu hikkoshi shimashita', 'Bulan lalu saya pindah rumah.', 'I moved house last month.', 'Bulan lalu, tanpa に. Seri: せんげつ → こんげつ → らいげつ.', 'Last month, no に. Series: せんげつ → こんげつ → らいげつ.'),
  'らいげつ': VocabUsage('らいげつ けっこん します', 'raigetsu kekkon shimasu', 'Bulan depan saya menikah.', 'I am getting married next month.', 'Bulan depan, tanpa に. Seri: せん- (lalu), こん- (ini), らい- (depan).', 'Next month, no に. Series: せん- (last), こん- (this), らい- (next).'),
  'おととし': VocabUsage('おととし にほん へ きました', 'ototoshi nihon e kimashita', 'Dua tahun lalu saya datang ke Jepang.', 'I came to Japan the year before last.', 'Waktu relatif, tanpa に. Urutan: おととし → きょねん → ことし.', 'Relative time word, no に. Order: おととし → きょねん → ことし.'),
  'さらいねん': VocabUsage('さらいねん だいがく に はいります', 'sarainen daigaku ni hairimasu', 'Dua tahun lagi saya masuk universitas.', 'I will enter university the year after next.', 'さ + らいねん = tahun setelah tahun depan. Tanpa に.', 'さ + らいねん = the year after next. No に.'),
  'さらいしゅう': VocabUsage('さらいしゅう テスト が あります', 'saraishuu tesuto ga arimasu', 'Dua minggu lagi ada ujian.', 'There is a test the week after next.', 'さ + らいしゅう = minggu setelah minggu depan. Tanpa に.', 'さ + らいしゅう = the week after next. No に.'),
  'まえ': VocabUsage('ねる まえ に は を みがきます', 'neru mae ni ha o migakimasu', 'Sebelum tidur saya menggosok gigi.', 'I brush my teeth before going to bed.', 'Waktu: [kata kerja kamus] まえ に / [benda] の まえ に. Tempat: [benda] の まえ.', 'Time: [dictionary verb] まえ に / [noun] の まえ に. Place: [noun] の まえ.'),
  'あと': VocabUsage('しごと の あと で ビール を のみます', 'shigoto no ato de biiru o nomimasu', 'Sesudah kerja saya minum bir.', 'I drink beer after work.', 'Pola: [benda] の あと で / [kata kerja ~た] あと で. Lawan dari まえ.', 'Pattern: [noun] の あと で / [verb ~た] あと で. Opposite of まえ.'),
  'とき': VocabUsage('こども の とき よく およぎました', 'kodomo no toki yoku oyogimashita', 'Waktu kecil saya sering berenang.', 'I often swam when I was a child.', 'Pola: [benda] の とき / [kata kerja/sifat] とき = ketika ～.', 'Pattern: [noun] の とき / [verb/adjective] とき = when ～.'),
  'はじめ': VocabUsage('らいげつ の はじめ に りょこう します', 'raigetsu no hajime ni ryokou shimasu', 'Awal bulan depan saya akan berwisata.', 'I will travel at the beginning of next month.', 'Kata benda. Pola: [waktu] の はじめ に. Lawan: おわり (akhir).', 'Noun. Pattern: [time] の はじめ に. Opposite: おわり (end).'),
  'つぎ': VocabUsage('つぎ の えき で おります', 'tsugi no eki de orimasu', 'Saya turun di stasiun berikutnya.', 'I get off at the next station.', 'Kata benda; sebelum benda pakai の: つぎ の [benda]. Juga: つぎ は ～.', 'Noun; before a noun use の: つぎ の [noun]. Also: つぎ は ～.'),
  'さき': VocabUsage('どうぞ おさき に', 'douzo osaki ni', 'Silakan duluan.', 'Please go ahead.', 'Ungkapan umum: おさき に (duluan); おさき に しつれい します saat pulang duluan.', 'Common phrases: おさき に (go ahead / before you); おさき に しつれい します when leaving first.'),
  'やすみ': VocabUsage('あした は がっこう が やすみ です', 'ashita wa gakkou ga yasumi desu', 'Besok sekolah libur.', 'School is closed tomorrow.', 'Kata benda dari やすみます. Pola: ～は やすみ です; ひる やすみ (istirahat siang).', 'Noun from やすみます. Pattern: ～は やすみ です; ひる やすみ (lunch break).'),
  'なつやすみ': VocabUsage('なつやすみ に くに へ かえります', 'natsuyasumi ni kuni e kaerimasu', 'Saat libur musim panas saya pulang kampung.', 'I will go back to my country during summer vacation.', 'なつ + やすみ. Pola: なつやすみ に ～. Mirip: ふゆやすみ, はるやすみ.', 'なつ + やすみ. Pattern: なつやすみ に ～. Similar: ふゆやすみ, はるやすみ.'),
  'たんじょうび': VocabUsage('おたんじょうび おめでとう ございます', 'otanjoubi omedetou gozaimasu', 'Selamat ulang tahun.', 'Happy birthday.', 'Kata benda; sopan: おたんじょうび. Pola: [orang] の たんじょうび.', 'Noun; polite: おたんじょうび. Pattern: [person] の たんじょうび.'),
  'はる': VocabUsage('はる に なりました', 'haru ni narimashita', 'Sudah musim semi.', 'Spring has come.', 'Musim; pola: はる に なります (menjadi musim semi), はる は ～.', 'Season; pattern: はる に なります (spring comes), はる は ～.'),
  'なつ': VocabUsage('なつ は うみ で およぎます', 'natsu wa umi de oyogimasu', 'Di musim panas saya berenang di laut.', 'In summer I swim in the sea.', 'Musim; pola: なつ は ～ / なつ に ～. Turunan: なつやすみ.', 'Season; pattern: なつ は ～ / なつ に ～. Derived: なつやすみ.'),
  'あき': VocabUsage('あき は すずしい です', 'aki wa suzushii desu', 'Musim gugur sejuk.', 'Autumn is cool.', 'Musim; sering dengan すずしい, こうよう (daun merah).', 'Season; often with すずしい, こうよう (autumn leaves).'),
  'ふゆ': VocabUsage('ふゆ は ゆき が ふります', 'fuyu wa yuki ga furimasu', 'Di musim dingin turun salju.', 'It snows in winter.', 'Musim; sering dengan さむい, ゆき. Turunan: ふゆやすみ.', 'Season; often with さむい, ゆき. Derived: ふゆやすみ.'),
  'はれ': VocabUsage('あした は はれ です', 'ashita wa hare desu', 'Besok cerah.', 'It will be sunny tomorrow.', 'Kata benda cuaca. Pola: ～は はれ です. Kata kerja: はれます (menjadi cerah).', 'Weather noun. Pattern: ～は はれ です. Verb: はれます (to clear up).'),
  'くもり': VocabUsage('きょう は くもり です', 'kyou wa kumori desu', 'Hari ini mendung.', 'It is cloudy today.', 'Kata benda cuaca. Pola: くもり です; くもり のち あめ (berawan lalu hujan).', 'Weather noun. Pattern: くもり です; くもり のち あめ (cloudy, then rain).'),
  '風邪': VocabUsage('かぜ を ひきました', 'kaze o hikimashita', 'Saya masuk angin.', 'I caught a cold.', 'Kata benda. Kolokasi tetap: かぜ を ひきます (terkena pilek). Beda dengan かぜ \'angin\'.', 'Noun. Fixed collocation: かぜ を ひきます (catch a cold). Different from かぜ \'wind\'.'),
  'あたたかい': VocabUsage('きょう は あたたかい です ね', 'kyou wa atatakai desu ne', 'Hari ini hangat, ya.', 'It is warm today, isn\'t it?', 'Kata sifat い. Untuk cuaca maupun benda/minuman. Lawan: さむい / つめたい.', 'い-adjective. For weather and things/drinks. Opposites: さむい / つめたい.'),
  'すずしい': VocabUsage('あさ は すずしい です', 'asa wa suzushii desu', 'Pagi hari sejuk.', 'It is cool in the morning.', 'Kata sifat い untuk udara/cuaca yang sejuk menyenangkan. Bukan untuk benda.', 'い-adjective for pleasantly cool air/weather. Not used for objects.'),
  'つめたい': VocabUsage('つめたい みず を ください', 'tsumetai mizu o kudasai', 'Tolong air dingin.', 'Cold water, please.', 'Kata sifat い untuk benda dingin saat disentuh/diminum. Cuaca dingin: さむい.', 'い-adjective for things cold to touch/drink. Cold weather: さむい.'),
  'りょうしん': VocabUsage('りょうしん は げんき です', 'ryoushin wa genki desu', 'Orang tua saya sehat.', 'My parents are well.', 'Kata benda untuk orang tua sendiri. Orang tua orang lain: ごりょうしん.', 'Noun for one\'s own parents. Someone else\'s: ごりょうしん.'),
  'きょうだい': VocabUsage('きょうだい が なんにん います か', 'kyoudai ga nannin imasu ka', 'Kamu punya berapa saudara?', 'How many siblings do you have?', 'Kata benda; pola: きょうだい が [n]にん います. Sopan: ごきょうだい.', 'Noun; pattern: きょうだい が [n]にん います. Polite: ごきょうだい.'),
  'おじさん': VocabUsage('おじさん は おおさか に すんで います', 'ojisan wa oosaka ni sunde imasu', 'Paman saya tinggal di Osaka.', 'My uncle lives in Osaka.', 'Paman, juga sapaan untuk pria paruh baya. Beda: おじいさん (kakek).', 'Uncle; also for middle-aged men. Different: おじいさん (grandfather).'),
  'おばさん': VocabUsage('おばさん に てがみ を かきます', 'obasan ni tegami o kakimasu', 'Saya menulis surat untuk bibi.', 'I write a letter to my aunt.', 'Bibi, juga sapaan untuk wanita paruh baya. Beda: おばあさん (nenek).', 'Aunt; also for middle-aged women. Different: おばあさん (grandmother).'),
  'おくさん': VocabUsage('おくさん は おげんき です か', 'okusan wa ogenki desu ka', 'Apakah istri Anda sehat?', 'Is your wife well?', 'Untuk istri orang lain (sopan). Istri sendiri: かない / つま.', 'For someone else\'s wife (polite). One\'s own wife: かない / つま.'),
  'おとな': VocabUsage('おとな は ごひゃく えん です', 'otona wa gohyaku en desu', 'Dewasa harganya 500 yen.', 'It is 500 yen for adults.', 'Kata benda; lawan こども. Sering di tiket: おとな / こども.', 'Noun; opposite of こども. Common on tickets: おとな / こども.'),
  'おとこのこ': VocabUsage('こうえん に おとこのこ が います', 'kouen ni otokonoko ga imasu', 'Ada anak laki-laki di taman.', 'There is a boy in the park.', 'おとこ + の + こ. Pakai います untuk keberadaan. Pria dewasa: おとこ の ひと.', 'おとこ + の + こ. Use います for existence. Adult man: おとこ の ひと.'),
  'おんなのこ': VocabUsage('あの おんなのこ は わたし の いもうと です', 'ano onnanoko wa watashi no imouto desu', 'Anak perempuan itu adik saya.', 'That girl is my younger sister.', 'おんな + の + こ. Wanita dewasa: おんな の ひと.', 'おんな + の + こ. Adult woman: おんな の ひと.'),
  'みなさん': VocabUsage('みなさん おはよう ございます', 'minasan ohayou gozaimasu', 'Selamat pagi, semuanya.', 'Good morning, everyone.', 'Sapaan sopan untuk kelompok/hadirin. Versi santai: みんな.', 'Polite address to a group/audience. Casual version: みんな.'),
  'みんな': VocabUsage('みんな で うた を うたいましょう', 'minna de uta o utaimashou', 'Ayo kita semua bernyanyi.', 'Let\'s all sing a song together.', 'Semua orang (santai). Pola: みんな で ～ (bersama-sama). Sopan: みなさん.', 'Everyone (casual). Pattern: みんな で ～ (together). Polite: みなさん.'),
  'じぶん': VocabUsage('じぶん で りょうり を つくります', 'jibun de ryouri o tsukurimasu', 'Saya memasak sendiri.', 'I cook by myself.', 'Kata benda refleksif. Pola: じぶん で ～ (sendiri), じぶん の ～ (milik sendiri).', 'Reflexive noun. Patterns: じぶん で ～ (by oneself), じぶん の ～ (one\'s own).'),
  'いしゃ': VocabUsage('あに は いしゃ です', 'ani wa isha desu', 'Kakak laki-laki saya dokter.', 'My older brother is a doctor.', 'Profesi. Saat menyapa/hormat: おいしゃさん. Ke dokter: いしゃ に いきます.', 'Profession. Respectful: おいしゃさん. See a doctor: いしゃ に いきます.'),
  'けいかん': VocabUsage('けいかん に みち を ききました', 'keikan ni michi o kikimashita', 'Saya bertanya jalan kepada polisi.', 'I asked a police officer for directions.', 'Istilah resmi untuk polisi. Sapaan akrab: おまわりさん.', 'Formal term for police officer. Friendly term: おまわりさん.'),
  'おまわりさん': VocabUsage('おまわりさん が こうばん に います', 'omawarisan ga kouban ni imasu', 'Ada pak polisi di pos polisi.', 'There is a police officer at the police box.', 'Sebutan ramah untuk polisi (dipakai anak-anak & sehari-hari). Resmi: けいかん.', 'Friendly word for a police officer (used by kids and daily). Formal: けいかん.'),
  'りゅうがくせい': VocabUsage('わたし は インドネシア の りゅうがくせい です', 'watashi wa indoneshia no ryuugakusei desu', 'Saya pelajar asing dari Indonesia.', 'I am an international student from Indonesia.', 'Kata benda. Pola: [negara] の りゅうがくせい. Kata kerja: りゅうがく します.', 'Noun. Pattern: [country] の りゅうがくせい. Verb: りゅうがく します.'),
  'がいこくじん': VocabUsage('この まち は がいこくじん が おおい です', 'kono machi wa gaikokujin ga ooi desu', 'Di kota ini banyak orang asing.', 'There are many foreigners in this town.', 'がいこく + じん. Bentuk singkat がいじん terdengar kurang sopan; pakai がいこくじん.', 'がいこく + じん. The short がいじん can sound rude; use がいこくじん.'),
