  'しまる': VocabUsage('ドア が しまりました', 'doa ga shimarimashita', 'Pintunya tertutup.', 'The door closed.', 'Kata kerja gol. I, intransitif. Bentuk sopan: しまります. Pola: [benda] が しまる. Pasangan: しめる.', 'Group 1 verb, intransitive. Polite: しまります. Pattern: [thing] が しまる. Transitive pair: しめる.'),
  'あげる': VocabUsage('ともだち に ほん を あげました', 'tomodachi ni hon o agemashita', 'Saya memberi buku kepada teman.', 'I gave a book to my friend.', 'Kata kerja gol. II. Bentuk sopan: あげます. Pola: [orang] に [benda] を あげる (dari saya ke orang lain).', 'Group 2 verb. Polite: あげます. Pattern: [person] に [thing] を あげる (giving outward).'),
