  '貼る': VocabUsage('ふうとう に きって を はります', 'fuutou ni kitte o harimasu', 'Saya menempel perangko di amplop.', 'I stick a stamp on the envelope.', 'Kata kerja gol. I. Bentuk sopan: はります. Pola: [tempat] に [benda] を はる.', 'Group 1 verb. Polite: はります. Pattern: [surface] に [thing] を はる.'),
  'はれる': VocabUsage('あした は はれる でしょう', 'ashita wa hareru deshou', 'Besok mungkin akan cerah.', 'It will probably be sunny tomorrow.', 'Kata kerja gol. II. Bentuk sopan: はれます. Untuk cuaca; keadaan cerah: はれています. Kata benda: はれ.', 'Group 2 verb. Polite: はれます. Weather; state: はれています. Noun: はれ.'),
  'くもる': VocabUsage('ごご から くもりました', 'gogo kara kumorimashita', 'Sejak siang langit menjadi mendung.', 'It became cloudy in the afternoon.', 'Kata kerja gol. I. Bentuk sopan: くもります. Keadaan: くもっています. Kata benda: くもり.', 'Group 1 verb. Polite: くもります. State: くもっています. Noun: くもり.'),
  'ふる': VocabUsage('きょう は あめ が ふって います', 'kyou wa ame ga futte imasu', 'Hari ini sedang turun hujan.', 'It is raining today.', 'Kata kerja gol. I. Bentuk sopan: ふります. Pola: あめ/ゆき が ふる.', 'Group 1 verb. Polite: ふります. Pattern: あめ/ゆき が ふる.'),
  '吹く': VocabUsage('つよい かぜ が ふいて います', 'tsuyoi kaze ga fuite imasu', 'Angin kencang sedang bertiup.', 'A strong wind is blowing.', 'Kata kerja gol. I. Bentuk sopan: ふきます. Pola: かぜ が ふく. Juga meniup alat musik: ふえ を ふく.', 'Group 1 verb. Polite: ふきます. Pattern: かぜ が ふく. Also play wind instruments: ふえ を ふく.'),
  'まがる': VocabUsage('つぎ の かど を みぎ に まがって ください', 'tsugi no kado o migi ni magatte kudasai', 'Tolong belok kanan di tikungan berikutnya.', 'Please turn right at the next corner.', 'Kata kerja gol. I. Bentuk sopan: まがります. Pola: [tikungan] を [arah] に まがる.', 'Group 1 verb. Polite: まがります. Pattern: [corner] を [direction] に まがる.'),
  'みがく': VocabUsage('ねる まえ に は を みがきます', 'neru mae ni ha o migakimasu', 'Sebelum tidur saya menggosok gigi.', 'I brush my teeth before bed.', 'Kata kerja gol. I. Bentuk sopan: みがきます. Kolokasi: は を みがく, くつ を みがく.', 'Group 1 verb. Polite: みがきます. Collocations: は を みがく, くつ を みがく.'),
  'みせる': VocabUsage('パスポート を みせて ください', 'pasupooto o misete kudasai', 'Tolong perlihatkan paspor Anda.', 'Please show me your passport.', 'Kata kerja gol. II. Bentuk sopan: みせます. Pola: [orang] に [benda] を みせる.', 'Group 2 verb. Polite: みせます. Pattern: [person] に [thing] を みせる.'),
  'もうす': VocabUsage('わたし は たなか と もうします', 'watashi wa tanaka to moushimasu', 'Nama saya Tanaka.', 'My name is Tanaka.', 'Kata kerja gol. I, merendah (kenjougo). Selalu bentuk もうします. Pola: [nama] と もうします.', 'Group 1 humble verb. Used as もうします. Pattern: [name] と もうします.'),
  'もつ': VocabUsage('おおきい かばん を もって います', 'ookii kaban o motte imasu', 'Saya membawa tas besar.', 'I am carrying a big bag.', 'Kata kerja gol. I. Biasanya もっています (membawa/punya). Pola: [benda] を もつ.', 'Group 1 verb. Usually もっています (carry/own). Pattern: [thing] を もつ.'),
  'やる': VocabUsage('いっしょに テニス を やろう', 'isshoni tenisu o yarou', 'Ayo main tenis bersama.', 'Let\'s play tennis together.', 'Kata kerja gol. I. Bentuk sopan: やります. Versi santai dari する; jangan dipakai ke atasan.', 'Group 1 verb. Polite: やります. Casual version of する; avoid with superiors.'),
  'よぶ': VocabUsage('タクシー を よんで ください', 'takushii o yonde kudasai', 'Tolong panggilkan taksi.', 'Please call a taxi.', 'Kata kerja gol. I. Bentuk sopan: よびます. Pola: [orang] を よぶ (memanggil/mengundang). Menelepon: でんわ する.', 'Group 1 verb. Polite: よびます. Pattern: [person] を よぶ (call over/invite). Phone call: でんわ する.'),
  'わたる': VocabUsage('この はし を わたって ください', 'kono hashi o watatte kudasai', 'Tolong seberangi jembatan ini.', 'Please cross this bridge.', 'Kata kerja gol. I. Bentuk sopan: わたります. Pola: [jalan/jembatan] を わたる.', 'Group 1 verb. Polite: わたります. Pattern: [road/bridge] を わたる.'),
  'さんぽする': VocabUsage('あさ こうえん を さんぽします', 'asa kouen o sanposhimasu', 'Pagi hari saya berjalan-jalan di taman.', 'I take a walk in the park in the morning.', 'Kata kerja gol. III. Bentuk sopan: さんぽします. Pola: [tempat] を さんぽする.', 'Group 3 verb. Polite: さんぽします. Pattern: [place] を さんぽする.'),
  'そうじする': VocabUsage('まいしゅう へや を そうじします', 'maishuu heya o soujishimasu', 'Setiap minggu saya membersihkan kamar.', 'I clean my room every week.', 'Kata kerja gol. III. Bentuk sopan: そうじします. Pola: [tempat] を そうじする.', 'Group 3 verb. Polite: そうじします. Pattern: [place] を そうじする.'),
  'せんたくする': VocabUsage('にちようび に せんたくします', 'nichiyoubi ni sentakushimasu', 'Saya mencuci pakaian pada hari Minggu.', 'I do the laundry on Sundays.', 'Kata kerja gol. III. Bentuk sopan: せんたくします. Khusus pakaian; mencuci barang lain: あらう.', 'Group 3 verb. Polite: せんたくします. For clothes only; other washing uses あらう.'),
  'りょうりする': VocabUsage('はは は まいばん りょうりします', 'haha wa maiban ryourishimasu', 'Ibu saya memasak setiap malam.', 'My mother cooks every evening.', 'Kata kerja gol. III. Bentuk sopan: りょうりします. りょうり juga kata benda \'masakan\'.', 'Group 3 verb. Polite: りょうりします. りょうり alone is the noun \'cooking/dish\'.'),
  'れんしゅうする': VocabUsage('まいにち ピアノ を れんしゅうします', 'mainichi piano o renshuushimasu', 'Setiap hari saya berlatih piano.', 'I practice the piano every day.', 'Kata kerja gol. III. Bentuk sopan: れんしゅうします. Pola: [hal] を れんしゅうする.', 'Group 3 verb. Polite: れんしゅうします. Pattern: [skill] を れんしゅうする.'),
  'けっこんする': VocabUsage('あね は らいねん けっこんします', 'ane wa rainen kekkonshimasu', 'Kakak perempuan saya akan menikah tahun depan.', 'My older sister will get married next year.', 'Kata kerja gol. III. Bentuk sopan: けっこんします. Pola: [orang] と けっこんする. Status: けっこんしています.', 'Group 3 verb. Polite: けっこんします. Pattern: [person] と けっこんする. Status: けっこんしています.'),
  'コピーする': VocabUsage('この しりょう を コピーして ください', 'kono shiryou o kopiishite kudasai', 'Tolong fotokopi dokumen ini.', 'Please copy this document.', 'Kata kerja gol. III (kata serapan + する). Bentuk sopan: コピーします. Pola: [dokumen] を コピーする.', 'Group 3 verb (loanword + する). Polite: コピーします. Pattern: [document] を コピーする.'),
  'あかるい': VocabUsage('この へや は あかるい です', 'kono heya wa akarui desu', 'Kamar ini terang.', 'This room is bright.', 'Kata sifat い. Negatif: あかるくない. Untuk tempat (terang) dan sifat orang (ceria). Lawan: くらい.', 'い-adjective. Negative: あかるくない. For places (bright) and people (cheerful). Opposite: くらい.'),
  'くらい': VocabUsage('そと は もう くらい です', 'soto wa mou kurai desu', 'Di luar sudah gelap.', 'It is already dark outside.', 'Kata sifat い. Negatif: くらくない. Lawan: あかるい. Jangan tertukar dengan ぐらい (kira-kira).', 'い-adjective. Negative: くらくない. Opposite: あかるい. Don\'t confuse with ぐらい (about).'),
  'あぶない': VocabUsage('あぶない です から はしらないで ください', 'abunai desu kara hashiranaide kudasai', 'Berbahaya, jadi jangan berlari.', 'It is dangerous, so please don\'t run.', 'Kata sifat い. Negatif: あぶなくない. Diucapkan sendiri 「あぶない!」 = \'Awas!\'.', 'い-adjective. Negative: あぶなくない. Alone, 「あぶない!」 means \'Watch out!\'.'),
  'あまい': VocabUsage('この ケーキ は とても あまい です', 'kono keeki wa totemo amai desu', 'Kue ini sangat manis.', 'This cake is very sweet.', 'Kata sifat い. Negatif: あまくない. Juga berarti \'lunak/memanjakan\' pada orang.', 'い-adjective. Negative: あまくない. Also \'lenient/soft\' about people.'),
  'からい': VocabUsage('インドネシア の りょうり は からい です', 'indoneshia no ryouri wa karai desu', 'Masakan Indonesia pedas.', 'Indonesian food is spicy.', 'Kata sifat い. Negatif: からくない. Juga bisa berarti \'asin\' di beberapa daerah.', 'い-adjective. Negative: からくない. Can also mean \'salty\' in some regions.'),
  'まずい': VocabUsage('この コーヒー は まずい です', 'kono koohii wa mazui desu', 'Kopi ini tidak enak.', 'This coffee tastes bad.', 'Kata sifat い. Negatif: まずくない. Agak kasar; lebih halus: あまり おいしくない.', 'い-adjective. Negative: まずくない. Blunt; softer: あまり おいしくない.'),
  'いたい': VocabUsage('あたま が いたい です', 'atama ga itai desu', 'Kepala saya sakit.', 'I have a headache.', 'Kata sifat い. Pola: [bagian tubuh] が いたい. Negatif: いたくない.', 'い-adjective. Pattern: [body part] が いたい. Negative: いたくない.'),
  'うすい': VocabUsage('この ほん は うすい です', 'kono hon wa usui desu', 'Buku ini tipis.', 'This book is thin.', 'Kata sifat い. Untuk benda pipih (tipis) & rasa/minuman (encer). Lawan: あつい (tebal), こい (pekat).', 'い-adjective. Flat things (thin) and drinks/taste (weak). Opposites: あつい (thick), こい (strong).'),
  '厚い': VocabUsage('ふゆ は あつい コート を きます', 'fuyu wa atsui kooto o kimasu', 'Di musim dingin saya memakai mantel tebal.', 'In winter I wear a thick coat.', 'Kata sifat い. Negatif: あつくない. Untuk benda pipih yang tebal; beda dengan あつい \'panas\'.', 'い-adjective. Negative: あつくない. Thickness of flat things; not あつい \'hot\'.'),
  'うるさい': VocabUsage('となり の へや が うるさい です', 'tonari no heya ga urusai desu', 'Kamar sebelah berisik.', 'The room next door is noisy.', 'Kata sifat い. Negatif: うるさくない. Diucapkan sendiri bisa kasar (\'Berisik!\').', 'い-adjective. Negative: うるさくない. Said alone it is rude (\'Shut up!\').'),
  'おそい': VocabUsage('この でんしゃ は おそい です', 'kono densha wa osoi desu', 'Kereta ini lambat.', 'This train is slow.', 'Kata sifat い. Lambat & larut. Adverbia: おそく (おそく おきました). Lawan: はやい.', 'い-adjective. Slow & late. Adverb: おそく (おそく おきました). Opposite: はやい.'),
  '早い': VocabUsage('ちち は あさ が はやい です', 'chichi wa asa ga hayai desu', 'Ayah saya bangun pagi-pagi.', 'My father is an early riser.', 'Kata sifat い. Untuk waktu (awal). Adverbia: はやく おきます. \'Cepat\' (kecepatan) ditulis kanji lain.', 'い-adjective about time (early). Adverb: はやく おきます. Speed \'fast\' uses a different kanji.'),
  'おもい': VocabUsage('この にもつ は おもい です', 'kono nimotsu wa omoi desu', 'Barang bawaan ini berat.', 'This luggage is heavy.', 'Kata sifat い. Negatif: おもくない. Lawan: かるい.', 'い-adjective. Negative: おもくない. Opposite: かるい.'),
  'かるい': VocabUsage('この パソコン は かるい です', 'kono pasokon wa karui desu', 'Laptop ini ringan.', 'This computer is light.', 'Kata sifat い. Negatif: かるくない. Lawan: おもい. Juga: かるい しょくじ (makanan ringan).', 'い-adjective. Negative: かるくない. Opposite: おもい. Also かるい しょくじ (light meal).'),
  'おもしろい': VocabUsage('この まんが は おもしろい です', 'kono manga wa omoshiroi desu', 'Komik ini menarik.', 'This manga is interesting.', 'Kata sifat い. Negatif: おもしろくない. Mencakup \'menarik\' dan \'lucu\'. Lawan: つまらない.', 'い-adjective. Negative: おもしろくない. Covers \'interesting\' and \'funny\'. Opposite: つまらない.'),
  'つまらない': VocabUsage('きのう の えいが は つまらなかった です', 'kinou no eiga wa tsumaranakatta desu', 'Film kemarin membosankan.', 'Yesterday\'s movie was boring.', 'Kata sifat い. Lampau: つまらなかった. Juga dalam ungkapan merendah つまらない もの です (saat memberi hadiah).', 'い-adjective. Past: つまらなかった. Also humble gift phrase つまらない もの です.'),
  'おおい': VocabUsage('この まち は ひと が おおい です', 'kono machi wa hito ga ooi desu', 'Kota ini banyak orangnya.', 'This town has many people.', 'Kata sifat い. Pola: [tempat] は [benda] が おおい. Jarang langsung di depan kata benda; pakai おおくの.', 'い-adjective. Pattern: [place] は [thing] が おおい. Before nouns use おおくの, not おおい.'),
  'すくない': VocabUsage('この むら は こども が すくない です', 'kono mura wa kodomo ga sukunai desu', 'Desa ini sedikit anak-anaknya.', 'There are few children in this village.', 'Kata sifat い. Pola: [tempat] は [benda] が すくない. Lawan: おおい.', 'い-adjective. Pattern: [place] は [thing] が すくない. Opposite: おおい.'),
  'きたない': VocabUsage('へや が きたない です から そうじします', 'heya ga kitanai desu kara soujishimasu', 'Kamarnya kotor, jadi saya bersihkan.', 'The room is dirty, so I will clean it.', 'Kata sifat い. Negatif: きたなくない. Lawan: きれい. Juga untuk tulisan jelek: じ が きたない.', 'い-adjective. Negative: きたなくない. Opposite: きれい. Also messy handwriting: じ が きたない.'),
  'ひろい': VocabUsage('あたらしい いえ は ひろい です', 'atarashii ie wa hiroi desu', 'Rumah baru itu luas.', 'The new house is spacious.', 'Kata sifat い. Negatif: ひろくない. Untuk ruang/area. Lawan: せまい.', 'い-adjective. Negative: ひろくない. For spaces/areas. Opposite: せまい.'),
  'せまい': VocabUsage('わたし の へや は せまい です', 'watashi no heya wa semai desu', 'Kamar saya sempit.', 'My room is small.', 'Kata sifat い. Untuk luas ruang (bukan ukuran benda; itu ちいさい). Lawan: ひろい.', 'い-adjective. For space (not object size, which is ちいさい). Opposite: ひろい.'),
  'ちかい': VocabUsage('えき は ここ から ちかい です', 'eki wa koko kara chikai desu', 'Stasiun dekat dari sini.', 'The station is close to here.', 'Kata sifat い. Pola: [tempat] から/に ちかい. Di depan kata benda: ちかく の [benda].', 'い-adjective. Pattern: [place] から/に ちかい. Before nouns: ちかく の [noun].'),
  'とおい': VocabUsage('がっこう は うち から とおい です', 'gakkou wa uchi kara tooi desu', 'Sekolah jauh dari rumah.', 'School is far from my house.', 'Kata sifat い. Pola: [tempat] から とおい. Di depan kata benda: とおく の [benda].', 'い-adjective. Pattern: [place] から とおい. Before nouns: とおく の [noun].'),
  'つよい': VocabUsage('きょう は かぜ が つよい です', 'kyou wa kaze ga tsuyoi desu', 'Hari ini anginnya kencang.', 'The wind is strong today.', 'Kata sifat い. Negatif: つよくない. Untuk tenaga, angin, tim. Lawan: よわい.', 'い-adjective. Negative: つよくない. For strength, wind, teams. Opposite: よわい.'),
  'よわい': VocabUsage('わたし は さけ に よわい です', 'watashi wa sake ni yowai desu', 'Saya tidak kuat minum alkohol.', 'I can\'t handle alcohol well.', 'Kata sifat い. Pola: [hal] に よわい = lemah terhadap/tidak tahan. Lawan: つよい.', 'い-adjective. Pattern: [thing] に よわい = weak at/against. Opposite: つよい.'),
  'ふとい': VocabUsage('この ペン は ふとい です', 'kono pen wa futoi desu', 'Pulpen ini tebal (batangnya).', 'This pen is thick.', 'Kata sifat い. Untuk benda panjang/garis (batang, kaki). Bandingkan あつい untuk benda pipih.', 'い-adjective. For long things/lines. Compare あつい for flat things.'),
  'ほそい': VocabUsage('かのじょ は あし が ほそい です', 'kanojo wa ashi ga hosoi desu', 'Kakinya ramping.', 'She has slender legs.', 'Kata sifat い. Untuk benda panjang/garis/jalan. Lawan: ふとい. Bandingkan うすい untuk benda pipih.', 'い-adjective. For long things/lines/roads. Opposite: ふとい. Compare うすい for flat things.'),
  'まるい': VocabUsage('まるい テーブル を かいました', 'marui teeburu o kaimashita', 'Saya membeli meja bundar.', 'I bought a round table.', 'Kata sifat い. Negatif: まるくない. Bentuk benda: まるい かお, まるい つき.', 'い-adjective. Negative: まるくない. Shapes: まるい かお, まるい つき.'),
  'わかい': VocabUsage('あの せんせい は わかい です', 'ano sensei wa wakai desu', 'Guru itu masih muda.', 'That teacher is young.', 'Kata sifat い. Untuk usia orang/hewan, bukan benda (benda baru: あたらしい).', 'い-adjective. For age of people/animals, not things (new things: あたらしい).'),
  'ほしい': VocabUsage('あたらしい くるま が ほしい です', 'atarashii kuruma ga hoshii desu', 'Saya ingin mobil baru.', 'I want a new car.', 'Kata sifat い. Pola: [benda] が ほしい. Untuk keinginan sendiri; untuk orang ketiga: ほしがっています.', 'い-adjective. Pattern: [thing] が ほしい. For one\'s own wish; third person: ほしがっています.'),
  'かわいい': VocabUsage('この ねこ は かわいい です ね', 'kono neko wa kawaii desu ne', 'Kucing ini imut, ya.', 'This cat is cute, isn\'t it?', 'Kata sifat い. Negatif: かわいくない. Untuk anak, hewan, barang, gaya.', 'い-adjective. Negative: かわいくない. For kids, animals, items, styles.'),
  'しずか': VocabUsage('としょかん は しずか です', 'toshokan wa shizuka desu', 'Perpustakaan itu tenang.', 'The library is quiet.', 'Kata sifat な. Di depan benda: しずか な へや. Negatif: しずか じゃ ありません. Lawan: にぎやか.', 'な-adjective. Before nouns: しずか な へや. Negative: しずか じゃ ありません. Opposite: にぎやか.'),
  'にぎやか': VocabUsage('よる の まち は にぎやか です', 'yoru no machi wa nigiyaka desu', 'Kota di malam hari ramai.', 'The town is lively at night.', 'Kata sifat な. Di depan benda: にぎやか な まち. Nuansa positif (meriah). Lawan: しずか.', 'な-adjective. Before nouns: にぎやか な まち. Positive nuance (lively). Opposite: しずか.'),
  'げんき': VocabUsage('そふ は いつも げんき です', 'sofu wa itsumo genki desu', 'Kakek saya selalu sehat.', 'My grandfather is always healthy.', 'Kata sifat な. Di depan benda: げんき な こども. Salam: おげんき です か.', 'な-adjective. Before nouns: げんき な こども. Greeting: おげんき です か.'),
  'きれい': VocabUsage('この はな は きれい です', 'kono hana wa kirei desu', 'Bunga ini cantik.', 'This flower is pretty.', 'Kata sifat な (walau berakhiran い). Di depan benda: きれい な へや. Negatif: きれい じゃ ありません.', 'な-adjective despite ending in い. Before nouns: きれい な へや. Negative: きれい じゃ ありません.'),
  'すき': VocabUsage('わたし は ねこ が すき です', 'watashi wa neko ga suki desu', 'Saya suka kucing.', 'I like cats.', 'Kata sifat な. Pola: [hal] が すき です (pakai が). Di depan benda: すき な たべもの.', 'な-adjective. Pattern: [thing] が すき です (uses が). Before nouns: すき な たべもの.'),
  'だいすき': VocabUsage('わたし は すし が だいすき です', 'watashi wa sushi ga daisuki desu', 'Saya sangat suka sushi.', 'I love sushi.', 'Kata sifat な. Pola: [hal] が だいすき です. Lebih kuat dari すき.', 'な-adjective. Pattern: [thing] が だいすき です. Stronger than すき.'),
  'きらい': VocabUsage('おとうと は やさい が きらい です', 'otouto wa yasai ga kirai desu', 'Adik laki-laki saya tidak suka sayur.', 'My younger brother dislikes vegetables.', 'Kata sifat な (walau berakhiran い). Pola: [hal] が きらい です. Cukup kuat; lebih halus: あまり すき じゃ ない.', 'な-adjective despite い ending. Pattern: [thing] が きらい です. Strong; softer: あまり すき じゃ ない.'),
  'じょうず': VocabUsage('マリア さん は りょうり が じょうず です', 'maria san wa ryouri ga jouzu desu', 'Maria pandai memasak.', 'Maria is good at cooking.', 'Kata sifat な. Pola: [orang] は [hal] が じょうず. Untuk memuji orang lain, bukan diri sendiri (pakai とくい).', 'な-adjective. Pattern: [person] は [skill] が じょうず. Praise others; for yourself use とくい.'),
  'へた': VocabUsage('わたし は うた が へた です', 'watashi wa uta ga heta desu', 'Saya tidak pandai bernyanyi.', 'I am bad at singing.', 'Kata sifat な. Pola: [hal] が へた です. Lawan: じょうず.', 'な-adjective. Pattern: [skill] が へた です. Opposite: じょうず.'),
  'ひま': VocabUsage('あした は ひま です か', 'ashita wa hima desu ka', 'Besok kamu senggang?', 'Are you free tomorrow?', 'Kata sifat な/kata benda. Di depan benda: ひま な とき. Untuk ajakan, lebih sopan: ごつごう は どう です か.', 'な-adjective/noun. Before nouns: ひま な とき. Politer invite: ごつごう は どう です か.'),
  'いや': VocabUsage('あめ の ひ は いや です', 'ame no hi wa iya desu', 'Saya tidak suka hari hujan.', 'I hate rainy days.', 'Kata sifat な. Di depan benda: いや な におい. Diucapkan sendiri 「いや!」 = \'Tidak mau!\'.', 'な-adjective. Before nouns: いや な におい. Alone, 「いや!」 means \'No way!\'.'),
  'いろいろ': VocabUsage('デパート に いろいろ な もの が あります', 'depaato ni iroiro na mono ga arimasu', 'Di department store ada bermacam-macam barang.', 'There are all kinds of things at the department store.', 'Kata sifat な / adverbia. Pola: いろいろ な [benda]; いろいろ ありがとう (terima kasih untuk semuanya).', 'な-adjective/adverb. Pattern: いろいろ な [noun]; いろいろ ありがとう (thanks for everything).'),
  'おなじ': VocabUsage('わたし と あね は おなじ がっこう です', 'watashi to ane wa onaji gakkou desu', 'Saya dan kakak perempuan saya satu sekolah.', 'My sister and I go to the same school.', 'Langsung di depan benda TANPA な: おなじ [benda]. Pola: A は B と おなじ です.', 'Goes directly before nouns WITHOUT な: おなじ [noun]. Pattern: A は B と おなじ です.'),
  'だいじょうぶ': VocabUsage('あし は もう だいじょうぶ です', 'ashi wa mou daijoubu desu', 'Kaki saya sudah tidak apa-apa.', 'My leg is fine now.', 'Kata sifat な. Tanya: だいじょうぶ です か. Juga untuk menolak halus: だいじょうぶ です (tidak usah).', 'な-adjective. Ask: だいじょうぶ です か. Also a soft refusal: だいじょうぶ です (no thanks).'),
  'たいへん': VocabUsage('しごと が たいへん です', 'shigoto ga taihen desu', 'Pekerjaannya berat.', 'Work is tough.', 'Kata sifat な / adverbia. Ungkapan simpati: たいへん です ね. Sebagai adverbia = \'sangat\' (formal).', 'な-adjective/adverb. Sympathy: たいへん です ね. As adverb = \'very\' (formal).'),
  'りっぱ': VocabUsage('りっぱ な たてもの です ね', 'rippa na tatemono desu ne', 'Gedung yang megah, ya.', 'What a splendid building.', 'Kata sifat な. Di depan benda: りっぱ な [benda]. Untuk bangunan megah & orang terpuji.', 'な-adjective. Before nouns: りっぱ な [noun]. For grand buildings and admirable people.'),
  'けっこう': VocabUsage('おみず は けっこう です', 'omizu wa kekkou desu', 'Air putihnya tidak usah, terima kasih.', 'No water for me, thank you.', 'Kata sifat な/adverbia. 「けっこう です」 sering berarti menolak halus. Adverbia: \'cukup\' (けっこう おいしい).', 'な-adjective/adverb. 「けっこう です」 often politely declines. Adverb: \'quite\' (けっこう おいしい).'),
  'だめ': VocabUsage('ここ で しゃしん を とって は だめ です', 'koko de shashin o totte wa dame desu', 'Tidak boleh memotret di sini.', 'You can\'t take photos here.', 'Kata sifat な. Pola larangan: ~て は だめ です. Juga \'tidak bagus/gagal\'.', 'な-adjective. Prohibition: ~て は だめ です. Also \'no good/useless\'.'),
  'あまり': VocabUsage('この みせ は あまり たかく ない です', 'kono mise wa amari takaku nai desu', 'Toko ini tidak begitu mahal.', 'This shop is not very expensive.', 'Adverbia, selalu dengan bentuk negatif: あまり ~ない / ~ません.', 'Adverb, always with a negative: あまり ~ない / ~ません.'),
  'いちばん': VocabUsage('くだもの の なか で りんご が いちばん すき です', 'kudamono no naka de ringo ga ichiban suki desu', 'Di antara buah-buahan, saya paling suka apel.', 'Of all fruits, I like apples best.', 'Adverbia/kata benda. Pola superlatif: [grup] の なか で [X] が いちばん ~.', 'Adverb/noun. Superlative: [group] の なか で [X] が いちばん ~.'),
  'いっしょに': VocabUsage('いっしょに ひるごはん を たべましょう', 'isshoni hirugohan o tabemashou', 'Ayo makan siang bersama.', 'Let\'s have lunch together.', 'Adverbia. Pola: [orang] と いっしょに ~. Sering dengan ajakan ~ましょう / ~ませんか.', 'Adverb. Pattern: [person] と いっしょに ~. Often with ~ましょう / ~ませんか.'),
  'すぐ': VocabUsage('いま すぐ いきます', 'ima sugu ikimasu', 'Saya segera ke sana sekarang.', 'I\'ll go right away.', 'Adverbia. Waktu: すぐ (segera); jarak: すぐ ちかく (dekat sekali). Bisa すぐに.', 'Adverb. Time: すぐ (right away); distance: すぐ ちかく (very close). Also すぐに.'),
  'ゆっくり': VocabUsage('もう すこし ゆっくり はなして ください', 'mou sukoshi yukkuri hanashite kudasai', 'Tolong bicara sedikit lebih pelan.', 'Please speak a little more slowly.', 'Adverbia. Juga \'santai\': ゆっくり やすんで ください (istirahatlah dengan santai).', 'Adverb. Also \'take it easy\': ゆっくり やすんで ください.'),
  'まっすぐ': VocabUsage('この みち を まっすぐ いって ください', 'kono michi o massugu itte kudasai', 'Tolong jalan lurus di jalan ini.', 'Please go straight along this road.', 'Adverbia/kata sifat な. Umum untuk petunjuk arah: まっすぐ いく. Juga \'langsung\': まっすぐ かえる.', 'Adverb/な-adjective. Common in directions: まっすぐ いく. Also \'directly\': まっすぐ かえる.'),
  'もっと': VocabUsage('もっと たべて ください', 'motto tabete kudasai', 'Silakan makan lebih banyak.', 'Please eat more.', 'Adverbia. Di depan kata kerja/sifat: もっと おおきい (lebih besar). Bandingan formal: より.', 'Adverb. Before verbs/adjectives: もっと おおきい (bigger). Formal comparison: より.'),
  'また': VocabUsage('また あした きます', 'mata ashita kimasu', 'Saya datang lagi besok.', 'I\'ll come again tomorrow.', 'Adverbia. \'Lagi\' untuk pengulangan; salam: また あした / じゃあ また.', 'Adverb. \'Again\' for repetition; farewells: また あした / じゃあ また.'),
  'たぶん': VocabUsage('あした は たぶん あめ でしょう', 'ashita wa tabun ame deshou', 'Besok mungkin hujan.', 'It will probably rain tomorrow.', 'Adverbia. Sering berpasangan dengan ~でしょう / ~と おもいます.', 'Adverb. Often paired with ~でしょう / ~と おもいます.'),
  'だんだん': VocabUsage('だんだん さむく なりました', 'dandan samuku narimashita', 'Lama-lama menjadi dingin.', 'It gradually got colder.', 'Adverbia. Sering dengan perubahan: だんだん ~く/に なる.', 'Adverb. Often with change: だんだん ~く/に なる.'),
  'ちょうど': VocabUsage('いま ちょうど くじ です', 'ima choudo kuji desu', 'Sekarang tepat pukul sembilan.', 'It is exactly nine o\'clock now.', 'Adverbia. Untuk waktu/jumlah tepat: ちょうど せんえん. Juga \'pas sekali\' (ちょうど いい).', 'Adverb. Exact time/amount: ちょうど せんえん. Also \'just right\' (ちょうど いい).'),
  'はじめて': VocabUsage('はじめて にほん に きました', 'hajimete nihon ni kimashita', 'Saya datang ke Jepang untuk pertama kali.', 'I came to Japan for the first time.', 'Adverbia. Biasanya dengan bentuk lampau. Beda dengan はじめに (pertama-tama, urutan).', 'Adverb. Usually with past tense. Differs from はじめに (first, in order).'),
  'ほんとう': VocabUsage('それ は ほんとう です か', 'sore wa hontou desu ka', 'Apakah itu benar?', 'Is that true?', 'Kata benda/kata sifat な. ほんとう です か = \'Sungguh?\'. Di depan benda: ほんとう の [benda].', 'Noun/な-adjective. ほんとう です か = \'Really?\'. Before nouns: ほんとう の [noun].'),
  'ぜんぶ': VocabUsage('ケーキ を ぜんぶ たべました', 'keeki o zenbu tabemashita', 'Saya makan semua kuenya.', 'I ate all of the cake.', 'Kata benda/adverbia. Pola: [benda] を ぜんぶ ~; ぜんぶ で いくら です か (total berapa).', 'Noun/adverb. Pattern: [thing] を ぜんぶ ~; ぜんぶ で いくら です か (how much in total).'),
  'ほんとうに': VocabUsage('ほんとうに ありがとう ございます', 'hontouni arigatou gozaimasu', 'Sungguh terima kasih banyak.', 'Thank you so much.', 'Adverbia dari ほんとう. Menguatkan perasaan/sifat: ほんとうに おいしい.', 'Adverb form of ほんとう. Intensifies: ほんとうに おいしい.'),
  'なん': VocabUsage('これ は なん です か', 'kore wa nan desu ka', 'Ini apa?', 'What is this?', 'Bentuk なに sebelum で/です/の atau penghitung: なん です か, なんじ, なんにん.', 'Form of なに before で/です/の or counters: なん です か, なんじ, なんにん.'),
  'どなた': VocabUsage('あの かた は どなた です か', 'ano kata wa donata desu ka', 'Beliau itu siapa?', 'Who is that person?', 'Kata tanya sopan untuk だれ. Cocok dengan かた (orang, sopan).', 'Polite form of だれ. Pairs with かた (polite \'person\').'),
  'どれ': VocabUsage('あなた の かばん は どれ です か', 'anata no kaban wa dore desu ka', 'Tas Anda yang mana?', 'Which one is your bag?', 'Kata tanya, berdiri sendiri (tanpa kata benda). Untuk 3+ pilihan; 2 pilihan: どちら.', 'Question word, stands alone. For 3+ options; for two use どちら.'),
  'どうして': VocabUsage('どうして きのう やすみました か', 'doushite kinou yasumimashita ka', 'Kenapa kemarin kamu absen?', 'Why were you absent yesterday?', 'Kata tanya alasan. Jawaban biasanya ~から です. Lebih formal: なぜ.', 'Asks for reasons. Answer usually ~から です. More formal: なぜ.'),
  'いかが': VocabUsage('おちゃ は いかが です か', 'ocha wa ikaga desu ka', 'Bagaimana kalau teh?', 'Would you like some tea?', 'Versi sopan dari どう. Untuk menawarkan: [benda] は いかが です か.', 'Polite form of どう. For offers: [thing] は いかが です か.'),
  'だれか': VocabUsage('だれか きて ください', 'dareka kite kudasai', 'Tolong seseorang datang ke sini.', 'Somebody, please come.', 'Kata ganti tak tentu. Partikel が/を sering dihilangkan. Negatif pakai だれも ~ない.', 'Indefinite pronoun. が/を often dropped. Negative uses だれも ~ない.'),
  'なにか': VocabUsage('なにか のみます か', 'nanika nomimasu ka', 'Mau minum sesuatu?', 'Would you like something to drink?', 'Kata ganti tak tentu. Partikel が/を sering dihilangkan. Negatif: なにも ~ない.', 'Indefinite pronoun. が/を often dropped. Negative: なにも ~ない.'),
  'ここ': VocabUsage('ここ は わたし の へや です', 'koko wa watashi no heya desu', 'Ini kamar saya.', 'This is my room.', 'Kata tunjuk tempat dekat pembicara. Pola: ここ に/で ~. Seri: ここ・そこ・あそこ・どこ.', 'Place word near the speaker. Pattern: ここ に/で ~. Series: ここ・そこ・あそこ・どこ.'),
  'そこ': VocabUsage('そこ に かばん を おいて ください', 'soko ni kaban o oite kudasai', 'Tolong taruh tas di situ.', 'Please put your bag there.', 'Kata tunjuk tempat dekat lawan bicara. Pola: そこ に/で ~.', 'Place word near the listener. Pattern: そこ に/で ~.'),
  'あそこ': VocabUsage('トイレ は あそこ です', 'toire wa asoko desu', 'Toiletnya di sana.', 'The toilet is over there.', 'Kata tunjuk tempat jauh dari keduanya. Pola: [benda] は あそこ です.', 'Place word far from both. Pattern: [thing] は あそこ です.'),
  'こちら': VocabUsage('こちら は やまだ さん です', 'kochira wa yamada san desu', 'Ini Bapak Yamada.', 'This is Mr. Yamada.', 'Versi sopan ここ/これ. Juga untuk memperkenalkan orang: こちら は ~ です.', 'Polite form of ここ/これ. Also for introducing people: こちら は ~ です.'),
  'そちら': VocabUsage('そちら は いかが です か', 'sochira wa ikaga desu ka', 'Bagaimana keadaan di tempat Anda?', 'How are things on your side?', 'Versi sopan そこ/それ. Juga merujuk pihak lawan bicara (Anda/tempat Anda).', 'Polite form of そこ/それ. Also refers to the listener\'s side.'),
  'あちら': VocabUsage('エレベーター は あちら です', 'erebeetaa wa achira desu', 'Liftnya di sebelah sana.', 'The elevator is that way.', 'Versi sopan あそこ/あれ. Umum dipakai staf toko/hotel.', 'Polite form of あそこ/あれ. Common among shop/hotel staff.'),
  'どちら': VocabUsage('おくに は どちら です か', 'okuni wa dochira desu ka', 'Anda berasal dari negara mana?', 'Which country are you from?', 'Versi sopan どこ/どれ. Juga untuk memilih dari dua: A と B と どちら が ~.', 'Polite form of どこ/どれ. Also for two choices: A と B と どちら が ~.'),
  'こっち': VocabUsage('こっち に きて', 'kocchi ni kite', 'Ke sini.', 'Come over here.', 'Versi santai こちら. Dipakai dengan teman/keluarga.', 'Casual form of こちら. Used with friends/family.'),
  'そっち': VocabUsage('そっち は どう', 'socchi wa dou', 'Di situ bagaimana?', 'How are things there?', 'Versi santai そちら. Juga \'kamu/pihakmu\' dalam obrolan santai.', 'Casual form of そちら. Also \'you/your side\' in casual talk.'),
  'あっち': VocabUsage('あっち に コンビニ が ある よ', 'acchi ni konbini ga aru yo', 'Di sana ada minimarket, lho.', 'There\'s a convenience store over there.', 'Versi santai あちら. Dipakai dengan teman/keluarga.', 'Casual form of あちら. Used with friends/family.'),
  'どっち': VocabUsage('いぬ と ねこ と どっち が すき', 'inu to neko to docchi ga suki', 'Kamu lebih suka anjing atau kucing?', 'Which do you like better, dogs or cats?', 'Versi santai どちら. Pola pilih dua: A と B と どっち が ~.', 'Casual form of どちら. Two-choice pattern: A と B と どっち が ~.'),
  'この': VocabUsage('この ほん は おもしろい です', 'kono hon wa omoshiroi desu', 'Buku ini menarik.', 'This book is interesting.', 'Selalu diikuti kata benda: この [benda]. Berdiri sendiri pakai これ.', 'Always followed by a noun: この [noun]. Standalone form: これ.'),
  'その': VocabUsage('その かさ は だれ の です か', 'sono kasa wa dare no desu ka', 'Payung itu milik siapa?', 'Whose umbrella is that?', 'Selalu diikuti kata benda (dekat lawan bicara). Berdiri sendiri: それ.', 'Always followed by a noun (near listener). Standalone: それ.'),
  'あの': VocabUsage('あの ひと は だれ です か', 'ano hito wa dare desu ka', 'Orang itu siapa?', 'Who is that person over there?', 'Selalu diikuti kata benda (jauh dari keduanya). Berdiri sendiri: あれ.', 'Always followed by a noun (far from both). Standalone: あれ.'),
  'どの': VocabUsage('どの バス に のります か', 'dono basu ni norimasu ka', 'Naik bus yang mana?', 'Which bus do you take?', 'Kata tanya + kata benda: どの [benda]. Berdiri sendiri: どれ.', 'Question word + noun: どの [noun]. Standalone: どれ.'),
  'こんな': VocabUsage('こんな かばん が ほしい です', 'konna kaban ga hoshii desu', 'Saya ingin tas seperti ini.', 'I want a bag like this.', 'Diikuti kata benda: こんな [benda] (tanpa な tambahan). Nuansa kadang kurang sopan.', 'Followed by a noun: こんな [noun] (no extra な). Can sound slightly dismissive.'),
  'そんな': VocabUsage('そんな こと は ありません', 'sonna koto wa arimasen', 'Tidak begitu, kok.', 'That\'s not true.', 'Diikuti kata benda: そんな [benda]. Ungkapan rendah hati: そんな こと ない.', 'Followed by a noun: そんな [noun]. Modest reply: そんな こと ない.'),
  'あんな': VocabUsage('あんな いえ に すみたい です', 'anna ie ni sumitai desu', 'Saya ingin tinggal di rumah seperti itu.', 'I want to live in a house like that.', 'Diikuti kata benda: あんな [benda], merujuk hal jauh/yang sama-sama diketahui.', 'Followed by a noun: あんな [noun], for distant or shared-known things.'),
  'どんな': VocabUsage('どんな おんがく が すき です か', 'donna ongaku ga suki desu ka', 'Kamu suka musik seperti apa?', 'What kind of music do you like?', 'Kata tanya + kata benda: どんな [benda]. Menanyakan jenis/sifat.', 'Question word + noun: どんな [noun]. Asks about type/quality.'),
  'こう': VocabUsage('この じ は こう かきます', 'kono ji wa kou kakimasu', 'Huruf ini ditulis begini.', 'This character is written like this.', 'Adverbia tunjuk \'begini\', biasa sambil memperagakan. Seri: こう・そう・ああ・どう.', 'Demonstrative adverb, often while demonstrating. Series: こう・そう・ああ・どう.'),
  'そう': VocabUsage('わたし も そう おもいます', 'watashi mo sou omoimasu', 'Saya juga berpikir begitu.', 'I think so too.', 'Adverbia tunjuk \'begitu\'. Umum: そう です (benar), そう おもいます.', 'Demonstrative adverb. Common: そう です (that\'s right), そう おもいます.'),
  'ああ': VocabUsage('ああ いう ひと が すき です', 'aa iu hito ga suki desu', 'Saya suka orang seperti itu.', 'I like people like that.', 'Adverbia tunjuk \'seperti itu (jauh)\': ああ いう [benda]. Juga seruan \'ah\'.', 'Demonstrative adverb: ああ いう [noun]. Also the interjection \'ah\'.'),
  'そして': VocabUsage('あさ ごはん を たべます そして がっこう へ いきます', 'asa gohan o tabemasu soshite gakkou e ikimasu', 'Saya sarapan, lalu pergi ke sekolah.', 'I eat breakfast, and then go to school.', 'Kata sambung di awal kalimat/klausa. Agak formal; dalam percakapan sering それから.', 'Conjunction starting a sentence/clause. A bit formal; speech often uses それから.'),
  'それから': VocabUsage('えいが を みました それから しょくじ を しました', 'eiga o mimashita sorekara shokuji o shimashita', 'Saya menonton film. Setelah itu kami makan.', 'We watched a movie. After that we had dinner.', 'Kata sambung urutan waktu \'setelah itu\'. Juga \'lalu, selain itu\' saat menambah.', 'Conjunction for sequence \'after that\'. Also \'and also\' when adding items.'),
  'しかし': VocabUsage('この へや は ひろい です しかし たかい です', 'kono heya wa hiroi desu shikashi takai desu', 'Kamar ini luas. Akan tetapi, mahal.', 'This room is spacious. However, it is expensive.', 'Kata sambung pertentangan di awal kalimat; nuansa formal/tulisan. Lisan: でも.', 'Contrastive conjunction at sentence start; formal/written. Spoken: でも.'),
  'でも': VocabUsage('にほんご は むずかしい です でも おもしろい です', 'nihongo wa muzukashii desu demo omoshiroi desu', 'Bahasa Jepang sulit. Tapi menarik.', 'Japanese is difficult. But it is interesting.', 'Kata sambung \'tapi\' di awal kalimat, umum dalam percakapan. Beda dengan partikel ~でも (~pun).', 'Conjunction \'but\' at sentence start, common in speech. Not the particle ~でも (even).'),
  'それでは': VocabUsage('それでは じゅぎょう を はじめましょう', 'soredewa jugyou o hajimemashou', 'Kalau begitu, mari kita mulai pelajarannya.', 'Well then, let\'s begin the lesson.', 'Kata sambung untuk memulai/menutup topik; formal. Versi santai: じゃあ, では.', 'Conjunction to start/close a topic; formal. Casual: じゃあ, では.'),
  'じゃあ': VocabUsage('じゃあ また あした', 'jaa mata ashita', 'Kalau begitu, sampai besok.', 'Well then, see you tomorrow.', 'Versi santai それでは. Sering untuk berpamitan atau mengambil keputusan: じゃあ、これ に します.', 'Casual form of それでは. Used in goodbyes or decisions: じゃあ、これ に します.'),
  'おはようございます': VocabUsage('たなか せんせい おはようございます', 'tanaka sensei ohayougozaimasu', 'Selamat pagi, Pak Tanaka.', 'Good morning, Mr. Tanaka.', 'Salam pagi sopan (sampai ±jam 10). Ke teman: おはよう.', 'Polite morning greeting (until about 10 a.m.). To friends: おはよう.'),
  'ありがとうございます': VocabUsage('てつだって くれて ありがとうございます', 'tetsudatte kurete arigatougozaimasu', 'Terima kasih sudah membantu.', 'Thank you for helping me.', 'Ungkapan terima kasih sopan. Pola: ~て くれて ありがとうございます. Untuk hal lampau: ありがとうございました.', 'Polite thanks. Pattern: ~て くれて ありがとうございます. For finished acts: ありがとうございました.'),
  'どうも': VocabUsage('どうも ありがとう ございます', 'doumo arigatou gozaimasu', 'Terima kasih banyak.', 'Thank you very much.', 'Adverbia penguat untuk ありがとう/すみません. Diucapkan sendiri = \'makasih\' ringan.', 'Intensifier for ありがとう/すみません. Alone it is a light \'thanks\'.'),
  'どういたしまして': VocabUsage('「ありがとう」 「いいえ どういたしまして」', '\'arigatou\' \'iie douitashimashite\'', '\'Terima kasih.\' \'Sama-sama.\'', '\'Thank you.\' \'You\'re welcome.\'', 'Jawaban untuk ありがとう. Dalam praktik orang Jepang sering cukup bilang いいえ.', 'Reply to ありがとう. In practice Japanese often just say いいえ.'),
  'ごめんなさい': VocabUsage('おそく なって ごめんなさい', 'osoku natte gomennasai', 'Maaf saya terlambat.', 'Sorry I\'m late.', 'Permintaan maaf ke teman/keluarga. Pola: ~て ごめんなさい. Formal: もうしわけ ありません.', 'Apology to friends/family. Pattern: ~て ごめんなさい. Formal: もうしわけ ありません.'),
  'おやすみなさい': VocabUsage('それでは みなさん おやすみなさい', 'soredewa minasan oyasuminasai', 'Kalau begitu, selamat tidur semuanya.', 'Well then, good night, everyone.', 'Salam sebelum tidur atau berpisah malam hari. Santai: おやすみ.', 'Said before bed or parting at night. Casual: おやすみ.'),
  'いただきます': VocabUsage('みんな で いただきます と いいました', 'minna de itadakimasu to iimashita', 'Kami semua mengucapkan \'itadakimasu\'.', 'We all said \'itadakimasu\'.', 'Diucapkan sebelum makan sebagai syukur. Pasangannya setelah makan: ごちそうさまでした.', 'Said before eating as thanks. After eating: ごちそうさまでした.'),
  'ごちそうさまでした': VocabUsage('おいしかった です ごちそうさまでした', 'oishikatta desu gochisousamadeshita', 'Enak sekali. Terima kasih atas makanannya.', 'It was delicious. Thank you for the meal.', 'Diucapkan setelah makan ke tuan rumah/penjual. Santai: ごちそうさま.', 'Said after eating to the host/cook. Casual: ごちそうさま.'),
  'いってきます': VocabUsage('じゃあ おかあさん いってきます', 'jaa okaasan ittekimasu', 'Bu, saya berangkat ya.', 'Mom, I\'m off.', 'Diucapkan saat keluar rumah (akan kembali). Jawabannya: いってらっしゃい.', 'Said when leaving home (and coming back). Reply: いってらっしゃい.'),
  'いってらっしゃい': VocabUsage('き を つけて いってらっしゃい', 'ki o tsukete itterasshai', 'Hati-hati di jalan ya.', 'Take care, see you later.', 'Jawaban untuk いってきます, diucapkan oleh yang tinggal di rumah.', 'Reply to いってきます, said by the person staying home.'),
  'ただいま': VocabUsage('ただいま おなか が すきました', 'tadaima onaka ga sukimashita', 'Aku pulang! Lapar nih.', 'I\'m home! I\'m hungry.', 'Diucapkan saat tiba di rumah. Jawabannya: おかえりなさい.', 'Said when arriving home. Reply: おかえりなさい.'),
  'おかえりなさい': VocabUsage('おかえりなさい つかれました か', 'okaerinasai tsukaremashita ka', 'Selamat datang kembali. Capek?', 'Welcome home. Are you tired?', 'Jawaban untuk ただいま. Santai: おかえり.', 'Reply to ただいま. Casual: おかえり.'),
  'はじめまして': VocabUsage('はじめまして リナ です', 'hajimemashite rina desu', 'Salam kenal, saya Rina.', 'Nice to meet you, I\'m Rina.', 'Hanya saat pertama bertemu, di awal perkenalan; ditutup dengan どうぞ よろしく.', 'Only at a first meeting, opening a self-intro; close with どうぞ よろしく.'),
  'どうぞよろしく': VocabUsage('ブディ です どうぞよろしく', 'budi desu douzoyoroshiku', 'Saya Budi, mohon bantuannya.', 'I\'m Budi, pleased to meet you.', 'Penutup perkenalan. Lebih sopan: どうぞ よろしく おねがいします.', 'Closes a self-intro. More polite: どうぞ よろしく おねがいします.'),
  'こちらこそ': VocabUsage('こちらこそ よろしく おねがいします', 'kochirakoso yoroshiku onegaishimasu', 'Saya juga, mohon bantuannya.', 'Likewise, I look forward to working with you.', 'Balasan \'saya juga/justru saya\'. Sering menjawab よろしく atau ありがとう.', 'Reply meaning \'the same from my side\'. Often answers よろしく or ありがとう.'),
  'いらっしゃいませ': VocabUsage('いらっしゃいませ なんめいさま です か', 'irasshaimase nanmeisama desu ka', 'Selamat datang. Untuk berapa orang?', 'Welcome. How many people?', 'Diucapkan staf toko/restoran ke pelanggan. Pelanggan tidak perlu membalas.', 'Said by shop/restaurant staff to customers. Customers needn\'t reply.'),
  'おねがいします': VocabUsage('コーヒー を おねがいします', 'koohii o onegaishimasu', 'Kopi, tolong.', 'Coffee, please.', 'Pola: [benda/hal] を おねがいします untuk meminta/memesan dengan sopan.', 'Pattern: [thing] を おねがいします to request or order politely.'),
  'しつれいします': VocabUsage('しつれいします せんせい いらっしゃいます か', 'shitsureishimasu sensei irasshaimasu ka', 'Permisi, apakah Bapak Guru ada?', 'Excuse me, is the teacher in?', 'Diucapkan saat masuk/keluar ruangan atau menutup telepon. Lampau saat pamit: しつれいしました.', 'Said entering/leaving a room or ending a call. Past when leaving: しつれいしました.'),
  'おげんきですか': VocabUsage('おひさしぶり です おげんきですか', 'ohisashiburi desu ogenkidesuka', 'Lama tak jumpa. Apa kabar?', 'Long time no see. How are you?', 'Dipakai setelah lama tidak bertemu, bukan salam harian. Jawab: はい、げんき です.', 'Used after a long absence, not as a daily greeting. Reply: はい、げんき です.'),
  'もしもし': VocabUsage('もしもし たなか です', 'moshimoshi tanaka desu', 'Halo, ini Tanaka.', 'Hello, this is Tanaka.', 'Khusus pembuka di telepon. Bukan salam tatap muka.', 'Only for opening phone calls, not face-to-face greetings.'),
  'どうぞ': VocabUsage('どうぞ はいって ください', 'douzo haitte kudasai', 'Silakan masuk.', 'Please come in.', 'Untuk mempersilakan/menawarkan. Sering bersama ~て ください. Saat memberi barang: どうぞ.', 'Used to offer or invite. Often with ~て ください. When handing something: どうぞ.'),
  'ください': VocabUsage('みず を ください', 'mizu o kudasai', 'Tolong beri saya air.', 'Water, please.', 'Pola: [benda] を ください (minta barang); [kata kerja ~て] ください (minta tolong).', 'Patterns: [thing] を ください (ask for items); [verb ~て] ください (request actions).'),
  'ええ': VocabUsage('ええ そう です', 'ee sou desu', 'Ya, betul.', 'Yes, that\'s right.', 'Jawaban \'ya\' yang lebih lembut/santai dari はい. Kurang cocok untuk atasan dalam situasi formal.', 'Softer, casual \'yes\' than はい. Less suitable in formal settings with superiors.'),
  'あのう': VocabUsage('あのう すみません えき は どこ です か', 'anou sumimasen eki wa doko desu ka', 'Anu, permisi, stasiun di mana?', 'Um, excuse me, where is the station?', 'Pembuka ragu-ragu untuk menarik perhatian dengan sopan, sering sebelum すみません.', 'Hesitant opener to get attention politely, often before すみません.'),
  'さあ': VocabUsage('さあ いっしょに いきましょう', 'saa isshoni ikimashou', 'Ayo, kita berangkat bersama.', 'Come on, let\'s go together.', 'Seruan ajakan, sering + ~ましょう. Juga \'entahlah\' saat tidak tahu: さあ、わかりません.', 'Urging interjection, often + ~ましょう. Also \'hmm, no idea\': さあ、わかりません.'),
  'さんびゃく': VocabUsage('この ノート は さんびゃく えん です', 'kono nooto wa sanbyaku en desu', 'Buku catatan ini 300 yen.', 'This notebook is 300 yen.', 'Angka 300; ひゃく berubah jadi びゃく. Juga 600 (ろっぴゃく) & 800 (はっぴゃく) berubah.', 'Number 300; ひゃく becomes びゃく. Also changes in 600 (ろっぴゃく) and 800 (はっぴゃく).'),
  'ろっぴゃく': VocabUsage('パン は ろっぴゃく えん でした', 'pan wa roppyaku en deshita', 'Rotinya 600 yen.', 'The bread was 600 yen.', 'Angka 600; ろく + ひゃく → ろっぴゃく. Sering untuk harga: [angka] えん.', 'Number 600; ろく + ひゃく → ろっぴゃく. Common with prices: [number] えん.'),
  'はっぴゃく': VocabUsage('はっぴゃく メートル あるきました', 'happyaku meetoru arukimashita', 'Saya berjalan 800 meter.', 'I walked 800 meters.', 'Angka 800; はち + ひゃく → はっぴゃく.', 'Number 800; はち + ひゃく → はっぴゃく.'),
  'さんぜん': VocabUsage('この シャツ は さんぜん えん です', 'kono shatsu wa sanzen en desu', 'Kemeja ini 3.000 yen.', 'This shirt is 3,000 yen.', 'Angka 3.000; せん berubah jadi ぜん. Juga 8.000 jadi はっせん.', 'Number 3,000; せん becomes ぜん. Also 8,000 becomes はっせん.'),
  'はっせん': VocabUsage('ホテル は いっぱく はっせん えん です', 'hoteru wa ippaku hassen en desu', 'Hotelnya 8.000 yen per malam.', 'The hotel is 8,000 yen per night.', 'Angka 8.000; はち + せん → はっせん.', 'Number 8,000; はち + せん → はっせん.'),
  'じゅうよっか': VocabUsage('じゅうよっか は わたし の たんじょうび です', 'juuyokka wa watashi no tanjoubi desu', 'Tanggal 14 adalah hari ulang tahun saya.', 'The 14th is my birthday.', 'Tanggal 14 (bacaan khusus, bukan じゅうよんにち). Pola: [bulan] [tanggal] に.', 'Date 14th (irregular, not じゅうよんにち). Pattern: [month] [date] に.'),
  'さんぷん': VocabUsage('えき まで あるいて さんぷん です', 'eki made aruite sanpun desu', 'Ke stasiun 3 menit jalan kaki.', 'It\'s a three-minute walk to the station.', '3 menit; ふん berubah jadi ぷん. Pola: [tempat] まで [waktu] です/かかります.', '3 minutes; ふん becomes ぷん. Pattern: [place] まで [time] です/かかります.'),
  'よんぷん': VocabUsage('いま くじ よんぷん です', 'ima kuji yonpun desu', 'Sekarang pukul sembilan lewat empat menit.', 'It is 9:04 now.', '4 menit; よん + ふん → よんぷん. Untuk jam: [jam] じ [menit] ふん/ぷん.', '4 minutes; よん + ふん → よんぷん. Time: [hour] じ [minute] ふん/ぷん.'),
  'ろっぷん': VocabUsage('バス は ろっぷん ご に きます', 'basu wa roppun go ni kimasu', 'Bus datang enam menit lagi.', 'The bus comes in six minutes.', '6 menit; ろく + ふん → ろっぷん. Pola: [waktu] ご = \'... lagi/kemudian\'.', '6 minutes; ろく + ふん → ろっぷん. Pattern: [time] ご = \'in/after ...\'.'),
  'はっぷん': VocabUsage('たまご を はっぷん ゆでます', 'tamago o happun yudemasu', 'Saya merebus telur selama delapan menit.', 'I boil the eggs for eight minutes.', '8 menit; はち + ふん → はっぷん (juga はちふん).', '8 minutes; はち + ふん → はっぷん (also はちふん).'),
  'さんぼん': VocabUsage('ペン を さんぼん かいました', 'pen o sanbon kaimashita', 'Saya membeli tiga batang pulpen.', 'I bought three pens.', 'Penghitung ほん untuk benda panjang (pulpen, botol); 3 → さんぼん. Pola: [benda] を さんぼん ~.', 'Counter ほん for long items (pens, bottles); 3 → さんぼん. Pattern: [thing] を さんぼん ~.'),
  'ろっぽん': VocabUsage('ビール を ろっぽん ください', 'biiru o roppon kudasai', 'Tolong beri saya enam botol bir.', 'Six bottles of beer, please.', 'Penghitung ほん; 6 → ろっぽん. Untuk botol, payung, pohon, dll.', 'Counter ほん; 6 → ろっぽん. For bottles, umbrellas, trees, etc.'),
  'はっぽん': VocabUsage('かさ が はっぽん あります', 'kasa ga happon arimasu', 'Ada delapan payung.', 'There are eight umbrellas.', 'Penghitung ほん; 8 → はっぽん. Pola: [benda] が [jumlah] あります.', 'Counter ほん; 8 → はっぽん. Pattern: [thing] が [count] あります.'),
  'さんびき': VocabUsage('いえ に ねこ が さんびき います', 'ie ni neko ga sanbiki imasu', 'Di rumah ada tiga ekor kucing.', 'There are three cats at home.', 'Penghitung ひき untuk hewan kecil; 3 → さんびき. Pakai います untuk makhluk hidup.', 'Counter ひき for small animals; 3 → さんびき. Use います for living things.'),
  'ろっぴき': VocabUsage('いけ に さかな が ろっぴき います', 'ike ni sakana ga roppiki imasu', 'Di kolam ada enam ekor ikan.', 'There are six fish in the pond.', 'Penghitung ひき; 6 → ろっぴき. Juga 1 いっぴき, 8 はっぴき, 10 じゅっぴき.', 'Counter ひき; 6 → ろっぴき. Also 1 いっぴき, 8 はっぴき, 10 じゅっぴき.'),
  'さんがい': VocabUsage('くつ うりば は さんがい です', 'kutsu uriba wa sangai desu', 'Bagian sepatu ada di lantai tiga.', 'The shoe department is on the third floor.', 'Penghitung lantai かい; 3 → さんがい (bukan さんかい). Tanya: なんがい.', 'Floor counter かい; 3 → さんがい (not さんかい). Ask: なんがい.'),
  'ぐらい': VocabUsage('まいにち いちじかん ぐらい べんきょうします', 'mainichi ichijikan gurai benkyoushimasu', 'Setiap hari saya belajar kira-kira satu jam.', 'I study for about an hour every day.', 'Akhiran setelah jumlah/durasi: [jumlah] ぐらい. Untuk jam tertentu pakai ごろ (さんじ ごろ).', 'Suffix after amounts/durations: [amount] ぐらい. For clock times use ごろ (さんじ ごろ).'),
  'おとこのひと': VocabUsage('あの おとこのひと は せんせい です', 'ano otokonohito wa sensei desu', 'Pria itu seorang guru.', 'That man is a teacher.', 'Kata benda netral & sopan untuk pria dewasa. Lebih sopan lagi: おとこのかた.', 'Neutral, polite noun for an adult man. More polite: おとこのかた.'),
  'おんなのひと': VocabUsage('おんなのひと が みせ に はいりました', 'onnanohito ga mise ni hairimashita', 'Seorang wanita masuk ke toko.', 'A woman entered the shop.', 'Kata benda netral & sopan untuk wanita dewasa. Lebih sopan: おんなのかた.', 'Neutral, polite noun for an adult woman. More polite: おんなのかた.'),
  'にほんじん': VocabUsage('かれ は にほんじん です', 'kare wa nihonjin desu', 'Dia orang Jepang.', 'He is Japanese.', 'Kata benda: [negara] + じん = orang dari negara itu (インドネシアじん).', 'Noun: [country] + じん = person from that country (インドネシアじん).'),
  'かいしゃいん': VocabUsage('あに は かいしゃいん です', 'ani wa kaishain desu', 'Kakak laki-laki saya karyawan perusahaan.', 'My older brother is a company employee.', 'Kata benda untuk pekerjaan. Pola: [orang] は かいしゃいん です. Akhiran いん = anggota/staf.', 'Noun for occupation. Pattern: [person] は かいしゃいん です. Suffix いん = member/staff.'),
  'こと': VocabUsage('にほん の こと を はなしました', 'nihon no koto o hanashimashita', 'Kami membicarakan tentang Jepang.', 'We talked about Japan.', 'Kata benda abstrak \'hal\'. Pola: [benda] の こと = \'tentang\'; [kata kerja] こと が できる.', 'Abstract noun \'matter\'. Patterns: [noun] の こと = \'about\'; [verb] こと が できる.'),
  'ひるやすみ': VocabUsage('ひるやすみ に こうえん で たべます', 'hiruyasumi ni kouen de tabemasu', 'Saat istirahat siang saya makan di taman.', 'I eat in the park during lunch break.', 'Kata benda waktu. Pola: ひるやすみ に ~ / ひるやすみ は [jam] から です.', 'Time noun. Patterns: ひるやすみ に ~ / ひるやすみ は [time] から です.'),
  'ビール': VocabUsage('よる つめたい ビール を のみます', 'yoru tsumetai biiru o nomimasu', 'Malam hari saya minum bir dingin.', 'I drink cold beer at night.', 'Kata serapan. Pola: ビール を のむ. Hitung botol: いっぽん, にほん.', 'Loanword. Pattern: ビール を のむ. Count bottles: いっぽん, にほん.'),
  'ケーキ': VocabUsage('たんじょうび に ケーキ を たべました', 'tanjoubi ni keeki o tabemashita', 'Saya makan kue di hari ulang tahun.', 'I ate cake on my birthday.', 'Kata serapan untuk kue ala Barat. Pola: ケーキ を たべる/つくる.', 'Loanword for Western-style cake. Pattern: ケーキ を たべる/つくる.'),
  'ピアノ': VocabUsage('まいばん ピアノ を ひきます', 'maiban piano o hikimasu', 'Setiap malam saya bermain piano.', 'I play the piano every evening.', 'Kata serapan. Kata kerja khas: ピアノ を ひく (bukan する).', 'Loanword. Typical verb: ピアノ を ひく (not する).'),
  'テニス': VocabUsage('どようび に テニス を します', 'doyoubi ni tenisu o shimasu', 'Hari Sabtu saya bermain tenis.', 'I play tennis on Saturdays.', 'Kata serapan. Pola olahraga: テニス を する.', 'Loanword. Sports pattern: テニス を する.'),
  'サッカー': VocabUsage('こども たち は サッカー が すき です', 'kodomo tachi wa sakkaa ga suki desu', 'Anak-anak suka sepak bola.', 'The children like soccer.', 'Kata serapan. Pola: サッカー を する (main), サッカー を みる (menonton).', 'Loanword. Patterns: サッカー を する (play), サッカー を みる (watch).'),
  'パソコン': VocabUsage('パソコン で メール を かきます', 'pasokon de meeru o kakimasu', 'Saya menulis email dengan komputer.', 'I write emails on my computer.', 'Kata serapan singkatan \'personal computer\'. Pola alat: パソコン で ~.', 'Loanword short for \'personal computer\'. Tool pattern: パソコン で ~.'),
  'あか': VocabUsage('あか の ペン で かいて ください', 'aka no pen de kaite kudasai', 'Tolong tulis dengan pulpen merah.', 'Please write with a red pen.', 'Kata benda warna; menerangkan dengan の (あか の ペン) atau bentuk sifat あかい.', 'Color noun; modify with の (あか の ペン) or use adjective あかい.'),
  'あお': VocabUsage('しんごう が あお に なりました', 'shingou ga ao ni narimashita', 'Lampu lalu lintas berubah hijau.', 'The traffic light turned green.', 'Kata benda warna \'biru\'; untuk lampu lalu lintas berarti hijau. Bentuk sifat: あおい.', 'Color noun \'blue\'; for traffic lights it means green. Adjective: あおい.'),
  'しろ': VocabUsage('しろ と くろ の ねこ が います', 'shiro to kuro no neko ga imasu', 'Ada kucing putih-hitam.', 'There is a black-and-white cat.', 'Kata benda warna; menerangkan dengan の. Bentuk sifat: しろい.', 'Color noun; modifies with の. Adjective form: しろい.'),
  'くろ': VocabUsage('くろ が いちばん すき な いろ です', 'kuro ga ichiban suki na iro desu', 'Hitam adalah warna yang paling saya suka.', 'Black is my favorite color.', 'Kata benda warna; menerangkan dengan の. Bentuk sifat: くろい.', 'Color noun; modifies with の. Adjective form: くろい.'),
  'きいろ': VocabUsage('きいろ の はな が さいて います', 'kiiro no hana ga saite imasu', 'Bunga kuning sedang mekar.', 'Yellow flowers are blooming.', 'Kata benda warna; menerangkan dengan の. Bentuk sifat: きいろい.', 'Color noun; modifies with の. Adjective form: きいろい.'),
  'ぜんぜん': VocabUsage('わたし は おさけ を ぜんぜん のみません', 'watashi wa osake o zenzen nomimasen', 'Saya sama sekali tidak minum alkohol.', 'I don\'t drink alcohol at all.', 'Adverbia dengan bentuk negatif: ぜんぜん ~ない/~ません. Lebih kuat dari あまり.', 'Adverb with negatives: ぜんぜん ~ない/~ません. Stronger than あまり.'),
  'たいてい': VocabUsage('にちようび は たいてい うち に います', 'nichiyoubi wa taitei uchi ni imasu', 'Hari Minggu saya biasanya di rumah.', 'I am usually at home on Sundays.', 'Adverbia frekuensi (±80%). Urutan: いつも > たいてい > よく > ときどき.', 'Frequency adverb (~80%). Scale: いつも > たいてい > よく > ときどき.'),
