  'せいひん': VocabUsage('この かいしゃ の せいひん は にんき が あります', 'kono kaisha no seihin wa ninki ga arimasu', 'Produk perusahaan ini populer.', 'This company\'s products are popular.', 'Kata benda; barang hasil pabrik. Bandingkan しょうひん (barang yang dijual).', 'Noun; manufactured item. Compare しょうひん (merchandise for sale).'),
  'しょうひん': VocabUsage('あたらしい しょうひん が みせ に ならんで います', 'atarashii shouhin ga mise ni narande imasu', 'Barang dagangan baru dipajang di toko.', 'New goods are lined up in the shop.', 'Kata benda; barang yang dijual di toko. Bandingkan せいひん (hasil produksi).', 'Noun; items sold in a shop. Compare せいひん (manufactured product).'),
