  'しっぱいする': VocabUsage('はじめて の りょうり は しっぱい しました', 'hajimete no ryouri wa shippai shimashita', 'Masakan pertama saya gagal.', 'My first attempt at cooking failed.', 'Kata kerja gol. III. ~ます: しっぱいします. Pola: [X] に しっぱいする. Lawan: せいこうする.', 'Group 3 verb. ~ます: しっぱいします. Pattern: [X] に しっぱいする. Opposite: せいこうする.'),
  'せいこうする': VocabUsage('パーティー は だいせいこう しました', 'paatii wa daiseikou shimashita', 'Pestanya sukses besar.', 'The party was a big success.', 'Kata kerja gol. III. ~ます: せいこうします. Pola: [X] に せいこうする. だいせいこう = sukses besar.', 'Group 3 verb. ~ます: せいこうします. Pattern: [X] に せいこうする. だいせいこう = huge success.'),
