  'わすれもの': VocabUsage('でんしゃ に わすれもの を しました', 'densha ni wasuremono o shimashita', 'Saya meninggalkan barang di kereta.', 'I left something behind on the train.', 'Kata benda. Pola: [tempat] に わすれもの を する. わすれもの は ない です か = ada yang tertinggal?', 'Noun. Pattern: [place] に わすれもの を する. Asked as わすれもの は ない です か.'),
  'おつり': VocabUsage('せん えん だして おつり を もらいました', 'sen en dashite otsuri o moraimashita', 'Saya membayar 1000 yen dan menerima kembalian.', 'I paid 1,000 yen and got change.', 'Kata benda. Pola: おつり を もらう/わたす. Uang receh: こぜに.', 'Noun. Patterns: おつり を もらう/わたす. Small coins: こぜに.'),
  '億': VocabUsage('この いえ は いちおく えん です', 'kono ie wa ichioku en desu', 'Rumah ini harganya seratus juta yen.', 'This house costs one hundred million yen.', 'Angka (おく) = 100.000.000. Hitung: いちおく, じゅうおく. Satuan di bawahnya: まん (10.000).', 'Number (おく) = 100,000,000. Count: いちおく, じゅうおく. Unit below: まん (10,000).'),
  'ばい': VocabUsage('ねだん が にばい に なりました', 'nedan ga nibai ni narimashita', 'Harganya menjadi dua kali lipat.', 'The price doubled.', 'Penghitung/kata benda. Pola: [angka]ばい (にばい = dua kali lipat). ばい に なる = menjadi dua kali lipat.', 'Counter/noun. Pattern: [number]ばい (にばい = twice). ばい に なる = to double.'),
  'りょうほう': VocabUsage('コーヒー と こうちゃ と りょうほう すき です', 'koohii to koucha to ryouhou suki desu', 'Saya suka kopi dan teh, keduanya.', 'I like both coffee and tea.', 'Kata benda. Pola: [A] と [B] と りょうほう / りょうほう とも. Untuk dua hal saja.', 'Noun. Patterns: [A] と [B] と りょうほう / りょうほう とも. Only for two things.'),
  'けが': VocabUsage('サッカー で あし に けが を しました', 'sakkaa de ashi ni kega o shimashita', 'Kaki saya cedera saat bermain sepak bola.', 'I hurt my leg playing soccer.', 'Kata benda. Pola: [bagian tubuh] に けが を する. Untuk luka fisik, bukan penyakit.', 'Noun. Pattern: [body part] に けが を する. Physical injury, not illness.'),
  'ねつ': VocabUsage('きのう から ねつ が あります', 'kinou kara netsu ga arimasu', 'Saya demam sejak kemarin.', 'I have had a fever since yesterday.', 'Kata benda. Pola: ねつ が ある/でる/さがる. ねつ を はかる = mengukur suhu.', 'Noun. Patterns: ねつ が ある/でる/さがる. ねつ を はかる = take one\'s temperature.'),
  'ぐあい': VocabUsage('きょう は からだ の ぐあい が わるい です', 'kyou wa karada no guai ga warui desu', 'Hari ini kondisi badan saya kurang baik.', 'I am not feeling well today.', 'Kata benda. Pola: ぐあい が いい/わるい, (お)からだ の ぐあい. Juga untuk kondisi mesin.', 'Noun. Patterns: ぐあい が いい/わるい, からだ の ぐあい. Also for machines.'),
  '注射': VocabUsage('びょういん で ちゅうしゃ を しました', 'byouin de chuusha o shimashita', 'Saya disuntik di rumah sakit.', 'I got an injection at the hospital.', 'Kata benda (ちゅうしゃ). Pola: ちゅうしゃ を する/うつ. Homofon ちゅうしゃ (parkir).', 'Noun (ちゅうしゃ). Patterns: ちゅうしゃ を する/うつ. Homophone of ちゅうしゃ (parking).'),
  '髪': VocabUsage('かのじょ は かみ が ながい です', 'kanojo wa kami ga nagai desu', 'Rambutnya panjang.', 'She has long hair.', 'Kata benda (かみ); rambut kepala. Pola: かみ を きる/あらう. Bulu badan: け.', 'Noun (かみ); head hair. Patterns: かみ を きる/あらう. Body hair: け.'),
  'け': VocabUsage('この いぬ は け が しろくて ながい です', 'kono inu wa ke ga shirokute nagai desu', 'Bulu anjing ini putih dan panjang.', 'This dog\'s fur is white and long.', 'Kata benda; bulu badan/hewan, juga sehelai rambut. Rambut kepala secara umum: かみ.', 'Noun; body hair, fur, or a single hair. Head hair in general: かみ.'),
  'ひげ': VocabUsage('ちち は まいあさ ひげ を そります', 'chichi wa maiasa hige o sorimasu', 'Ayah mencukur kumis dan jenggotnya setiap pagi.', 'My father shaves every morning.', 'Kata benda. Pola: ひげ を そる (bercukur), ひげ が はえる (tumbuh).', 'Noun. Patterns: ひげ を そる (shave), ひげ が はえる (grow).'),
  'のど': VocabUsage('かぜ で のど が いたい です', 'kaze de nodo ga itai desu', 'Tenggorokan saya sakit karena flu.', 'My throat hurts because of a cold.', 'Kata benda. Pola: のど が いたい, のど が かわく (haus).', 'Noun. Patterns: のど が いたい, のど が かわく (be thirsty).'),
