  'うで': VocabUsage('テニス を して うで が いたく なりました', 'tenisu o shite ude ga itaku narimashita', 'Lengan saya jadi sakit setelah main tenis.', 'My arm started hurting after playing tennis.', 'Kata benda. Juga kemampuan: うで が いい (terampil). Tangan (telapak): て.', 'Noun. Also skill: うで が いい (skilled). Hand: て.'),
  'ゆび': VocabUsage('ナイフ で ゆび を きって しまいました', 'naifu de yubi o kitte shimaimashita', 'Jari saya teriris pisau.', 'I cut my finger with a knife.', 'Kata benda. Pola: ゆび を きる. おやゆび = ibu jari, ゆびわ = cincin.', 'Noun. Pattern: ゆび を きる. おやゆび = thumb, ゆびわ = ring.'),
  'つめ': VocabUsage('つめ が ながく なった から きります', 'tsume ga nagaku natta kara kirimasu', 'Kuku saya sudah panjang, jadi saya potong.', 'My nails got long, so I will cut them.', 'Kata benda. Pola: つめ を きる (memotong kuku). つめきり = gunting kuku.', 'Noun. Pattern: つめ を きる (cut nails). つめきり = nail clipper.'),
  'ち': VocabUsage('ゆび から ち が でて います', 'yubi kara chi ga dete imasu', 'Jari saya berdarah.', 'My finger is bleeding.', 'Kata benda. Pola: ち が でる (berdarah). けつえきがた = golongan darah.', 'Noun. Pattern: ち が でる (bleed). けつえきがた = blood type.'),
  'こうつう': VocabUsage('とうきょう は こうつう が べんり です', 'toukyou wa koutsuu ga benri desu', 'Transportasi di Tokyo praktis.', 'Getting around Tokyo is convenient.', 'Kata benda; lalu lintas dan transportasi. Pola: こうつう が べんり, こうつうじこ (kecelakaan lalin).', 'Noun; traffic and transport. Patterns: こうつう が べんり, こうつうじこ.'),
  'じこ': VocabUsage('けさ えき の まえ で じこ が ありました', 'kesa eki no mae de jiko ga arimashita', 'Tadi pagi ada kecelakaan di depan stasiun.', 'There was an accident in front of the station this morning.', 'Kata benda. Pola: じこ が ある/おこる, じこ に あう (mengalami kecelakaan).', 'Noun. Patterns: じこ が ある/おこる, じこ に あう (be in an accident).'),
  'しんごう': VocabUsage('しんごう が あお に なって から わたります', 'shingou ga ao ni natte kara watarimasu', 'Saya menyeberang setelah lampu lalu lintas hijau.', 'I cross after the light turns green.', 'Kata benda. Pola: しんごう が あお/あか に なる. Lampu hijau disebut あお di Jepang.', 'Noun. Pattern: しんごう が あお/あか に なる. Green light is called あお in Japanese.'),
  'とおり': VocabUsage('この とおり に は みせ が たくさん あります', 'kono toori ni wa mise ga takusan arimasu', 'Di jalan ini ada banyak toko.', 'There are many shops on this street.', 'Kata benda; jalan besar/ramai. Lebih spesifik dari みち. Nama jalan: [nama]どおり.', 'Noun; main street. More specific than みち. Street names: [name]どおり.'),
  'くうこう': VocabUsage('くうこう まで バス で いちじかん です', 'kuukou made basu de ichijikan desu', 'Ke bandara satu jam naik bus.', 'It takes an hour by bus to the airport.', 'Kata benda. Pola: くうこう に つく (tiba di bandara), くうこう まで むかえ に いく.', 'Noun. Patterns: くうこう に つく (arrive), くうこう まで むかえ に いく (pick up).'),
