  'とっきゅう': VocabUsage('とっきゅう は とっきゅうけん が ひつよう です', 'tokkyuu wa tokkyuuken ga hitsuyou desu', 'Untuk kereta ekspres terbatas perlu tiket tambahan khusus.', 'The limited express requires a special express ticket.', 'Kata benda. Pola: とっきゅう に のる. Biasanya perlu とっきゅうけん (tiket tambahan).', 'Noun. Pattern: とっきゅう に のる. Usually requires とっきゅうけん (surcharge ticket).'),
  'しんかんせん': VocabUsage('しんかんせん で おおさか へ いきました', 'shinkansen de oosaka e ikimashita', 'Saya pergi ke Osaka naik shinkansen.', 'I went to Osaka by bullet train.', 'Kata benda. Pola: しんかんせん で いく / しんかんせん に のる.', 'Noun. Patterns: しんかんせん で いく / しんかんせん に のる.'),
