  'えだ': VocabUsage('き の えだ に とり が います', 'ki no eda ni tori ga imasu', 'Ada burung di dahan pohon.', 'There is a bird on the tree branch.', 'Kata benda. Pola: き の えだ. Kolokasi: えだ が おれる (dahan patah).', 'Noun. Pattern: き の えだ. Collocation: えだ が おれる (branch breaks).'),
  '葉': VocabUsage('あき に は が あかく なります', 'aki ni ha ga akaku narimasu', 'Di musim gugur daun menjadi merah.', 'Leaves turn red in autumn.', 'Kata benda (は). Sering disebut はっぱ dalam percakapan. Pola: き の は.', 'Noun (は). Often はっぱ in casual speech. Pattern: き の は.'),
  'いし': VocabUsage('かわ に いし を なげました', 'kawa ni ishi o nagemashita', 'Saya melempar batu ke sungai.', 'I threw a stone into the river.', 'Kata benda. Kolokasi: いし を なげる, いし の ように かたい.', 'Noun. Collocations: いし を なげる, いし の ように かたい (hard as stone).'),
  'すな': VocabUsage('こども が すな で あそんで います', 'kodomo ga suna de asonde imasu', 'Anak-anak bermain pasir.', 'The children are playing in the sand.', 'Kata benda. Pantai berpasir = すなはま. Pola: すな で あそぶ.', 'Noun. Sandy beach = すなはま. Pattern: すな で あそぶ.'),
  'くうき': VocabUsage('やま の くうき は きれい です', 'yama no kuuki wa kirei desu', 'Udara di gunung bersih.', 'The mountain air is clean.', 'Kata benda. Kiasan: くうき を よむ (membaca suasana).', 'Noun. Idiom: くうき を よむ (read the room).'),
  'こおり': VocabUsage('ジュース に こおり を いれます', 'juusu ni koori o iremasu', 'Saya memasukkan es ke dalam jus.', 'I put ice in the juice.', 'Kata benda. Es batu/es beku. Pola: こおり を いれる.', 'Noun. Ice. Pattern: こおり を いれる.'),
  'かじ': VocabUsage('きのう ちかく で かじ が ありました', 'kinou chikaku de kaji ga arimashita', 'Kemarin ada kebakaran di dekat sini.', 'There was a fire nearby yesterday.', 'Kata benda. Kebakaran (musibah); api biasa = ひ. Pola: かじ が ある/おこる.', 'Noun. A fire (disaster); ordinary fire = ひ. Pattern: かじ が ある/おこる.'),
  'けしき': VocabUsage('ここ から の けしき は きれい です', 'koko kara no keshiki wa kirei desu', 'Pemandangan dari sini indah.', 'The view from here is beautiful.', 'Kata benda. Pemandangan alam. Pola: [tempat] から の けしき.', 'Noun. Scenery. Pattern: [place] から の けしき.'),
  'きせつ': VocabUsage('いちばん すきな きせつ は はる です', 'ichiban sukina kisetsu wa haru desu', 'Musim yang paling saya sukai adalah musim semi.', 'My favorite season is spring.', 'Kata benda. Pola: どの きせつ が すき です か.', 'Noun. Pattern: どの きせつ が すき です か (which season do you like).'),
  'てんきよほう': VocabUsage('てんきよほう に よると あした は あめ です', 'tenkiyohou ni yoru to ashita wa ame desu', 'Menurut prakiraan cuaca, besok hujan.', 'According to the weather forecast, it will rain tomorrow.', 'Kata benda. Pola: てんきよほう に よると ... (menurut prakiraan cuaca).', 'Noun. Pattern: てんきよほう に よると ... (according to the forecast).'),
  'ことり': VocabUsage('あさ ことり が ないて います', 'asa kotori ga naite imasu', 'Pagi-pagi burung kecil berkicau.', 'Small birds are singing in the morning.', 'Kata benda. こ (kecil) + とり. Pola: ことり が なく (berkicau).', 'Noun. こ (small) + とり. Pattern: ことり が なく (birds chirp).'),
  'むし': VocabUsage('なつ は むし が おおい です', 'natsu wa mushi ga ooi desu', 'Di musim panas banyak serangga.', 'There are many insects in summer.', 'Kata benda. Serangga/kutu umum. Kolokasi: むし に さされる (digigit serangga).', 'Noun. Bugs in general. Collocation: むし に さされる (get bitten).'),
  'このあいだ': VocabUsage('このあいだ ともだち に あいました', 'konoaida tomodachi ni aimashita', 'Beberapa waktu lalu saya bertemu teman.', 'I met a friend the other day.', 'Keterangan waktu. Dipakai dengan bentuk lampau; agak santai, mirip せんじつ.', 'Time noun. Used with past tense; casual, similar to せんじつ.'),
  'このごろ': VocabUsage('このごろ よく あめ が ふります', 'konogoro yoku ame ga furimasu', 'Akhir-akhir ini sering hujan.', 'It often rains these days.', 'Keterangan waktu. Untuk keadaan yang berlangsung sekarang; beda dari さいきん yang juga untuk kejadian sekali.', 'Time noun. For ongoing current states; unlike さいきん, not for one-off events.'),
  'さいきん': VocabUsage('さいきん にほんご を べんきょう して います', 'saikin nihongo o benkyou shite imasu', 'Baru-baru ini saya belajar bahasa Jepang.', 'Recently I have been studying Japanese.', 'Keterangan waktu. Bisa dengan lampau (kejadian) atau ～ている (keadaan).', 'Time noun. Works with past (events) or ～ている (ongoing states).'),
  'さっき': VocabUsage('さっき せんせい から でんわ が ありました', 'sakki sensei kara denwa ga arimashita', 'Tadi ada telepon dari guru.', 'There was a call from the teacher a while ago.', 'Keterangan waktu, santai. Beberapa menit/jam lalu; versi formal: さきほど.', 'Casual time word. Minutes or hours ago; formal: さきほど.'),
  'むかし': VocabUsage('むかし ここ に がっこう が ありました', 'mukashi koko ni gakkou ga arimashita', 'Dulu di sini ada sekolah.', 'Long ago there was a school here.', 'Keterangan waktu. Pembuka dongeng: むかし むかし ... (pada zaman dahulu).', 'Time noun. Fairy-tale opener: むかし むかし ... (once upon a time).'),
  'しょうらい': VocabUsage('しょうらい いしゃ に なりたい です', 'shourai isha ni naritai desu', 'Di masa depan saya ingin menjadi dokter.', 'In the future I want to become a doctor.', 'Kata benda/keterangan. Masa depan pribadi; sering dengan ～たい/～に なる.', 'Noun/adverb. One\'s future; often with ～たい/～に なる.'),
  'ひるま': VocabUsage('ひるま は いえ に だれ も いません', 'hiruma wa ie ni dare mo imasen', 'Siang hari tidak ada siapa pun di rumah.', 'Nobody is home during the day.', 'Kata benda waktu. Waktu siang (terang); lawan よる. Beda dengan ひる (siang/makan siang).', 'Time noun. Daytime; opposite of よる. Unlike ひる, it does not mean lunch.'),
  'さらいげつ': VocabUsage('さらいげつ にほん へ いきます', 'saraigetsu nihon e ikimasu', 'Dua bulan lagi saya pergi ke Jepang.', 'I am going to Japan the month after next.', 'Keterangan waktu, tanpa partikel に. Seri: こんげつ, らいげつ, さらいげつ.', 'Time word, no に needed. Series: こんげつ, らいげつ, さらいげつ.'),
  'さいしょ': VocabUsage('さいしょ は むずかしかった です', 'saisho wa muzukashikatta desu', 'Awalnya sulit.', 'It was difficult at first.', 'Kata benda. Pola: さいしょ は ... (awalnya), さいしょ の [kata benda]. Lawan: さいご.', 'Noun. Patterns: さいしょ は ... (at first), さいしょ の [noun]. Opposite: さいご.'),
