  'けんきゅうする': VocabUsage('だいがく で にほん の れきし を けんきゅう して います', 'daigaku de nihon no rekishi o kenkyuu shite imasu', 'Saya meneliti sejarah Jepang di universitas.', 'I research Japanese history at university.', 'Kata kerja gol. III. Bentuk sopan: けんきゅう します. Pola: [topik] を けんきゅう する. Peneliti: けんきゅうしゃ.', 'Group 3 verb. Polite: けんきゅう します. Pattern: [topic] を けんきゅう する. Researcher: けんきゅうしゃ.'),
  'けんぶつする': VocabUsage('きょうと で おてら を けんぶつ しました', 'kyouto de otera o kenbutsu shimashita', 'Saya melihat-lihat kuil di Kyoto.', 'I went sightseeing at temples in Kyoto.', 'Kata kerja gol. III. Bentuk sopan: けんぶつ します. Pola: [tempat] を けんぶつ する; けんぶつ に いく.', 'Group 3 verb. Polite: けんぶつ します. Pattern: [place] を けんぶつ する; けんぶつ に いく.'),
  'しゅっぱつする': VocabUsage('バス は くじ に しゅっぱつ します', 'basu wa kuji ni shuppatsu shimasu', 'Bus berangkat jam sembilan.', 'The bus departs at nine.', 'Kata kerja gol. III. Bentuk sopan: しゅっぱつ します. Pola: [tempat] を しゅっぱつ する. Lawan: とうちゃく する.', 'Group 3 verb. Polite: しゅっぱつ します. Pattern: [place] を しゅっぱつ する. Opposite: とうちゃく する.'),
  'ちゅういする': VocabUsage('くるま に ちゅうい して ください', 'kuruma ni chuui shite kudasai', 'Hati-hati dengan mobil.', 'Please watch out for cars.', 'Kata kerja gol. III. Pola: [bahaya] に ちゅうい する (hati-hati); [orang] に ちゅうい する (menegur).', 'Group 3 verb. Pattern: [danger] に ちゅうい する (watch out); [person] に ちゅうい する (warn).'),
  'ほんやくする': VocabUsage('この ぶん を えいご に ほんやく して ください', 'kono bun o eigo ni honyaku shite kudasai', 'Tolong terjemahkan kalimat ini ke bahasa Inggris.', 'Please translate this sentence into English.', 'Kata kerja gol. III. Pola: [teks] を [bahasa] に ほんやく する. Untuk tulisan; lisan = つうやく.', 'Group 3 verb. Pattern: [text] を [language] に ほんやく する. Written; oral = つうやく.'),
  'れんらくする': VocabUsage('あとで でんわ で れんらく します', 'atode denwa de renraku shimasu', 'Nanti saya hubungi lewat telepon.', 'I\'ll contact you by phone later.', 'Kata kerja gol. III. Pola: [orang] に れんらく する; [alat] で れんらく する.', 'Group 3 verb. Pattern: [person] に れんらく する; [means] で れんらく する.'),
  'けんかする': VocabUsage('きのう あに と けんか しました', 'kinou ani to kenka shimashita', 'Kemarin saya bertengkar dengan kakak laki-laki.', 'I had a fight with my older brother yesterday.', 'Kata kerja gol. III. Bentuk sopan: けんか します. Pola: [orang] と けんか する.', 'Group 3 verb. Polite: けんか します. Pattern: [person] と けんか する.'),
  'ちこくする': VocabUsage('けさ がっこう に ちこく しました', 'kesa gakkou ni chikoku shimashita', 'Tadi pagi saya terlambat ke sekolah.', 'I was late for school this morning.', 'Kata kerja gol. III. Pola: [sekolah/kantor] に ちこく する. Untuk jam masuk; terlambat umum = おくれる.', 'Group 3 verb. Pattern: [school/work] に ちこく する. For start times; general lateness = おくれる.'),
  'ねぼうする': VocabUsage('ねぼう して でんしゃ に おくれました', 'nebou shite densha ni okuremashita', 'Saya bangun kesiangan dan ketinggalan kereta.', 'I overslept and missed the train.', 'Kata kerja gol. III. Bentuk sopan: ねぼう します. Sering bentuk て sebagai alasan: ねぼう して ～.', 'Group 3 verb. Polite: ねぼう します. Often て-form as a reason: ねぼう して ～.'),
  'よういする': VocabUsage('りょこう の にもつ を ようい しました', 'ryokou no nimotsu o youi shimashita', 'Saya sudah menyiapkan barang untuk perjalanan.', 'I prepared my luggage for the trip.', 'Kata kerja gol. III. Pola: [benda] を よういする. Mirip じゅんび する; ようい lebih ke menyediakan barang.', 'Group 3 verb. Pattern: [thing] を よういする. Like じゅんび する; ようい stresses providing items.'),
  'こしょうする': VocabUsage('エアコン が こしょう しました', 'eakon ga koshou shimashita', 'AC-nya rusak.', 'The air conditioner broke down.', 'Kata kerja gol. III. Pola: [mesin] が こしょう する. Keadaan: こしょう して いる / こしょう ちゅう.', 'Group 3 verb. Pattern: [machine] が こしょう する. State: こしょう して いる / こしょう ちゅう.'),
  'りようする': VocabUsage('まいにち としょかん を りよう して います', 'mainichi toshokan o riyou shite imasu', 'Saya memanfaatkan perpustakaan setiap hari.', 'I use the library every day.', 'Kata kerja gol. III. Pola: [fasilitas/layanan] を りよう する. Lebih formal dari つかう.', 'Group 3 verb. Pattern: [facility/service] を りよう する. More formal than つかう.'),
  'けしょうする': VocabUsage('あね は かがみ の まえ で けしょう して います', 'ane wa kagami no mae de keshou shite imasu', 'Kakak perempuan sedang berdandan di depan cermin.', 'My older sister is putting on makeup in front of the mirror.', 'Kata kerja gol. III. Bentuk sopan: けしょう します. Kata benda sopan: おけしょう.', 'Group 3 verb. Polite: けしょう します. Polite noun: おけしょう.'),
  'ほうそうする': VocabUsage('その しあい は テレビ で ほうそう します', 'sono shiai wa terebi de housou shimasu', 'Pertandingan itu disiarkan di televisi.', 'That match will be broadcast on TV.', 'Kata kerja gol. III. Pola: [acara] を ほうそう する; pengumuman di stasiun juga ほうそう.', 'Group 3 verb. Pattern: [program] を ほうそう する; station announcements are also ほうそう.'),
  'よしゅうする': VocabUsage('じゅぎょう の まえ に よしゅう します', 'jugyou no mae ni yoshuu shimasu', 'Saya belajar materi sebelum pelajaran.', 'I prepare before class.', 'Kata kerja gol. III. Bentuk sopan: よしゅう します. Pasangan: ふくしゅう する (mengulang setelah kelas).', 'Group 3 verb. Polite: よしゅう します. Counterpart: ふくしゅう する (review after class).'),
  'ふくしゅうする': VocabUsage('いえ で きょう の ぶんぽう を ふくしゅう します', 'ie de kyou no bunpou o fukushuu shimasu', 'Saya mengulang tata bahasa hari ini di rumah.', 'I review today\'s grammar at home.', 'Kata kerja gol. III. Pola: [materi] を ふくしゅう する. Pasangan: よしゅう する.', 'Group 3 verb. Pattern: [material] を ふくしゅう する. Counterpart: よしゅう する.'),
  'しょうたいする': VocabUsage('ともだち を けっこんしき に しょうたい しました', 'tomodachi o kekkonshiki ni shoutai shimashita', 'Saya mengundang teman ke pesta pernikahan.', 'I invited my friends to the wedding.', 'Kata kerja gol. III. Pola: [orang] を [acara] に しょうたい する. Lebih resmi dari さそう. Kartu: しょうたいじょう.', 'Group 3 verb. Pattern: [person] を [event] に しょうたい する. More formal than さそう. Card: しょうたいじょう.'),
  'にゅういんする': VocabUsage('そふ は きのう から にゅういん して います', 'sofu wa kinou kara nyuuin shite imasu', 'Kakek dirawat inap sejak kemarin.', 'My grandfather has been in hospital since yesterday.', 'Kata kerja gol. III. Bentuk sopan: にゅういん します. Lawan: たいいん する.', 'Group 3 verb. Polite: にゅういん します. Opposite: たいいん する.'),
  'たいいんする': VocabUsage('はは は らいしゅう たいいん します', 'haha wa raishuu taiin shimasu', 'Ibu keluar dari rumah sakit minggu depan.', 'My mother will leave the hospital next week.', 'Kata kerja gol. III. Bentuk sopan: たいいん します. Lawan: にゅういん する.', 'Group 3 verb. Polite: たいいん します. Opposite: にゅういん する.'),
  'にゅうがくする': VocabUsage('おとうと は しがつ に しょうがっこう に にゅうがく します', 'otouto wa shigatsu ni shougakkou ni nyuugaku shimasu', 'Adik laki-laki masuk SD bulan April.', 'My younger brother starts elementary school in April.', 'Kata kerja gol. III. Pola: [sekolah] に にゅうがく する. Lawan: そつぎょう する.', 'Group 3 verb. Pattern: [school] に にゅうがく する. Opposite: そつぎょう する.'),
  'そつぎょうする': VocabUsage('あね は きょねん だいがく を そつぎょう しました', 'ane wa kyonen daigaku o sotsugyou shimashita', 'Kakak perempuan lulus kuliah tahun lalu.', 'My older sister graduated from university last year.', 'Kata kerja gol. III. Pola: [sekolah] を そつぎょう する (partikel を). Lawan: にゅうがく する.', 'Group 3 verb. Pattern: [school] を そつぎょう する (particle を). Opposite: にゅうがく する.'),
  'うつくしい': VocabUsage('やま の けしき が うつくしい です', 'yama no keshiki ga utsukushii desu', 'Pemandangan gunung indah.', 'The mountain scenery is beautiful.', 'Kata sifat い. Lebih puitis/formal dari きれい. Pola: うつくしい [kata benda].', 'い-adjective. More poetic/formal than きれい. Pattern: うつくしい [noun].'),
  'かなしい': VocabUsage('ともだち が かえって かなしい です', 'tomodachi ga kaette kanashii desu', 'Saya sedih karena teman pulang.', 'I\'m sad because my friend went home.', 'Kata sifat い. Untuk perasaan sendiri; orang lain: かなしそう. Lawan: うれしい.', 'い-adjective. For one\'s own feelings; others: かなしそう. Opposite: うれしい.'),
  'さびしい': VocabUsage('ひとり で すんで いて さびしい です', 'hitori de sunde ite sabishii desu', 'Saya kesepian karena tinggal sendiri.', 'I\'m lonely living alone.', 'Kata sifat い. Kesepian/sepi; juga untuk tempat yang sepi: さびしい まち.', 'い-adjective. Lonely; also for deserted places: さびしい まち.'),
  'はずかしい': VocabUsage('みんな の まえ で うたう の は はずかしい です', 'minna no mae de utau no wa hazukashii desu', 'Bernyanyi di depan semua orang itu memalukan.', 'Singing in front of everyone is embarrassing.', 'Kata sifat い. Pola: ～の は はずかしい. Malu/canggung; beda dari \'rendah diri\'.', 'い-adjective. Pattern: ～の は はずかしい. Embarrassed or shy.'),
  'ひどい': VocabUsage('きのう は ひどい あめ でした', 'kinou wa hidoi ame deshita', 'Kemarin hujannya parah.', 'There was terrible rain yesterday.', 'Kata sifat い. \'Parah\' untuk cuaca/sakit, \'kejam\' untuk perbuatan: ひどい ひと.', 'い-adjective. \'Terrible\' for weather/illness, \'cruel\' for actions: ひどい ひと.'),
  'やわらかい': VocabUsage('この パン は やわらかい です', 'kono pan wa yawarakai desu', 'Roti ini lembut.', 'This bread is soft.', 'Kata sifat い. Lawan: かたい. Untuk makanan, kain, kasur.', 'い-adjective. Opposite: かたい. For food, fabric, beds.'),
  'かたい': VocabUsage('この にく は かたい です', 'kono niku wa katai desu', 'Daging ini keras.', 'This meat is tough.', 'Kata sifat い. Lawan: やわらかい. Juga untuk sikap kaku: あたま が かたい.', 'い-adjective. Opposite: やわらかい. Also stubborn: あたま が かたい.'),
  'ふかい': VocabUsage('この かわ は ふかい です', 'kono kawa wa fukai desu', 'Sungai ini dalam.', 'This river is deep.', 'Kata sifat い. Lawan: あさい. Kata benda: ふかさ (kedalaman).', 'い-adjective. Opposite: あさい. Noun: ふかさ (depth).'),
  'あさい': VocabUsage('ここ は あさい から あんぜん です', 'koko wa asai kara anzen desu', 'Di sini dangkal, jadi aman.', 'It\'s shallow here, so it\'s safe.', 'Kata sifat い. Lawan: ふかい. Juga: ねむり が あさい (tidur tidak nyenyak).', 'い-adjective. Opposite: ふかい. Also: ねむり が あさい (light sleep).'),
  'こまかい': VocabUsage('こまかい こと は きに しないで ください', 'komakai koto wa ki ni shinaide kudasai', 'Jangan pedulikan hal-hal kecil.', 'Don\'t worry about the small details.', 'Kata sifat い. Halus/kecil-kecil/rinci; こまかい おかね = uang receh.', 'い-adjective. Fine, small, detailed; こまかい おかね = small change.'),
  'ねむい': VocabUsage('きのう おそく ねた から ねむい です', 'kinou osoku neta kara nemui desu', 'Saya mengantuk karena kemarin tidur larut.', 'I\'m sleepy because I went to bed late.', 'Kata sifat い. Untuk perasaan sendiri; orang lain: ねむそう.', 'い-adjective. For one\'s own state; others: ねむそう.'),
  'ただしい': VocabUsage('ただしい こたえ を えらんで ください', 'tadashii kotae o erande kudasai', 'Pilihlah jawaban yang benar.', 'Please choose the correct answer.', 'Kata sifat い. Benar secara aturan/fakta. Santai: あって いる. Keterangan: ただしく.', 'い-adjective. Correct by rule or fact. Casual: あって いる. Adverb: ただしく.'),
  'めずらしい': VocabUsage('ここ で ゆき が ふる の は めずらしい です', 'koko de yuki ga furu no wa mezurashii desu', 'Jarang turun salju di sini.', 'It\'s rare for snow to fall here.', 'Kata sifat い. Pola: ～の は めずらしい. Juga \'unik/langka\': めずらしい どうぶつ.', 'い-adjective. Pattern: ～の は めずらしい. Also \'unusual\': めずらしい どうぶつ.'),
  'すごい': VocabUsage('かれ の にほんご は すごい です', 'kare no nihongo wa sugoi desu', 'Bahasa Jepangnya hebat.', 'His Japanese is amazing.', 'Kata sifat い, santai. Keterangan: すごく (sangat). Bisa positif/negatif: すごい あめ.', 'Casual い-adjective. Adverb: すごく (very). Positive or negative: すごい あめ.'),
  'すばらしい': VocabUsage('すばらしい えんそう でした', 'subarashii ensou deshita', 'Penampilannya luar biasa.', 'It was a wonderful performance.', 'Kata sifat い. Pujian kuat dan lebih sopan dari すごい; selalu positif.', 'い-adjective. Strong, more polite praise than すごい; always positive.'),
  'きびしい': VocabUsage('あの せんせい は とても きびしい です', 'ano sensei wa totemo kibishii desu', 'Guru itu sangat tegas.', 'That teacher is very strict.', 'Kata sifat い. Pola: [orang] に きびしい (tegas terhadap). Juga: きびしい さむさ (dingin menusuk).', 'い-adjective. Pattern: [person] に きびしい (strict with). Also: きびしい さむさ (severe cold).'),
  'にがい': VocabUsage('この くすり は にがい です', 'kono kusuri wa nigai desu', 'Obat ini pahit.', 'This medicine is bitter.', 'Kata sifat い. Rasa pahit; kiasan: にがい おもいで (kenangan pahit).', 'い-adjective. Bitter taste; figurative: にがい おもいで (bitter memory).'),
  'おかしい': VocabUsage('この けいさん は おかしい です ね', 'kono keisan wa okashii desu ne', 'Perhitungan ini janggal, ya.', 'This calculation seems wrong.', 'Kata sifat い. \'Lucu\' atau \'aneh/tidak beres\' tergantung konteks.', 'い-adjective. \'Funny\' or \'strange/wrong\' depending on context.'),
  'えらい': VocabUsage('まいにち べんきょう して えらい です ね', 'mainichi benkyou shite erai desu ne', 'Hebat ya, belajar setiap hari.', 'Studying every day, how admirable.', 'Kata sifat い. Memuji usaha orang; juga \'berkedudukan tinggi\': えらい ひと.', 'い-adjective. Praises effort; also \'high-ranking\': えらい ひと.'),
  'おとなしい': VocabUsage('この いぬ は おとなしい です', 'kono inu wa otonashii desu', 'Anjing ini kalem.', 'This dog is gentle.', 'Kata sifat い. Pendiam/jinak untuk orang atau hewan. Keterangan: おとなしく (dengan tenang).', 'い-adjective. Quiet/gentle for people or animals. Adverb: おとなしく (quietly).'),
  'よろしい': VocabUsage('ここ に すわって も よろしい です か', 'koko ni suwatte mo yoroshii desu ka', 'Bolehkah saya duduk di sini?', 'May I sit here?', 'Kata sifat い, versi sopan dari いい. Pola: ～ても よろしい です か (bolehkah ...).', 'い-adjective, polite form of いい. Pattern: ～ても よろしい です か (may I ...).'),
  'いっしょうけんめい': VocabUsage('かれ は いっしょうけんめい はたらいて います', 'kare wa isshoukenmei hataraite imasu', 'Dia bekerja dengan sungguh-sungguh.', 'He is working with all his might.', 'Kata sifat な / keterangan. Dipakai langsung di depan kata kerja, atau いっしょうけんめい に.', 'な-adjective / adverb. Used directly before verbs, or as いっしょうけんめい に.'),
  'さかん': VocabUsage('この まち は サッカー が さかん です', 'kono machi wa sakkaa ga sakan desu', 'Sepak bola populer di kota ini.', 'Soccer is popular in this town.', 'Kata sifat な. Pola: [tempat] は [kegiatan] が さかん だ (marak/berkembang).', 'な-adjective. Pattern: [place] は [activity] が さかん だ (is thriving).'),
  'しつれい': VocabUsage('ひと に しつれい な こと を いって は いけません', 'hito ni shitsurei na koto o itte wa ikemasen', 'Tidak boleh mengatakan hal yang tidak sopan kepada orang.', 'You mustn\'t say rude things to people.', 'Kata sifat な. Juga ungkapan: しつれい します (permisi), しつれい です が (maaf, ...).', 'な-adjective. Also set phrases: しつれい します (excuse me), しつれい です が (pardon me, but).'),
  'じゃま': VocabUsage('そこ に たつ と じゃま です よ', 'soko ni tatsu to jama desu yo', 'Kalau berdiri di situ, menghalangi, lho.', 'If you stand there, you\'re in the way.', 'Kata sifat な / kata benda. Pola: じゃま を する (mengganggu); おじゃま します (permisi masuk).', 'な-adjective / noun. Pattern: じゃま を する (disturb); おじゃま します (said when entering).'),
  'てきとう': VocabUsage('てきとう な ことば を いれて ください', 'tekitou na kotoba o irete kudasai', 'Masukkan kata yang sesuai.', 'Please fill in a suitable word.', 'Kata sifat な. Artinya \'sesuai\', tapi sehari-hari sering \'asal-asalan\': てきとう に やる.', 'な-adjective. \'Suitable\', but casually often \'sloppy\': てきとう に やる.'),
  'とくい': VocabUsage('あに は すうがく が とくい です', 'ani wa suugaku ga tokui desu', 'Kakak laki-laki mahir matematika.', 'My older brother is good at math.', 'Kata sifat な. Pola: [orang] は [bidang] が とくい だ. Lawan: にがて. Lebih percaya diri dari じょうず.', 'な-adjective. Pattern: [person] は [skill] が とくい だ. Opposite: にがて. Unlike じょうず, used for oneself.'),
  'にがて': VocabUsage('わたし は スポーツ が にがて です', 'watashi wa supootsu ga nigate desu', 'Saya tidak pandai olahraga.', 'I\'m not good at sports.', 'Kata sifat な. Pola: [bidang] が にがて だ; juga \'tidak suka\': にがて な たべもの.', 'な-adjective. Pattern: [skill] が にがて だ; also \'dislike\': にがて な たべもの.'),
  'ふつう': VocabUsage('ふつう は あるいて がっこう へ いきます', 'futsuu wa aruite gakkou e ikimasu', 'Biasanya saya pergi ke sekolah jalan kaki.', 'I usually walk to school.', 'Kata sifat な / kata benda / keterangan. ふつう の [kata benda]; ふつう は = biasanya.', 'な-adjective / noun / adverb. ふつう の [noun]; ふつう は = usually.'),
  'だいじ': VocabUsage('これ は だいじ な しゃしん です', 'kore wa daiji na shashin desu', 'Ini foto yang berharga.', 'This is a precious photo.', 'Kata sifat な. Pola: だいじ に する (menjaga baik-baik); おだいじ に (semoga lekas sembuh).', 'な-adjective. Pattern: だいじ に する (take good care of); おだいじ に (get well soon).'),
  'たしか': VocabUsage('たしか かれ は らいしゅう きます', 'tashika kare wa raishuu kimasu', 'Kalau tidak salah, dia datang minggu depan.', 'If I\'m not mistaken, he\'s coming next week.', 'Keterangan: \'kalau tidak salah\' (di awal kalimat). Kata sifat な: たしか な じょうほう (info pasti).', 'Adverb: \'if I remember right\' (sentence-initial). な-adjective: たしか な じょうほう (reliable info).'),
  'きっと': VocabUsage('あした は きっと はれる でしょう', 'ashita wa kitto hareru deshou', 'Besok pasti cerah.', 'It will surely be sunny tomorrow.', 'Keterangan keyakinan pembicara. Sering dengan でしょう/と おもう. Lebih subjektif dari かならず.', 'Adverb of the speaker\'s conviction. Often with でしょう/と おもう. More subjective than かならず.'),
  'かならず': VocabUsage('しゅくだい は かならず だして ください', 'shukudai wa kanarazu dashite kudasai', 'PR wajib dikumpulkan tanpa kecuali.', 'Please be sure to hand in your homework.', 'Keterangan \'pasti, selalu\'. Untuk janji/aturan/keharusan; tidak dipakai dengan でしょう.', 'Adverb \'without fail\'. For promises, rules, obligations; not used with でしょう.'),
  'ずいぶん': VocabUsage('にほんご が ずいぶん じょうず に なりました ね', 'nihongo ga zuibun jouzu ni narimashita ne', 'Bahasa Jepangmu sudah jauh lebih mahir, ya.', 'Your Japanese has gotten much better.', 'Keterangan derajat. Menunjukkan lebih dari perkiraan, sering dengan rasa kagum.', 'Degree adverb. Shows more than expected, often with surprise.'),
  'かなり': VocabUsage('きょう は かなり さむい です', 'kyou wa kanari samui desu', 'Hari ini cukup dingin.', 'It\'s fairly cold today.', 'Keterangan derajat. Lebih dari biasa, tapi di bawah とても.', 'Degree adverb. More than usual, but weaker than とても.'),
  'だいぶ': VocabUsage('かぜ は だいぶ よく なりました', 'kaze wa daibu yoku narimashita', 'Flu saya sudah cukup membaik.', 'My cold has gotten a lot better.', 'Keterangan derajat. Sering untuk perubahan: だいぶ ～ なった.', 'Degree adverb. Often for change: だいぶ ～ なった.'),
  'なかなか': VocabUsage('バス が なかなか きません', 'basu ga nakanaka kimasen', 'Busnya tak kunjung datang.', 'The bus just won\'t come.', 'Keterangan. Dengan negatif: \'tidak mudah/tak kunjung\'; dengan positif: \'cukup (bagus)\'.', 'Adverb. With negative: \'not easily\'; with positive: \'quite (good)\'.'),
  'ぜひ': VocabUsage('ぜひ いちど あそび に きて ください', 'zehi ichido asobi ni kite kudasai', 'Silakan mampirlah sekali-sekali.', 'Please do come and visit sometime.', 'Keterangan harapan kuat. Dipakai dengan ～たい / ～て ください, bukan negatif.', 'Adverb of strong wish. Used with ～たい / ～て ください, not negatives.'),
  'けっして': VocabUsage('この こと は けっして わすれません', 'kono koto wa kesshite wasuremasen', 'Saya tidak akan pernah melupakan hal ini.', 'I will never forget this.', 'Keterangan, selalu dengan bentuk negatif: けっして ～ない (sama sekali tidak).', 'Adverb, always with a negative: けっして ～ない (never).'),
  'ちっとも': VocabUsage('この ほん は ちっとも おもしろく ありません', 'kono hon wa chittomo omoshiroku arimasen', 'Buku ini sama sekali tidak menarik.', 'This book isn\'t interesting at all.', 'Keterangan santai, selalu dengan negatif. Mirip ぜんぜん.', 'Casual adverb, always with a negative. Similar to ぜんぜん.'),
  'しっかり': VocabUsage('しっかり べんきょう して ください', 'shikkari benkyou shite kudasai', 'Belajarlah dengan sungguh-sungguh.', 'Please study properly.', 'Keterangan. Kuat/teguh/benar-benar. Juga: しっかり した ひと (orang yang dapat diandalkan).', 'Adverb. Firmly, properly. Also: しっかり した ひと (a reliable person).'),
  'すっかり': VocabUsage('やくそく を すっかり わすれて いました', 'yakusoku o sukkari wasurete imashita', 'Saya benar-benar lupa janjinya.', 'I completely forgot about the appointment.', 'Keterangan \'sepenuhnya\'. Sering dengan perubahan/lupa: すっかり わすれる, すっかり よく なる.', 'Adverb \'completely\'. Often with change or forgetting: すっかり わすれる, すっかり よく なる.'),
  'ずっと': VocabUsage('あさ から ずっと あめ が ふって います', 'asa kara zutto ame ga futte imasu', 'Hujan terus turun sejak pagi.', 'It has been raining all day since morning.', 'Keterangan. \'Terus-menerus\' (dengan ～ている) atau \'jauh lebih\' dalam perbandingan: ずっと たかい.', 'Adverb. \'All along\' (with ～ている) or \'by far\' in comparisons: ずっと たかい.'),
  'とうとう': VocabUsage('とうとう かれ は きません でした', 'toutou kare wa kimasen deshita', 'Pada akhirnya dia tidak datang.', 'In the end he didn\'t come.', 'Keterangan. Hasil akhir setelah lama, bisa positif atau negatif. Beda: やっと hanya untuk hasil yang diharapkan.', 'Adverb. Final outcome after a long time, good or bad. やっと is only for hoped-for results.'),
  'やっと': VocabUsage('やっと しゅくだい が おわりました', 'yatto shukudai ga owarimashita', 'Akhirnya PR saya selesai.', 'I finally finished my homework.', 'Keterangan. Hasil yang ditunggu setelah susah payah, dengan rasa lega.', 'Adverb. A long-awaited result after effort, with relief.'),
  'もし': VocabUsage('もし あめ が ふったら いきません', 'moshi ame ga futtara ikimasen', 'Jika hujan, saya tidak pergi.', 'If it rains, I won\'t go.', 'Keterangan pengandaian. Berpasangan dengan ～たら/～ば/～なら.', 'Conditional adverb. Paired with ～たら/～ば/～なら.'),
  'もちろん': VocabUsage('もちろん いっしょ に いきます', 'mochiron issho ni ikimasu', 'Tentu saja saya ikut bersama.', 'Of course I\'ll go with you.', 'Keterangan. Bisa berdiri sendiri sebagai jawaban: もちろん です.', 'Adverb. Can stand alone as an answer: もちろん です.'),
  'やはり': VocabUsage('やはり この みせ の ラーメン が いちばん です', 'yahari kono mise no raamen ga ichiban desu', 'Ternyata ramen toko ini memang yang terbaik.', 'As expected, this shop\'s ramen is the best.', 'Keterangan \'sudah kuduga/tetap saja\'. Versi santai: やっぱり.', 'Adverb \'as expected/after all\'. Casual: やっぱり.'),
  'ほとんど': VocabUsage('しゅくだい は ほとんど おわりました', 'shukudai wa hotondo owarimashita', 'PR-nya hampir semua selesai.', 'My homework is almost done.', 'Keterangan/kata benda. ほとんど の [kata benda] = sebagian besar; dengan negatif: hampir tidak.', 'Adverb/noun. ほとんど の [noun] = most; with negative: hardly.'),
  'はっきり': VocabUsage('もう すこし はっきり いって ください', 'mou sukoshi hakkiri itte kudasai', 'Tolong katakan dengan lebih jelas.', 'Please say it a bit more clearly.', 'Keterangan. Dengan する: はっきり する (menjadi jelas). Untuk suara, jawaban, penglihatan.', 'Adverb. With する: はっきり する (become clear). For speech, answers, sight.'),
  'そろそろ': VocabUsage('そろそろ かえりましょう', 'sorosoro kaerimashou', 'Sudah waktunya kita pulang.', 'It\'s about time we went home.', 'Keterangan. Ungkapan pamit: そろそろ しつれい します (saya pamit dulu).', 'Adverb. Leave-taking phrase: そろそろ しつれい します (I should be going).'),
