  'むすぶ': VocabUsage('くつ の ひも を むすんで ください', 'kutsu no himo o musunde kudasai', 'Tolong ikat tali sepatumu.', 'Please tie your shoelaces.', 'Kata kerja gol. I. Bentuk sopan: むすびます. Pola: ひも を むすぶ; A と B を むすぶ (menghubungkan).', 'Group 1 verb. Polite: むすびます. Patterns: ひも を むすぶ; A と B を むすぶ (link).'),
  'もうしこむ': VocabUsage('らいげつ の しけん に もうしこみました', 'raigetsu no shiken ni moushikomimashita', 'Saya sudah mendaftar ujian bulan depan.', 'I applied for next month\'s exam.', 'Kata kerja gol. I. Bentuk sopan: もうしこみます. Pola: [acara] に もうしこむ. Nomina: もうしこみ.', 'Group 1 verb. Polite: もうしこみます. Pattern: [event] に もうしこむ. Noun: もうしこみ.'),
  'もやす': VocabUsage('もやす ごみ は げつようび に だします', 'moyasu gomi wa getsuyoubi ni dashimasu', 'Sampah bakar dibuang hari Senin.', 'Burnable garbage goes out on Mondays.', 'Kata kerja gol. I, transitif. Bentuk sopan: もやします. Intransitif: もえる; もえる ごみ juga umum.', 'Group 1 transitive verb. Polite: もやします. Intransitive: もえる; もえる ごみ is also common.'),
  'ゆずる': VocabUsage('でんしゃ で おとしより に せき を ゆずりました', 'densha de otoshiyori ni seki o yuzurimashita', 'Saya memberikan kursi kepada lansia di kereta.', 'I gave up my seat to an elderly person on the train.', 'Kata kerja gol. I. Bentuk sopan: ゆずります. Pola: [orang] に せき/みち を ゆずる.', 'Group 1 verb. Polite: ゆずります. Pattern: [person] に せき/みち を ゆずる.'),
  'わける': VocabUsage('ごみ を みっつ に わけて ください', 'gomi o mittsu ni wakete kudasai', 'Tolong pilah sampah menjadi tiga.', 'Please sort the garbage into three groups.', 'Kata kerja gol. II. Bentuk sopan: わけます. Pola: [benda] を [jumlah] に わける.', 'Group 2 verb. Polite: わけます. Pattern: [thing] を [number] に わける.'),
  'あずける': VocabUsage('ホテル に にもつ を あずけました', 'hoteru ni nimotsu o azukemashita', 'Saya menitipkan barang di hotel.', 'I left my luggage with the hotel.', 'Kata kerja gol. II. Bentuk sopan: あずけます. Pola: [orang/tempat] に [barang] を あずける.', 'Group 2 verb. Polite: あずけます. Pattern: [person/place] に [item] を あずける.'),
  'あずかる': VocabUsage('となり の ひと の いぬ を あずかって います', 'tonari no hito no inu o azukatte imasu', 'Saya sedang dititipi anjing tetangga.', 'I\'m looking after my neighbor\'s dog.', 'Kata kerja gol. I. Bentuk sopan: あずかります. Kebalikan arah dari あずける (pihak penerima titipan).', 'Group 1 verb. Polite: あずかります. Receiving side of あずける.'),
  'あわてる': VocabUsage('じしん の とき は あわてないで ください', 'jishin no toki wa awatenaide kudasai', 'Saat gempa, jangan panik.', 'Please don\'t panic during an earthquake.', 'Kata kerja gol. II. Bentuk sopan: あわてます. Sering: あわてないで, あわてて (buru-buru).', 'Group 2 verb. Polite: あわてます. Common: あわてないで, あわてて (in a hurry).'),
  'いわう': VocabUsage('みんな で ちち の たんじょうび を いわいました', 'minna de chichi no tanjoubi o iwaimashita', 'Kami semua merayakan ulang tahun ayah.', 'We all celebrated my father\'s birthday.', 'Kata kerja gol. I. Bentuk sopan: いわいます. Nomina: おいわい (perayaan/hadiah ucapan selamat).', 'Group 1 verb. Polite: いわいます. Noun: おいわい (celebration/congratulatory gift).'),
