  'そんけいする': VocabUsage('わたし は ちち を そんけいして います', 'watashi wa chichi o sonkei shite imasu', 'Saya menghormati ayah saya.', 'I respect my father.', 'Kata kerja gol. III. Bentuk sopan: そんけいします. Pola: [orang] を そんけいする; biasa ～ている.', 'Group 3 verb. Polite: そんけいします. Pattern: [person] を そんけいする; usually ～ている.'),
  'はんだんする': VocabUsage('じぶん で はんだんして ください', 'jibun de handan shite kudasai', 'Silakan nilai sendiri.', 'Please judge for yourself.', 'Kata kerja gol. III. Bentuk sopan: はんだんします. Pola: [hal] を はんだんする; はんだん が むずかしい.', 'Group 3 verb. Polite: はんだんします. Pattern: [thing] を はんだんする; はんだん が むずかしい.'),
  'よそうする': VocabUsage('せんもんか は ねだん が あがる と よそうして いる', 'senmonka wa nedan ga agaru to yosou shite iru', 'Para ahli memperkirakan harga akan naik.', 'Experts predict that prices will rise.', 'Kata kerja gol. III. Bentuk sopan: よそうします. Pola: よそう どおり (sesuai perkiraan), よそう より ～.', 'Group 3 verb. Polite: よそうします. Patterns: よそう どおり (as expected), よそう より ～.'),
  'ゆたか': VocabUsage('この くに は しぜん が ゆたか です', 'kono kuni wa shizen ga yutaka desu', 'Negara ini kaya akan alam.', 'This country is rich in nature.', 'Kata sifat な. Pola: [hal] が ゆたか だ, ゆたかな せいかつ (hidup makmur).', 'な-adjective. Patterns: [thing] が ゆたか だ, ゆたかな せいかつ (affluent life).'),
  'びんぼう': VocabUsage('がくせい の とき は びんぼう でした', 'gakusei no toki wa binbou deshita', 'Waktu mahasiswa saya miskin.', 'I was poor when I was a student.', 'Kata sifat な/kata benda, agak santai. Pola: びんぼうな せいかつ. Lawan: おかねもち.', 'な-adjective/noun, a bit casual. Pattern: びんぼうな せいかつ. Opposite: おかねもち.'),
  'ふくざつな': VocabUsage('この もんだい は とても ふくざつな もんだい です', 'kono mondai wa totemo fukuzatsuna mondai desu', 'Masalah ini adalah masalah yang sangat rumit.', 'This is a very complex problem.', 'Kata sifat な (ふくざつ). Pola: ふくざつな [benda]; lawan: たんじゅん. ふくざつな きもち = perasaan campur aduk.', 'な-adjective (ふくざつ). Pattern: ふくざつな [noun]; opposite: たんじゅん. ふくざつな きもち = mixed feelings.'),
  'たんじゅん': VocabUsage('この ゲーム の ルール は たんじゅん です', 'kono geemu no ruuru wa tanjun desu', 'Aturan game ini sederhana.', 'The rules of this game are simple.', 'Kata sifat な. Lawan: ふくざつ. Bisa bernada \'naif\' untuk orang: たんじゅんな ひと.', 'な-adjective. Opposite: ふくざつ. For people can mean \'naive\': たんじゅんな ひと.'),
  '正確': VocabUsage('じかん を せいかく に はかって ください', 'jikan o seikaku ni hakatte kudasai', 'Tolong ukur waktunya dengan akurat.', 'Please measure the time accurately.', 'Kata sifat な (せいかく). Pola: せいかくな じょうほう, せいかく に (secara akurat). Homofon: watak.', 'な-adjective (せいかく). Patterns: せいかくな じょうほう, せいかく に (accurately). Homophone: personality.'),
  'あいまい': VocabUsage('かれ の こたえ は いつも あいまい だ', 'kare no kotae wa itsumo aimai da', 'Jawabannya selalu ambigu.', 'His answers are always vague.', 'Kata sifat な. Pola: あいまいな こたえ/へんじ; lawan: はっきり した.', 'な-adjective. Pattern: あいまいな こたえ/へんじ; opposite: はっきり した.'),
  'せっきょくてき': VocabUsage('かのじょ は じゅぎょう で せっきょくてき に はつげん する', 'kanojo wa jugyou de sekkyokuteki ni hatsugen suru', 'Dia aktif berbicara di kelas.', 'She actively speaks up in class.', 'Kata sifat な (～てき). Pola: せっきょくてき に ～する, せっきょくてきな ひと. Lawan: しょうきょくてき.', 'な-adjective (～てき). Patterns: せっきょくてき に ～する, せっきょくてきな ひと. Opposite: しょうきょくてき.'),
  'しょうきょくてき': VocabUsage('かれ は あたらしい こと に しょうきょくてき だ', 'kare wa atarashii koto ni shoukyokuteki da', 'Dia pasif terhadap hal-hal baru.', 'He is passive about new things.', 'Kata sifat な (～てき). Pola: [hal] に しょうきょくてき だ. Lawan: せっきょくてき.', 'な-adjective (～てき). Pattern: [thing] に しょうきょくてき だ. Opposite: せっきょくてき.'),
  'こうへい': VocabUsage('せんせい は せいと を こうへい に あつかう', 'sensei wa seito o kouhei ni atsukau', 'Guru memperlakukan murid dengan adil.', 'The teacher treats students fairly.', 'Kata sifat な. Pola: こうへい に (secara adil), こうへいな はんだん. Lawan: ふこうへい.', 'な-adjective. Patterns: こうへい に (fairly), こうへいな はんだん. Opposite: ふこうへい.'),
  'ふこうへい': VocabUsage('おとこ と おんな で きゅうりょう が ちがう の は ふこうへい だ', 'otoko to onna de kyuuryou ga chigau no wa fukouhei da', 'Gaji yang berbeda antara pria dan wanita itu tidak adil.', 'It\'s unfair that men and women get different pay.', 'Kata sifat な (ふ + こうへい). Pola: ～の は ふこうへい だ, ふこうへいな あつかい.', 'な-adjective (ふ + こうへい). Patterns: ～の は ふこうへい だ, ふこうへいな あつかい.'),
  'じゅうよう': VocabUsage('これ は とても じゅうような しょるい です', 'kore wa totemo juuyouna shorui desu', 'Ini dokumen yang sangat penting.', 'This is a very important document.', 'Kata sifat な, lebih formal dari たいせつ/だいじ. Pola: じゅうような [benda].', 'な-adjective, more formal than たいせつ/だいじ. Pattern: じゅうような [noun].'),
  'きちょう': VocabUsage('きちょうな けいけん を させて いただきました', 'kichouna keiken o sasete itadakimashita', 'Saya mendapat pengalaman yang berharga.', 'I was given a valuable experience.', 'Kata sifat な. Kolokasi: きちょうな けいけん/じかん/いけん; きちょうひん = barang berharga.', 'な-adjective. Collocations: きちょうな けいけん/じかん/いけん; きちょうひん = valuables.'),
  'きけんな': VocabUsage('よる ひとり で あるく の は きけんな こと です', 'yoru hitori de aruku no wa kikenna koto desu', 'Berjalan sendirian di malam hari itu berisiko.', 'Walking alone at night is risky.', 'Kata sifat な (きけん). Lebih formal dari あぶない; sering di papan peringatan: きけん.', 'な-adjective (きけん). More formal than あぶない; seen on warning signs: きけん.'),
  'すなお': VocabUsage('あの こ は すなおで いい こ です', 'ano ko wa sunao de ii ko desu', 'Anak itu penurut dan baik.', 'That child is obedient and good.', 'Kata sifat な. Pola: すなおな ひと, すなお に (dengan jujur/terbuka) あやまる.', 'な-adjective. Patterns: すなおな ひと, すなお に (frankly) あやまる.'),
  'しょうじき': VocabUsage('しょうじき に はなして ください', 'shoujiki ni hanashite kudasai', 'Tolong bicara dengan jujur.', 'Please speak honestly.', 'Kata sifat な/adverbia. Pola: しょうじき に (dengan jujur), しょうじき いって (terus terang).', 'な-adjective/adverb. Patterns: しょうじき に (honestly), しょうじき いって (frankly speaking).'),
  'らくてん': VocabUsage('かれ は らくてんてき な せいかく です', 'kare wa rakutenteki na seikaku desu', 'Dia berwatak optimis.', 'He has an optimistic personality.', 'Kata benda; sering jadi らくてんてき (な). Lawan: ひかん/ひかんてき (pesimis).', 'Noun; usually らくてんてき (な). Opposite: ひかん/ひかんてき (pessimistic).'),
  'しんちょう': VocabUsage('かれ は なにごと に も しんちょう です', 'kare wa nanigoto ni mo shinchou desu', 'Dia berhati-hati dalam segala hal.', 'He is cautious about everything.', 'Kata sifat な. Pola: しんちょう に (dengan hati-hati) かんがえる. Homofon しんちょう = tinggi badan.', 'な-adjective. Pattern: しんちょう に かんがえる (think carefully). Homophone しんちょう = height.'),
};

const Map<String, VocabUsage> vocabUsageEn = {
  'analyze': VocabUsage('The researchers analyzed the survey data to identify common patterns.', '', 'Para peneliti menganalisis data survei untuk menemukan pola umum.', '', 'Kata kerja. Kolokasi: analyze data/results/trends. Nomina: analysis; ahli: analyst.', 'Verb. Collocations: analyze data/results/trends. Noun: analysis; person: analyst.'),
  'approach': VocabUsage('This study takes a new approach to measuring student motivation.', '', 'Penelitian ini memakai pendekatan baru untuk mengukur motivasi siswa.', '', 'Nomina/verba. Pola: an approach to + noun/V-ing. Sebagai verba tanpa \'to\': approach the problem.', 'Noun/verb. Pattern: an approach to + noun/V-ing. As a verb, no \'to\': approach the problem.'),
  'area': VocabUsage('Rural areas often have limited access to quality health care.', '', 'Daerah pedesaan sering memiliki akses terbatas ke layanan kesehatan yang baik.', '', 'Nomina. Bisa berarti wilayah (rural area) atau bidang ilmu (area of research).', 'Noun. Means a place (rural area) or a field of study (area of research).'),
  'assess': VocabUsage('Teachers assess each student\'s progress at the end of the term.', '', 'Guru menilai kemajuan setiap siswa di akhir semester.', '', 'Kata kerja. Kolokasi: assess the impact/risk/progress. Nomina: assessment.', 'Verb. Collocations: assess the impact/risk/progress. Noun: assessment.'),
  'assume': VocabUsage('Many people assume that economic growth always reduces poverty.', '', 'Banyak orang menganggap pertumbuhan ekonomi selalu mengurangi kemiskinan.', '', 'Kata kerja. Pola: assume that + klausa. Nomina: assumption. Sering bernuansa \'tanpa bukti\'.', 'Verb. Pattern: assume that + clause. Noun: assumption. Often implies \'without proof\'.'),
  'authority': VocabUsage('Local authorities have the authority to close schools during floods.', '', 'Pemerintah daerah berwenang menutup sekolah saat banjir.', '', 'Nomina. Pola: have the authority to + V. Jamak \'the authorities\' = pihak berwenang.', 'Noun. Pattern: have the authority to + verb. Plural \'the authorities\' = officials.'),
  'available': VocabUsage('The full report is available on the university website.', '', 'Laporan lengkapnya tersedia di situs web universitas.', '', 'Adjektiva. Pola: available to/for + orang; available on/at + tempat. Nomina: availability.', 'Adjective. Pattern: available to/for someone; available on/at a place. Noun: availability.'),
  'benefit': VocabUsage('Regular exercise has many benefits for both physical and mental health.', '', 'Olahraga teratur punya banyak manfaat bagi kesehatan fisik dan mental.', '', 'Nomina/verba. Pola: the benefit of X; benefit from X. Adjektiva: beneficial.', 'Noun/verb. Patterns: the benefit of X; benefit from X. Adjective: beneficial.'),
  'concept': VocabUsage('The concept of sustainability is central to modern urban planning.', '', 'Konsep keberlanjutan menjadi inti perencanaan kota modern.', '', 'Nomina. Pola: the concept of + noun. Adjektiva: conceptual.', 'Noun. Pattern: the concept of + noun. Adjective: conceptual.'),
  'consist': VocabUsage('The committee consists of five experts from different universities.', '', 'Komite itu terdiri dari lima pakar dari berbagai universitas.', '', 'Kata kerja. Selalu \'consist of\'; tidak dipakai bentuk pasif atau -ing progresif.', 'Verb. Always \'consist of\'; not used in passive or progressive form.'),
  'constitute': VocabUsage('Women constitute nearly half of the country\'s workforce.', '', 'Perempuan merupakan hampir separuh angkatan kerja negara itu.', '', 'Kata kerja formal, mirip \'make up\'. Nomina: constitution (juga berarti UUD).', 'Formal verb, similar to \'make up\'. Noun: constitution (also a national charter).'),
  'context': VocabUsage('Words can have different meanings depending on their context.', '', 'Kata bisa bermakna berbeda tergantung konteksnya.', '', 'Nomina. Pola: in the context of + noun; out of context. Adjektiva: contextual.', 'Noun. Patterns: in the context of + noun; out of context. Adjective: contextual.'),
  'contract': VocabUsage('Both companies signed a three-year contract to share research costs.', '', 'Kedua perusahaan menandatangani kontrak tiga tahun untuk berbagi biaya riset.', '', 'Nomina. Kolokasi: sign/break/renew a contract. Pihak: contractor.', 'Noun. Collocations: sign/break/renew a contract. Person: contractor.'),
  'create': VocabUsage('The new policy aims to create more jobs for young graduates.', '', 'Kebijakan baru ini bertujuan menciptakan lebih banyak lapangan kerja bagi lulusan muda.', '', 'Kata kerja. Kolokasi: create jobs/opportunities/problems. Nomina: creation; adj: creative.', 'Verb. Collocations: create jobs/opportunities/problems. Noun: creation; adj: creative.'),
  'data': VocabUsage('The data clearly show a rise in online shopping since 2020.', '', 'Data dengan jelas menunjukkan kenaikan belanja daring sejak 2020.', '', 'Nomina. Akademik sering jamak (the data show), sehari-hari tunggal (the data shows).', 'Noun. Academic style often plural (the data show); everyday use singular (shows).'),
  'define': VocabUsage('It is important to define key terms at the start of an essay.', '', 'Penting untuk mendefinisikan istilah kunci di awal esai.', '', 'Kata kerja. Pola: define X as Y. Nomina: definition.', 'Verb. Pattern: define X as Y. Noun: definition.'),
  'derive': VocabUsage('Many English words are derived from Latin and Greek.', '', 'Banyak kata bahasa Inggris berasal dari bahasa Latin dan Yunani.', '', 'Kata kerja. Pola: derive X from Y; be derived from. Nomina: derivation.', 'Verb. Patterns: derive X from Y; be derived from. Noun: derivation.'),
  'distribute': VocabUsage('Volunteers distributed food and water to families affected by the flood.', '', 'Para relawan membagikan makanan dan air kepada keluarga korban banjir.', '', 'Kata kerja. Pola: distribute X to/among Y. Nomina: distribution.', 'Verb. Pattern: distribute X to/among Y. Noun: distribution.'),
  'economy': VocabUsage('Tourism plays a key role in the local economy.', '', 'Pariwisata berperan penting dalam ekonomi lokal.', '', 'Nomina. Adj: economic (terkait ekonomi) vs economical (hemat). Ahli: economist.', 'Noun. Adj: economic (about the economy) vs economical (saving money). Person: economist.'),
  'environment': VocabUsage('Plastic waste causes serious damage to the marine environment.', '', 'Sampah plastik menyebabkan kerusakan serius pada lingkungan laut.', '', 'Nomina. Kolokasi: protect/damage the environment. Adj: environmental.', 'Noun. Collocations: protect/damage the environment. Adjective: environmental.'),
  'establish': VocabUsage('The university was established in 1950 to train future teachers.', '', 'Universitas itu didirikan pada tahun 1950 untuk mendidik calon guru.', '', 'Kata kerja. Arti \'mendirikan\' (lembaga) atau \'menetapkan/membuktikan\' (establish a link).', 'Verb. Means \'found\' (an institution) or \'prove/set up\' (establish a link).'),
  'estimate': VocabUsage('Experts estimate that the population will reach ten million by 2040.', '', 'Para ahli memperkirakan populasi akan mencapai sepuluh juta pada 2040.', '', 'Kata kerja/nomina. Pola: estimate that + klausa; a rough estimate. Ucapan nomina akhir -mat.', 'Verb/noun. Patterns: estimate that + clause; a rough estimate. Noun ends in -mət sound.'),
  'evident': VocabUsage('It is evident from the results that the treatment was effective.', '', 'Dari hasilnya jelas terlihat bahwa pengobatan itu efektif.', '', 'Adjektiva. Pola: it is evident that... Nomina: evidence (bukti, tak berbilang).', 'Adjective. Pattern: it is evident that... Noun: evidence (uncountable).'),
  'export': VocabUsage('Indonesia exports large amounts of palm oil and coffee every year.', '', 'Indonesia mengekspor kelapa sawit dan kopi dalam jumlah besar setiap tahun.', '', 'Nomina/verba. Lawan: import. Tekanan nomina EX-port, verba ex-PORT.', 'Noun/verb. Opposite: import. Stress: noun EX-port, verb ex-PORT.'),
  'factor': VocabUsage('Cost is the main factor when students choose a university.', '', 'Biaya adalah faktor utama saat siswa memilih universitas.', '', 'Nomina. Kolokasi: a key/major factor in + noun/V-ing; risk factor.', 'Noun. Collocations: a key/major factor in + noun/V-ing; risk factor.'),
  'finance': VocabUsage('The project was financed by a grant from the government.', '', 'Proyek itu dibiayai oleh hibah dari pemerintah.', '', 'Nomina/verba. Verba = membiayai. Adj: financial; jamak \'finances\' = kondisi keuangan.', 'Noun/verb. Verb = to fund. Adj: financial; plural \'finances\' = money situation.'),
  'formula': VocabUsage('Students must use the correct formula to calculate the area.', '', 'Siswa harus memakai rumus yang benar untuk menghitung luas.', '', 'Nomina. Jamak: formulas atau formulae (akademik). Pola: a formula for + noun.', 'Noun. Plural: formulas or formulae (academic). Pattern: a formula for + noun.'),
  'function': VocabUsage('The main function of the kidneys is to filter the blood.', '', 'Fungsi utama ginjal adalah menyaring darah.', '', 'Nomina/verba. Pola: function as + noun (berfungsi sebagai). Adj: functional.', 'Noun/verb. Pattern: function as + noun. Adjective: functional.'),
  'identify': VocabUsage('The study identified three main causes of traffic accidents.', '', 'Penelitian itu mengidentifikasi tiga penyebab utama kecelakaan lalu lintas.', '', 'Kata kerja. Pola: identify X as Y; identify with (merasa sama). Nomina: identification.', 'Verb. Patterns: identify X as Y; identify with (relate to). Noun: identification.'),
  'income': VocabUsage('Families with a low income often struggle to pay for education.', '', 'Keluarga berpenghasilan rendah sering kesulitan membiayai pendidikan.', '', 'Nomina. Kolokasi: low/high income, annual income, income tax. Beda: salary = gaji tetap.', 'Noun. Collocations: low/high income, annual income, income tax. Salary = fixed pay.'),
  'indicate': VocabUsage('Recent figures indicate that unemployment is slowly falling.', '', 'Angka terbaru menunjukkan bahwa pengangguran perlahan menurun.', '', 'Kata kerja. Pola: indicate that + klausa. Nomina: indication, indicator.', 'Verb. Pattern: indicate that + clause. Nouns: indication, indicator.'),
  'individual': VocabUsage('Each individual has the right to express their opinion.', '', 'Setiap individu berhak menyampaikan pendapatnya.', '', 'Nomina/adjektiva. Adj: individual needs (kebutuhan tiap orang). Adv: individually.', 'Noun/adjective. Adj: individual needs. Adverb: individually.'),
  'interpret': VocabUsage('Researchers may interpret the same results in different ways.', '', 'Peneliti bisa menafsirkan hasil yang sama dengan cara berbeda.', '', 'Kata kerja. Pola: interpret X as Y. Nomina: interpretation; penerjemah lisan: interpreter.', 'Verb. Pattern: interpret X as Y. Nouns: interpretation; interpreter (oral translator).'),
  'involve': VocabUsage('The project involves collecting data from over two hundred schools.', '', 'Proyek itu melibatkan pengumpulan data dari lebih dari dua ratus sekolah.', '', 'Kata kerja. Pola: involve + V-ing; be involved in. Nomina: involvement.', 'Verb. Patterns: involve + V-ing; be involved in. Noun: involvement.'),
  'issue': VocabUsage('Climate change is one of the most urgent issues of our time.', '', 'Perubahan iklim adalah salah satu isu paling mendesak di zaman kita.', '', 'Nomina. Kolokasi: address/raise an issue; a key issue. Lebih netral daripada \'problem\'.', 'Noun. Collocations: address/raise an issue; a key issue. More neutral than \'problem\'.'),
  'labor': VocabUsage('The factory moved overseas to take advantage of cheaper labor.', '', 'Pabrik itu pindah ke luar negeri untuk memanfaatkan tenaga kerja yang lebih murah.', '', 'Nomina. Ejaan Inggris Britania: labour. Kolokasi: labor market, labor force, manual labor.', 'Noun. British spelling: labour. Collocations: labor market, labor force, manual labor.'),
  'legal': VocabUsage('The company sought legal advice before signing the agreement.', '', 'Perusahaan itu meminta nasihat hukum sebelum menandatangani perjanjian.', '', 'Adjektiva: sah/terkait hukum. Lawan: illegal. Kolokasi: legal advice/action/system.', 'Adjective: lawful or relating to law. Opposite: illegal. Collocations: legal advice/action.'),
  'legislate': VocabUsage('Governments should legislate to protect workers from unsafe conditions.', '', 'Pemerintah sebaiknya membuat undang-undang untuk melindungi pekerja dari kondisi tidak aman.', '', 'Kata kerja formal. Pola: legislate for/against + noun. Nomina: legislation (tak berbilang).', 'Formal verb. Pattern: legislate for/against + noun. Noun: legislation (uncountable).'),
  'major': VocabUsage('Air pollution is a major cause of respiratory disease in cities.', '', 'Polusi udara adalah penyebab utama penyakit pernapasan di kota.', '', 'Adjektiva: besar/penting. Lawan: minor. Nomina AS: jurusan kuliah (my major is biology).', 'Adjective: large/important. Opposite: minor. US noun: field of study (my major).'),
  'method': VocabUsage('The scientists tested a new method for cleaning polluted water.', '', 'Para ilmuwan menguji metode baru untuk membersihkan air tercemar.', '', 'Nomina. Pola: a method of/for + V-ing. Adj: methodical; nomina: methodology.', 'Noun. Pattern: a method of/for + V-ing. Adj: methodical; noun: methodology.'),
  'occur': VocabUsage('Most road accidents occur during the evening rush hour.', '', 'Sebagian besar kecelakaan jalan terjadi saat jam sibuk sore hari.', '', 'Kata kerja intransitif, formal dari \'happen\'. Ejaan: occurred, occurring. Nomina: occurrence.', 'Intransitive verb, formal for \'happen\'. Spelling: occurred, occurring. Noun: occurrence.'),
  'percent': VocabUsage('About sixty percent of the respondents preferred online classes.', '', 'Sekitar enam puluh persen responden lebih memilih kelas daring.', '', 'Nomina/adv. Selalu tunggal: 20 percent. Nomina terkait: percentage (tanpa angka).', 'Noun/adverb. Always singular: 20 percent. Related: percentage (used without a number).'),
  'period': VocabUsage('Prices remained stable over a period of five years.', '', 'Harga tetap stabil selama periode lima tahun.', '', 'Nomina. Pola: over/for a period of + waktu. Adj: periodic (berkala).', 'Noun. Pattern: over/for a period of + time. Adjective: periodic.'),
  'policy': VocabUsage('The government introduced a new policy to reduce plastic use.', '', 'Pemerintah memperkenalkan kebijakan baru untuk mengurangi penggunaan plastik.', '', 'Nomina. Kolokasi: introduce/implement a policy; policy on + topik. Beda: politics = politik.', 'Noun. Collocations: introduce/implement a policy; policy on + topic. Not \'politics\'.'),
  'principle': VocabUsage('Equality is a basic principle of a democratic society.', '', 'Kesetaraan adalah prinsip dasar masyarakat demokratis.', '', 'Nomina. Pola: in principle (pada dasarnya). Jangan tertukar dengan \'principal\' (utama/kepala).', 'Noun. Phrase: in principle. Don\'t confuse with \'principal\' (main/head).'),
  'proceed': VocabUsage('After the break, the committee proceeded with the discussion.', '', 'Setelah jeda, komite melanjutkan diskusi.', '', 'Kata kerja formal. Pola: proceed with + noun; proceed to + V. Nomina: procedure, proceedings.', 'Formal verb. Patterns: proceed with + noun; proceed to + verb. Nouns: procedure.'),
  'process': VocabUsage('Learning a new language is a slow but rewarding process.', '', 'Belajar bahasa baru adalah proses yang lambat tetapi memuaskan.', '', 'Nomina/verba. Pola: in the process of + V-ing. Verba: process data (mengolah).', 'Noun/verb. Pattern: in the process of + V-ing. Verb: process data.'),
  'require': VocabUsage('All applicants are required to submit a recent photograph.', '', 'Semua pelamar diwajibkan menyerahkan foto terbaru.', '', 'Kata kerja formal. Pola: be required to + V; require + noun. Nomina: requirement.', 'Formal verb. Patterns: be required to + verb; require + noun. Noun: requirement.'),
  'research': VocabUsage('Recent research shows that sleep affects memory and learning.', '', 'Penelitian terbaru menunjukkan bahwa tidur memengaruhi daya ingat dan belajar.', '', 'Nomina tak berbilang (bukan \'a research\'). Pola: research on/into + topik. Orang: researcher.', 'Uncountable noun (not \'a research\'). Pattern: research on/into + topic. Person: researcher.'),
  'respond': VocabUsage('The company responded quickly to customer complaints.', '', 'Perusahaan itu cepat menanggapi keluhan pelanggan.', '', 'Kata kerja. Pola: respond to + noun. Nomina: response; responden: respondent.', 'Verb. Pattern: respond to + noun. Nouns: response; respondent.'),
  'role': VocabUsage('Parents play an important role in their children\'s education.', '', 'Orang tua berperan penting dalam pendidikan anak.', '', 'Nomina. Kolokasi: play a role in + noun/V-ing; role model (teladan).', 'Noun. Collocations: play a role in + noun/V-ing; role model.'),
  'section': VocabUsage('The final section of the report presents the recommendations.', '', 'Bagian akhir laporan menyajikan rekomendasi.', '', 'Nomina. Untuk bagian teks, tempat, atau kelompok. Pola: in section 3; a section of.', 'Noun. Used for parts of texts, places or groups. Patterns: in section 3; a section of.'),
  'sector': VocabUsage('The service sector employs most workers in developed countries.', '', 'Sektor jasa mempekerjakan sebagian besar pekerja di negara maju.', '', 'Nomina. Kolokasi: public/private sector, the energy/health sector.', 'Noun. Collocations: public/private sector, the energy/health sector.'),
  'significant': VocabUsage('There was a significant increase in sales after the campaign.', '', 'Terjadi kenaikan penjualan yang berarti setelah kampanye itu.', '', 'Adjektiva. Kolokasi: significant increase/difference/impact. Adv: significantly.', 'Adjective. Collocations: significant increase/difference/impact. Adverb: significantly.'),
  'similar': VocabUsage('The two studies reached similar conclusions about diet and health.', '', 'Kedua penelitian mencapai kesimpulan yang mirip tentang pola makan dan kesehatan.', '', 'Adjektiva. Pola: similar to + noun (bukan \'similar with\'). Nomina: similarity.', 'Adjective. Pattern: similar to + noun (not \'similar with\'). Noun: similarity.'),
  'source': VocabUsage('Solar power is a clean source of energy.', '', 'Tenaga surya adalah sumber energi yang bersih.', '', 'Nomina. Pola: a source of + noun. Kolokasi: reliable source, energy source.', 'Noun. Pattern: a source of + noun. Collocations: reliable source, energy source.'),
  'specific': VocabUsage('The teacher gave specific instructions for the group project.', '', 'Guru memberi instruksi khusus untuk proyek kelompok.', '', 'Adjektiva: khusus/rinci. Pola: specific to + noun. Lawan: general. Adv: specifically.', 'Adjective: particular/detailed. Pattern: specific to + noun. Opposite: general.'),
  'structure': VocabUsage('The essay has a clear structure with an introduction and conclusion.', '', 'Esai itu memiliki struktur yang jelas dengan pendahuluan dan kesimpulan.', '', 'Nomina/verba. Kolokasi: social structure, sentence structure. Adj: structural.', 'Noun/verb. Collocations: social structure, sentence structure. Adjective: structural.'),
  'theory': VocabUsage('Darwin\'s theory of evolution changed the way we see nature.', '', 'Teori evolusi Darwin mengubah cara kita memandang alam.', '', 'Nomina. Pola: a theory of/about; in theory (secara teori). Adj: theoretical.', 'Noun. Patterns: a theory of/about; in theory. Adjective: theoretical.'),
  'vary': VocabUsage('Prices vary greatly from one region to another.', '', 'Harga sangat bervariasi dari satu daerah ke daerah lain.', '', 'Kata kerja. Pola: vary from X to Y; vary in + noun. Nomina: variation, variety.', 'Verb. Patterns: vary from X to Y; vary in + noun. Nouns: variation, variety.'),
  'achieve': VocabUsage('Hard work helped her achieve the highest score in the class.', '', 'Kerja keras membantunya meraih nilai tertinggi di kelas.', '', 'Kata kerja. Kolokasi: achieve a goal/success/results. Nomina: achievement.', 'Verb. Collocations: achieve a goal/success/results. Noun: achievement.'),
  'acquire': VocabUsage('Children acquire language naturally through daily interaction.', '', 'Anak-anak memperoleh bahasa secara alami melalui interaksi sehari-hari.', '', 'Kata kerja formal dari \'get\'. Kolokasi: acquire skills/knowledge. Nomina: acquisition.', 'Formal verb for \'get\'. Collocations: acquire skills/knowledge. Noun: acquisition.'),
  'administrate': VocabUsage('A small team administrates the scholarship program for the whole region.', '', 'Tim kecil mengelola program beasiswa untuk seluruh daerah.', '', 'Kata kerja; lebih umum \'administer\'. Nomina: administration; orang: administrator.', 'Verb; \'administer\' is more common. Noun: administration; person: administrator.'),
  'affect': VocabUsage('Lack of sleep can seriously affect students\' concentration.', '', 'Kurang tidur bisa sangat memengaruhi konsentrasi siswa.', '', 'Kata kerja (affect) vs nomina \'effect\'. Pola: affect + objek langsung, tanpa \'on\'.', 'Verb (affect) vs noun \'effect\'. Pattern: affect + direct object, no \'on\'.'),
  'appropriate': VocabUsage('Formal language is more appropriate for academic writing.', '', 'Bahasa formal lebih pantas untuk tulisan akademik.', '', 'Adjektiva. Pola: appropriate for/to + noun. Lawan: inappropriate.', 'Adjective. Pattern: appropriate for/to + noun. Opposite: inappropriate.'),
  'aspect': VocabUsage('The course covers every aspect of running a small business.', '', 'Kursus itu membahas setiap aspek menjalankan usaha kecil.', '', 'Nomina. Pola: an aspect of + noun. Kolokasi: key/important aspect.', 'Noun. Pattern: an aspect of + noun. Collocations: key/important aspect.'),
  'assist': VocabUsage('Teaching assistants assist lecturers with grading and tutorials.', '', 'Asisten pengajar membantu dosen dalam penilaian dan tutorial.', '', 'Kata kerja formal dari \'help\'. Pola: assist (sb) with/in + noun. Nomina: assistance.', 'Formal verb for \'help\'. Pattern: assist (sb) with/in + noun. Noun: assistance.'),
  'category': VocabUsage('The participants were divided into three age categories.', '', 'Para peserta dibagi menjadi tiga kategori usia.', '', 'Nomina. Pola: fall into a category. Verba: categorize.', 'Noun. Pattern: fall into a category. Verb: categorize.'),
  'chapter': VocabUsage('The second chapter reviews previous studies on the topic.', '', 'Bab kedua mengulas penelitian terdahulu tentang topik tersebut.', '', 'Nomina. Pola: in chapter 2 (tanpa \'the\' bila diikuti angka).', 'Noun. Pattern: in chapter 2 (no \'the\' before a number).'),
  'commission': VocabUsage('The government set up a commission to investigate the accident.', '', 'Pemerintah membentuk komisi untuk menyelidiki kecelakaan itu.', '', 'Nomina. Juga berarti upah persentase penjualan (earn a commission). Kolokasi: set up a commission.', 'Noun. Also a percentage fee on sales (earn a commission). Collocation: set up a commission.'),
  'community': VocabUsage('The new library has become a meeting place for the local community.', '', 'Perpustakaan baru itu menjadi tempat berkumpul masyarakat setempat.', '', 'Nomina. Kolokasi: local/online community, community service.', 'Noun. Collocations: local/online community, community service.'),
  'complex': VocabUsage('Climate change is a complex problem with no simple solution.', '', 'Perubahan iklim adalah masalah rumit tanpa solusi sederhana.', '', 'Adjektiva: rumit, banyak bagian. Lawan: simple. Nomina: complexity.', 'Adjective: having many parts. Opposite: simple. Noun: complexity.'),
  'compute': VocabUsage('The software computes the average score for each class.', '', 'Perangkat lunak itu menghitung nilai rata-rata setiap kelas.', '', 'Kata kerja formal dari \'calculate\'. Nomina: computation; alat: computer.', 'Formal verb for \'calculate\'. Noun: computation; device: computer.'),
  'conclude': VocabUsage('The authors conclude that more research is needed in this area.', '', 'Para penulis menyimpulkan bahwa diperlukan lebih banyak penelitian di bidang ini.', '', 'Kata kerja. Pola: conclude that + klausa; conclude with (mengakhiri). Nomina: conclusion.', 'Verb. Patterns: conclude that + clause; conclude with (end). Noun: conclusion.'),
  'conduct': VocabUsage('The team conducted interviews with more than fifty teachers.', '', 'Tim itu melakukan wawancara dengan lebih dari lima puluh guru.', '', 'Kata kerja. Kolokasi: conduct research/a survey/an experiment. Nomina: conduct = perilaku.', 'Verb. Collocations: conduct research/a survey/an experiment. Noun conduct = behavior.'),
  'consequent': VocabUsage('The storm and the consequent power cuts closed many schools.', '', 'Badai itu dan pemadaman listrik yang menyusul akibatnya membuat banyak sekolah tutup.', '', 'Adjektiva formal. Lebih umum: consequently (adv) dan consequence (nomina).', 'Formal adjective. More common: consequently (adverb) and consequence (noun).'),
  'construct': VocabUsage('The students constructed a simple model of the solar system.', '', 'Para siswa membuat model sederhana tata surya.', '', 'Kata kerja: membangun fisik atau menyusun ide (construct an argument). Nomina: construction.', 'Verb: build physically or form ideas (construct an argument). Noun: construction.'),
  'consume': VocabUsage('Developed countries consume far more energy per person than poorer ones.', '', 'Negara maju mengonsumsi jauh lebih banyak energi per orang daripada negara miskin.', '', 'Kata kerja formal. Kolokasi: consume energy/food/time. Nomina: consumption; orang: consumer.', 'Formal verb. Collocations: consume energy/food/time. Nouns: consumption; consumer.'),
  'credit': VocabUsage('The researcher gave credit to her assistants for collecting the data.', '', 'Peneliti itu memberi pengakuan kepada asistennya atas pengumpulan data.', '', 'Nomina. Pola: give credit to sb for + noun/V-ing. Juga: kredit bank, SKS kuliah.', 'Noun. Pattern: give credit to sb for + noun/V-ing. Also: bank loan, course credit.'),
  'culture': VocabUsage('Food is an important part of every country\'s culture.', '', 'Makanan adalah bagian penting dari budaya setiap negara.', '', 'Nomina. Adj: cultural. Kolokasi: local/popular culture, culture shock.', 'Noun. Adjective: cultural. Collocations: local/popular culture, culture shock.'),
  'design': VocabUsage('The design of the new building allows plenty of natural light.', '', 'Rancangan gedung baru itu memungkinkan banyak cahaya alami masuk.', '', 'Nomina/verba. Pola: be designed to + V (dirancang untuk). Orang: designer.', 'Noun/verb. Pattern: be designed to + verb. Person: designer.'),
  'distinct': VocabUsage('The study found two distinct groups of language learners.', '', 'Penelitian itu menemukan dua kelompok pembelajar bahasa yang jelas berbeda.', '', 'Adjektiva. Pola: distinct from + noun. Nomina: distinction. Beda dengan \'distinctive\' (khas).', 'Adjective. Pattern: distinct from + noun. Noun: distinction. Compare \'distinctive\'.'),
  'element': VocabUsage('Trust is an essential element of any successful partnership.', '', 'Kepercayaan adalah unsur penting dari setiap kemitraan yang sukses.', '', 'Nomina. Pola: an element of + noun. Juga unsur kimia. Adj: elementary (dasar).', 'Noun. Pattern: an element of + noun. Also chemical element. Adj: elementary (basic).'),
  'equate': VocabUsage('Many people equate success with having a high income.', '', 'Banyak orang menyamakan kesuksesan dengan berpenghasilan tinggi.', '', 'Kata kerja. Pola: equate X with Y. Nomina: equation (persamaan).', 'Verb. Pattern: equate X with Y. Noun: equation.'),
  'evaluate': VocabUsage('The teachers evaluated the new program after one semester.', '', 'Para guru mengevaluasi program baru itu setelah satu semester.', '', 'Kata kerja. Kolokasi: evaluate the effectiveness/performance. Nomina: evaluation.', 'Verb. Collocations: evaluate the effectiveness/performance. Noun: evaluation.'),
  'feature': VocabUsage('One key feature of the app is its offline mode.', '', 'Salah satu fitur utama aplikasi itu adalah mode luring.', '', 'Nomina/verba. Pola: a feature of + noun; verba: feature in (tampil di).', 'Noun/verb. Pattern: a feature of + noun; verb: feature in (appear in).'),
  'final': VocabUsage('The final results will be announced at the end of the month.', '', 'Hasil akhir akan diumumkan pada akhir bulan.', '', 'Adjektiva. Kolokasi: final decision/result/exam. Adv: finally.', 'Adjective. Collocations: final decision/result/exam. Adverb: finally.'),
  'focus': VocabUsage('This essay focuses on the effects of social media on teenagers.', '', 'Esai ini berfokus pada dampak media sosial terhadap remaja.', '', 'Kata kerja/nomina. Pola: focus on + noun/V-ing; the focus of + noun.', 'Verb/noun. Patterns: focus on + noun/V-ing; the focus of + noun.'),
  'impact': VocabUsage('Tourism has a strong impact on the local environment.', '', 'Pariwisata berdampak kuat terhadap lingkungan setempat.', '', 'Nomina. Pola: have an impact on + noun. Kolokasi: positive/negative/major impact.', 'Noun. Pattern: have an impact on + noun. Collocations: positive/negative/major impact.'),
  'injure': VocabUsage('Three workers were injured when the machine broke down.', '', 'Tiga pekerja terluka saat mesin itu rusak.', '', 'Kata kerja, sering pasif: be injured. Nomina: injury. Untuk kecelakaan; \'wound\' untuk senjata.', 'Verb, often passive: be injured. Noun: injury. For accidents; \'wound\' for weapons.'),
  'institute': VocabUsage('She works at a research institute that studies tropical diseases.', '', 'Ia bekerja di lembaga penelitian yang mempelajari penyakit tropis.', '', 'Nomina: lembaga. Verba formal: institute a policy (memberlakukan). Mirip: institution.', 'Noun: organization. Formal verb: institute a policy. Similar: institution.'),
  'invest': VocabUsage('Many countries invest heavily in renewable energy.', '', 'Banyak negara berinvestasi besar-besaran di energi terbarukan.', '', 'Kata kerja. Pola: invest in + noun; invest time/money. Nomina: investment; orang: investor.', 'Verb. Patterns: invest in + noun; invest time/money. Nouns: investment; investor.'),
  'item': VocabUsage('Each item on the questionnaire was scored from one to five.', '', 'Setiap butir kuesioner diberi skor dari satu sampai lima.', '', 'Nomina berbilang untuk benda/butir daftar. Kolokasi: an item on the list/agenda.', 'Countable noun for things or list entries. Collocation: an item on the list/agenda.'),
  'journal': VocabUsage('Her article was published in an international science journal.', '', 'Artikelnya diterbitkan di jurnal sains internasional.', '', 'Nomina. Kolokasi: academic/peer-reviewed journal; publish in a journal. Juga: buku harian.', 'Noun. Collocations: academic/peer-reviewed journal; publish in a journal. Also a diary.'),
  'maintain': VocabUsage('It is difficult to maintain old buildings without regular funding.', '', 'Sulit memelihara bangunan tua tanpa pendanaan rutin.', '', 'Kata kerja: memelihara; juga \'bersikeras\' (maintain that...). Nomina: maintenance.', 'Verb: keep in good condition; also \'insist\' (maintain that...). Noun: maintenance.'),
  'normal': VocabUsage('Body temperature usually returns to normal within a few days.', '', 'Suhu tubuh biasanya kembali normal dalam beberapa hari.', '', 'Adjektiva. Pola: return to normal; it is normal to + V. Adv: normally.', 'Adjective. Patterns: return to normal; it is normal to + verb. Adverb: normally.'),
  'obtain': VocabUsage('Researchers must obtain permission before interviewing children.', '', 'Peneliti harus memperoleh izin sebelum mewawancarai anak-anak.', '', 'Kata kerja formal dari \'get\'. Kolokasi: obtain permission/data/information.', 'Formal verb for \'get\'. Collocations: obtain permission/data/information.'),
  'participate': VocabUsage('More than two hundred students participated in the study.', '', 'Lebih dari dua ratus siswa ikut serta dalam penelitian itu.', '', 'Kata kerja. Pola: participate in + noun. Nomina: participation; orang: participant.', 'Verb. Pattern: participate in + noun. Nouns: participation; participant.'),
  'perceive': VocabUsage('Young people often perceive social media as a source of news.', '', 'Anak muda sering memandang media sosial sebagai sumber berita.', '', 'Kata kerja formal. Pola: perceive X as Y. Nomina: perception.', 'Formal verb. Pattern: perceive X as Y. Noun: perception.'),
  'positive': VocabUsage('The new teaching method had a positive effect on test scores.', '', 'Metode mengajar baru itu berdampak positif pada nilai ujian.', '', 'Adjektiva. Kolokasi: positive effect/attitude/result. Lawan: negative.', 'Adjective. Collocations: positive effect/attitude/result. Opposite: negative.'),
  'potential': VocabUsage('Solar energy has great potential in tropical countries.', '', 'Energi surya punya potensi besar di negara tropis.', '', 'Nomina/adjektiva. Pola: the potential to + V; potential risks (risiko yang mungkin).', 'Noun/adjective. Patterns: the potential to + verb; potential risks.'),
  'previous': VocabUsage('Previous studies have focused mainly on adult learners.', '', 'Penelitian terdahulu sebagian besar berfokus pada pembelajar dewasa.', '', 'Adjektiva, di depan nomina: previous year/study. Adv: previously.', 'Adjective, before a noun: previous year/study. Adverb: previously.'),
  'primary': VocabUsage('The primary aim of this study is to compare two teaching methods.', '', 'Tujuan utama penelitian ini adalah membandingkan dua metode mengajar.', '', 'Adjektiva: utama/pertama. Kolokasi: primary aim/source, primary school (SD). Adv: primarily.', 'Adjective: main/first. Collocations: primary aim/source, primary school. Adv: primarily.'),
  'purchase': VocabUsage('Customers can purchase tickets online or at the station.', '', 'Pelanggan dapat membeli tiket secara daring atau di stasiun.', '', 'Kata kerja/nomina formal dari \'buy\'. Kolokasi: make a purchase, purchase price.', 'Formal verb/noun for \'buy\'. Collocations: make a purchase, purchase price.'),
  'range': VocabUsage('The course attracts students from a wide range of backgrounds.', '', 'Kursus itu menarik siswa dari berbagai macam latar belakang.', '', 'Nomina/verba. Pola: a wide range of + noun; range from X to Y.', 'Noun/verb. Patterns: a wide range of + noun; range from X to Y.'),
  'region': VocabUsage('Coffee is grown mainly in the mountain regions of the island.', '', 'Kopi terutama ditanam di daerah pegunungan pulau itu.', '', 'Nomina. Adj: regional. Pola: in the region of (sekitar, untuk angka).', 'Noun. Adjective: regional. Phrase: in the region of (about, with numbers).'),
  'regulate': VocabUsage('Governments regulate the use of chemicals in food production.', '', 'Pemerintah mengatur penggunaan bahan kimia dalam produksi pangan.', '', 'Kata kerja. Nomina: regulation (peraturan). Kolokasi: strictly regulated.', 'Verb. Noun: regulation. Collocation: strictly regulated.'),
  'relevant': VocabUsage('Please include only information that is relevant to the question.', '', 'Harap sertakan hanya informasi yang relevan dengan pertanyaan.', '', 'Adjektiva. Pola: relevant to + noun. Lawan: irrelevant. Nomina: relevance.', 'Adjective. Pattern: relevant to + noun. Opposite: irrelevant. Noun: relevance.'),
  'reside': VocabUsage('Most of the participants reside in urban areas.', '', 'Sebagian besar peserta bertempat tinggal di daerah perkotaan.', '', 'Kata kerja formal dari \'live\'. Pola: reside in/at + tempat. Nomina: residence, resident.', 'Formal verb for \'live\'. Pattern: reside in/at + place. Nouns: residence, resident.'),
  'resource': VocabUsage('Water is a limited resource in many dry regions.', '', 'Air adalah sumber daya yang terbatas di banyak daerah kering.', '', 'Nomina, sering jamak. Kolokasi: natural/human resources, limited resources.', 'Noun, often plural. Collocations: natural/human resources, limited resources.'),
  'restrict': VocabUsage('The new law restricts the sale of alcohol to minors.', '', 'Undang-undang baru itu membatasi penjualan alkohol kepada anak di bawah umur.', '', 'Kata kerja. Pola: restrict X to Y. Nomina: restriction. Mirip: limit.', 'Verb. Pattern: restrict X to Y. Noun: restriction. Similar: limit.'),
  'secure': VocabUsage('The company stores customer data on secure servers.', '', 'Perusahaan itu menyimpan data pelanggan di server yang aman.', '', 'Adjektiva/verba. Verba: secure funding (berhasil memperoleh). Nomina: security.', 'Adjective/verb. Verb: secure funding (manage to get). Noun: security.'),
  'seek': VocabUsage('Many graduates seek work abroad after finishing university.', '', 'Banyak lulusan mencari kerja di luar negeri setelah lulus kuliah.', '', 'Kata kerja formal, tak beraturan: seek-sought-sought. Kolokasi: seek help/advice/work.', 'Formal irregular verb: seek-sought-sought. Collocations: seek help/advice/work.'),
  'select': VocabUsage('Participants were selected randomly from the student list.', '', 'Peserta dipilih secara acak dari daftar siswa.', '', 'Kata kerja, lebih formal dari \'choose\'. Kolokasi: randomly selected. Nomina: selection.', 'Verb, more formal than \'choose\'. Collocation: randomly selected. Noun: selection.'),
  'site': VocabUsage('The company chose a site near the port for its new factory.', '', 'Perusahaan itu memilih lokasi dekat pelabuhan untuk pabrik barunya.', '', 'Nomina. Kolokasi: building site, website, historic site. Jangan tertukar dengan \'sight\'.', 'Noun. Collocations: building site, website, historic site. Don\'t confuse with \'sight\'.'),
  'strategy': VocabUsage('The school developed a strategy to reduce student dropout rates.', '', 'Sekolah itu menyusun strategi untuk menurunkan angka putus sekolah.', '', 'Nomina. Pola: a strategy for + V-ing / to + V. Adj: strategic.', 'Noun. Pattern: a strategy for + V-ing / to + verb. Adjective: strategic.'),
  'survey': VocabUsage('A recent survey found that most workers prefer flexible hours.', '', 'Survei terbaru menemukan bahwa sebagian besar pekerja lebih suka jam kerja fleksibel.', '', 'Nomina/verba. Kolokasi: conduct/carry out a survey. Tekanan nomina SUR-vey.', 'Noun/verb. Collocations: conduct/carry out a survey. Noun stress: SUR-vey.'),
  'text': VocabUsage('Students must read the text carefully before answering the questions.', '', 'Siswa harus membaca teks dengan cermat sebelum menjawab pertanyaan.', '', 'Nomina; verba = mengirim SMS. Adj: textual. Kolokasi: original/full text.', 'Noun; verb = send a message. Adjective: textual. Collocations: original/full text.'),
  'tradition': VocabUsage('Sharing food with neighbors is a long tradition in many villages.', '', 'Berbagi makanan dengan tetangga adalah tradisi lama di banyak desa.', '', 'Nomina. Kolokasi: follow/keep a tradition. Adj: traditional.', 'Noun. Collocations: follow/keep a tradition. Adjective: traditional.'),
  'transfer': VocabUsage('The patient was transferred to a larger hospital for treatment.', '', 'Pasien itu dipindahkan ke rumah sakit yang lebih besar untuk perawatan.', '', 'Kata kerja/nomina. Pola: transfer X from A to B. Kolokasi: bank transfer, knowledge transfer.', 'Verb/noun. Pattern: transfer X from A to B. Collocations: bank transfer, knowledge transfer.'),
  'alternative': VocabUsage('Public transport is a cheaper alternative to driving.', '', 'Transportasi umum adalah alternatif yang lebih murah daripada menyetir.', '', 'Nomina/adjektiva. Pola: an alternative to + noun. Adv: alternatively.', 'Noun/adjective. Pattern: an alternative to + noun. Adverb: alternatively.'),
  'circumstance': VocabUsage('Under certain circumstances, students may submit their work late.', '', 'Dalam keadaan tertentu, siswa boleh mengumpulkan tugas terlambat.', '', 'Nomina, sering jamak. Pola: under/in these circumstances; under no circumstances.', 'Noun, often plural. Patterns: under/in these circumstances; under no circumstances.'),
  'comment': VocabUsage('The professor made several helpful comments on my draft.', '', 'Profesor memberi beberapa komentar yang membantu pada draf saya.', '', 'Nomina/verba. Pola: comment on + noun; make a comment. Nomina terkait: commentary.', 'Noun/verb. Patterns: comment on + noun; make a comment. Related: commentary.'),
  'compensate': VocabUsage('The company agreed to compensate workers for the lost wages.', '', 'Perusahaan setuju mengganti rugi pekerja atas upah yang hilang.', '', 'Kata kerja. Pola: compensate sb for + noun; compensate for (mengimbangi). Nomina: compensation.', 'Verb. Patterns: compensate sb for + noun; compensate for (offset). Noun: compensation.'),
  'component': VocabUsage('Vocabulary is an essential component of language learning.', '', 'Kosakata adalah komponen penting dalam belajar bahasa.', '', 'Nomina. Pola: a component of + noun. Kolokasi: key/essential component.', 'Noun. Pattern: a component of + noun. Collocations: key/essential component.'),
  'consent': VocabUsage('Participants gave written consent before taking part in the study.', '', 'Para peserta memberikan persetujuan tertulis sebelum mengikuti penelitian.', '', 'Nomina/verba formal. Pola: give consent; consent to + noun/V-ing. Kolokasi: informed consent.', 'Formal noun/verb. Patterns: give consent; consent to + noun/V-ing. Collocation: informed consent.'),
  'considerable': VocabUsage('The project required a considerable amount of time and money.', '', 'Proyek itu membutuhkan waktu dan uang yang cukup besar.', '', 'Adjektiva. Kolokasi: considerable amount/effort/impact. Beda: considerate = penuh perhatian.', 'Adjective. Collocations: considerable amount/effort/impact. Compare: considerate = kind.'),
  'constant': VocabUsage('The machine must be kept at a constant temperature.', '', 'Mesin itu harus dijaga pada suhu yang tetap.', '', 'Adjektiva: tetap atau terus-menerus. Kolokasi: constant temperature/pressure. Adv: constantly.', 'Adjective: unchanging or continuous. Collocations: constant temperature/pressure. Adv: constantly.'),
  'constrain': VocabUsage('Limited funding constrained the scope of the research.', '', 'Dana yang terbatas membatasi cakupan penelitian itu.', '', 'Kata kerja formal. Sering pasif: be constrained by. Nomina: constraint (kendala).', 'Formal verb. Often passive: be constrained by. Noun: constraint.'),
  'contribute': VocabUsage('Many factors contribute to the rise in obesity among children.', '', 'Banyak faktor berkontribusi pada meningkatnya obesitas di kalangan anak.', '', 'Kata kerja. Pola: contribute to + noun/V-ing. Nomina: contribution; orang: contributor.', 'Verb. Pattern: contribute to + noun/V-ing. Nouns: contribution; contributor.'),
  'convene': VocabUsage('The council will convene next week to discuss the budget.', '', 'Dewan akan mengadakan rapat minggu depan untuk membahas anggaran.', '', 'Kata kerja formal: berkumpul atau mengadakan rapat. Kolokasi: convene a meeting/panel.', 'Formal verb: meet or call a meeting. Collocations: convene a meeting/panel.'),
  'coordinate': VocabUsage('A small team coordinates the activities of all volunteers.', '', 'Tim kecil mengoordinasikan kegiatan semua relawan.', '', 'Kata kerja. Pola: coordinate with + orang. Nomina: coordination; orang: coordinator.', 'Verb. Pattern: coordinate with + person. Nouns: coordination; coordinator.'),
  'core': VocabUsage('Reading and writing are core skills in the school curriculum.', '', 'Membaca dan menulis adalah keterampilan inti dalam kurikulum sekolah.', '', 'Nomina/adjektiva. Kolokasi: core values/skills/subjects; at the core of.', 'Noun/adjective. Collocations: core values/skills/subjects; at the core of.'),
  'corporate': VocabUsage('Corporate social responsibility has become important for large firms.', '', 'Tanggung jawab sosial perusahaan menjadi penting bagi perusahaan besar.', '', 'Adjektiva, di depan nomina. Kolokasi: corporate culture/image/tax. Nomina: corporation.', 'Adjective, before a noun. Collocations: corporate culture/image/tax. Noun: corporation.'),
  'correspond': VocabUsage('The results correspond closely with earlier findings.', '', 'Hasilnya sangat sesuai dengan temuan sebelumnya.', '', 'Kata kerja. Pola: correspond with/to (sesuai); correspond with sb (surat-menyurat).', 'Verb. Patterns: correspond with/to (match); correspond with sb (exchange letters).'),
  'criteria': VocabUsage('Applicants are selected according to strict criteria.', '', 'Pelamar dipilih berdasarkan kriteria yang ketat.', '', 'Nomina jamak; tunggalnya criterion. Pola: meet the criteria; criteria for + noun.', 'Plural noun; singular criterion. Patterns: meet the criteria; criteria for + noun.'),
  'deduce': VocabUsage('From the evidence, we can deduce that the fire started at night.', '', 'Dari bukti yang ada, kita dapat menyimpulkan bahwa api mulai pada malam hari.', '', 'Kata kerja. Pola: deduce X from Y; deduce that... Nomina: deduction.', 'Verb. Patterns: deduce X from Y; deduce that... Noun: deduction.'),
  'demonstrate': VocabUsage('The experiment demonstrates how heat affects the speed of reactions.', '', 'Eksperimen itu menunjukkan bagaimana panas memengaruhi kecepatan reaksi.', '', 'Kata kerja: membuktikan/memperagakan. Pola: demonstrate that/how. Nomina: demonstration.', 'Verb: prove or show how. Patterns: demonstrate that/how. Noun: demonstration.'),
  'document': VocabUsage('Please attach a copy of your identity document to the form.', '', 'Harap lampirkan salinan dokumen identitas Anda pada formulir.', '', 'Nomina/verba. Verba: mendokumentasikan. Nomina: documentation; adj: documentary.', 'Noun/verb. Verb: to record. Noun: documentation; adjective: documentary.'),
  'dominate': VocabUsage('A few large companies dominate the global smartphone market.', '', 'Beberapa perusahaan besar mendominasi pasar ponsel pintar global.', '', 'Kata kerja. Adj: dominant. Nomina: domination, dominance.', 'Verb. Adjective: dominant. Nouns: domination, dominance.'),
  'emphasis': VocabUsage('The new curriculum places greater emphasis on critical thinking.', '', 'Kurikulum baru memberi penekanan lebih besar pada berpikir kritis.', '', 'Nomina. Pola: put/place emphasis on + noun. Verba: emphasize.', 'Noun. Pattern: put/place emphasis on + noun. Verb: emphasize.'),
  'ensure': VocabUsage('Teachers must ensure that all students understand the instructions.', '', 'Guru harus memastikan semua siswa memahami instruksi.', '', 'Kata kerja. Pola: ensure that + klausa. Beda: insure = mengasuransikan.', 'Verb. Pattern: ensure that + clause. Compare: insure = buy insurance.'),
  'exclude': VocabUsage('Students under eighteen were excluded from the survey.', '', 'Siswa di bawah delapan belas tahun dikecualikan dari survei.', '', 'Kata kerja. Pola: exclude X from Y. Lawan: include. Nomina: exclusion.', 'Verb. Pattern: exclude X from Y. Opposite: include. Noun: exclusion.'),
  'framework': VocabUsage('The study uses a clear theoretical framework to explain the results.', '', 'Penelitian itu memakai kerangka teori yang jelas untuk menjelaskan hasilnya.', '', 'Nomina. Kolokasi: theoretical/legal framework; within the framework of.', 'Noun. Collocations: theoretical/legal framework; within the framework of.'),
  'fund': VocabUsage('The school raised funds to build a new library.', '', 'Sekolah itu menggalang dana untuk membangun perpustakaan baru.', '', 'Nomina/verba. Kolokasi: raise funds; be funded by. Nomina: funding (tak berbilang).', 'Noun/verb. Collocations: raise funds; be funded by. Noun: funding (uncountable).'),
  'illustrate': VocabUsage('The graph illustrates the rise in internet use over ten years.', '', 'Grafik itu menggambarkan peningkatan penggunaan internet selama sepuluh tahun.', '', 'Kata kerja. Umum di IELTS Task 1: the chart illustrates... Nomina: illustration.', 'Verb. Common in IELTS Task 1: the chart illustrates... Noun: illustration.'),
  'immigrate': VocabUsage('His grandparents immigrated to Canada in the 1960s.', '', 'Kakek-neneknya berimigrasi ke Kanada pada tahun 1960-an.', '', 'Kata kerja. Pola: immigrate to + negara tujuan. Lawan: emigrate from. Nomina: immigration.', 'Verb. Pattern: immigrate to + new country. Opposite: emigrate from. Noun: immigration.'),
  'imply': VocabUsage('The results imply that diet plays a larger role than exercise.', '', 'Hasilnya menyiratkan bahwa pola makan berperan lebih besar daripada olahraga.', '', 'Kata kerja. Pola: imply that + klausa. Nomina: implication. Beda: infer = menyimpulkan.', 'Verb. Pattern: imply that + clause. Noun: implication. Compare: infer = conclude.'),
  'initial': VocabUsage('Initial results suggest that the new drug is safe.', '', 'Hasil awal menunjukkan bahwa obat baru itu aman.', '', 'Adjektiva, di depan nomina. Kolokasi: initial stage/results. Adv: initially.', 'Adjective, before a noun. Collocations: initial stage/results. Adverb: initially.'),
  'instance': VocabUsage('There are many instances of students helping each other online.', '', 'Ada banyak contoh siswa saling membantu secara daring.', '', 'Nomina. Frasa: for instance (misalnya) = for example. Pola: an instance of + noun.', 'Noun. Phrase: for instance = for example. Pattern: an instance of + noun.'),
  'interact': VocabUsage('Children learn social skills by interacting with their peers.', '', 'Anak-anak belajar keterampilan sosial dengan berinteraksi bersama teman sebaya.', '', 'Kata kerja. Pola: interact with + noun. Nomina: interaction; adj: interactive.', 'Verb. Pattern: interact with + noun. Noun: interaction; adjective: interactive.'),
  'justify': VocabUsage('The government must justify its decision to raise taxes.', '', 'Pemerintah harus memberi alasan atas keputusannya menaikkan pajak.', '', 'Kata kerja. Kolokasi: justify a decision/cost. Nomina: justification.', 'Verb. Collocations: justify a decision/cost. Noun: justification.'),
  'layer': VocabUsage('A thin layer of dust covered the old books.', '', 'Lapisan debu tipis menutupi buku-buku tua itu.', '', 'Nomina. Pola: a layer of + noun. Kolokasi: ozone layer, thin/outer layer.', 'Noun. Pattern: a layer of + noun. Collocations: ozone layer, thin/outer layer.'),
  'link': VocabUsage('Studies have found a strong link between smoking and lung disease.', '', 'Penelitian menemukan hubungan kuat antara merokok dan penyakit paru-paru.', '', 'Nomina/verba. Pola: a link between X and Y; link X to/with Y.', 'Noun/verb. Patterns: a link between X and Y; link X to/with Y.'),
  'locate': VocabUsage('The rescue team managed to locate the missing climbers.', '', 'Tim penyelamat berhasil menemukan letak para pendaki yang hilang.', '', 'Kata kerja. Pasif: be located in/near (terletak di). Nomina: location.', 'Verb. Passive: be located in/near. Noun: location.'),
  'maximize': VocabUsage('Farmers use new techniques to maximize their crop yields.', '', 'Petani memakai teknik baru untuk memaksimalkan hasil panen.', '', 'Kata kerja. Lawan: minimize. Kolokasi: maximize profit/efficiency. Adj: maximum.', 'Verb. Opposite: minimize. Collocations: maximize profit/efficiency. Adj: maximum.'),
  'minor': VocabUsage('The report contains only a few minor errors.', '', 'Laporan itu hanya berisi sedikit kesalahan kecil.', '', 'Adjektiva. Lawan: major. Nomina: minor = anak di bawah umur. Nomina: minority.', 'Adjective. Opposite: major. Noun: minor = person under 18. Noun: minority.'),
  'negate': VocabUsage('One careless mistake can negate months of hard work.', '', 'Satu kesalahan ceroboh bisa meniadakan kerja keras berbulan-bulan.', '', 'Kata kerja formal. Mirip: cancel out. Adj: negative; nomina: negation.', 'Formal verb. Similar: cancel out. Adjective: negative; noun: negation.'),
  'outcome': VocabUsage('Researchers could not predict the outcome of the experiment.', '', 'Para peneliti tidak dapat memprediksi hasil akhir eksperimen itu.', '', 'Nomina. Pola: the outcome of + noun. Kolokasi: positive/likely outcome.', 'Noun. Pattern: the outcome of + noun. Collocations: positive/likely outcome.'),
  'partner': VocabUsage('The university works with industry partners on several projects.', '', 'Universitas itu bekerja sama dengan mitra industri dalam beberapa proyek.', '', 'Nomina/verba. Pola: partner with + noun. Nomina: partnership.', 'Noun/verb. Pattern: partner with + noun. Noun: partnership.'),
  'philosophy': VocabUsage('She studied philosophy and political science at university.', '', 'Ia belajar filsafat dan ilmu politik di universitas.', '', 'Nomina. Juga berarti prinsip hidup/kerja (company philosophy). Adj: philosophical.', 'Noun. Also a guiding principle (company philosophy). Adjective: philosophical.'),
  'physical': VocabUsage('Regular physical activity reduces the risk of heart disease.', '', 'Aktivitas fisik rutin menurunkan risiko penyakit jantung.', '', 'Adjektiva. Kolokasi: physical activity/health/education. Adv: physically.', 'Adjective. Collocations: physical activity/health/education. Adverb: physically.'),
  'proportion': VocabUsage('A large proportion of the population lives in cities.', '', 'Sebagian besar penduduk tinggal di kota.', '', 'Nomina. Pola: a proportion of + noun; in proportion to. Adj: proportional.', 'Noun. Patterns: a proportion of + noun; in proportion to. Adjective: proportional.'),
  'publish': VocabUsage('The journal publishes new research on climate science every month.', '', 'Jurnal itu menerbitkan penelitian baru tentang ilmu iklim setiap bulan.', '', 'Kata kerja. Pasif: be published in. Nomina: publication; orang/perusahaan: publisher.', 'Verb. Passive: be published in. Nouns: publication; publisher.'),
  'react': VocabUsage('People react differently to stress at work.', '', 'Orang bereaksi secara berbeda terhadap stres di tempat kerja.', '', 'Kata kerja. Pola: react to + noun; react with (kimia). Nomina: reaction.', 'Verb. Patterns: react to + noun; react with (chemistry). Noun: reaction.'),
  'register': VocabUsage('All students must register for classes before the semester begins.', '', 'Semua mahasiswa harus mendaftar kelas sebelum semester dimulai.', '', 'Kata kerja/nomina. Pola: register for/with + noun. Nomina: registration.', 'Verb/noun. Pattern: register for/with + noun. Noun: registration.'),
  'rely': VocabUsage('Many small farmers rely on rain to water their crops.', '', 'Banyak petani kecil mengandalkan hujan untuk mengairi tanaman.', '', 'Kata kerja. Selalu \'rely on/upon\'. Adj: reliable; nomina: reliance.', 'Verb. Always \'rely on/upon\'. Adjective: reliable; noun: reliance.'),
  'remove': VocabUsage('The website removed all posts that contained false information.', '', 'Situs web itu menghapus semua unggahan yang berisi informasi palsu.', '', 'Kata kerja. Pola: remove X from Y. Nomina: removal.', 'Verb. Pattern: remove X from Y. Noun: removal.'),
  'scheme': VocabUsage('The government launched a scheme to help first-time home buyers.', '', 'Pemerintah meluncurkan skema untuk membantu pembeli rumah pertama.', '', 'Nomina (Inggris Britania: program resmi). Di AS bisa bernuansa negatif: rencana licik.', 'Noun (British: official plan). In US English it can mean a dishonest plan.'),
  'sequence': VocabUsage('The events are described in the sequence in which they happened.', '', 'Peristiwa-peristiwa itu dijelaskan sesuai urutan terjadinya.', '', 'Nomina. Pola: in sequence; a sequence of + noun. Adj: sequential.', 'Noun. Patterns: in sequence; a sequence of + noun. Adjective: sequential.'),
  'sex': VocabUsage('The data were grouped by age and sex.', '', 'Data dikelompokkan berdasarkan usia dan jenis kelamin.', '', 'Nomina. Di data riset = kategori biologis; \'gender\' lebih ke peran sosial.', 'Noun. In research data = biological category; \'gender\' refers to social roles.'),
  'shift': VocabUsage('There has been a shift in public attitudes toward remote work.', '', 'Telah terjadi pergeseran sikap publik terhadap kerja jarak jauh.', '', 'Nomina/verba. Pola: a shift in/toward + noun; shift from X to Y. Juga: giliran kerja.', 'Noun/verb. Patterns: a shift in/toward + noun; shift from X to Y. Also: work shift.'),
  'specify': VocabUsage('The contract specifies the exact date of delivery.', '', 'Kontrak itu merinci tanggal pengiriman yang tepat.', '', 'Kata kerja. Pola: specify that/what... Nomina: specification. Adj: specific.', 'Verb. Pattern: specify that/what... Noun: specification. Adjective: specific.'),
  'sufficient': VocabUsage('The sample size was not sufficient to draw firm conclusions.', '', 'Jumlah sampel tidak cukup untuk menarik kesimpulan yang kuat.', '', 'Adjektiva formal dari \'enough\'. Pola: sufficient for/to + V. Lawan: insufficient.', 'Formal adjective for \'enough\'. Pattern: sufficient for/to + verb. Opposite: insufficient.'),
  'task': VocabUsage('Each group was given a different task to complete in one hour.', '', 'Setiap kelompok diberi tugas berbeda untuk diselesaikan dalam satu jam.', '', 'Nomina. Kolokasi: perform/complete a task; a difficult task. Beda: homework = PR.', 'Noun. Collocations: perform/complete a task; a difficult task. Homework = school task.'),
  'technical': VocabUsage('The engineers solved the technical problems before the launch.', '', 'Para insinyur memecahkan masalah teknis sebelum peluncuran.', '', 'Adjektiva. Kolokasi: technical support/problem/term. Adv: technically.', 'Adjective. Collocations: technical support/problem/term. Adverb: technically.'),
  'technique': VocabUsage('The artist used a traditional technique to paint the walls.', '', 'Seniman itu memakai teknik tradisional untuk melukis dinding.', '', 'Nomina: cara khusus melakukan sesuatu. Pola: a technique for + V-ing.', 'Noun: a special way of doing something. Pattern: a technique for + V-ing.'),
  'technology': VocabUsage('Technology has changed the way students learn and communicate.', '', 'Teknologi telah mengubah cara siswa belajar dan berkomunikasi.', '', 'Nomina. Adj: technological. Kolokasi: modern/new technology, information technology.', 'Noun. Adjective: technological. Collocations: modern/new technology, information technology.'),
  'valid': VocabUsage('Your visa is valid for six months from the date of entry.', '', 'Visa Anda berlaku selama enam bulan sejak tanggal masuk.', '', 'Adjektiva: sah/berlaku; juga argumen yang masuk akal (a valid point). Nomina: validity.', 'Adjective: legally acceptable; also sound (a valid point). Noun: validity.'),
  'volume': VocabUsage('The volume of online sales doubled during the pandemic.', '', 'Volume penjualan daring berlipat ganda selama pandemi.', '', 'Nomina: jumlah/isi; juga tingkat suara dan jilid buku. Pola: the volume of + noun.', 'Noun: amount/space; also loudness and book volume. Pattern: the volume of + noun.'),
  'access': VocabUsage('Many rural students still lack access to the internet.', '', 'Banyak siswa di pedesaan masih kekurangan akses ke internet.', '', 'Nomina/verba. Pola: access to + noun (nomina); verba tanpa \'to\': access the data.', 'Noun/verb. Pattern: access to + noun; as a verb, no \'to\': access the data.'),
  'adequate': VocabUsage('Many schools still lack adequate facilities for disabled students.', '', 'Banyak sekolah masih kekurangan fasilitas yang memadai bagi siswa disabilitas.', '', 'Adjektiva: cukup memadai (tidak lebih). Lawan: inadequate. Mirip: sufficient.', 'Adjective: good enough (not more). Opposite: inadequate. Similar: sufficient.'),
  'annual': VocabUsage('The company publishes an annual report on its environmental impact.', '', 'Perusahaan itu menerbitkan laporan tahunan tentang dampak lingkungannya.', '', 'Adjektiva, di depan nomina. Kolokasi: annual report/income/meeting. Adv: annually.', 'Adjective, before a noun. Collocations: annual report/income/meeting. Adv: annually.'),
  'apparent': VocabUsage('It soon became apparent that the plan would not work.', '', 'Segera tampak jelas bahwa rencana itu tidak akan berhasil.', '', 'Adjektiva. Pola: it became apparent that... Adv: apparently (rupanya/kabarnya).', 'Adjective. Pattern: it became apparent that... Adverb: apparently.'),
  'approximate': VocabUsage('The approximate cost of the project is two million dollars.', '', 'Perkiraan biaya proyek itu sekitar dua juta dolar.', '', 'Adjektiva/verba. Adj: approximate cost/number. Adv: approximately = sekitar.', 'Adjective/verb. Adj: approximate cost/number. Adverb: approximately = about.'),
  'attitude': VocabUsage('Public attitudes toward recycling have improved in recent years.', '', 'Sikap masyarakat terhadap daur ulang membaik dalam beberapa tahun terakhir.', '', 'Nomina. Pola: attitude to/toward + noun. Kolokasi: positive/negative attitude.', 'Noun. Pattern: attitude to/toward + noun. Collocations: positive/negative attitude.'),
  'attribute': VocabUsage('Scientists attribute the rise in temperature to human activity.', '', 'Para ilmuwan menghubungkan kenaikan suhu dengan aktivitas manusia.', '', 'Kata kerja. Pola: attribute X to Y (menganggap Y penyebab X). Nomina AT-tribute = sifat.', 'Verb. Pattern: attribute X to Y (Y causes X). Noun AT-tribute = quality.'),
  'civil': VocabUsage('Civil servants must remain neutral during election campaigns.', '', 'Pegawai negeri sipil harus tetap netral selama masa kampanye pemilu.', '', 'Adjektiva. Kolokasi: civil servant/rights/war/society. Juga berarti sopan.', 'Adjective. Collocations: civil servant/rights/war/society. Also means polite.'),
  'code': VocabUsage('All employees must follow the company\'s code of conduct.', '', 'Semua karyawan wajib mematuhi kode etik perusahaan.', '', 'Nomina. Kolokasi: code of conduct, dress code, postal code. Juga: kode program.', 'Noun. Collocations: code of conduct, dress code, postal code. Also: program code.'),
  'commit': VocabUsage('The government is committed to reducing carbon emissions by 2030.', '', 'Pemerintah berkomitmen mengurangi emisi karbon pada 2030.', '', 'Kata kerja. Pola: be committed to + V-ing; commit a crime/an error. Nomina: commitment.', 'Verb. Patterns: be committed to + V-ing; commit a crime/an error. Noun: commitment.'),
  'communicate': VocabUsage('Good leaders communicate clearly with their team members.', '', 'Pemimpin yang baik berkomunikasi dengan jelas kepada anggota timnya.', '', 'Kata kerja. Pola: communicate with + orang. Nomina: communication.', 'Verb. Pattern: communicate with + person. Noun: communication.'),
  'concentrate': VocabUsage('It is hard to concentrate in a noisy classroom.', '', 'Sulit berkonsentrasi di kelas yang bising.', '', 'Kata kerja. Pola: concentrate on + noun/V-ing. Nomina: concentration.', 'Verb. Pattern: concentrate on + noun/V-ing. Noun: concentration.'),
  'confer': VocabUsage('The university conferred an honorary degree on the former president.', '', 'Universitas itu memberikan gelar kehormatan kepada mantan presiden.', '', 'Kata kerja formal. Pola: confer X on Y (memberi gelar); confer with (berunding). Nomina: conference.', 'Formal verb. Patterns: confer X on Y (give); confer with (discuss). Noun: conference.'),
  'contrast': VocabUsage('In contrast to cities, rural areas have cleaner air.', '', 'Berbeda dengan kota, daerah pedesaan memiliki udara yang lebih bersih.', '', 'Nomina/verba. Pola: in contrast to/with; by contrast; contrast X with Y.', 'Noun/verb. Patterns: in contrast to/with; by contrast; contrast X with Y.'),
  'cycle': VocabUsage('Recycling helps complete the life cycle of many products.', '', 'Daur ulang membantu menuntaskan siklus hidup banyak produk.', '', 'Nomina. Kolokasi: life cycle, water cycle, business cycle. Adj: cyclical.', 'Noun. Collocations: life cycle, water cycle, business cycle. Adjective: cyclical.'),
  'debate': VocabUsage('There is an ongoing debate about the value of homework.', '', 'Ada perdebatan yang terus berlangsung tentang manfaat pekerjaan rumah.', '', 'Nomina/verba. Pola: debate about/over + noun; verba tanpa \'about\': debate the issue.', 'Noun/verb. Pattern: debate about/over + noun; as a verb: debate the issue.'),
  'despite': VocabUsage('Despite the heavy rain, the event attracted a large crowd.', '', 'Meskipun hujan deras, acara itu menarik banyak pengunjung.', '', 'Preposisi + nomina/V-ing (bukan klausa). Tanpa \'of\'. Mirip: in spite of; although + klausa.', 'Preposition + noun/V-ing (not a clause). No \'of\'. Similar: in spite of; although + clause.'),
  'dimension': VocabUsage('The report examines the social dimension of poverty.', '', 'Laporan itu menelaah dimensi sosial dari kemiskinan.', '', 'Nomina: ukuran (panjang/lebar) atau aspek. Pola: a new dimension to + noun.', 'Noun: measurement or aspect. Pattern: a new dimension to + noun.'),
  'domestic': VocabUsage('Domestic flights are often cheaper than international ones.', '', 'Penerbangan dalam negeri sering lebih murah daripada penerbangan internasional.', '', 'Adjektiva. Kolokasi: domestic market/flights (dalam negeri); domestic work (rumah tangga).', 'Adjective. Collocations: domestic market/flights (national); domestic work (household).'),
  'emerge': VocabUsage('New evidence emerged during the second stage of the investigation.', '', 'Bukti baru muncul pada tahap kedua penyelidikan.', '', 'Kata kerja. Pola: emerge from + noun; it emerged that... Nomina: emergence. Adj: emerging.', 'Verb. Patterns: emerge from + noun; it emerged that... Noun: emergence. Adj: emerging.'),
  'error': VocabUsage('A small error in the calculation affected the final results.', '', 'Kesalahan kecil dalam perhitungan memengaruhi hasil akhir.', '', 'Nomina, lebih formal dari \'mistake\'. Kolokasi: make an error; human error; in error.', 'Noun, more formal than \'mistake\'. Collocations: make an error; human error; in error.'),
  'ethnic': VocabUsage('The city is home to many different ethnic groups.', '', 'Kota itu menjadi tempat tinggal banyak kelompok etnis.', '', 'Adjektiva. Kolokasi: ethnic group/minority/diversity. Nomina: ethnicity.', 'Adjective. Collocations: ethnic group/minority/diversity. Noun: ethnicity.'),
  'goal': VocabUsage('The main goal of the program is to improve reading skills.', '', 'Tujuan utama program ini adalah meningkatkan kemampuan membaca.', '', 'Nomina. Kolokasi: set/achieve/reach a goal. Mirip: aim, objective.', 'Noun. Collocations: set/achieve/reach a goal. Similar: aim, objective.'),
  'grant': VocabUsage('The research team received a large grant from a private foundation.', '', 'Tim peneliti menerima hibah besar dari sebuah yayasan swasta.', '', 'Nomina/verba. Verba: grant permission/a request. Frasa: take for granted (menganggap remeh).', 'Noun/verb. Verb: grant permission/a request. Phrase: take for granted.'),
  'hence': VocabUsage('The roads were icy; hence, many schools were closed.', '', 'Jalanan licin karena es; oleh karena itu, banyak sekolah ditutup.', '', 'Adverbia formal = therefore. Bisa diikuti nomina saja: hence the delay.', 'Formal adverb = therefore. Can be followed by a noun alone: hence the delay.'),
  'hypothesis': VocabUsage('The experiment was designed to test the hypothesis.', '', 'Eksperimen itu dirancang untuk menguji hipotesis.', '', 'Nomina. Jamak: hypotheses. Kolokasi: test/support/reject a hypothesis.', 'Noun. Plural: hypotheses. Collocations: test/support/reject a hypothesis.'),
  'implement': VocabUsage('Schools will implement the new curriculum next year.', '', 'Sekolah-sekolah akan menerapkan kurikulum baru tahun depan.', '', 'Kata kerja. Kolokasi: implement a plan/policy/system. Nomina: implementation.', 'Verb. Collocations: implement a plan/policy/system. Noun: implementation.'),
  'implicate': VocabUsage('Two senior officials were implicated in the bribery scandal.', '', 'Dua pejabat senior tersangkut dalam skandal suap itu.', '', 'Kata kerja, sering pasif: be implicated in + kesalahan. Nomina: implication.', 'Verb, often passive: be implicated in + wrongdoing. Noun: implication.'),
  'impose': VocabUsage('The city imposed a fine on drivers who park illegally.', '', 'Kota itu memberlakukan denda bagi pengemudi yang parkir sembarangan.', '', 'Kata kerja. Pola: impose X on Y. Kolokasi: impose a tax/fine/ban/restrictions.', 'Verb. Pattern: impose X on Y. Collocations: impose a tax/fine/ban/restrictions.'),
  'integrate': VocabUsage('The school integrates technology into every subject.', '', 'Sekolah itu memadukan teknologi ke dalam setiap mata pelajaran.', '', 'Kata kerja. Pola: integrate X into/with Y. Nomina: integration.', 'Verb. Pattern: integrate X into/with Y. Noun: integration.'),
  'internal': VocabUsage('The company carried out an internal review of its safety rules.', '', 'Perusahaan itu melakukan tinjauan internal atas aturan keselamatannya.', '', 'Adjektiva. Lawan: external. Kolokasi: internal affairs/organs/review.', 'Adjective. Opposite: external. Collocations: internal affairs/organs/review.'),
  'investigate': VocabUsage('Police are investigating the cause of the fire.', '', 'Polisi sedang menyelidiki penyebab kebakaran itu.', '', 'Kata kerja. Tanpa \'about\': investigate the cause. Nomina: investigation.', 'Verb. No \'about\': investigate the cause. Noun: investigation.'),
  'job': VocabUsage('Many young people find it difficult to get a stable job.', '', 'Banyak anak muda merasa sulit mendapat pekerjaan tetap.', '', 'Nomina berbilang (a job). Kolokasi: get/lose a job; job market. Beda: work (tak berbilang).', 'Countable noun (a job). Collocations: get/lose a job; job market. Work is uncountable.'),
  'label': VocabUsage('Food labels must show the ingredients and expiry date.', '', 'Label makanan harus mencantumkan bahan dan tanggal kedaluwarsa.', '', 'Nomina/verba. Verba: label X as Y (mencap, sering negatif).', 'Noun/verb. Verb: label X as Y (often negative).'),
  'mechanism': VocabUsage('Scientists are still studying the mechanism of the disease.', '', 'Para ilmuwan masih mempelajari mekanisme penyakit itu.', '', 'Nomina. Pola: a mechanism for + V-ing. Kolokasi: defense mechanism.', 'Noun. Pattern: a mechanism for + V-ing. Collocation: defense mechanism.'),
  'obvious': VocabUsage('The benefits of the new system were obvious to everyone.', '', 'Manfaat sistem baru itu sangat jelas bagi semua orang.', '', 'Adjektiva. Pola: obvious to + orang; it is obvious that... Adv: obviously.', 'Adjective. Patterns: obvious to + person; it is obvious that... Adverb: obviously.'),
  'occupy': VocabUsage('Offices occupy most of the floors in the new building.', '', 'Kantor-kantor menempati sebagian besar lantai di gedung baru itu.', '', 'Kata kerja. Juga: menyibukkan (be occupied with). Nomina: occupation (pekerjaan/pendudukan).', 'Verb. Also: keep busy (be occupied with). Noun: occupation (job/takeover).'),
  'option': VocabUsage('Studying abroad is a popular option for many graduates.', '', 'Kuliah di luar negeri adalah pilihan populer bagi banyak lulusan.', '', 'Nomina. Kolokasi: have no option but to + V. Adj: optional (tidak wajib).', 'Noun. Phrase: have no option but to + verb. Adjective: optional.'),
  'output': VocabUsage('The factory increased its output by twenty percent last year.', '', 'Pabrik itu meningkatkan hasil produksinya dua puluh persen tahun lalu.', '', 'Nomina tak berbilang. Lawan: input. Kolokasi: increase/reduce output.', 'Uncountable noun. Opposite: input. Collocations: increase/reduce output.'),
  'overall': VocabUsage('Overall, the results of the program were very encouraging.', '', 'Secara keseluruhan, hasil program itu sangat menggembirakan.', '', 'Adverbia/adjektiva. Di awal kalimat untuk merangkum (umum di IELTS Task 1).', 'Adverb/adjective. Used at the start to summarize (common in IELTS Task 1).'),
  'parallel': VocabUsage('The road runs parallel to the river for several kilometers.', '', 'Jalan itu sejajar dengan sungai sepanjang beberapa kilometer.', '', 'Adjektiva/nomina. Pola: parallel to/with + noun; draw a parallel (membandingkan).', 'Adjective/noun. Patterns: parallel to/with + noun; draw a parallel (compare).'),
  'parameter': VocabUsage('The study was carried out within strict parameters set by the ethics board.', '', 'Penelitian itu dilakukan dalam batasan ketat yang ditetapkan dewan etik.', '', 'Nomina, biasanya jamak. Pola: within the parameters of + noun.', 'Noun, usually plural. Pattern: within the parameters of + noun.'),
  'phase': VocabUsage('The first phase of the project will finish in March.', '', 'Tahap pertama proyek akan selesai pada bulan Maret.', '', 'Nomina/verba. Verba: phase in/out (memberlakukan/menghapus bertahap).', 'Noun/verb. Verb: phase in/out (introduce/remove gradually).'),
  'predict': VocabUsage('Experts predict that sea levels will continue to rise.', '', 'Para ahli memprediksi bahwa permukaan laut akan terus naik.', '', 'Kata kerja. Pola: predict that + klausa. Nomina: prediction; adj: predictable.', 'Verb. Pattern: predict that + clause. Noun: prediction; adjective: predictable.'),
  'principal': VocabUsage('The principal reason for the delay was a shortage of staff.', '', 'Alasan pokok keterlambatan itu adalah kekurangan staf.', '', 'Adjektiva: utama; nomina: kepala sekolah. Jangan tertukar dengan \'principle\' (prinsip).', 'Adjective: main; noun: school head. Don\'t confuse with \'principle\' (rule/belief).'),
  'prior': VocabUsage('No prior experience is required for this course.', '', 'Tidak diperlukan pengalaman sebelumnya untuk kursus ini.', '', 'Adjektiva formal. Pola: prior to + noun/V-ing = before. Nomina: priority.', 'Formal adjective. Pattern: prior to + noun/V-ing = before. Noun: priority.'),
  'professional': VocabUsage('It is wise to seek professional advice before investing.', '', 'Sebaiknya meminta saran profesional sebelum berinvestasi.', '', 'Adjektiva/nomina. Kolokasi: professional advice/development. Lawan: amateur.', 'Adjective/noun. Collocations: professional advice/development. Opposite: amateur.'),
  'project': VocabUsage('The students worked on a group project about renewable energy.', '', 'Para siswa mengerjakan proyek kelompok tentang energi terbarukan.', '', 'Nomina/verba. Verba pro-JECT: memproyeksikan (projected growth). Kolokasi: carry out a project.', 'Noun/verb. Verb pro-JECT: forecast (projected growth). Collocation: carry out a project.'),
  'promote': VocabUsage('The campaign aims to promote healthy eating among teenagers.', '', 'Kampanye itu bertujuan mempromosikan pola makan sehat di kalangan remaja.', '', 'Kata kerja. Juga: menaikkan jabatan (be promoted to manager). Nomina: promotion.', 'Verb. Also: raise in rank (be promoted to manager). Noun: promotion.'),
  'regime': VocabUsage('The old regime controlled the media for decades.', '', 'Rezim lama menguasai media selama puluhan tahun.', '', 'Nomina, sering negatif untuk pemerintahan. Juga: aturan/program (a training regime).', 'Noun, often negative for governments. Also: set of rules (a training regime).'),
  'resolve': VocabUsage('The two sides met to resolve their differences.', '', 'Kedua pihak bertemu untuk menyelesaikan perbedaan mereka.', '', 'Kata kerja. Kolokasi: resolve a problem/conflict/dispute. Nomina: resolution.', 'Verb. Collocations: resolve a problem/conflict/dispute. Noun: resolution.'),
  'retain': VocabUsage('The company offers bonuses to retain its best employees.', '', 'Perusahaan itu memberi bonus untuk mempertahankan karyawan terbaiknya.', '', 'Kata kerja formal dari \'keep\'. Kolokasi: retain staff/information/heat. Nomina: retention.', 'Formal verb for \'keep\'. Collocations: retain staff/information/heat. Noun: retention.'),
  'series': VocabUsage('The museum held a series of lectures on local history.', '', 'Museum itu mengadakan serangkaian kuliah tentang sejarah lokal.', '', 'Nomina, bentuk sama untuk tunggal/jamak. Pola: a series of + nomina jamak.', 'Noun, same form singular/plural. Pattern: a series of + plural noun.'),
  'statistic': VocabUsage('One worrying statistic shows that obesity rates have doubled.', '', 'Satu data statistik yang mengkhawatirkan menunjukkan angka obesitas berlipat ganda.', '', 'Nomina: satu angka statistik; jamak statistics = data/ilmu statistik. Adj: statistical.', 'Noun: one figure; plural statistics = data or the field. Adjective: statistical.'),
  'status': VocabUsage('Education can improve a person\'s social status.', '', 'Pendidikan dapat meningkatkan kedudukan sosial seseorang.', '', 'Nomina. Kolokasi: social/legal/marital status; status symbol.', 'Noun. Collocations: social/legal/marital status; status symbol.'),
  'stress': VocabUsage('Long working hours can cause high levels of stress.', '', 'Jam kerja yang panjang dapat menyebabkan tingkat stres yang tinggi.', '', 'Nomina/verba. Verba: menekankan (stress the importance of). Adj: stressful.', 'Noun/verb. Verb: emphasize (stress the importance of). Adjective: stressful.'),
  'subsequent': VocabUsage('The policy was changed in subsequent years.', '', 'Kebijakan itu diubah pada tahun-tahun berikutnya.', '', 'Adjektiva formal. Pola: subsequent to = after. Adv: subsequently.', 'Formal adjective. Pattern: subsequent to = after. Adverb: subsequently.'),
  'sum': VocabUsage('The government spent a large sum on new hospitals.', '', 'Pemerintah menghabiskan sejumlah besar uang untuk rumah sakit baru.', '', 'Nomina/verba. Kolokasi: a large sum of money. Verba: sum up (merangkum).', 'Noun/verb. Collocation: a large sum of money. Verb: sum up (summarize).'),
  'summary': VocabUsage('Write a short summary of the article in about one hundred words.', '', 'Tulislah ringkasan singkat artikel itu dalam sekitar seratus kata.', '', 'Nomina. Pola: a summary of + noun; in summary (singkatnya). Verba: summarize.', 'Noun. Patterns: a summary of + noun; in summary. Verb: summarize.'),
  'undertake': VocabUsage('The university undertook a major study of student well-being.', '', 'Universitas itu menjalankan studi besar tentang kesejahteraan mahasiswa.', '', 'Kata kerja formal, tak beraturan: undertake-undertook-undertaken. Kolokasi: undertake research/a task.', 'Formal irregular verb: undertake-undertook-undertaken. Collocations: undertake research/a task.'),
  'academy': VocabUsage('She trained at a well-known music academy in Vienna.', '', 'Ia berlatih di akademi musik terkenal di Wina.', '', 'Nomina: lembaga pendidikan khusus. Adj: academic (akademik).', 'Noun: specialized school. Adjective: academic.'),
  'adjust': VocabUsage('It took several weeks for the students to adjust to the new schedule.', '', 'Butuh beberapa minggu bagi siswa untuk menyesuaikan diri dengan jadwal baru.', '', 'Kata kerja. Pola: adjust to + noun/V-ing (menyesuaikan diri); adjust X (menyetel). Nomina: adjustment.', 'Verb. Patterns: adjust to + noun/V-ing; adjust X (change slightly). Noun: adjustment.'),
  'alter': VocabUsage('The new evidence did not alter the main conclusions.', '', 'Bukti baru itu tidak mengubah kesimpulan utama.', '', 'Kata kerja formal dari \'change\', biasanya sedikit. Nomina: alteration.', 'Formal verb for \'change\', usually slightly. Noun: alteration.'),
  'amend': VocabUsage('Parliament voted to amend the law on data protection.', '', 'Parlemen memutuskan untuk mengamandemen undang-undang perlindungan data.', '', 'Kata kerja formal untuk aturan/dokumen. Nomina: amendment. Frasa: make amends (menebus).', 'Formal verb for laws/documents. Noun: amendment. Phrase: make amends.'),
  'aware': VocabUsage('Many people are not aware of the risks of too much screen time.', '', 'Banyak orang tidak sadar akan risiko terlalu lama menatap layar.', '', 'Adjektiva. Pola: be aware of + noun; aware that... Nomina: awareness (raise awareness).', 'Adjective. Patterns: be aware of + noun; aware that... Noun: awareness.'),
  'capacity': VocabUsage('The stadium has a capacity of fifty thousand people.', '', 'Stadion itu berkapasitas lima puluh ribu orang.', '', 'Nomina. Pola: a capacity of + angka; capacity for/to + V (kemampuan). Frasa: at full capacity.', 'Noun. Patterns: a capacity of + number; capacity for/to + verb. Phrase: at full capacity.'),
  'challenge': VocabUsage('Finding affordable housing is a major challenge for young families.', '', 'Mencari rumah yang terjangkau adalah tantangan besar bagi keluarga muda.', '', 'Nomina/verba. Kolokasi: face/meet a challenge. Adj: challenging.', 'Noun/verb. Collocations: face/meet a challenge. Adjective: challenging.'),
  'clause': VocabUsage('The contract includes a clause about early termination.', '', 'Kontrak itu memuat pasal tentang pemutusan lebih awal.', '', 'Nomina: pasal dalam dokumen hukum; juga klausa dalam tata bahasa.', 'Noun: section of a legal document; also a grammatical clause.'),
  'compound': VocabUsage('Water is a compound of hydrogen and oxygen.', '', 'Air adalah senyawa hidrogen dan oksigen.', '', 'Nomina/verba. Verba: memperparah (compound the problem). Kolokasi: chemical compound.', 'Noun/verb. Verb: make worse (compound the problem). Collocation: chemical compound.'),
  'conflict': VocabUsage('The conflict between the two groups lasted for many years.', '', 'Konflik antara kedua kelompok berlangsung bertahun-tahun.', '', 'Nomina/verba. Pola: conflict between/with; in conflict with; verba con-FLICT.', 'Noun/verb. Patterns: conflict between/with; in conflict with; verb stress con-FLICT.'),
  'consult': VocabUsage('Researchers should consult the existing literature before designing a new study.', '', 'Peneliti sebaiknya merujuk literatur yang ada sebelum merancang studi baru.', '', 'Kata kerja. Pola: consult + seseorang/sumber; consult with (berunding). Nomina: consultation.', 'Verb. Pattern: consult + person/source; consult with (discuss). Noun: consultation.'),
  'contact': VocabUsage('Please contact the research office if you have questions about funding.', '', 'Silakan hubungi kantor riset jika ada pertanyaan tentang pendanaan.', '', 'Kata kerja/benda. Contact + orang (tanpa \'to\'); be in contact with; contact details.', 'Verb/noun. Contact + person (no \'to\'); be in contact with; contact details.'),
  'decline': VocabUsage('The number of students enrolling in languages has declined steadily since 2010.', '', 'Jumlah mahasiswa yang mendaftar di jurusan bahasa terus menurun sejak 2010.', '', 'Kata kerja/benda. Decline by 10% / to 50; a sharp/steady decline in. Juga berarti \'menolak dengan sopan\'.', 'Verb/noun. Decline by 10% / to 50; a sharp/steady decline in. Also means \'politely refuse\'.'),
  'discrete': VocabUsage('The process can be divided into four discrete stages for analysis.', '', 'Proses itu dapat dibagi menjadi empat tahap terpisah untuk dianalisis.', '', 'Kata sifat. Kolokasi: discrete stages/units/categories. Jangan tertukar dengan discreet (bijaksana, hati-hati).', 'Adjective. Collocations: discrete stages/units/categories. Don\'t confuse with discreet (careful, tactful).'),
  'draft': VocabUsage('She sent the first draft of her essay to her supervisor for feedback.', '', 'Ia mengirim draf pertama esainya kepada pembimbing untuk mendapat masukan.', '', 'Kata benda/kerja. Kolokasi: first/final draft, draft a proposal/report.', 'Noun/verb. Collocations: first/final draft, draft a proposal/report.'),
  'enable': VocabUsage('Online databases enable students to access thousands of journal articles.', '', 'Basis data daring memungkinkan mahasiswa mengakses ribuan artikel jurnal.', '', 'Kata kerja. Pola: enable + seseorang + to + kata kerja. Lebih formal daripada \'allow\'.', 'Verb. Pattern: enable + someone + to + verb. More formal than \'allow\'.'),
  'energy': VocabUsage('Many countries are investing heavily in renewable energy such as solar power.', '', 'Banyak negara berinvestasi besar dalam energi terbarukan seperti tenaga surya.', '', 'Kata benda. Kolokasi: renewable/solar energy, energy consumption, save energy. Adj: energetic.', 'Noun. Collocations: renewable/solar energy, energy consumption, save energy. Adj: energetic.'),
  'enforce': VocabUsage('The government must enforce the new regulations on industrial pollution.', '', 'Pemerintah harus menegakkan peraturan baru tentang polusi industri.', '', 'Kata kerja. Kolokasi: enforce a law/rule/ban. Nomina: enforcement (law enforcement).', 'Verb. Collocations: enforce a law/rule/ban. Noun: enforcement (law enforcement).'),
  'entity': VocabUsage('The subsidiary operates as a separate legal entity from its parent company.', '', 'Anak perusahaan itu beroperasi sebagai entitas hukum yang terpisah dari induknya.', '', 'Kata benda formal. Kolokasi: legal/separate/single entity. Jamak: entities.', 'Formal noun. Collocations: legal/separate/single entity. Plural: entities.'),
  'equivalent': VocabUsage('A score of 6.5 in IELTS is roughly equivalent to a B2 level.', '', 'Skor 6,5 IELTS kurang lebih setara dengan level B2.', '', 'Kata sifat/benda. Pola: equivalent to sesuatu; the equivalent of. Jangan pakai \'equivalent with\'.', 'Adjective/noun. Pattern: equivalent to something; the equivalent of. Avoid \'equivalent with\'.'),
  'evolve': VocabUsage('Language constantly evolves as new technologies change the way people communicate.', '', 'Bahasa terus berkembang seiring teknologi baru mengubah cara orang berkomunikasi.', '', 'Kata kerja. Pola: evolve into/from sesuatu. Nomina: evolution; adj: evolutionary.', 'Verb. Pattern: evolve into/from something. Noun: evolution; adj: evolutionary.'),
  'expand': VocabUsage('The university plans to expand its research facilities over the next five years.', '', 'Universitas berencana memperluas fasilitas risetnya dalam lima tahun ke depan.', '', 'Kata kerja. Kolokasi: expand a business/market, expand on (menjabarkan). Nomina: expansion.', 'Verb. Collocations: expand a business/market, expand on (explain more). Noun: expansion.'),
  'expose': VocabUsage('The report exposed serious weaknesses in the country\'s healthcare system.', '', 'Laporan itu membuka kelemahan serius dalam sistem kesehatan negara tersebut.', '', 'Kata kerja. Pola: expose sesuatu; be exposed to (terpapar). Nomina: exposure.', 'Verb. Pattern: expose something; be exposed to (subjected to). Noun: exposure.'),
  'external': VocabUsage('The project was reviewed by two external examiners from other universities.', '', 'Proyek itu dinilai oleh dua penguji eksternal dari universitas lain.', '', 'Kata sifat. Lawan: internal. Kolokasi: external factors/examiner/pressure.', 'Adjective. Opposite: internal. Collocations: external factors/examiner/pressure.'),
  'facilitate': VocabUsage('Group discussions can facilitate deeper understanding of complex topics.', '', 'Diskusi kelompok dapat memudahkan pemahaman yang lebih dalam atas topik yang rumit.', '', 'Kata kerja formal. Langsung + objek (facilitate learning), bukan \'facilitate someone to\'. Nomina: facilitator.', 'Formal verb. Takes a direct object (facilitate learning), not \'facilitate someone to\'. Noun: facilitator.'),
  'fundamental': VocabUsage('Access to clean water is a fundamental human right.', '', 'Akses terhadap air bersih adalah hak asasi manusia yang mendasar.', '', 'Kata sifat. Kolokasi: fundamental principle/right/change; fundamental to sesuatu. Adv: fundamentally.', 'Adjective. Collocations: fundamental principle/right/change; fundamental to something. Adv: fundamentally.'),
  'generate': VocabUsage('Wind turbines generate electricity without producing greenhouse gases.', '', 'Turbin angin menghasilkan listrik tanpa menghasilkan gas rumah kaca.', '', 'Kata kerja. Kolokasi: generate electricity/income/interest/ideas. Nomina: generation, generator.', 'Verb. Collocations: generate electricity/income/interest/ideas. Nouns: generation, generator.'),
  'generation': VocabUsage('The younger generation tends to rely more on social media for news.', '', 'Generasi muda cenderung lebih mengandalkan media sosial untuk mendapatkan berita.', '', 'Kata benda. Kolokasi: younger/older/future generation(s), from generation to generation.', 'Noun. Collocations: younger/older/future generation(s), from generation to generation.'),
  'image': VocabUsage('The company launched a campaign to improve its public image.', '', 'Perusahaan itu meluncurkan kampanye untuk memperbaiki citra publiknya.', '', 'Kata benda. Arti gambar atau citra/reputasi. Kolokasi: public/brand image, digital image.', 'Noun. Means a picture or public impression. Collocations: public/brand image, digital image.'),
  'liberal': VocabUsage('The country adopted more liberal policies on trade and immigration.', '', 'Negara itu menerapkan kebijakan yang lebih liberal dalam perdagangan dan imigrasi.', '', 'Kata sifat/benda. Kolokasi: liberal attitudes/policies/democracy. Lawan: conservative.', 'Adjective/noun. Collocations: liberal attitudes/policies/democracy. Opposite: conservative.'),
  'license': VocabUsage('Every pharmacy must obtain a license before selling prescription drugs.', '', 'Setiap apotek harus memperoleh izin sebelum menjual obat resep.', '', 'Kata benda/kerja. Kolokasi: driving license, obtain/grant a license. Ejaan Inggris Britania (benda): licence.', 'Noun/verb. Collocations: driving license, obtain/grant a license. British noun spelling: licence.'),
  'logic': VocabUsage('The logic behind the argument is clear, but the evidence is weak.', '', 'Logika di balik argumen itu jelas, tetapi buktinya lemah.', '', 'Kata benda tak terhitung. Pola: the logic of/behind sesuatu. Adj: logical; adv: logically.', 'Uncountable noun. Pattern: the logic of/behind something. Adj: logical; adv: logically.'),
  'margin': VocabUsage('The candidate won the election by a narrow margin of two percent.', '', 'Kandidat itu memenangkan pemilu dengan selisih tipis dua persen.', '', 'Kata benda. Kolokasi: by a narrow/wide margin, profit margin, in the margin (pinggir halaman). Adj: marginal.', 'Noun. Collocations: by a narrow/wide margin, profit margin, in the margin (page edge). Adj: marginal.'),
  'medical': VocabUsage('Patients in rural areas often have limited access to medical services.', '', 'Pasien di daerah pedesaan sering kali memiliki akses terbatas ke layanan medis.', '', 'Kata sifat. Kolokasi: medical treatment/research/care/records. Beda: medicinal (berkhasiat obat).', 'Adjective. Collocations: medical treatment/research/care/records. Compare: medicinal (having healing effects).'),
  'mental': VocabUsage('Regular exercise has a positive effect on both physical and mental health.', '', 'Olahraga teratur berdampak positif pada kesehatan fisik maupun mental.', '', 'Kata sifat. Kolokasi: mental health/illness/state. Adv: mentally. Sering berpasangan dengan \'physical\'.', 'Adjective. Collocations: mental health/illness/state. Adv: mentally. Often paired with \'physical\'.'),
  'modify': VocabUsage('The researchers modified the questionnaire after receiving feedback from the pilot study.', '', 'Para peneliti memodifikasi kuesioner setelah menerima masukan dari studi percobaan.', '', 'Kata kerja. Arti: mengubah sedikit, bukan total. Nomina: modification. Kolokasi: genetically modified.', 'Verb. Means a small change, not a total one. Noun: modification. Collocation: genetically modified.'),
  'monitor': VocabUsage('Scientists monitor air quality in the city every hour.', '', 'Para ilmuwan memantau kualitas udara di kota itu setiap jam.', '', 'Kata kerja/benda. Kolokasi: monitor progress/performance/closely. Sebagai benda: layar komputer.', 'Verb/noun. Collocations: monitor progress/performance/closely. As a noun: a computer screen.'),
  'network': VocabUsage('The study examined how social networks influence students\' career choices.', '', 'Studi itu meneliti bagaimana jaringan sosial memengaruhi pilihan karier mahasiswa.', '', 'Kata benda/kerja. Kolokasi: social/computer/transport network. Kata kerja: networking (menjalin relasi).', 'Noun/verb. Collocations: social/computer/transport network. Verb: networking (building contacts).'),
  'notion': VocabUsage('The author challenges the notion that intelligence is fixed at birth.', '', 'Penulis menentang anggapan bahwa kecerdasan sudah tetap sejak lahir.', '', 'Kata benda. Pola: the notion that + klausa; the notion of sesuatu. Mirip: idea, concept.', 'Noun. Pattern: the notion that + clause; the notion of something. Similar: idea, concept.'),
  'objective': VocabUsage('Journalists are expected to remain objective when reporting on political issues.', '', 'Wartawan diharapkan tetap objektif saat memberitakan isu politik.', '', 'Kata sifat (tidak memihak) dan benda (tujuan). Lawan: subjective. Nomina: objectivity.', 'Adjective (unbiased) and noun (aim). Opposite: subjective. Noun: objectivity.'),
  'orient': VocabUsage('The course is oriented towards students who want to work in business.', '', 'Mata kuliah itu diarahkan untuk mahasiswa yang ingin bekerja di bidang bisnis.', '', 'Kata kerja, sering pasif: be oriented towards/to. Bentuk lain: orientation, -oriented (goal-oriented).', 'Verb, often passive: be oriented towards/to. Related: orientation, -oriented (goal-oriented).'),
  'perspective': VocabUsage('The essay examines climate change from an economic perspective.', '', 'Esai itu mengkaji perubahan iklim dari sudut pandang ekonomi.', '', 'Kata benda. Pola: from a ... perspective; put things into perspective (melihat secara proporsional).', 'Noun. Pattern: from a ... perspective; put things into perspective (see them proportionally).'),
  'precise': VocabUsage('Scientists need precise measurements to confirm their hypothesis.', '', 'Ilmuwan memerlukan pengukuran yang tepat untuk mengonfirmasi hipotesis mereka.', '', 'Kata sifat. Kolokasi: precise details/measurement/location. Adv: precisely; nomina: precision.', 'Adjective. Collocations: precise details/measurement/location. Adv: precisely; noun: precision.'),
  'prime': VocabUsage('Rising housing costs are a prime concern for young families.', '', 'Biaya perumahan yang naik adalah kekhawatiran paling utama bagi keluarga muda.', '', 'Kata sifat. Kolokasi: prime concern/example/minister/location. Mirip: main, chief.', 'Adjective. Collocations: prime concern/example/minister/location. Similar: main, chief.'),
  'psychology': VocabUsage('She is studying child psychology to understand how young learners develop.', '', 'Ia mempelajari psikologi anak untuk memahami perkembangan pembelajar muda.', '', 'Kata benda. Huruf p tidak dibaca. Bentuk terkait: psychologist, psychological.', 'Noun. The p is silent. Related: psychologist, psychological.'),
  'pursue': VocabUsage('Many graduates choose to pursue a master\'s degree abroad.', '', 'Banyak lulusan memilih untuk menempuh gelar magister di luar negeri.', '', 'Kata kerja. Kolokasi: pursue a career/degree/goal/dream. Nomina: pursuit.', 'Verb. Collocations: pursue a career/degree/goal/dream. Noun: pursuit.'),
  'ratio': VocabUsage('The student-to-teacher ratio in public schools is about thirty to one.', '', 'Rasio murid terhadap guru di sekolah negeri sekitar tiga puluh banding satu.', '', 'Kata benda. Pola: the ratio of A to B; a ratio of 3:1 (dibaca three to one).', 'Noun. Pattern: the ratio of A to B; a ratio of 3:1 (read three to one).'),
  'reject': VocabUsage('The committee rejected the proposal because of its high cost.', '', 'Komite menolak usulan itu karena biayanya yang tinggi.', '', 'Kata kerja. Kolokasi: reject a proposal/offer/idea/hypothesis. Nomina: rejection.', 'Verb. Collocations: reject a proposal/offer/idea/hypothesis. Noun: rejection.'),
  'revenue': VocabUsage('Tourism generates a large share of the region\'s annual revenue.', '', 'Pariwisata menghasilkan bagian besar dari pemasukan tahunan wilayah itu.', '', 'Kata benda. Kolokasi: generate/increase revenue, tax revenue. Mirip: income; beda dengan profit (laba).', 'Noun. Collocations: generate/increase revenue, tax revenue. Similar: income; differs from profit.'),
  'stable': VocabUsage('The economy has remained stable despite global uncertainty.', '', 'Perekonomian tetap stabil meskipun ada ketidakpastian global.', '', 'Kata sifat. Kolokasi: stable economy/condition/relationship. Nomina: stability; kerja: stabilize.', 'Adjective. Collocations: stable economy/condition/relationship. Noun: stability; verb: stabilize.'),
  'style': VocabUsage('Each student has a different learning style that teachers should consider.', '', 'Setiap siswa memiliki gaya belajar berbeda yang perlu diperhatikan guru.', '', 'Kata benda. Kolokasi: learning/writing/leadership style. Adj: stylish (bergaya).', 'Noun. Collocations: learning/writing/leadership style. Adj: stylish (fashionable).'),
  'substitute': VocabUsage('Honey can be used as a substitute for sugar in many recipes.', '', 'Madu dapat dipakai sebagai pengganti gula dalam banyak resep.', '', 'Kata benda/kerja. Pola: a substitute for X; substitute A for B (pakai A menggantikan B).', 'Noun/verb. Pattern: a substitute for X; substitute A for B (use A instead of B).'),
  'sustain': VocabUsage('Farmers struggle to sustain their income during long periods of drought.', '', 'Petani kesulitan mempertahankan penghasilan mereka saat kemarau panjang.', '', 'Kata kerja. Kolokasi: sustain growth/interest/life. Adj: sustainable; nomina: sustainability.', 'Verb. Collocations: sustain growth/interest/life. Adj: sustainable; noun: sustainability.'),
  'symbol': VocabUsage('The dove is widely recognized as a symbol of peace.', '', 'Burung merpati dikenal luas sebagai lambang perdamaian.', '', 'Kata benda. Pola: a symbol of sesuatu. Adj: symbolic; kerja: symbolize.', 'Noun. Pattern: a symbol of something. Adj: symbolic; verb: symbolize.'),
  'target': VocabUsage('The government set a target of reducing emissions by forty percent.', '', 'Pemerintah menetapkan target pengurangan emisi sebesar empat puluh persen.', '', 'Kata benda/kerja. Kolokasi: set/meet/reach a target; target audience. Kerja: target + kelompok.', 'Noun/verb. Collocations: set/meet/reach a target; target audience. Verb: target + a group.'),
  'transit': VocabUsage('The city is investing in public transit to reduce traffic congestion.', '', 'Kota itu berinvestasi pada angkutan umum untuk mengurangi kemacetan.', '', 'Kata benda. Kolokasi: public transit, in transit (dalam perjalanan), transit passenger.', 'Noun. Collocations: public transit, in transit (on the way), transit passenger.'),
  'trend': VocabUsage('There is a growing trend towards working from home in many industries.', '', 'Ada kecenderungan yang meningkat untuk bekerja dari rumah di banyak industri.', '', 'Kata benda. Pola: a trend towards/in sesuatu; upward/downward trend. Adj: trendy (gaul).', 'Noun. Pattern: a trend towards/in something; upward/downward trend. Adj: trendy.'),
  'version': VocabUsage('The revised version of the paper includes more recent data.', '', 'Versi revisi makalah itu memuat data yang lebih baru.', '', 'Kata benda. Kolokasi: latest/revised/earlier version, version of sesuatu.', 'Noun. Collocations: latest/revised/earlier version, version of something.'),
  'welfare': VocabUsage('Governments have a responsibility to protect the welfare of their citizens.', '', 'Pemerintah bertanggung jawab melindungi kesejahteraan warganya.', '', 'Kata benda tak terhitung. Kolokasi: social welfare, animal welfare, welfare system.', 'Uncountable noun. Collocations: social welfare, animal welfare, welfare system.'),
  'whereas': VocabUsage('Some students prefer group work, whereas others learn better alone.', '', 'Sebagian siswa lebih suka kerja kelompok, sedangkan yang lain belajar lebih baik sendiri.', '', 'Konjungsi untuk membandingkan dua fakta yang kontras. Mirip: while. Biasanya didahului koma.', 'Conjunction contrasting two facts. Similar: while. Usually preceded by a comma.'),
  'abstract': VocabUsage('Read the abstract first to decide whether the article is relevant.', '', 'Bacalah abstraknya dulu untuk memutuskan apakah artikel itu relevan.', '', 'Kata sifat (abstrak) dan benda (ringkasan makalah). Lawan: concrete. Kolokasi: abstract concept/idea.', 'Adjective (not concrete) and noun (paper summary). Opposite: concrete. Collocations: abstract concept/idea.'),
  'accurate': VocabUsage('Accurate data is essential for making reliable predictions.', '', 'Data yang akurat sangat penting untuk membuat prediksi yang andal.', '', 'Kata sifat. Kolokasi: accurate information/data/description. Nomina: accuracy; adv: accurately.', 'Adjective. Collocations: accurate information/data/description. Noun: accuracy; adv: accurately.'),
  'acknowledge': VocabUsage('The author acknowledges that the sample size was relatively small.', '', 'Penulis mengakui bahwa jumlah sampelnya relatif kecil.', '', 'Kata kerja. Pola: acknowledge that + klausa; acknowledge receipt of. Nomina: acknowledgement.', 'Verb. Pattern: acknowledge that + clause; acknowledge receipt of. Noun: acknowledgement.'),
  'aggregate': VocabUsage('The aggregate score is calculated from all four sections of the test.', '', 'Skor gabungan dihitung dari keempat bagian tes.', '', 'Kata sifat/benda. Kolokasi: aggregate data/score/demand; in aggregate (secara keseluruhan).', 'Adjective/noun. Collocations: aggregate data/score/demand; in aggregate (as a whole).'),
  'allocate': VocabUsage('The school allocated more funds to science laboratories this year.', '', 'Sekolah itu mengalokasikan lebih banyak dana untuk laboratorium sains tahun ini.', '', 'Kata kerja. Pola: allocate sesuatu to/for tujuan. Nomina: allocation.', 'Verb. Pattern: allocate something to/for a purpose. Noun: allocation.'),
  'assign': VocabUsage('The lecturer assigned each group a different research topic.', '', 'Dosen menugaskan topik penelitian yang berbeda kepada setiap kelompok.', '', 'Kata kerja. Pola: assign sb sth / assign sth to sb. Nomina: assignment (tugas).', 'Verb. Pattern: assign sb sth / assign sth to sb. Noun: assignment.'),
  'attach': VocabUsage('Please attach a copy of your certificate to the application form.', '', 'Harap lampirkan salinan sertifikat Anda pada formulir pendaftaran.', '', 'Kata kerja. Pola: attach sth to sth; be attached to (sayang pada). Nomina: attachment (lampiran).', 'Verb. Pattern: attach sth to sth; be attached to (fond of). Noun: attachment.'),
  'author': VocabUsage('The author argues that education should be free for everyone.', '', 'Penulis berpendapat bahwa pendidikan seharusnya gratis bagi semua orang.', '', 'Kata benda. Kolokasi: the author argues/claims, co-author. Kerja: author a report (menulis).', 'Noun. Collocations: the author argues/claims, co-author. Verb: author a report.'),
  'bond': VocabUsage('Shared experiences help create a strong bond between team members.', '', 'Pengalaman bersama membantu menciptakan ikatan kuat antaranggota tim.', '', 'Kata benda. Pola: a bond between/with; dalam keuangan: government bonds (obligasi).', 'Noun. Pattern: a bond between/with; in finance: government bonds.'),
  'brief': VocabUsage('The speaker gave a brief summary of the main findings.', '', 'Pembicara memberikan ringkasan singkat tentang temuan utama.', '', 'Kata sifat. Kolokasi: brief summary/introduction/period; in brief (singkatnya). Adv: briefly.', 'Adjective. Collocations: brief summary/introduction/period; in brief (in short). Adv: briefly.'),
  'capable': VocabUsage('Modern computers are capable of processing huge amounts of data.', '', 'Komputer modern mampu memproses data dalam jumlah sangat besar.', '', 'Kata sifat. Pola: capable of + V-ing/benda (bukan \'capable to\'). Nomina: capability.', 'Adjective. Pattern: capable of + V-ing/noun (not \'capable to\'). Noun: capability.'),
  'cite': VocabUsage('Students must cite all sources they use in their assignments.', '', 'Mahasiswa wajib mengutip semua sumber yang mereka pakai dalam tugas.', '', 'Kata kerja. Kolokasi: cite a source/study/example. Nomina: citation. Jangan tertukar dengan site/sight.', 'Verb. Collocations: cite a source/study/example. Noun: citation. Don\'t confuse with site/sight.'),
  'cooperate': VocabUsage('The two universities agreed to cooperate on a joint research project.', '', 'Kedua universitas sepakat bekerja sama dalam proyek riset bersama.', '', 'Kata kerja. Pola: cooperate with sb on sth. Nomina: cooperation; adj: cooperative.', 'Verb. Pattern: cooperate with sb on sth. Noun: cooperation; adj: cooperative.'),
  'discriminate': VocabUsage('It is illegal to discriminate against job applicants on the basis of age.', '', 'Membeda-bedakan pelamar kerja berdasarkan usia adalah melanggar hukum.', '', 'Kata kerja. Pola: discriminate against sb (tidak adil); discriminate between A and B (membedakan). Nomina: discrimination.', 'Verb. Pattern: discriminate against sb (unfairly); discriminate between A and B. Noun: discrimination.'),
  'display': VocabUsage('The museum displays artefacts from several ancient civilizations.', '', 'Museum itu memajang artefak dari beberapa peradaban kuno.', '', 'Kata kerja/benda. Kolokasi: on display (dipamerkan), display results/data.', 'Verb/noun. Collocations: on display, display results/data.'),
  'diverse': VocabUsage('Universities benefit from having a diverse student population.', '', 'Universitas diuntungkan dengan memiliki populasi mahasiswa yang beragam.', '', 'Kata sifat. Kolokasi: diverse group/population/range. Nomina: diversity; kerja: diversify.', 'Adjective. Collocations: diverse group/population/range. Noun: diversity; verb: diversify.'),
  'domain': VocabUsage('Artificial intelligence is no longer limited to the domain of computer science.', '', 'Kecerdasan buatan tidak lagi terbatas pada ranah ilmu komputer.', '', 'Kata benda. Pola: the domain of sesuatu; public domain (milik umum); domain name (internet).', 'Noun. Pattern: the domain of something; public domain; domain name (internet).'),
  'edit': VocabUsage('The journal asked her to edit the manuscript to meet the word limit.', '', 'Jurnal itu memintanya menyunting naskah agar sesuai batas jumlah kata.', '', 'Kata kerja. Bentuk terkait: editor, edition (edisi), editorial.', 'Verb. Related forms: editor, edition, editorial.'),
  'enhance': VocabUsage('Using visual aids can enhance students\' understanding of difficult concepts.', '', 'Penggunaan alat bantu visual dapat meningkatkan pemahaman siswa atas konsep yang sulit.', '', 'Kata kerja. Untuk meningkatkan mutu/nilai: enhance quality/performance/reputation. Nomina: enhancement.', 'Verb. Improves quality or value: enhance quality/performance/reputation. Noun: enhancement.'),
  'estate': VocabUsage('After his death, the family\'s estate was divided among his three children.', '', 'Setelah ia wafat, harta keluarga dibagi di antara ketiga anaknya.', '', 'Kata benda. Kolokasi: real estate (properti), housing estate (kompleks perumahan), estate agent.', 'Noun. Collocations: real estate, housing estate, estate agent.'),
  'exceed': VocabUsage('The number of applicants exceeded the university\'s expectations this year.', '', 'Jumlah pendaftar tahun ini melebihi perkiraan universitas.', '', 'Kata kerja (tanpa \'than\'). Kolokasi: exceed expectations/the limit. Adj/adv: excessive, exceedingly.', 'Verb (no \'than\'). Collocations: exceed expectations/the limit. Related: excessive, exceedingly.'),
  'expert': VocabUsage('Experts warn that sea levels could rise faster than predicted.', '', 'Para ahli memperingatkan bahwa permukaan laut bisa naik lebih cepat dari perkiraan.', '', 'Kata benda/sifat. Pola: an expert in/on sesuatu. Nomina: expertise (keahlian).', 'Noun/adjective. Pattern: an expert in/on something. Noun: expertise.'),
  'explicit': VocabUsage('The instructions should be explicit so that every participant understands them.', '', 'Petunjuknya harus tersurat agar setiap peserta memahaminya.', '', 'Kata sifat. Lawan: implicit (tersirat). Kolokasi: explicit instructions/reference. Adv: explicitly.', 'Adjective. Opposite: implicit. Collocations: explicit instructions/reference. Adv: explicitly.'),
  'federal': VocabUsage('The federal government provides funding for scientific research.', '', 'Pemerintah federal menyediakan dana untuk penelitian ilmiah.', '', 'Kata sifat. Kolokasi: federal government/law/agency. Nomina: federation.', 'Adjective. Collocations: federal government/law/agency. Noun: federation.'),
  'fee': VocabUsage('International students usually pay higher tuition fees than local students.', '', 'Mahasiswa internasional biasanya membayar biaya kuliah lebih tinggi daripada mahasiswa lokal.', '', 'Kata benda. Untuk jasa/pendaftaran: tuition/registration/entrance fee. Beda: fare (ongkos transport).', 'Noun. For services or entry: tuition/registration/entrance fee. Compare: fare (transport price).'),
  'flexible': VocabUsage('Flexible working hours can improve employees\' work-life balance.', '', 'Jam kerja yang fleksibel dapat memperbaiki keseimbangan kerja dan hidup karyawan.', '', 'Kata sifat. Kolokasi: flexible hours/approach/schedule. Nomina: flexibility.', 'Adjective. Collocations: flexible hours/approach/schedule. Noun: flexibility.'),
  'furthermore': VocabUsage('The method is inexpensive; furthermore, it produces very reliable results.', '', 'Metode itu murah; selain itu, hasilnya sangat andal.', '', 'Adverbia penghubung formal untuk menambah poin. Biasanya di awal kalimat + koma. Mirip: moreover.', 'Formal linking adverb adding a point. Usually sentence-initial + comma. Similar: moreover.'),
  'gender': VocabUsage('The study found no significant difference in test scores based on gender.', '', 'Studi itu tidak menemukan perbedaan nilai tes yang signifikan berdasarkan gender.', '', 'Kata benda. Kolokasi: gender equality/gap/roles. Sex lebih ke aspek biologis.', 'Noun. Collocations: gender equality/gap/roles. Sex refers more to biology.'),
  'ignorance': VocabUsage('Many myths about the disease persist because of public ignorance.', '', 'Banyak mitos tentang penyakit itu bertahan karena ketidaktahuan masyarakat.', '', 'Kata benda. Pola: ignorance of/about sesuatu. Adj: ignorant; kerja: ignore (mengabaikan, beda arti).', 'Noun. Pattern: ignorance of/about something. Adj: ignorant; verb ignore has a different meaning.'),
  'incentive': VocabUsage('Tax breaks provide an incentive for companies to invest in green technology.', '', 'Keringanan pajak memberi insentif bagi perusahaan untuk berinvestasi pada teknologi hijau.', '', 'Kata benda. Pola: an incentive for sb to do sth; financial incentive.', 'Noun. Pattern: an incentive for sb to do sth; financial incentive.'),
  'incidence': VocabUsage('The incidence of heart disease is higher among people who smoke.', '', 'Tingkat kejadian penyakit jantung lebih tinggi pada orang yang merokok.', '', 'Kata benda. Pola: the incidence of + penyakit/kejahatan. Beda: incident (satu peristiwa).', 'Noun. Pattern: the incidence of + disease/crime. Compare: incident (a single event).'),
  'incorporate': VocabUsage('The new curriculum incorporates environmental topics into science lessons.', '', 'Kurikulum baru memasukkan topik lingkungan ke dalam pelajaran sains.', '', 'Kata kerja. Pola: incorporate A into B. Nomina: incorporation; adj: incorporated (Inc., berbadan hukum).', 'Verb. Pattern: incorporate A into B. Noun: incorporation; adj: incorporated (Inc.).'),
  'index': VocabUsage('The consumer price index rose by three percent last year.', '', 'Indeks harga konsumen naik tiga persen tahun lalu.', '', 'Kata benda. Kolokasi: price index, index finger. Jamak: indexes atau indices (akademik).', 'Noun. Collocations: price index, index finger. Plural: indexes or indices (academic).'),
  'inhibit': VocabUsage('High interest rates may inhibit economic growth.', '', 'Suku bunga tinggi dapat menghambat pertumbuhan ekonomi.', '', 'Kata kerja formal. Kolokasi: inhibit growth/development. Nomina: inhibition.', 'Formal verb. Collocations: inhibit growth/development. Noun: inhibition.'),
  'initiate': VocabUsage('The government initiated a programme to reduce youth unemployment.', '', 'Pemerintah memulai program untuk mengurangi pengangguran kaum muda.', '', 'Kata kerja formal. Kolokasi: initiate a project/discussion/change. Nomina: initiative, initiation.', 'Formal verb. Collocations: initiate a project/discussion/change. Nouns: initiative, initiation.'),
  'input': VocabUsage('The final report includes input from teachers, parents and students.', '', 'Laporan akhir memuat masukan dari guru, orang tua, dan siswa.', '', 'Kata benda (umumnya tak terhitung). Pola: input from/into; lawan: output.', 'Noun (usually uncountable). Pattern: input from/into; opposite: output.'),
  'instruct': VocabUsage('Participants were instructed to complete the survey within ten minutes.', '', 'Peserta diinstruksikan untuk menyelesaikan survei dalam sepuluh menit.', '', 'Kata kerja. Pola: instruct sb to do sth. Nomina: instruction, instructor.', 'Verb. Pattern: instruct sb to do sth. Nouns: instruction, instructor.'),
  'intelligence': VocabUsage('Researchers still debate whether intelligence can be measured accurately.', '', 'Para peneliti masih memperdebatkan apakah kecerdasan dapat diukur secara akurat.', '', 'Kata benda tak terhitung. Kolokasi: artificial intelligence, emotional intelligence. Adj: intelligent.', 'Uncountable noun. Collocations: artificial intelligence, emotional intelligence. Adj: intelligent.'),
  'interval': VocabUsage('Blood samples were taken at regular intervals throughout the day.', '', 'Sampel darah diambil dengan selang waktu teratur sepanjang hari.', '', 'Kata benda. Kolokasi: at regular intervals, at intervals of two hours. Juga: jeda pertunjukan (BrE).', 'Noun. Collocations: at regular intervals, at intervals of two hours. Also: a break in a show (BrE).'),
  'lecture': VocabUsage('The professor gave a lecture on the history of economic thought.', '', 'Profesor itu memberikan kuliah tentang sejarah pemikiran ekonomi.', '', 'Kata benda/kerja. Kolokasi: give/attend a lecture on sth. Nomina: lecturer (dosen).', 'Noun/verb. Collocations: give/attend a lecture on sth. Noun: lecturer.'),
  'migrate': VocabUsage('Many young people migrate to big cities in search of better jobs.', '', 'Banyak anak muda bermigrasi ke kota besar untuk mencari pekerjaan yang lebih baik.', '', 'Kata kerja. Pola: migrate from A to B. Nomina: migration, migrant. Beda: immigrate (masuk), emigrate (keluar).', 'Verb. Pattern: migrate from A to B. Nouns: migration, migrant. Compare: immigrate, emigrate.'),
  'minimum': VocabUsage('Applicants need a minimum score of 6.0 in each section of the test.', '', 'Pelamar memerlukan skor minimum 6,0 di setiap bagian tes.', '', 'Kata benda/sifat. Kolokasi: minimum wage/requirement, keep sth to a minimum. Lawan: maximum.', 'Noun/adjective. Collocations: minimum wage/requirement, keep sth to a minimum. Opposite: maximum.'),
  'ministry': VocabUsage('The Ministry of Education announced changes to the national exam.', '', 'Kementerian Pendidikan mengumumkan perubahan pada ujian nasional.', '', 'Kata benda. Pola: the Ministry of + bidang (huruf kapital). Pejabatnya: minister (menteri).', 'Noun. Pattern: the Ministry of + field (capitalized). Its head: minister.'),
  'motive': VocabUsage('Police are still trying to establish the motive for the attack.', '', 'Polisi masih berusaha memastikan motif serangan itu.', '', 'Kata benda. Pola: motive for sesuatu. Bentuk terkait: motivate, motivation.', 'Noun. Pattern: motive for something. Related: motivate, motivation.'),
  'neutral': VocabUsage('Switzerland has remained politically neutral for centuries.', '', 'Swiss tetap netral secara politik selama berabad-abad.', '', 'Kata sifat. Kolokasi: remain/stay neutral, neutral position/colour. Nomina: neutrality.', 'Adjective. Collocations: remain/stay neutral, neutral position/colour. Noun: neutrality.'),
  'nevertheless': VocabUsage('The experiment had several limitations; nevertheless, the results were valuable.', '', 'Eksperimen itu punya beberapa keterbatasan; namun demikian, hasilnya tetap berharga.', '', 'Adverbia penghubung formal untuk kontras. Mirip: however, nonetheless. Biasanya diikuti koma.', 'Formal linking adverb for contrast. Similar: however, nonetheless. Usually followed by a comma.'),
  'overseas': VocabUsage('More students are choosing to study overseas than a decade ago.', '', 'Lebih banyak mahasiswa memilih kuliah di luar negeri dibanding sepuluh tahun lalu.', '', 'Adverbia/sifat. Go/study/work overseas (tanpa \'to\'); overseas students. Mirip: abroad.', 'Adverb/adjective. Go/study/work overseas (no \'to\'); overseas students. Similar: abroad.'),
  'precede': VocabUsage('A short introduction precedes each chapter of the book.', '', 'Sebuah pengantar singkat mendahului setiap bab buku itu.', '', 'Kata kerja. Adj: preceding (sebelumnya); nomina: precedent (preseden). Lawan: follow.', 'Verb. Adj: preceding; noun: precedent. Opposite: follow.'),
  'presume': VocabUsage('We presume that all participants answered the questions honestly.', '', 'Kami mengira bahwa semua peserta menjawab pertanyaan dengan jujur.', '', 'Kata kerja. Pola: presume that + klausa. Nomina: presumption; adv: presumably (agaknya).', 'Verb. Pattern: presume that + clause. Noun: presumption; adv: presumably.'),
  'rational': VocabUsage('Consumers do not always make rational decisions when shopping.', '', 'Konsumen tidak selalu membuat keputusan rasional saat berbelanja.', '', 'Kata sifat. Lawan: irrational. Kolokasi: rational decision/explanation/choice.', 'Adjective. Opposite: irrational. Collocations: rational decision/explanation/choice.'),
  'recover': VocabUsage('It took the economy several years to recover from the financial crisis.', '', 'Butuh beberapa tahun bagi perekonomian untuk pulih dari krisis keuangan.', '', 'Kata kerja. Pola: recover from sesuatu; recover costs (memperoleh kembali). Nomina: recovery.', 'Verb. Pattern: recover from something; recover costs (get back). Noun: recovery.'),
  'reveal': VocabUsage('The survey revealed that most employees wanted more training.', '', 'Survei itu mengungkapkan bahwa sebagian besar karyawan menginginkan lebih banyak pelatihan.', '', 'Kata kerja. Pola: reveal that + klausa; reveal a secret. Nomina: revelation.', 'Verb. Pattern: reveal that + clause; reveal a secret. Noun: revelation.'),
  'scope': VocabUsage('The scope of this study is limited to secondary schools in Jakarta.', '', 'Cakupan studi ini terbatas pada sekolah menengah di Jakarta.', '', 'Kata benda. Kolokasi: the scope of, beyond the scope of, scope for (peluang untuk).', 'Noun. Collocations: the scope of, beyond the scope of, scope for (room for).'),
  'subsidy': VocabUsage('Fuel subsidies place a heavy burden on the national budget.', '', 'Subsidi bahan bakar menjadi beban berat bagi anggaran negara.', '', 'Kata benda. Kolokasi: fuel/farm subsidies, cut subsidies. Kerja: subsidize.', 'Noun. Collocations: fuel/farm subsidies, cut subsidies. Verb: subsidize.'),
  'tape': VocabUsage('The interviews were recorded on tape and later transcribed.', '', 'Wawancara direkam pada pita lalu ditranskripsikan.', '', 'Kata benda/kerja. Kolokasi: sticky/adhesive tape, on tape; red tape (birokrasi berbelit).', 'Noun/verb. Collocations: sticky/adhesive tape, on tape; red tape (bureaucracy).'),
  'trace': VocabUsage('Historians traced the origins of the custom back to the twelfth century.', '', 'Para sejarawan melacak asal-usul adat itu hingga abad kedua belas.', '', 'Kata kerja/benda. Pola: trace sth back to; without trace; a trace of (sedikit sekali).', 'Verb/noun. Pattern: trace sth back to; without trace; a trace of (tiny amount).'),
  'transform': VocabUsage('The internet has transformed the way people shop and communicate.', '', 'Internet telah mengubah cara orang berbelanja dan berkomunikasi.', '', 'Kata kerja. Pola: transform A into B. Nomina: transformation. Lebih kuat dari \'change\'.', 'Verb. Pattern: transform A into B. Noun: transformation. Stronger than \'change\'.'),
  'transport': VocabUsage('Most goods are transported to the island by ship.', '', 'Sebagian besar barang diangkut ke pulau itu dengan kapal.', '', 'Kata kerja/benda. Public transport (BrE) = public transportation (AmE). Transport sth by sea/road.', 'Verb/noun. Public transport (BrE) = public transportation (AmE). Transport sth by sea/road.'),
  'underlie': VocabUsage('Several economic factors underlie the recent rise in unemployment.', '', 'Beberapa faktor ekonomi mendasari kenaikan pengangguran baru-baru ini.', '', 'Kata kerja tak beraturan (underlay, underlain). Lebih sering: underlying cause/problem.', 'Irregular verb (underlay, underlain). More common: underlying cause/problem.'),
  'utilize': VocabUsage('The study utilized satellite images to measure forest loss.', '', 'Studi itu menggunakan citra satelit untuk mengukur hilangnya hutan.', '', 'Kata kerja formal, mirip \'use\'. Nomina: utilization. Ejaan BrE: utilise.', 'Formal verb similar to \'use\'. Noun: utilization. BrE spelling: utilise.'),
  'adapt': VocabUsage('International students often need time to adapt to a new culture.', '', 'Mahasiswa internasional sering butuh waktu untuk menyesuaikan diri dengan budaya baru.', '', 'Kata kerja. Pola: adapt to sesuatu; adapt sth for. Nomina: adaptation. Beda: adopt (mengadopsi).', 'Verb. Pattern: adapt to something; adapt sth for. Noun: adaptation. Compare: adopt.'),
  'adult': VocabUsage('Many adults return to education to improve their career prospects.', '', 'Banyak orang dewasa kembali bersekolah untuk memperbaiki prospek karier mereka.', '', 'Kata benda/sifat. Kolokasi: adult education, young adult. Nomina: adulthood.', 'Noun/adjective. Collocations: adult education, young adult. Noun: adulthood.'),
  'advocate': VocabUsage('Many doctors advocate a diet low in sugar and salt.', '', 'Banyak dokter menganjurkan pola makan rendah gula dan garam.', '', 'Kata kerja (dibaca -keit) + objek langsung, tanpa \'for\'. Benda (dibaca -ket): an advocate of.', 'Verb (-kate) + direct object, no \'for\'. Noun (-kit): an advocate of.'),
  'aid': VocabUsage('The country received international aid after the earthquake.', '', 'Negara itu menerima bantuan internasional setelah gempa bumi.', '', 'Kata benda/kerja. Kolokasi: foreign/financial aid, first aid, in aid of. Lebih formal dari \'help\'.', 'Noun/verb. Collocations: foreign/financial aid, first aid, in aid of. More formal than \'help\'.'),
  'channel': VocabUsage('Social media has become an important channel for political communication.', '', 'Media sosial telah menjadi saluran penting untuk komunikasi politik.', '', 'Kata benda/kerja. Kolokasi: TV channel, communication channel; channel funds into (menyalurkan).', 'Noun/verb. Collocations: TV channel, communication channel; channel funds into.'),
  'chemical': VocabUsage('Farmers are being encouraged to reduce their use of chemical fertilizers.', '', 'Petani didorong untuk mengurangi penggunaan pupuk kimia.', '', 'Kata benda/sifat. Kolokasi: toxic/harmful chemicals, chemical reaction. Nomina: chemistry.', 'Noun/adjective. Collocations: toxic/harmful chemicals, chemical reaction. Noun: chemistry.'),
  'classic': VocabUsage('This book is considered a classic in the field of sociology.', '', 'Buku ini dianggap karya klasik di bidang sosiologi.', '', 'Kata sifat/benda: contoh unggul/khas (a classic example). Beda: classical (musik/era klasik).', 'Adjective/noun: excellent or typical (a classic example). Compare: classical (music/era).'),
  'comprehensive': VocabUsage('The report provides a comprehensive review of current teaching methods.', '', 'Laporan itu menyajikan tinjauan menyeluruh atas metode pengajaran saat ini.', '', 'Kata sifat. Kolokasi: comprehensive review/study/list. Jangan tertukar dengan comprehensible (dapat dipahami).', 'Adjective. Collocations: comprehensive review/study/list. Don\'t confuse with comprehensible.'),
  'comprise': VocabUsage('The committee comprises ten members from different departments.', '', 'Komite itu terdiri atas sepuluh anggota dari berbagai departemen.', '', 'Kata kerja. Pola: A comprises B (tanpa \'of\') atau A is comprised of B. Mirip: consist of.', 'Verb. Pattern: A comprises B (no \'of\') or A is comprised of B. Similar: consist of.'),
  'confirm': VocabUsage('Further tests confirmed the results of the initial experiment.', '', 'Uji lanjutan mengonfirmasi hasil eksperimen awal.', '', 'Kata kerja. Pola: confirm that + klausa; confirm a booking. Nomina: confirmation.', 'Verb. Pattern: confirm that + clause; confirm a booking. Noun: confirmation.'),
  'contrary': VocabUsage('Contrary to popular belief, eating fat does not always lead to weight gain.', '', 'Berlawanan dengan anggapan umum, makan lemak tidak selalu menyebabkan berat badan naik.', '', 'Kata sifat/benda. Pola: contrary to sesuatu; on the contrary (justru sebaliknya).', 'Adjective/noun. Pattern: contrary to something; on the contrary.'),
  'convert': VocabUsage('The old factory was converted into a modern art gallery.', '', 'Pabrik tua itu diubah menjadi galeri seni modern.', '', 'Kata kerja. Pola: convert A into/to B; convert currency. Nomina: conversion.', 'Verb. Pattern: convert A into/to B; convert currency. Noun: conversion.'),
  'couple': VocabUsage('The study interviewed fifty married couples about how they share housework.', '', 'Studi itu mewawancarai lima puluh pasangan suami istri tentang cara mereka berbagi pekerjaan rumah.', '', 'Kata benda: sepasang orang (a married couple). A couple of = dua atau beberapa (a couple of days).', 'Noun: a pair of people (a married couple). A couple of = two or a few (a couple of days).'),
  'decade': VocabUsage('Global temperatures have risen significantly over the past decade.', '', 'Suhu global naik secara signifikan selama satu dekade terakhir.', '', 'Kata benda. Kolokasi: over the past/last decade, for decades, in the next decade.', 'Noun. Collocations: over the past/last decade, for decades, in the next decade.'),
  'definite': VocabUsage('There has been a definite improvement in students\' writing skills.', '', 'Ada peningkatan yang pasti dalam keterampilan menulis siswa.', '', 'Kata sifat. Adv: definitely. Beda: definitive (final, paling otoritatif). Definite article = \'the\'.', 'Adjective. Adv: definitely. Compare: definitive (final, authoritative). Definite article = \'the\'.'),
  'deny': VocabUsage('The minister denied that the policy had failed.', '', 'Menteri itu menyangkal bahwa kebijakan tersebut gagal.', '', 'Kata kerja. Pola: deny + V-ing / deny that + klausa; deny sb access (tidak memberi). Nomina: denial.', 'Verb. Pattern: deny + V-ing / deny that + clause; deny sb access. Noun: denial.'),
  'differentiate': VocabUsage('Young children may find it hard to differentiate between fact and fiction.', '', 'Anak kecil mungkin sulit membedakan antara fakta dan fiksi.', '', 'Kata kerja. Pola: differentiate between A and B; differentiate A from B. Mirip: distinguish.', 'Verb. Pattern: differentiate between A and B; differentiate A from B. Similar: distinguish.'),
  'dispose': VocabUsage('Hospitals must dispose of medical waste safely.', '', 'Rumah sakit harus membuang limbah medis dengan aman.', '', 'Kata kerja, selalu: dispose of sesuatu. Nomina: disposal; adj: disposable (sekali pakai).', 'Verb, always: dispose of something. Noun: disposal; adj: disposable.'),
  'dynamic': VocabUsage('Hong Kong has one of the most dynamic economies in Asia.', '', 'Hong Kong memiliki salah satu perekonomian paling dinamis di Asia.', '', 'Kata sifat (dinamis) dan benda jamak (dynamics: pola interaksi). Kolokasi: dynamic environment/team.', 'Adjective and plural noun (dynamics: patterns of interaction). Collocations: dynamic environment/team.'),
  'eliminate': VocabUsage('The new system aims to eliminate errors in data entry.', '', 'Sistem baru itu bertujuan menghilangkan kesalahan dalam entri data.', '', 'Kata kerja. Kolokasi: eliminate poverty/errors/the need for. Nomina: elimination.', 'Verb. Collocations: eliminate poverty/errors/the need for. Noun: elimination.'),
  'empirical': VocabUsage('There is little empirical evidence to support this theory.', '', 'Hanya ada sedikit bukti empiris yang mendukung teori ini.', '', 'Kata sifat. Kolokasi: empirical evidence/research/data. Lawan: theoretical.', 'Adjective. Collocations: empirical evidence/research/data. Opposite: theoretical.'),
  'equip': VocabUsage('Schools should equip students with the skills needed for the modern workplace.', '', 'Sekolah seharusnya membekali siswa dengan keterampilan yang dibutuhkan dunia kerja modern.', '', 'Kata kerja. Pola: equip sb/sth with sesuatu; well-equipped. Nomina: equipment (tak terhitung).', 'Verb. Pattern: equip sb/sth with something; well-equipped. Noun: equipment (uncountable).'),
  'extract': VocabUsage('Oil is extracted from the seeds and used in cosmetics.', '', 'Minyak diekstrak dari biji tersebut lalu dipakai dalam kosmetik.', '', 'Kata kerja. Pola: extract A from B. Sebagai benda (an extract): kutipan atau sari.', 'Verb. Pattern: extract A from B. As a noun (an extract): a passage or concentrate.'),
  'file': VocabUsage('All patient files are stored securely on the hospital\'s server.', '', 'Semua berkas pasien disimpan dengan aman di server rumah sakit.', '', 'Kata benda/kerja. Kolokasi: open/save/attach a file; file a complaint (mengajukan).', 'Noun/verb. Collocations: open/save/attach a file; file a complaint.'),
  'finite': VocabUsage('The Earth has a finite supply of fossil fuels.', '', 'Bumi memiliki persediaan bahan bakar fosil yang terbatas.', '', 'Kata sifat. Lawan: infinite (tak terbatas). Kolokasi: finite resources/number.', 'Adjective. Opposite: infinite. Collocations: finite resources/number.'),
  'foundation': VocabUsage('A good primary education provides the foundation for later learning.', '', 'Pendidikan dasar yang baik memberikan fondasi bagi pembelajaran selanjutnya.', '', 'Kata benda. Pola: the foundation for/of; juga \'yayasan\' (a charitable foundation). Kerja: found.', 'Noun. Pattern: the foundation for/of; also an organization (a charitable foundation). Verb: found.'),
  'globe': VocabUsage('The disease spread rapidly across the globe within months.', '', 'Penyakit itu menyebar cepat ke seluruh dunia dalam hitungan bulan.', '', 'Kata benda. Kolokasi: across/around the globe. Adj: global; nomina: globalization.', 'Noun. Collocations: across/around the globe. Adj: global; noun: globalization.'),
  'grade': VocabUsage('Students who attend tutorials regularly tend to receive higher grades.', '', 'Mahasiswa yang rutin mengikuti tutorial cenderung mendapat nilai lebih tinggi.', '', 'Kata benda/kerja. Kolokasi: get/receive a grade; in grade 5 (AmE: kelas). Kerja: grade papers.', 'Noun/verb. Collocations: get/receive a grade; in grade 5 (AmE school year). Verb: grade papers.'),
  'guarantee': VocabUsage('A university degree no longer guarantees a well-paid job.', '', 'Gelar sarjana tidak lagi menjamin pekerjaan bergaji tinggi.', '', 'Kata kerja/benda. Pola: guarantee that + klausa; there is no guarantee that; under guarantee.', 'Verb/noun. Pattern: guarantee that + clause; there is no guarantee that; under guarantee.'),
  'hierarchy': VocabUsage('Decisions are made quickly because the company has a flat hierarchy.', '', 'Keputusan dibuat dengan cepat karena perusahaan itu memiliki hierarki yang datar.', '', 'Kata benda. Kolokasi: social/corporate hierarchy, in the hierarchy. Adj: hierarchical.', 'Noun. Collocations: social/corporate hierarchy, in the hierarchy. Adj: hierarchical.'),
  'identical': VocabUsage('The two groups were given identical instructions before the test.', '', 'Kedua kelompok diberi instruksi yang sama persis sebelum tes.', '', 'Kata sifat. Pola: identical to/with sesuatu; identical twins (kembar identik).', 'Adjective. Pattern: identical to/with something; identical twins.'),
  'ideology': VocabUsage('The party\'s political ideology strongly influences its economic policies.', '', 'Ideologi politik partai itu sangat memengaruhi kebijakan ekonominya.', '', 'Kata benda. Kolokasi: political/religious ideology. Adj: ideological.', 'Noun. Collocations: political/religious ideology. Adj: ideological.'),
  'infer': VocabUsage('From the data, we can infer that older users prefer printed materials.', '', 'Dari data itu, kita dapat menyimpulkan bahwa pengguna lebih tua menyukai bahan cetak.', '', 'Kata kerja. Pola: infer sth from sth; infer that. Nomina: inference. Beda: imply (menyiratkan).', 'Verb. Pattern: infer sth from sth; infer that. Noun: inference. Compare: imply.'),
  'innovate': VocabUsage('Companies must continually innovate to stay ahead of their competitors.', '', 'Perusahaan harus terus berinovasi agar tetap unggul dari pesaing.', '', 'Kata kerja. Bentuk terkait: innovation, innovative, innovator.', 'Verb. Related forms: innovation, innovative, innovator.'),
  'insert': VocabUsage('Insert a table to summarise the main results of your survey.', '', 'Sisipkan tabel untuk merangkum hasil utama survei Anda.', '', 'Kata kerja. Pola: insert sth into/in sth. Nomina: insertion; sebagai benda: an insert (sisipan).', 'Verb. Pattern: insert sth into/in sth. Noun: insertion; also a noun: an insert.'),
  'intervene': VocabUsage('The central bank intervened to stop the currency from falling further.', '', 'Bank sentral campur tangan untuk menghentikan nilai mata uang agar tidak jatuh lebih jauh.', '', 'Kata kerja. Pola: intervene in sesuatu; intervene to do sth. Nomina: intervention.', 'Verb. Pattern: intervene in something; intervene to do sth. Noun: intervention.'),
  'isolate': VocabUsage('Scientists isolated the gene responsible for the disease.', '', 'Para ilmuwan mengisolasi gen yang menyebabkan penyakit itu.', '', 'Kata kerja. Pola: isolate A from B; feel isolated (merasa terasing). Nomina: isolation.', 'Verb. Pattern: isolate A from B; feel isolated. Noun: isolation.'),
  'media': VocabUsage('The media play a powerful role in shaping public opinion.', '', 'Media berperan kuat dalam membentuk opini publik.', '', 'Kata benda (jamak dari medium), bisa diikuti verba tunggal/jamak. Kolokasi: social/mass media.', 'Noun (plural of medium), takes singular or plural verb. Collocations: social/mass media.'),
  'mode': VocabUsage('Cycling is a healthy and cheap mode of transport.', '', 'Bersepeda adalah ragam transportasi yang sehat dan murah.', '', 'Kata benda. Kolokasi: mode of transport/communication, in silent/offline mode.', 'Noun. Collocations: mode of transport/communication, in silent/offline mode.'),
  'paradigm': VocabUsage('The discovery led to a paradigm shift in modern physics.', '', 'Penemuan itu memicu pergeseran paradigma dalam fisika modern.', '', 'Kata benda formal. Kolokasi: paradigm shift, new paradigm. Huruf g tidak dibaca.', 'Formal noun. Collocations: paradigm shift, new paradigm. The g is silent.'),
  'phenomenon': VocabUsage('Urbanization is a global phenomenon affecting both rich and poor countries.', '', 'Urbanisasi adalah fenomena global yang memengaruhi negara kaya maupun miskin.', '', 'Kata benda. Jamak: phenomena (bukan phenomenons). Adj: phenomenal (luar biasa).', 'Noun. Plural: phenomena (not phenomenons). Adj: phenomenal (extraordinary).'),
  'priority': VocabUsage('Improving public health should be a top priority for the government.', '', 'Meningkatkan kesehatan masyarakat seharusnya menjadi prioritas utama pemerintah.', '', 'Kata benda. Kolokasi: top/high priority, give priority to. Kerja: prioritize.', 'Noun. Collocations: top/high priority, give priority to. Verb: prioritize.'),
  'prohibit': VocabUsage('Smoking is prohibited in all public buildings.', '', 'Merokok dilarang di semua gedung umum.', '', 'Kata kerja formal, sering pasif. Pola: prohibit sb from + V-ing. Nomina: prohibition.', 'Formal verb, often passive. Pattern: prohibit sb from + V-ing. Noun: prohibition.'),
  'publication': VocabUsage('The publication of the report has been delayed until next year.', '', 'Penerbitan laporan itu ditunda hingga tahun depan.', '', 'Kata benda: proses menerbitkan atau karya terbitan. Kerja: publish.', 'Noun: the act of publishing or a published work. Verb: publish.'),
  'quote': VocabUsage('The essay begins with a quote from a famous economist.', '', 'Esai itu dibuka dengan kutipan dari seorang ekonom terkenal.', '', 'Kata benda/kerja. Pola: a quote from sb; quote sb. Formal: quotation. Juga \'penawaran harga\'.', 'Noun/verb. Pattern: a quote from sb; quote sb. Formal: quotation. Also a price estimate.'),
  'release': VocabUsage('The government will release the latest unemployment figures next week.', '', 'Pemerintah akan merilis angka pengangguran terbaru minggu depan.', '', 'Kata kerja/benda. Kolokasi: release data/a report/a film; release sb from; press release.', 'Verb/noun. Collocations: release data/a report/a film; release sb from; press release.'),
  'reverse': VocabUsage('The new policy aims to reverse the decline in rural populations.', '', 'Kebijakan baru itu bertujuan membalik penurunan populasi pedesaan.', '', 'Kata kerja/sifat/benda. Kolokasi: reverse a trend/decision; in reverse order. Adj: reversible.', 'Verb/adjective/noun. Collocations: reverse a trend/decision; in reverse order. Adj: reversible.'),
  'simulate': VocabUsage('Pilots train in machines that simulate real flight conditions.', '', 'Pilot berlatih di mesin yang menyimulasikan kondisi terbang sungguhan.', '', 'Kata kerja. Kolokasi: simulate conditions/an environment. Nomina: simulation, simulator.', 'Verb. Collocations: simulate conditions/an environment. Nouns: simulation, simulator.'),
  'sole': VocabUsage('Tourism is the sole source of income for many island communities.', '', 'Pariwisata adalah satu-satunya sumber penghasilan bagi banyak komunitas pulau.', '', 'Kata sifat (sebelum benda). Kolokasi: sole purpose/source/responsibility. Adv: solely.', 'Adjective (before a noun). Collocations: sole purpose/source/responsibility. Adv: solely.'),
  'somewhat': VocabUsage('The results were somewhat different from what we had expected.', '', 'Hasilnya agak berbeda dari yang kami harapkan.', '', 'Adverbia penurun intensitas, lebih formal dari \'a bit\'. Pola: somewhat + adj/adv.', 'Softening adverb, more formal than \'a bit\'. Pattern: somewhat + adj/adv.'),
  'submit': VocabUsage('All assignments must be submitted online before the deadline.', '', 'Semua tugas harus diserahkan secara daring sebelum tenggat waktu.', '', 'Kata kerja. Kolokasi: submit an assignment/application/proposal; submit to (tunduk). Nomina: submission.', 'Verb. Collocations: submit an assignment/application/proposal; submit to (yield). Noun: submission.'),
  'successor': VocabUsage('The retiring director will help train her successor.', '', 'Direktur yang akan pensiun itu akan membantu melatih penerusnya.', '', 'Kata benda. Pola: successor to sb/sth. Lawan: predecessor. Kerja: succeed (menggantikan).', 'Noun. Pattern: successor to sb/sth. Opposite: predecessor. Verb: succeed (follow).'),
  'survive': VocabUsage('Only a few species can survive in such extreme temperatures.', '', 'Hanya sedikit spesies yang dapat bertahan hidup dalam suhu seekstrem itu.', '', 'Kata kerja. Pola: survive (on/in) sesuatu; survive a crisis. Nomina: survival, survivor.', 'Verb. Pattern: survive (on/in) something; survive a crisis. Nouns: survival, survivor.'),
  'thesis': VocabUsage('He spent two years writing his thesis on urban water supply.', '', 'Ia menghabiskan dua tahun menulis tesisnya tentang pasokan air perkotaan.', '', 'Kata benda. Jamak: theses. Juga \'pendapat utama\' esai (thesis statement).', 'Noun. Plural: theses. Also the main claim of an essay (thesis statement).'),
  'topic': VocabUsage('Climate change is a common topic in IELTS writing tasks.', '', 'Perubahan iklim adalah topik yang umum dalam tugas menulis IELTS.', '', 'Kata benda. Kolokasi: discuss/choose a topic, topic sentence. Adj: topical (sedang hangat).', 'Noun. Collocations: discuss/choose a topic, topic sentence. Adj: topical (currently of interest).'),
  'transmit': VocabUsage('Mosquitoes can transmit diseases such as malaria and dengue.', '', 'Nyamuk dapat menularkan penyakit seperti malaria dan demam berdarah.', '', 'Kata kerja. Kolokasi: transmit a disease/signal/data. Nomina: transmission.', 'Verb. Collocations: transmit a disease/signal/data. Noun: transmission.'),
  'ultimate': VocabUsage('The ultimate goal of the project is to reduce child poverty.', '', 'Tujuan akhir proyek ini adalah mengurangi kemiskinan anak.', '', 'Kata sifat. Kolokasi: ultimate goal/aim/responsibility. Adv: ultimately (pada akhirnya).', 'Adjective. Collocations: ultimate goal/aim/responsibility. Adv: ultimately.'),
  'unique': VocabUsage('Each region has its own unique traditions and cuisine.', '', 'Setiap daerah memiliki tradisi dan kuliner uniknya sendiri.', '', 'Kata sifat. Pola: unique to sesuatu. Arti asli \'satu-satunya\', jadi hindari \'very unique\' dalam tulisan formal.', 'Adjective. Pattern: unique to something. Means one of a kind, so avoid \'very unique\' in formal writing.'),
  'visible': VocabUsage('The effects of pollution are clearly visible in the river.', '', 'Dampak polusi terlihat jelas di sungai itu.', '', 'Kata sifat. Kolokasi: clearly/highly visible, visible to sb. Lawan: invisible. Nomina: visibility.', 'Adjective. Collocations: clearly/highly visible, visible to sb. Opposite: invisible. Noun: visibility.'),
  'voluntary': VocabUsage('Participation in the study was entirely voluntary.', '', 'Keikutsertaan dalam studi itu sepenuhnya sukarela.', '', 'Kata sifat. Lawan: compulsory. Kolokasi: voluntary work/organization. Nomina: volunteer (relawan).', 'Adjective. Opposite: compulsory. Collocations: voluntary work/organization. Noun: volunteer.'),
  'abandon': VocabUsage('The project was abandoned due to a lack of funding.', '', 'Proyek itu ditinggalkan karena kekurangan dana.', '', 'Kata kerja. Kolokasi: abandon a plan/project/idea; abandoned building. Nomina: abandonment.', 'Verb. Collocations: abandon a plan/project/idea; abandoned building. Noun: abandonment.'),
  'accompany': VocabUsage('Children under twelve must be accompanied by an adult.', '', 'Anak di bawah dua belas tahun harus didampingi orang dewasa.', '', 'Kata kerja (tanpa \'with\'): accompany sb. Sering pasif: be accompanied by.', 'Verb (no \'with\'): accompany sb. Often passive: be accompanied by.'),
  'accumulate': VocabUsage('Plastic waste continues to accumulate in the world\'s oceans.', '', 'Sampah plastik terus menumpuk di samudra dunia.', '', 'Kata kerja. Kolokasi: accumulate wealth/data/debt. Nomina: accumulation.', 'Verb. Collocations: accumulate wealth/data/debt. Noun: accumulation.'),
  'ambiguous': VocabUsage('Some survey questions were ambiguous and confused the respondents.', '', 'Beberapa pertanyaan survei bermakna ganda dan membingungkan responden.', '', 'Kata sifat. Lawan: clear, unambiguous. Nomina: ambiguity.', 'Adjective. Opposite: clear, unambiguous. Noun: ambiguity.'),
  'append': VocabUsage('A full list of interview questions is appended to the report.', '', 'Daftar lengkap pertanyaan wawancara dilampirkan di akhir laporan.', '', 'Kata kerja formal. Pola: append sth to sth. Nomina: appendix (lampiran).', 'Formal verb. Pattern: append sth to sth. Noun: appendix.'),
  'appreciate': VocabUsage('Employees appreciate managers who listen to their ideas.', '', 'Karyawan menghargai manajer yang mau mendengarkan ide mereka.', '', 'Kata kerja. Pola: appreciate sth / I\'d appreciate it if. Juga \'naik nilai\'. Nomina: appreciation.', 'Verb. Pattern: appreciate sth / I\'d appreciate it if. Also \'rise in value\'. Noun: appreciation.'),
  'arbitrary': VocabUsage('The selection of participants should not be arbitrary.', '', 'Pemilihan peserta seharusnya tidak dilakukan sembarangan.', '', 'Kata sifat. Kolokasi: arbitrary decision/choice/arrest. Adv: arbitrarily.', 'Adjective. Collocations: arbitrary decision/choice/arrest. Adv: arbitrarily.'),
  'automate': VocabUsage('Many factories have automated their production lines to cut costs.', '', 'Banyak pabrik telah mengotomatiskan lini produksinya untuk memangkas biaya.', '', 'Kata kerja. Nomina: automation; adj: automatic, automated.', 'Verb. Noun: automation; adj: automatic, automated.'),
  'bias': VocabUsage('Researchers must avoid bias when selecting their samples.', '', 'Peneliti harus menghindari bias saat memilih sampel.', '', 'Kata benda/kerja. Pola: bias against/towards sesuatu. Adj: biased (berat sebelah).', 'Noun/verb. Pattern: bias against/towards something. Adj: biased.'),
  'chart': VocabUsage('The chart shows changes in energy consumption between 1990 and 2020.', '', 'Grafik itu menunjukkan perubahan konsumsi energi antara 1990 dan 2020.', '', 'Kata benda/kerja. Kolokasi: bar/pie chart, the chart shows/illustrates. Kerja: chart progress.', 'Noun/verb. Collocations: bar/pie chart, the chart shows/illustrates. Verb: chart progress.'),
  'clarify': VocabUsage('Could you clarify what you mean by sustainable development?', '', 'Bisakah Anda menjelaskan apa yang Anda maksud dengan pembangunan berkelanjutan?', '', 'Kata kerja. Kolokasi: clarify a point/issue/meaning. Nomina: clarification.', 'Verb. Collocations: clarify a point/issue/meaning. Noun: clarification.'),
  'commodity': VocabUsage('Coffee is one of the most traded commodities in the world.', '', 'Kopi adalah salah satu komoditas yang paling banyak diperdagangkan di dunia.', '', 'Kata benda. Kolokasi: commodity prices, valuable commodity. Jamak: commodities.', 'Noun. Collocations: commodity prices, valuable commodity. Plural: commodities.'),
  'complement': VocabUsage('The online course is designed to complement classroom teaching.', '', 'Kursus daring itu dirancang untuk melengkapi pengajaran di kelas.', '', 'Kata kerja/benda. Adj: complementary. Jangan tertukar dengan compliment (memuji).', 'Verb/noun. Adj: complementary. Don\'t confuse with compliment (praise).'),
  'conform': VocabUsage('All products must conform to international safety standards.', '', 'Semua produk harus mematuhi standar keselamatan internasional.', '', 'Kata kerja. Pola: conform to/with aturan. Nomina: conformity.', 'Verb. Pattern: conform to/with rules. Noun: conformity.'),
  'contemporary': VocabUsage('The gallery focuses on contemporary art from Southeast Asia.', '', 'Galeri itu berfokus pada seni kontemporer dari Asia Tenggara.', '', 'Kata sifat/benda. Kolokasi: contemporary art/society/issues. Juga \'sezaman\' (contemporary with).', 'Adjective/noun. Collocations: contemporary art/society/issues. Also \'of the same era\' (contemporary with).'),
  'contradict': VocabUsage('The new findings contradict earlier studies on the topic.', '', 'Temuan baru itu bertentangan dengan studi-studi sebelumnya tentang topik tersebut.', '', 'Kata kerja + objek langsung (tanpa \'with\'). Nomina: contradiction; adj: contradictory.', 'Verb + direct object (no \'with\'). Noun: contradiction; adj: contradictory.'),
  'crucial': VocabUsage('Early diagnosis is crucial for successful treatment of the disease.', '', 'Diagnosis dini sangat penting bagi keberhasilan pengobatan penyakit itu.', '', 'Kata sifat. Pola: crucial to/for sesuatu; it is crucial that. Lebih kuat dari \'important\'.', 'Adjective. Pattern: crucial to/for something; it is crucial that. Stronger than \'important\'.'),
  'currency': VocabUsage('The value of the local currency fell sharply against the US dollar.', '', 'Nilai mata uang lokal turun tajam terhadap dolar AS.', '', 'Kata benda. Kolokasi: foreign/local currency, currency exchange. Juga \'keberlakuan\' (gain currency).', 'Noun. Collocations: foreign/local currency, currency exchange. Also \'acceptance\' (gain currency).'),
  'denote': VocabUsage('In this chart, the red line denotes average monthly rainfall.', '', 'Dalam grafik ini, garis merah melambangkan rata-rata curah hujan bulanan.', '', 'Kata kerja formal. Mirip: represent, stand for. Nomina: denotation.', 'Formal verb. Similar: represent, stand for. Noun: denotation.'),
  'detect': VocabUsage('The test can detect the virus within the first few days of infection.', '', 'Tes itu dapat mendeteksi virus dalam beberapa hari pertama infeksi.', '', 'Kata kerja. Kolokasi: detect a change/signal/disease. Nomina: detection, detector, detective.', 'Verb. Collocations: detect a change/signal/disease. Nouns: detection, detector, detective.'),
  'deviate': VocabUsage('The results did not deviate significantly from the predicted values.', '', 'Hasilnya tidak menyimpang secara signifikan dari nilai yang diprediksi.', '', 'Kata kerja. Pola: deviate from sesuatu. Nomina: deviation (standard deviation).', 'Verb. Pattern: deviate from something. Noun: deviation (standard deviation).'),
  'displace': VocabUsage('Thousands of families were displaced by the construction of the dam.', '', 'Ribuan keluarga tergusur akibat pembangunan bendungan itu.', '', 'Kata kerja, sering pasif. Kolokasi: displaced people/workers. Nomina: displacement.', 'Verb, often passive. Collocations: displaced people/workers. Noun: displacement.'),
  'drama': VocabUsage('Studying drama can help students build confidence and communication skills.', '', 'Mempelajari drama dapat membantu siswa membangun kepercayaan diri dan keterampilan komunikasi.', '', 'Kata benda. Juga \'kejadian heboh\' (a lot of drama). Adj: dramatic (juga \'drastis\').', 'Noun. Also \'exciting events\' (a lot of drama). Adj: dramatic (also \'sudden and large\').'),
  'eventual': VocabUsage('The eventual cost of the project was twice the original estimate.', '', 'Biaya akhir proyek itu ternyata dua kali lipat dari perkiraan awal.', '', 'Kata sifat (sebelum benda). Adv: eventually (akhirnya). Bukan berarti \'mungkin\' seperti \'eventual\' di bahasa lain.', 'Adjective (before a noun). Adv: eventually. Does not mean \'possible\'.'),
  'exhibit': VocabUsage('The museum will exhibit works by young local artists next month.', '', 'Museum itu akan memamerkan karya seniman muda lokal bulan depan.', '', 'Kata kerja/benda. Juga \'menunjukkan\' (exhibit symptoms). Nomina: exhibition (pameran).', 'Verb/noun. Also \'show\' (exhibit symptoms). Noun: exhibition.'),
  'exploit': VocabUsage('Developing countries should exploit their natural resources sustainably.', '', 'Negara berkembang seharusnya memanfaatkan sumber daya alamnya secara berkelanjutan.', '', 'Kata kerja. Netral (memanfaatkan) atau negatif (exploit workers). Nomina: exploitation.', 'Verb. Neutral (make use of) or negative (exploit workers). Noun: exploitation.'),
  'fluctuate': VocabUsage('Food prices tend to fluctuate depending on the season.', '', 'Harga pangan cenderung naik-turun tergantung musim.', '', 'Kata kerja, khas deskripsi grafik IELTS. Pola: fluctuate between A and B. Nomina: fluctuation.', 'Verb, typical in IELTS graph descriptions. Pattern: fluctuate between A and B. Noun: fluctuation.'),
  'guideline': VocabUsage('The university has published guidelines on the use of AI tools in assignments.', '', 'Universitas telah menerbitkan pedoman penggunaan alat AI dalam tugas.', '', 'Kata benda, sering jamak. Kolokasi: follow/issue guidelines, guidelines on/for.', 'Noun, often plural. Collocations: follow/issue guidelines, guidelines on/for.'),
  'highlight': VocabUsage('The report highlights the need for better public transport.', '', 'Laporan itu menyoroti perlunya transportasi umum yang lebih baik.', '', 'Kata kerja/benda. Kolokasi: highlight the need/importance of; the highlight of (bagian terbaik).', 'Verb/noun. Collocations: highlight the need/importance of; the highlight of (best part).'),
  'implicit': VocabUsage('There is an implicit assumption that all students have internet access.', '', 'Ada asumsi tersirat bahwa semua siswa memiliki akses internet.', '', 'Kata sifat. Lawan: explicit. Pola: implicit in sesuatu. Adv: implicitly.', 'Adjective. Opposite: explicit. Pattern: implicit in something. Adv: implicitly.'),
  'induce': VocabUsage('Some medicines can induce sleepiness as a side effect.', '', 'Beberapa obat dapat menyebabkan kantuk sebagai efek samping.', '', 'Kata kerja formal. Pola: induce sth / induce sb to do sth. Nomina: inducement, induction.', 'Formal verb. Pattern: induce sth / induce sb to do sth. Nouns: inducement, induction.'),
  'inevitable': VocabUsage('Some job losses are inevitable as technology replaces manual work.', '', 'Sebagian kehilangan pekerjaan tak terhindarkan seiring teknologi menggantikan kerja manual.', '', 'Kata sifat. Pola: it is inevitable that. Adv: inevitably. Mirip: unavoidable.', 'Adjective. Pattern: it is inevitable that. Adv: inevitably. Similar: unavoidable.'),
  'infrastructure': VocabUsage('Poor infrastructure limits economic development in remote areas.', '', 'Infrastruktur yang buruk membatasi pembangunan ekonomi di daerah terpencil.', '', 'Kata benda tak terhitung. Kolokasi: transport/digital infrastructure, invest in infrastructure.', 'Uncountable noun. Collocations: transport/digital infrastructure, invest in infrastructure.'),
  'inspect': VocabUsage('Officials regularly inspect restaurants to ensure food safety.', '', 'Petugas rutin memeriksa restoran untuk memastikan keamanan pangan.', '', 'Kata kerja: memeriksa secara resmi/teliti. Nomina: inspection, inspector.', 'Verb: to check officially or carefully. Nouns: inspection, inspector.'),
  'intense': VocabUsage('The plan faced intense criticism from environmental groups.', '', 'Rencana itu menghadapi kritik hebat dari kelompok lingkungan.', '', 'Kata sifat. Kolokasi: intense pressure/heat/competition. Nomina: intensity; adj: intensive.', 'Adjective. Collocations: intense pressure/heat/competition. Noun: intensity; adj: intensive.'),
  'manipulate': VocabUsage('Advertisers sometimes manipulate consumers\' emotions to sell products.', '', 'Pengiklan terkadang memanipulasi emosi konsumen untuk menjual produk.', '', 'Kata kerja. Negatif untuk orang; netral untuk data/objek (manipulate variables). Nomina: manipulation.', 'Verb. Negative for people; neutral for data/objects (manipulate variables). Noun: manipulation.'),
  'minimize': VocabUsage('Wearing masks helps minimize the spread of respiratory infections.', '', 'Memakai masker membantu meminimalkan penyebaran infeksi saluran pernapasan.', '', 'Kata kerja. Kolokasi: minimize risk/costs/damage. Lawan: maximize. Ejaan BrE: minimise.', 'Verb. Collocations: minimize risk/costs/damage. Opposite: maximize. BrE spelling: minimise.'),
  'nuclear': VocabUsage('Some countries rely heavily on nuclear power for electricity.', '', 'Beberapa negara sangat bergantung pada tenaga nuklir untuk listrik.', '', 'Kata sifat. Kolokasi: nuclear power/energy/weapons; nuclear family (keluarga inti).', 'Adjective. Collocations: nuclear power/energy/weapons; nuclear family.'),
  'offset': VocabUsage('Higher sales offset the increase in production costs.', '', 'Penjualan yang lebih tinggi menutupi kenaikan biaya produksi.', '', 'Kata kerja tak beraturan (offset-offset). Pola: offset A by/against B; carbon offset.', 'Irregular verb (offset-offset). Pattern: offset A by/against B; carbon offset.'),
  'paragraph': VocabUsage('Each paragraph should begin with a clear topic sentence.', '', 'Setiap paragraf sebaiknya diawali dengan kalimat topik yang jelas.', '', 'Kata benda. Kolokasi: opening/final paragraph, in the second paragraph.', 'Noun. Collocations: opening/final paragraph, in the second paragraph.'),
  'plus': VocabUsage('The course fee is 500 dollars, plus a small registration charge.', '', 'Biaya kursus 500 dolar, ditambah biaya pendaftaran yang kecil.', '', 'Preposisi/benda. Pola: A plus B; a plus (nilai tambah). Lawan: minus.', 'Preposition/noun. Pattern: A plus B; a plus (an advantage). Opposite: minus.'),
  'practitioner': VocabUsage('Medical practitioners must update their knowledge regularly.', '', 'Praktisi medis harus memperbarui pengetahuan mereka secara rutin.', '', 'Kata benda. Kolokasi: medical/health practitioner, general practitioner (GP, dokter umum).', 'Noun. Collocations: medical/health practitioner, general practitioner (GP).'),
  'predominant': VocabUsage('English is the predominant language of international scientific journals.', '', 'Bahasa Inggris adalah bahasa paling menonjol di jurnal ilmiah internasional.', '', 'Kata sifat. Adv: predominantly (sebagian besar). Kerja: predominate.', 'Adjective. Adv: predominantly. Verb: predominate.'),
  'prospect': VocabUsage('The prospect of rising sea levels worries coastal communities.', '', 'Prospek naiknya permukaan laut mengkhawatirkan masyarakat pesisir.', '', 'Kata benda. Kolokasi: job/career prospects (jamak), the prospect of + V-ing. Adj: prospective.', 'Noun. Collocations: job/career prospects (plural), the prospect of + V-ing. Adj: prospective.'),
  'radical': VocabUsage('Tackling climate change will require radical changes to our lifestyles.', '', 'Mengatasi perubahan iklim membutuhkan perubahan radikal pada gaya hidup kita.', '', 'Kata sifat/benda. Kolokasi: radical change/reform/idea. Adv: radically.', 'Adjective/noun. Collocations: radical change/reform/idea. Adv: radically.'),
  'random': VocabUsage('Participants were selected at random from the city\'s population.', '', 'Peserta dipilih secara acak dari penduduk kota itu.', '', 'Kata sifat. Kolokasi: at random, random sample/selection. Adv: randomly; kerja: randomize.', 'Adjective. Collocations: at random, random sample/selection. Adv: randomly; verb: randomize.'),
  'reinforce': VocabUsage('Regular practice reinforces what students learn in class.', '', 'Latihan rutin memperkuat apa yang dipelajari siswa di kelas.', '', 'Kata kerja. Kolokasi: reinforce an idea/stereotype/learning. Nomina: reinforcement.', 'Verb. Collocations: reinforce an idea/stereotype/learning. Noun: reinforcement.'),
  'restore': VocabUsage('The government is working to restore public trust in the police.', '', 'Pemerintah berupaya memulihkan kepercayaan publik pada kepolisian.', '', 'Kata kerja. Kolokasi: restore trust/order/a building. Nomina: restoration.', 'Verb. Collocations: restore trust/order/a building. Noun: restoration.'),
  'revise': VocabUsage('Please revise your essay according to the reviewer\'s comments.', '', 'Silakan revisi esai Anda sesuai komentar penelaah.', '', 'Kata kerja. Nomina: revision. BrE juga \'belajar untuk ujian\' (revise for an exam).', 'Verb. Noun: revision. In BrE also \'study for an exam\' (revise for an exam).'),
  'schedule': VocabUsage('The exam schedule will be posted on the university website.', '', 'Jadwal ujian akan diumumkan di situs web universitas.', '', 'Kata benda/kerja. Kolokasi: on/behind/ahead of schedule; be scheduled for (dijadwalkan).', 'Noun/verb. Collocations: on/behind/ahead of schedule; be scheduled for.'),
  'tension': VocabUsage('Rising prices have created tension between workers and employers.', '', 'Kenaikan harga menimbulkan ketegangan antara pekerja dan pengusaha.', '', 'Kata benda. Pola: tension between A and B; ease/reduce tension. Adj: tense.', 'Noun. Pattern: tension between A and B; ease/reduce tension. Adj: tense.'),
  'terminate': VocabUsage('The company terminated the contract after repeated delays.', '', 'Perusahaan itu mengakhiri kontrak setelah keterlambatan berulang kali.', '', 'Kata kerja formal. Kolokasi: terminate a contract/agreement/employment. Nomina: termination.', 'Formal verb. Collocations: terminate a contract/agreement/employment. Noun: termination.'),
  'theme': VocabUsage('Identity is a central theme in many of her novels.', '', 'Identitas adalah tema sentral dalam banyak novelnya.', '', 'Kata benda. Kolokasi: central/main/recurring theme. Adj: thematic.', 'Noun. Collocations: central/main/recurring theme. Adj: thematic.'),
  'thereby': VocabUsage('The policy lowered taxes, thereby encouraging small businesses to grow.', '', 'Kebijakan itu menurunkan pajak, dengan demikian mendorong usaha kecil untuk tumbuh.', '', 'Adverbia formal. Biasanya: klausa, thereby + V-ing (menyatakan akibat).', 'Formal adverb. Usually: clause, thereby + V-ing (showing a result).'),
  'uniform': VocabUsage('Temperatures are not uniform across the whole country.', '', 'Suhu tidak seragam di seluruh negeri.', '', 'Kata sifat (seragam/merata) dan benda (pakaian seragam). Nomina: uniformity.', 'Adjective (consistent) and noun (school uniform). Noun: uniformity.'),
  'vehicle': VocabUsage('The city plans to ban older vehicles from the centre to reduce pollution.', '', 'Kota itu berencana melarang kendaraan tua masuk pusat kota untuk mengurangi polusi.', '', 'Kata benda. Kolokasi: motor/electric vehicle. Kiasan: a vehicle for (sarana) ide/perubahan.', 'Noun. Collocations: motor/electric vehicle. Figurative: a vehicle for ideas/change.'),
  'via': VocabUsage('The questionnaire was distributed to participants via email.', '', 'Kuesioner itu dibagikan kepada peserta melalui email.', '', 'Preposisi. Via + sarana (via email) atau tempat transit (fly via Singapore).', 'Preposition. Via + means (via email) or a transit point (fly via Singapore).'),
  'virtual': VocabUsage('Virtual classrooms became common during the pandemic.', '', 'Kelas virtual menjadi umum selama pandemi.', '', 'Kata sifat. Kolokasi: virtual reality/meeting/classroom. Adv: virtually (juga \'hampir\').', 'Adjective. Collocations: virtual reality/meeting/classroom. Adv: virtually (also \'almost\').'),
  'visual': VocabUsage('Visual aids such as diagrams help learners remember information.', '', 'Alat bantu visual seperti diagram membantu pelajar mengingat informasi.', '', 'Kata sifat. Kolokasi: visual aids/arts/learner. Kerja: visualize.', 'Adjective. Collocations: visual aids/arts/learner. Verb: visualize.'),
  'widespread': VocabUsage('There is widespread concern about the rising cost of living.', '', 'Ada kekhawatiran yang tersebar luas tentang naiknya biaya hidup.', '', 'Kata sifat. Kolokasi: widespread concern/support/use/belief.', 'Adjective. Collocations: widespread concern/support/use/belief.'),
  'accommodate': VocabUsage('The new lecture hall can accommodate up to five hundred students.', '', 'Aula kuliah baru itu dapat menampung hingga lima ratus mahasiswa.', '', 'Kata kerja. Juga \'mengakomodasi kebutuhan\' (accommodate needs). Nomina: accommodation (tempat tinggal).', 'Verb. Also \'meet needs\' (accommodate needs). Noun: accommodation (housing).'),
  'analogy': VocabUsage('The teacher used an analogy with water flow to explain electricity.', '', 'Guru memakai perumpamaan aliran air untuk menjelaskan listrik.', '', 'Kata benda. Pola: an analogy between A and B; draw an analogy. Adj: analogous.', 'Noun. Pattern: an analogy between A and B; draw an analogy. Adj: analogous.'),
  'anticipate': VocabUsage('Organizers anticipate that more than ten thousand people will attend.', '', 'Panitia memperkirakan lebih dari sepuluh ribu orang akan hadir.', '', 'Kata kerja. Pola: anticipate sth / that + klausa / + V-ing. Nomina: anticipation.', 'Verb. Pattern: anticipate sth / that + clause / + V-ing. Noun: anticipation.'),
  'assure': VocabUsage('The manager assured staff that no jobs would be lost.', '', 'Manajer meyakinkan staf bahwa tidak akan ada pekerjaan yang hilang.', '', 'Kata kerja. Pola: assure sb that / assure sb of. Beda: ensure (memastikan), insure (mengasuransikan).', 'Verb. Pattern: assure sb that / assure sb of. Compare: ensure, insure.'),
  'attain': VocabUsage('Few students attain full marks in the final examination.', '', 'Sedikit mahasiswa yang meraih nilai sempurna dalam ujian akhir.', '', 'Kata kerja formal. Kolokasi: attain a goal/level/standard. Nomina: attainment.', 'Formal verb. Collocations: attain a goal/level/standard. Noun: attainment.'),
  'behalf': VocabUsage('She accepted the award on behalf of the entire research team.', '', 'Ia menerima penghargaan itu atas nama seluruh tim peneliti.', '', 'Kata benda, hampir selalu dalam frasa on behalf of sb (AmE juga: in behalf of).', 'Noun, almost always in on behalf of sb (AmE also: in behalf of).'),
  'bulk': VocabUsage('The bulk of the funding comes from private donors.', '', 'Sebagian besar dana berasal dari donatur swasta.', '', 'Kata benda. Pola: the bulk of + benda; buy in bulk (membeli dalam jumlah besar). Adj: bulky.', 'Noun. Pattern: the bulk of + noun; buy in bulk. Adj: bulky.'),
  'cease': VocabUsage('The factory ceased production after the safety inspection.', '', 'Pabrik itu berhenti berproduksi setelah pemeriksaan keselamatan.', '', 'Kata kerja formal. Pola: cease + benda / to do / + V-ing. Ceasefire = gencatan senjata.', 'Formal verb. Pattern: cease + noun / to do / + V-ing. Ceasefire = truce.'),
  'coherent': VocabUsage('A good essay presents a coherent argument from start to finish.', '', 'Esai yang baik menyajikan argumen yang runtut dari awal sampai akhir.', '', 'Kata sifat, kriteria penting di IELTS (coherence and cohesion). Nomina: coherence.', 'Adjective, a key IELTS criterion (coherence and cohesion). Noun: coherence.'),
  'coincide': VocabUsage('The conference was planned to coincide with the anniversary of the university.', '', 'Konferensi itu direncanakan bertepatan dengan hari jadi universitas.', '', 'Kata kerja. Pola: coincide with sesuatu. Nomina: coincidence (kebetulan).', 'Verb. Pattern: coincide with something. Noun: coincidence.'),
  'commence': VocabUsage('The academic year will commence on the first of September.', '', 'Tahun akademik akan dimulai pada tanggal satu September.', '', 'Kata kerja sangat formal, mirip \'begin\'. Pola: commence + V-ing. Nomina: commencement (wisuda, AmE).', 'Very formal verb, like \'begin\'. Pattern: commence + V-ing. Noun: commencement (graduation, AmE).'),
  'compatible': VocabUsage('The software is not compatible with older operating systems.', '', 'Perangkat lunak itu tidak cocok dengan sistem operasi lama.', '', 'Kata sifat. Pola: compatible with sesuatu. Lawan: incompatible. Nomina: compatibility.', 'Adjective. Pattern: compatible with something. Opposite: incompatible. Noun: compatibility.'),
  'concurrent': VocabUsage('Students can take two concurrent courses during the summer term.', '', 'Mahasiswa dapat mengambil dua mata kuliah serentak selama semester musim panas.', '', 'Kata sifat. Pola: concurrent with sesuatu. Adv: concurrently. Mirip: simultaneous.', 'Adjective. Pattern: concurrent with something. Adv: concurrently. Similar: simultaneous.'),
  'confine': VocabUsage('Wild animals suffer when they are confined to small cages.', '', 'Hewan liar menderita ketika dikurung di kandang sempit.', '', 'Kata kerja, sering pasif. Pola: be confined to sesuatu (juga \'terbatas pada\'). Nomina: confinement.', 'Verb, often passive. Pattern: be confined to something (also \'limited to\'). Noun: confinement.'),
  'controversy': VocabUsage('The decision to close the library caused considerable controversy.', '', 'Keputusan menutup perpustakaan itu menimbulkan kontroversi yang cukup besar.', '', 'Kata benda. Kolokasi: cause/spark controversy, controversy over/about. Adj: controversial.', 'Noun. Collocations: cause/spark controversy, controversy over/about. Adj: controversial.'),
  'converse': VocabUsage('Students practise conversing with native speakers in weekly sessions.', '', 'Mahasiswa berlatih bercakap-cakap dengan penutur asli dalam sesi mingguan.', '', 'Kata kerja formal. Pola: converse with sb. Nomina: conversation. Sebagai benda: the converse (kebalikan).', 'Formal verb. Pattern: converse with sb. Noun: conversation. As a noun: the converse (the opposite).'),
  'device': VocabUsage('Most students now use mobile devices to access course materials.', '', 'Kebanyakan mahasiswa kini memakai perangkat seluler untuk mengakses materi kuliah.', '', 'Kata benda (dibaca di-vais). Kolokasi: mobile/electronic device. Beda: devise (kata kerja, merancang).', 'Noun. Collocations: mobile/electronic device. Compare: devise (verb, to plan).'),
  'devote': VocabUsage('She devoted her career to improving education for girls.', '', 'Ia mencurahkan kariernya untuk meningkatkan pendidikan bagi anak perempuan.', '', 'Kata kerja. Pola: devote time/effort to + benda/V-ing. Adj: devoted; nomina: devotion.', 'Verb. Pattern: devote time/effort to + noun/V-ing. Adj: devoted; noun: devotion.'),
  'diminish': VocabUsage('The importance of printed newspapers has diminished in the digital age.', '', 'Pentingnya koran cetak telah berkurang di era digital.', '', 'Kata kerja. Kolokasi: diminishing returns, diminish in value. Mirip: decrease, lessen.', 'Verb. Collocations: diminishing returns, diminish in value. Similar: decrease, lessen.'),
  'distort': VocabUsage('Selective reporting can distort the public\'s understanding of the issue.', '', 'Pemberitaan yang selektif dapat memutarbalikkan pemahaman publik tentang isu itu.', '', 'Kata kerja. Kolokasi: distort the truth/facts/results. Nomina: distortion.', 'Verb. Collocations: distort the truth/facts/results. Noun: distortion.'),
  'duration': VocabUsage('Participants were monitored for the full duration of the twelve-week study.', '', 'Para peserta dipantau selama seluruh durasi penelitian dua belas minggu itu.', '', 'Kata benda. Kolokasi: for the duration of, short/long duration. Lebih formal daripada \'length\'.', 'Noun. Collocations: for the duration of, short/long duration. More formal than \'length\'.'),
  'erode': VocabUsage('Strong winds and heavy rain gradually erode the soil on steep hillsides.', '', 'Angin kencang dan hujan lebat perlahan mengikis tanah di lereng yang curam.', '', 'Kata kerja. Bisa harfiah (soil, coast) atau kiasan: erode trust/confidence. Nomina: erosion.', 'Verb. Literal (soil, coast) or figurative: erode trust/confidence. Noun: erosion.'),
  'ethic': VocabUsage('The company promotes a strong work ethic among all of its employees.', '', 'Perusahaan itu menanamkan etos kerja yang kuat kepada semua karyawannya.', '', 'Kata benda. Kolokasi umum: work ethic. Bentuk jamak \'ethics\' = ilmu/aturan etika; adj: ethical.', 'Noun. Common: work ethic. Plural \'ethics\' = moral rules or the field; adj: ethical.'),
  'format': VocabUsage('The report must follow the standard format required by the journal.', '', 'Laporan itu harus mengikuti format standar yang disyaratkan oleh jurnal.', '', 'Kata benda/kerja. Kolokasi: in a ... format, file format, format a document.', 'Noun/verb. Collocations: in a ... format, file format, format a document.'),
  'found': VocabUsage('The university was founded in 1950 to train teachers for rural schools.', '', 'Universitas itu didirikan pada tahun 1950 untuk melatih guru sekolah pedesaan.', '', 'Kata kerja beraturan: found-founded-founded. Jangan tertukar dengan find-found. Nomina: founder, foundation.', 'Regular verb: found-founded-founded. Don\'t confuse with find-found. Nouns: founder, foundation.'),
  'inherent': VocabUsage('There are inherent risks in any study that relies on self-reported data.', '', 'Ada risiko yang melekat dalam setiap penelitian yang bergantung pada data laporan diri.', '', 'Kata sifat. Pola: inherent in sth, inherent risk/weakness. Adverb: inherently.', 'Adjective. Pattern: inherent in sth, inherent risk/weakness. Adverb: inherently.'),
  'insight': VocabUsage('The interviews provided valuable insight into the daily lives of farmers.', '', 'Wawancara itu memberikan wawasan berharga tentang kehidupan sehari-hari para petani.', '', 'Kata benda. Pola: insight into sth; gain/provide insight. Adj: insightful.', 'Noun. Pattern: insight into sth; gain/provide insight. Adj: insightful.'),
  'integral': VocabUsage('Regular feedback is an integral part of the learning process.', '', 'Umpan balik rutin adalah bagian tak terpisahkan dari proses belajar.', '', 'Kata sifat. Kolokasi: an integral part of, integral to sth.', 'Adjective. Collocations: an integral part of, integral to sth.'),
  'intermediate': VocabUsage('The course is designed for students at an intermediate level of English.', '', 'Kursus itu dirancang untuk siswa dengan tingkat bahasa Inggris menengah.', '', 'Kata sifat. Urutan level: beginner, intermediate, advanced. Juga: intermediate stage/step.', 'Adjective. Levels: beginner, intermediate, advanced. Also: intermediate stage/step.'),
  'manual': VocabUsage('Please read the user manual carefully before operating the new equipment.', '', 'Harap baca buku petunjuk dengan teliti sebelum mengoperasikan peralatan baru itu.', '', 'Kata benda (buku petunjuk) atau sifat (manual labour = kerja tangan). Lawan sifat: automatic.', 'Noun (handbook) or adjective (manual labour). Adjective opposite: automatic.'),
  'mature': VocabUsage('Most of the trees in the forest take decades to become fully mature.', '', 'Sebagian besar pohon di hutan itu butuh puluhan tahun untuk benar-benar matang.', '', 'Kata sifat/kerja. Untuk orang = dewasa (sikap). Nomina: maturity; lawan: immature.', 'Adjective/verb. For people = grown-up in behaviour. Noun: maturity; opposite: immature.'),
  'mediate': VocabUsage('A neutral officer was appointed to mediate between the union and management.', '', 'Seorang petugas netral ditunjuk untuk menengahi serikat pekerja dan manajemen.', '', 'Kata kerja. Pola: mediate between A and B, mediate a dispute. Nomina: mediation, mediator.', 'Verb. Pattern: mediate between A and B, mediate a dispute. Nouns: mediation, mediator.'),
  'medium': VocabUsage('Television remains a powerful medium for spreading public health messages.', '', 'Televisi tetap menjadi media yang ampuh untuk menyebarkan pesan kesehatan masyarakat.', '', 'Kata benda (jamak: media) atau sifat (ukuran sedang). Pola: a medium for/of sth.', 'Noun (plural: media) or adjective (middle size). Pattern: a medium for/of sth.'),
  'military': VocabUsage('The government increased military spending despite strong public opposition.', '', 'Pemerintah menaikkan belanja militer meskipun ada penolakan keras dari masyarakat.', '', 'Kata sifat/benda. Kolokasi: military service/force/spending; the military = angkatan bersenjata.', 'Adjective/noun. Collocations: military service/force/spending; the military = armed forces.'),
  'minimal': VocabUsage('The new process requires minimal training and saves a lot of time.', '', 'Proses baru itu hanya butuh pelatihan yang sangat sedikit dan menghemat banyak waktu.', '', 'Kata sifat. Kolokasi: minimal cost/effort/impact. Beda: minimum (batas terendah) vs minimal (sangat kecil).', 'Adjective. Collocations: minimal cost/effort/impact. Minimum = lowest limit; minimal = very small.'),
  'mutual': VocabUsage('The partnership is based on mutual respect and shared goals.', '', 'Kemitraan itu didasarkan pada sikap saling menghormati dan tujuan bersama.', '', 'Kata sifat. Kolokasi: mutual respect/trust/benefit/agreement. Adverb: mutually.', 'Adjective. Collocations: mutual respect/trust/benefit/agreement. Adverb: mutually.'),
  'norm': VocabUsage('In many cultures, it is the norm for adult children to support their parents.', '', 'Di banyak budaya, sudah menjadi norma bagi anak dewasa untuk menafkahi orang tuanya.', '', 'Kata benda. Pola: the norm, social norms, deviate from the norm. Adj: normative.', 'Noun. Patterns: the norm, social norms, deviate from the norm. Adj: normative.'),
  'overlap': VocabUsage('The two research projects overlap in several important areas.', '', 'Kedua proyek penelitian itu tumpang tindih di beberapa bidang penting.', '', 'Kata kerja/benda. Pola: overlap with sth; an overlap between A and B.', 'Verb/noun. Pattern: overlap with sth; an overlap between A and B.'),
  'passive': VocabUsage('Students learn less when they remain passive listeners during lectures.', '', 'Mahasiswa belajar lebih sedikit bila mereka hanya menjadi pendengar pasif saat kuliah.', '', 'Kata sifat. Lawan: active. Dalam tata bahasa: the passive voice (kalimat pasif).', 'Adjective. Opposite: active. In grammar: the passive voice.'),
  'portion': VocabUsage('A large portion of the budget was spent on staff salaries.', '', 'Sebagian besar anggaran dihabiskan untuk gaji staf.', '', 'Kata benda. Pola: a portion of sth; juga porsi makanan (a small portion). Mirip: part, share.', 'Noun. Pattern: a portion of sth; also food serving (a small portion). Similar: part, share.'),
  'preliminary': VocabUsage('Preliminary results suggest that the new drug is safe for adults.', '', 'Hasil pendahuluan menunjukkan bahwa obat baru itu aman bagi orang dewasa.', '', 'Kata sifat (sebelum kata benda). Kolokasi: preliminary results/findings/study/round.', 'Adjective (before nouns). Collocations: preliminary results/findings/study/round.'),
  'protocol': VocabUsage('All laboratory staff must follow the safety protocol when handling chemicals.', '', 'Semua staf laboratorium wajib mengikuti protokol keselamatan saat menangani bahan kimia.', '', 'Kata benda. Kolokasi: follow/breach protocol, safety protocol, diplomatic protocol.', 'Noun. Collocations: follow/breach protocol, safety protocol, diplomatic protocol.'),
  'qualitative': VocabUsage('The researchers used qualitative methods such as interviews and focus groups.', '', 'Para peneliti memakai metode kualitatif seperti wawancara dan diskusi kelompok terarah.', '', 'Kata sifat. Pasangan kontras: quantitative (berbasis angka). Kolokasi: qualitative data/research.', 'Adjective. Contrast: quantitative (number-based). Collocations: qualitative data/research.'),
  'refine': VocabUsage('The team spent months refining the model before publishing their results.', '', 'Tim itu menghabiskan berbulan-bulan menyempurnakan model sebelum menerbitkan hasilnya.', '', 'Kata kerja. Kolokasi: refine a method/model/skill. Juga \'memurnikan\' (refined sugar/oil).', 'Verb. Collocations: refine a method/model/skill. Also \'purify\' (refined sugar/oil).'),
  'relax': VocabUsage('Many employees find it hard to relax after a long week at work.', '', 'Banyak karyawan merasa sulit bersantai setelah seminggu bekerja keras.', '', 'Kata kerja. Juga \'melonggarkan\': relax the rules. Adj: relaxed (orang) vs relaxing (suasana).', 'Verb. Also \'loosen\': relax the rules. Adj: relaxed (person) vs relaxing (activity).'),
  'restrain': VocabUsage('The police had to restrain the crowd outside the stadium.', '', 'Polisi harus menahan kerumunan di luar stadion.', '', 'Kata kerja. Pola: restrain sb/sth from doing sth. Nomina: restraint.', 'Verb. Pattern: restrain sb/sth from doing sth. Noun: restraint.'),
  'revolution': VocabUsage('The industrial revolution transformed the way people lived and worked.', '', 'Revolusi industri mengubah cara orang hidup dan bekerja.', '', 'Kata benda. Kolokasi: industrial/digital revolution. Adj: revolutionary.', 'Noun. Collocations: industrial/digital revolution. Adj: revolutionary.'),
  'rigid': VocabUsage('Critics argue that the education system is too rigid to encourage creativity.', '', 'Para kritikus berpendapat bahwa sistem pendidikan terlalu kaku untuk mendorong kreativitas.', '', 'Kata sifat. Harfiah (bahan kaku) atau kiasan: rigid rules/schedule. Lawan: flexible.', 'Adjective. Literal (stiff material) or figurative: rigid rules/schedule. Opposite: flexible.'),
  'route': VocabUsage('The bus route was changed to serve the new housing area.', '', 'Rute bus itu diubah untuk melayani kawasan perumahan baru.', '', 'Kata benda. Kolokasi: bus/trade/escape route, en route (dalam perjalanan).', 'Noun. Collocations: bus/trade/escape route, en route (on the way).'),
  'scenario': VocabUsage('In the worst-case scenario, the project could be delayed by two years.', '', 'Dalam skenario terburuk, proyek itu bisa tertunda hingga dua tahun.', '', 'Kata benda. Kolokasi: worst-case/best-case scenario, a likely scenario.', 'Noun. Collocations: worst-case/best-case scenario, a likely scenario.'),
  'sphere': VocabUsage('Women are now more visible in the political sphere than ever before.', '', 'Perempuan kini lebih terlihat di ranah politik daripada sebelumnya.', '', 'Kata benda. Bentuk bola (geometri) atau ranah: public/political sphere, sphere of influence.', 'Noun. Ball shape (geometry) or area: public/political sphere, sphere of influence.'),
  'subordinate': VocabUsage('A good manager listens carefully to the ideas of subordinates.', '', 'Manajer yang baik mendengarkan ide para bawahannya dengan saksama.', '', 'Kata benda/sifat. Pola: subordinate to sb. Lawan: superior. Grammar: subordinate clause.', 'Noun/adjective. Pattern: subordinate to sb. Opposite: superior. Grammar: subordinate clause.'),
  'supplement': VocabUsage('Some students work part-time to supplement their scholarship income.', '', 'Sebagian mahasiswa bekerja paruh waktu untuk menambah penghasilan dari beasiswa mereka.', '', 'Kata benda/kerja. Kolokasi: dietary supplement, supplement sth with sth. Adj: supplementary.', 'Noun/verb. Collocations: dietary supplement, supplement sth with sth. Adj: supplementary.'),
  'suspend': VocabUsage('The trial was suspended after several patients reported serious side effects.', '', 'Uji coba itu ditangguhkan setelah beberapa pasien melaporkan efek samping serius.', '', 'Kata kerja. Kolokasi: suspend a service/student/license. Nomina: suspension.', 'Verb. Collocations: suspend a service/student/license. Noun: suspension.'),
  'team': VocabUsage('Each team was asked to present its findings at the end of the seminar.', '', 'Setiap tim diminta mempresentasikan temuannya di akhir seminar.', '', 'Kata benda. Kolokasi: team member/leader, work as a team, teamwork.', 'Noun. Collocations: team member/leader, work as a team, teamwork.'),
  'temporary': VocabUsage('The city built temporary shelters for families who lost their homes.', '', 'Kota itu membangun tempat penampungan sementara bagi keluarga yang kehilangan rumah.', '', 'Kata sifat. Lawan: permanent. Kolokasi: temporary job/contract/solution. Adverb: temporarily.', 'Adjective. Opposite: permanent. Collocations: temporary job/contract/solution. Adverb: temporarily.'),
  'trigger': VocabUsage('Rising food prices could trigger protests in several major cities.', '', 'Kenaikan harga pangan bisa memicu unjuk rasa di beberapa kota besar.', '', 'Kata kerja/benda. Kolokasi: trigger a reaction/crisis; a trigger for sth.', 'Verb/noun. Collocations: trigger a reaction/crisis; a trigger for sth.'),
  'unify': VocabUsage('The new president promised to unify a deeply divided nation.', '', 'Presiden baru itu berjanji menyatukan bangsa yang sangat terpecah.', '', 'Kata kerja. Nomina: unification, unity. Mirip: unite (lebih umum).', 'Verb. Nouns: unification, unity. Similar: unite (more common).'),
  'violate': VocabUsage('Companies that violate environmental laws should face heavy fines.', '', 'Perusahaan yang melanggar undang-undang lingkungan harus dikenai denda berat.', '', 'Kata kerja (formal). Kolokasi: violate a law/rule/rights/agreement. Nomina: violation.', 'Verb (formal). Collocations: violate a law/rule/rights/agreement. Noun: violation.'),
  'vision': VocabUsage('The founder had a clear vision of affordable education for everyone.', '', 'Pendirinya memiliki visi yang jelas tentang pendidikan terjangkau untuk semua orang.', '', 'Kata benda. Visi masa depan (a vision of/for) atau daya penglihatan (poor vision).', 'Noun. A plan for the future (a vision of/for) or eyesight (poor vision).'),
  'adjacent': VocabUsage('The research centre is located adjacent to the main hospital.', '', 'Pusat penelitian itu terletak bersebelahan dengan rumah sakit utama.', '', 'Kata sifat (formal). Pola: adjacent to sth. Mirip: next to, neighbouring.', 'Adjective (formal). Pattern: adjacent to sth. Similar: next to, neighbouring.'),
  'albeit': VocabUsage('The economy is growing, albeit more slowly than experts had predicted.', '', 'Ekonomi sedang tumbuh, walaupun lebih lambat daripada perkiraan para ahli.', '', 'Konjungsi formal, diikuti frasa (bukan klausa lengkap): albeit slowly/small.', 'Formal conjunction, followed by a phrase (not a full clause): albeit slowly/small.'),
  'assemble': VocabUsage('Workers assemble the components in a clean and controlled environment.', '', 'Para pekerja merakit komponen di lingkungan yang bersih dan terkendali.', '', 'Kata kerja. Merakit (assemble parts) atau berkumpul (people assemble). Nomina: assembly.', 'Verb. Put together (assemble parts) or gather (people assemble). Noun: assembly.'),
  'collapse': VocabUsage('The old bridge collapsed after weeks of heavy rain.', '', 'Jembatan tua itu runtuh setelah berminggu-minggu diguyur hujan lebat.', '', 'Kata kerja/benda. Juga kiasan: the economy/company collapsed (ambruk).', 'Verb/noun. Also figurative: the economy/company collapsed.'),
  'colleague': VocabUsage('She discussed the results with a colleague from another department.', '', 'Ia membahas hasilnya dengan seorang rekan kerja dari departemen lain.', '', 'Kata benda. Untuk rekan seprofesi/sekantor; lebih formal daripada coworker.', 'Noun. A fellow professional or office mate; more formal than coworker.'),
  'compile': VocabUsage('The researchers compiled data from more than two hundred hospitals.', '', 'Para peneliti menghimpun data dari lebih dari dua ratus rumah sakit.', '', 'Kata kerja. Kolokasi: compile data/a list/a report. Nomina: compilation.', 'Verb. Collocations: compile data/a list/a report. Noun: compilation.'),
  'conceive': VocabUsage('It is difficult to conceive of a world without the internet.', '', 'Sulit membayangkan dunia tanpa internet.', '', 'Kata kerja. Pola: conceive of sth (membayangkan), conceive an idea/plan (menggagas). Nomina: concept.', 'Verb. Patterns: conceive of sth (imagine), conceive an idea/plan. Noun: concept.'),
  'convince': VocabUsage('The evidence was strong enough to convince the committee to approve funding.', '', 'Buktinya cukup kuat untuk meyakinkan komite agar menyetujui pendanaan.', '', 'Kata kerja. Pola: convince sb of sth / convince sb to do sth. Adj: convincing, convinced.', 'Verb. Patterns: convince sb of sth / convince sb to do sth. Adj: convincing, convinced.'),
  'depress': VocabUsage('Long periods of isolation can depress even the most cheerful people.', '', 'Masa isolasi yang panjang bisa membuat sedih bahkan orang yang paling ceria.', '', 'Kata kerja. Juga \'menekan/menurunkan\': depress prices/wages. Adj: depressed, depressing.', 'Verb. Also \'lower\': depress prices/wages. Adj: depressed, depressing.'),
  'encounter': VocabUsage('Researchers often encounter unexpected problems during field work.', '', 'Para peneliti sering menjumpai masalah tak terduga selama kerja lapangan.', '', 'Kata kerja/benda. Kolokasi: encounter problems/difficulties/resistance. Lebih formal dari meet.', 'Verb/noun. Collocations: encounter problems/difficulties/resistance. More formal than meet.'),
  'enormous': VocabUsage('The project required an enormous amount of time and money.', '', 'Proyek itu membutuhkan waktu dan uang dalam jumlah sangat besar.', '', 'Kata sifat. Kolokasi: an enormous amount/number/impact. Mirip: huge, vast.', 'Adjective. Collocations: an enormous amount/number/impact. Similar: huge, vast.'),
  'forthcoming': VocabUsage('Details of the policy will be announced in a forthcoming report.', '', 'Rincian kebijakan itu akan diumumkan dalam laporan yang akan datang.', '', 'Kata sifat (formal). Sebelum nomina = akan datang; setelah be = tersedia/terbuka (help was not forthcoming).', 'Adjective (formal). Before a noun = upcoming; after be = available (help was not forthcoming).'),
  'incline': VocabUsage('Younger voters are more inclined to support environmental policies.', '', 'Pemilih muda lebih cenderung mendukung kebijakan lingkungan.', '', 'Biasanya pasif: be inclined to do sth. Nomina: inclination; juga \'tanjakan\' (an incline).', 'Usually passive: be inclined to do sth. Noun: inclination; also \'a slope\' (an incline).'),
  'integrity': VocabUsage('Journalists must maintain their integrity even under political pressure.', '', 'Wartawan harus menjaga integritasnya bahkan di bawah tekanan politik.', '', 'Kata benda tak terhitung. Kolokasi: maintain/lack integrity, academic integrity, data integrity.', 'Uncountable noun. Collocations: maintain/lack integrity, academic integrity, data integrity.'),
  'intrinsic': VocabUsage('Learning a language has intrinsic value beyond its use in the job market.', '', 'Belajar bahasa punya nilai hakiki di luar manfaatnya di pasar kerja.', '', 'Kata sifat. Kolokasi: intrinsic value/motivation. Lawan: extrinsic. Mirip: inherent.', 'Adjective. Collocations: intrinsic value/motivation. Opposite: extrinsic. Similar: inherent.'),
  'invoke': VocabUsage('The government invoked emergency powers to control the outbreak.', '', 'Pemerintah merujuk kewenangan darurat untuk mengendalikan wabah itu.', '', 'Kata kerja (formal). Kolokasi: invoke a law/rule/right/powers. Jangan tertukar dengan evoke.', 'Verb (formal). Collocations: invoke a law/rule/right/powers. Don\'t confuse with evoke.'),
  'levy': VocabUsage('The city introduced a levy on plastic bags to reduce waste.', '', 'Kota itu memberlakukan pungutan atas kantong plastik untuk mengurangi sampah.', '', 'Kata benda/kerja. Pola: a levy on sth; levy a tax on sth.', 'Noun/verb. Pattern: a levy on sth; levy a tax on sth.'),
  'likewise': VocabUsage('The first study found no effect; likewise, the second showed no change.', '', 'Studi pertama tidak menemukan efek; demikian pula, studi kedua tidak menunjukkan perubahan.', '', 'Adverbia penghubung untuk menambah poin yang mirip. Mirip: similarly, in the same way.', 'Linking adverb for a similar point. Similar: similarly, in the same way.'),
  'nonetheless': VocabUsage('The plan was expensive; nonetheless, the board decided to approve it.', '', 'Rencana itu mahal; meskipun begitu, dewan memutuskan untuk menyetujuinya.', '', 'Adverbia penghubung kontras. Sinonim: nevertheless, however. Sering setelah titik koma.', 'Contrast linking adverb. Synonyms: nevertheless, however. Often after a semicolon.'),
  'notwithstanding': VocabUsage('Notwithstanding the budget cuts, the library extended its opening hours.', '', 'Terlepas dari pemotongan anggaran, perpustakaan itu memperpanjang jam bukanya.', '', 'Preposisi sangat formal (gaya hukum/akademik). Mirip: despite, in spite of.', 'Very formal preposition (legal/academic style). Similar: despite, in spite of.'),
  'odd': VocabUsage('It seemed odd that nobody had noticed the error in the data.', '', 'Rasanya aneh bahwa tidak ada yang menyadari kesalahan dalam data itu.', '', 'Kata sifat. Aneh (it is odd that...) atau ganjil (odd numbers). Lawan bilangan: even.', 'Adjective. Strange (it is odd that...) or odd numbers. Number opposite: even.'),
  'ongoing': VocabUsage('The ongoing debate about climate policy shows no sign of ending.', '', 'Perdebatan yang sedang berlangsung tentang kebijakan iklim belum menunjukkan tanda akan berakhir.', '', 'Kata sifat. Kolokasi: ongoing research/debate/project/process.', 'Adjective. Collocations: ongoing research/debate/project/process.'),
  'panel': VocabUsage('A panel of experts reviewed all the applications for the grant.', '', 'Sebuah tim ahli meninjau semua permohonan hibah itu.', '', 'Kata benda. Pola: a panel of experts/judges; panel discussion. Juga lempeng (solar panel).', 'Noun. Pattern: a panel of experts/judges; panel discussion. Also a flat board (solar panel).'),
  'persist': VocabUsage('If symptoms persist for more than a week, patients should see a doctor.', '', 'Jika gejala terus berlanjut lebih dari seminggu, pasien sebaiknya menemui dokter.', '', 'Kata kerja. Pola: persist in doing sth; symptoms/problems persist. Adj: persistent.', 'Verb. Pattern: persist in doing sth; symptoms/problems persist. Adj: persistent.'),
  'pose': VocabUsage('Rising sea levels pose a serious threat to coastal communities.', '', 'Naiknya permukaan laut menimbulkan ancaman serius bagi masyarakat pesisir.', '', 'Kata kerja. Kolokasi: pose a threat/risk/problem/question. Juga \'berpose\' untuk foto.', 'Verb. Collocations: pose a threat/risk/problem/question. Also \'pose\' for a photo.'),
  'reluctance': VocabUsage('There is a growing reluctance among young people to buy cars.', '', 'Ada keengganan yang makin besar di kalangan anak muda untuk membeli mobil.', '', 'Kata benda. Pola: reluctance to do sth. Adj: reluctant; adverb: reluctantly.', 'Noun. Pattern: reluctance to do sth. Adj: reluctant; adverb: reluctantly.'),
  'so-called': VocabUsage('The so-called experts failed to predict the financial crisis.', '', 'Para ahli yang disebut-sebut itu gagal memprediksi krisis keuangan.', '', 'Kata sifat sebelum nomina. Sering bernada skeptis: nama itu dianggap kurang tepat.', 'Adjective before a noun. Often sceptical: suggests the name may not be deserved.'),
  'straightforward': VocabUsage('The application process is fairly straightforward and takes ten minutes.', '', 'Proses pendaftarannya cukup mudah dan hanya memakan waktu sepuluh menit.', '', 'Kata sifat. Untuk tugas = mudah; untuk orang = lugas/terus terang. Kolokasi: fairly straightforward.', 'Adjective. For tasks = easy; for people = honest and direct. Collocation: fairly straightforward.'),
  'undergo': VocabUsage('The building will undergo major repairs over the next six months.', '', 'Gedung itu akan menjalani perbaikan besar selama enam bulan ke depan.', '', 'Kata kerja tak beraturan: undergo-underwent-undergone. Kolokasi: undergo surgery/changes/tests.', 'Irregular verb: undergo-underwent-undergone. Collocations: undergo surgery/changes/tests.'),
  'whereby': VocabUsage('The firm introduced a system whereby staff can work from home twice a week.', '', 'Perusahaan itu menerapkan sistem yang memungkinkan staf bekerja dari rumah dua kali seminggu.', '', 'Kata penghubung formal = by which. Biasanya setelah system/process/arrangement/agreement.', 'Formal relative word = by which. Usually after system/process/arrangement/agreement.'),
  'abundant': VocabUsage('The region has abundant natural resources, including timber and minerals.', '', 'Wilayah itu memiliki sumber daya alam yang melimpah, termasuk kayu dan mineral.', '', 'Kata sifat. Kolokasi: abundant resources/evidence/supply. Nomina: abundance. Lawan: scarce.', 'Adjective. Collocations: abundant resources/evidence/supply. Noun: abundance. Opposite: scarce.'),
  'ancient': VocabUsage('Archaeologists discovered the remains of an ancient city near the river.', '', 'Para arkeolog menemukan sisa-sisa kota kuno di dekat sungai itu.', '', 'Kata sifat. Kolokasi: ancient history/civilization/ruins. Lebih tua dari \'old\'; lawan: modern.', 'Adjective. Collocations: ancient history/civilization/ruins. Older than \'old\'; opposite: modern.'),
  'approximately': VocabUsage('Approximately sixty percent of the respondents supported the proposal.', '', 'Kira-kira enam puluh persen responden mendukung usulan itu.', '', 'Adverbia formal sebelum angka. Mirip: about, roughly, around. Adj: approximate.', 'Formal adverb before numbers. Similar: about, roughly, around. Adj: approximate.'),
  'characteristic': VocabUsage('Bright colours are a key characteristic of this artist\'s work.', '', 'Warna cerah adalah ciri khas utama karya seniman ini.', '', 'Kata benda/sifat. Pola: a characteristic of sth; characteristic of sb (khas). Verb: characterize.', 'Noun/adjective. Pattern: a characteristic of sth; characteristic of sb. Verb: characterize.'),
  'consequence': VocabUsage('Poor sleep can have serious consequences for students\' academic performance.', '', 'Kurang tidur bisa berakibat serius terhadap prestasi akademik siswa.', '', 'Kata benda. Kolokasi: have consequences for, as a consequence (of), face the consequences.', 'Noun. Collocations: have consequences for, as a consequence (of), face the consequences.'),
  'controversial': VocabUsage('The decision to close the factory was highly controversial.', '', 'Keputusan menutup pabrik itu sangat kontroversial.', '', 'Kata sifat. Kolokasi: highly controversial, a controversial issue/decision. Nomina: controversy.', 'Adjective. Collocations: highly controversial, a controversial issue/decision. Noun: controversy.'),
  'dominant': VocabUsage('English has become the dominant language of international science.', '', 'Bahasa Inggris telah menjadi bahasa dominan dalam sains internasional.', '', 'Kata sifat. Kolokasi: dominant role/position/language. Verb: dominate; nomina: dominance.', 'Adjective. Collocations: dominant role/position/language. Verb: dominate; noun: dominance.'),
  'dramatic': VocabUsage('There has been a dramatic increase in online shopping since 2020.', '', 'Ada peningkatan drastis dalam belanja daring sejak tahun 2020.', '', 'Kata sifat. Sering untuk grafik: dramatic rise/fall/increase. Adverb: dramatically.', 'Adjective. Common for trends: dramatic rise/fall/increase. Adverb: dramatically.'),
  'efficient': VocabUsage('Public transport is a more efficient way to move large numbers of people.', '', 'Transportasi umum adalah cara yang lebih efisien untuk memindahkan banyak orang.', '', 'Kata sifat. Beda: efficient (hemat sumber daya) vs effective (berhasil). Nomina: efficiency.', 'Adjective. Efficient (no waste) vs effective (works well). Noun: efficiency.'),
  'emphasize': VocabUsage('The author emphasizes the importance of early education.', '', 'Penulis menekankan pentingnya pendidikan usia dini.', '', 'Kata kerja transitif (tanpa \'on\'): emphasize sth. Nomina: emphasis (put emphasis on).', 'Transitive verb (no \'on\'): emphasize sth. Noun: emphasis (put emphasis on).'),
  'extinct': VocabUsage('Many species became extinct because their habitats were destroyed.', '', 'Banyak spesies punah karena habitatnya dihancurkan.', '', 'Kata sifat. Pola: become/go extinct. Nomina: extinction. Juga: extinct volcano (gunung mati).', 'Adjective. Pattern: become/go extinct. Noun: extinction. Also: extinct volcano.'),
  'inhabit': VocabUsage('Thousands of bird species inhabit the tropical forests of Indonesia.', '', 'Ribuan spesies burung mendiami hutan tropis Indonesia.', '', 'Kata kerja transitif (tanpa \'in\'): inhabit an area. Nomina: inhabitant (penduduk).', 'Transitive verb (no \'in\'): inhabit an area. Noun: inhabitant.'),
  'innovation': VocabUsage('Innovation in renewable energy is essential for a sustainable future.', '', 'Inovasi di bidang energi terbarukan sangat penting bagi masa depan yang berkelanjutan.', '', 'Kata benda. Pola: innovation in sth; technological innovation. Adj: innovative.', 'Noun. Pattern: innovation in sth; technological innovation. Adj: innovative.'),
  'numerous': VocabUsage('Numerous studies have linked air pollution to heart disease.', '', 'Banyak sekali penelitian telah mengaitkan polusi udara dengan penyakit jantung.', '', 'Kata sifat formal + nomina jamak: numerous studies/occasions. Lebih formal dari many.', 'Formal adjective + plural noun: numerous studies/occasions. More formal than many.'),
  'preserve': VocabUsage('The government must do more to preserve historic buildings.', '', 'Pemerintah harus berbuat lebih banyak untuk melestarikan bangunan bersejarah.', '', 'Kata kerja. Kolokasi: preserve culture/heritage/food. Nomina: preservation. Mirip: conserve.', 'Verb. Collocations: preserve culture/heritage/food. Noun: preservation. Similar: conserve.'),
  'rapid': VocabUsage('The rapid growth of cities has put pressure on public services.', '', 'Pertumbuhan kota yang cepat telah membebani layanan publik.', '', 'Kata sifat formal. Kolokasi: rapid growth/change/increase. Adverb: rapidly.', 'Formal adjective. Collocations: rapid growth/change/increase. Adverb: rapidly.'),
  'reluctant': VocabUsage('Many patients are reluctant to talk about their mental health problems.', '', 'Banyak pasien enggan membicarakan masalah kesehatan mental mereka.', '', 'Kata sifat. Pola: be reluctant to do sth. Nomina: reluctance. Mirip: unwilling.', 'Adjective. Pattern: be reluctant to do sth. Noun: reluctance. Similar: unwilling.'),
  'remarkable': VocabUsage('The country has made remarkable progress in reducing poverty.', '', 'Negara itu telah membuat kemajuan luar biasa dalam mengurangi kemiskinan.', '', 'Kata sifat. Kolokasi: remarkable progress/achievement/success. Adverb: remarkably.', 'Adjective. Collocations: remarkable progress/achievement/success. Adverb: remarkably.'),
  'resemble': VocabUsage('The new building closely resembles a traditional Javanese house.', '', 'Bangunan baru itu sangat menyerupai rumah tradisional Jawa.', '', 'Kata kerja transitif (tanpa \'to/with\'), tidak dipakai bentuk -ing. Nomina: resemblance.', 'Transitive verb (no \'to/with\'), not used in -ing form. Noun: resemblance.'),
  'scarce': VocabUsage('Clean water is becoming scarce in many parts of the world.', '', 'Air bersih menjadi langka di banyak belahan dunia.', '', 'Kata sifat. Kolokasi: scarce resources; become scarce. Nomina: scarcity. Lawan: abundant.', 'Adjective. Collocations: scarce resources; become scarce. Noun: scarcity. Opposite: abundant.'),
  'sophisticated': VocabUsage('Banks use sophisticated software to detect fraud.', '', 'Bank menggunakan perangkat lunak canggih untuk mendeteksi penipuan.', '', 'Kata sifat. Untuk alat = canggih; untuk orang = berselera/berwawasan tinggi.', 'Adjective. For tools = advanced; for people = worldly and cultured.'),
  'vast': VocabUsage('Indonesia is a vast country with thousands of islands and hundreds of languages.', '', 'Indonesia adalah negara yang sangat luas dengan ribuan pulau dan ratusan bahasa.', '', 'Kata sifat. Kolokasi: the vast majority, a vast area/amount. Lebih kuat dari large.', 'Adjective. Collocations: the vast majority, a vast area/amount. Stronger than large.'),
  'carbon footprint': VocabUsage('Individuals can reduce their carbon footprint by flying less and eating less meat.', '', 'Setiap orang dapat mengurangi jejak karbonnya dengan lebih jarang terbang dan makan lebih sedikit daging.', '', 'Frasa nomina. Kolokasi: reduce/cut/shrink your carbon footprint.', 'Noun phrase. Collocations: reduce/cut/shrink your carbon footprint.'),
  'emission': VocabUsage('Governments must set stricter limits on vehicle emissions.', '', 'Pemerintah harus menetapkan batas yang lebih ketat untuk emisi kendaraan.', '', 'Kata benda, sering jamak. Kolokasi: carbon/CO2 emissions, cut/reduce emissions. Verb: emit.', 'Noun, often plural. Collocations: carbon/CO2 emissions, cut/reduce emissions. Verb: emit.'),
  'renewable': VocabUsage('Investing in renewable energy creates jobs and reduces pollution.', '', 'Investasi pada energi terbarukan menciptakan lapangan kerja dan mengurangi polusi.', '', 'Kata sifat. Kolokasi: renewable energy/resources/sources. Lawan: non-renewable.', 'Adjective. Collocations: renewable energy/resources/sources. Opposite: non-renewable.'),
  'deforestation': VocabUsage('Deforestation is one of the main causes of habitat loss in Southeast Asia.', '', 'Penggundulan hutan adalah salah satu penyebab utama hilangnya habitat di Asia Tenggara.', '', 'Kata benda tak terhitung. Kolokasi: tackle/combat deforestation, rapid deforestation.', 'Uncountable noun. Collocations: tackle/combat deforestation, rapid deforestation.'),
  'biodiversity': VocabUsage('Protecting coral reefs is vital for maintaining marine biodiversity.', '', 'Melindungi terumbu karang sangat penting untuk menjaga keanekaragaman hayati laut.', '', 'Kata benda tak terhitung. Kolokasi: protect/lose biodiversity, loss of biodiversity.', 'Uncountable noun. Collocations: protect/lose biodiversity, loss of biodiversity.'),
  'conservation': VocabUsage('Wildlife conservation programmes depend heavily on public funding.', '', 'Program pelestarian satwa liar sangat bergantung pada dana publik.', '', 'Kata benda. Kolokasi: wildlife/energy/water conservation. Verb: conserve.', 'Noun. Collocations: wildlife/energy/water conservation. Verb: conserve.'),
  'endangered': VocabUsage('The Sumatran tiger is one of the most endangered animals in the world.', '', 'Harimau Sumatra adalah salah satu hewan paling terancam punah di dunia.', '', 'Kata sifat. Kolokasi: endangered species/animals; critically endangered. Beda: extinct = sudah punah.', 'Adjective. Collocations: endangered species/animals; critically endangered. Extinct = already gone.'),
  'habitat': VocabUsage('Many animals are losing their natural habitat because of expanding farmland.', '', 'Banyak hewan kehilangan habitat alaminya karena lahan pertanian yang terus meluas.', '', 'Kata benda. Kolokasi: natural habitat, habitat loss/destruction.', 'Noun. Collocations: natural habitat, habitat loss/destruction.'),
  'recycle': VocabUsage('Households should be encouraged to recycle paper, glass and plastic.', '', 'Rumah tangga perlu didorong untuk mendaur ulang kertas, kaca, dan plastik.', '', 'Kata kerja. Nomina: recycling; adj: recycled (recycled paper). Rangkaian: reduce, reuse, recycle.', 'Verb. Noun: recycling; adj: recycled (recycled paper). Series: reduce, reuse, recycle.'),
  'fossil fuel': VocabUsage('Our dependence on fossil fuels is a major cause of climate change.', '', 'Ketergantungan kita pada bahan bakar fosil adalah penyebab utama perubahan iklim.', '', 'Frasa nomina, sering jamak. Kolokasi: burn fossil fuels, dependence on fossil fuels.', 'Noun phrase, often plural. Collocations: burn fossil fuels, dependence on fossil fuels.'),
  'greenhouse gas': VocabUsage('Cattle farming produces large amounts of methane, a powerful greenhouse gas.', '', 'Peternakan sapi menghasilkan banyak metana, sejenis gas rumah kaca yang kuat.', '', 'Frasa nomina. Kolokasi: greenhouse gas emissions, the greenhouse effect.', 'Noun phrase. Collocations: greenhouse gas emissions, the greenhouse effect.'),
  'extinction': VocabUsage('Without urgent action, many species face extinction within decades.', '', 'Tanpa tindakan segera, banyak spesies terancam kepunahan dalam beberapa dekade.', '', 'Kata benda. Kolokasi: face extinction, on the brink of extinction, mass extinction. Adj: extinct.', 'Noun. Collocations: face extinction, on the brink of extinction, mass extinction. Adj: extinct.'),
  'ecosystem': VocabUsage('Plastic waste is damaging fragile marine ecosystems around the world.', '', 'Sampah plastik merusak ekosistem laut yang rapuh di seluruh dunia.', '', 'Kata benda. Kolokasi: fragile/marine/local ecosystem, damage/disrupt an ecosystem.', 'Noun. Collocations: fragile/marine/local ecosystem, damage/disrupt an ecosystem.'),
  'wildlife': VocabUsage('Tourism can bring money to protect local wildlife if it is well managed.', '', 'Pariwisata dapat menghasilkan dana untuk melindungi satwa liar setempat jika dikelola dengan baik.', '', 'Kata benda tak terhitung (tanpa -s). Kolokasi: wildlife conservation/reserve/habitat.', 'Uncountable noun (no -s). Collocations: wildlife conservation/reserve/habitat.'),
  'poaching': VocabUsage('Poaching has pushed the rhino population to dangerously low levels.', '', 'Perburuan liar telah membuat populasi badak turun ke tingkat yang sangat mengkhawatirkan.', '', 'Kata benda. Verb: poach; pelaku: poacher. Kolokasi: crack down on poaching.', 'Noun. Verb: poach; person: poacher. Collocation: crack down on poaching.'),
  'rainforest': VocabUsage('The Amazon rainforest is often described as the lungs of the planet.', '', 'Hutan hujan Amazon sering digambarkan sebagai paru-paru bumi.', '', 'Kata benda. Kolokasi: tropical rainforest, destroy/clear the rainforest.', 'Noun. Collocations: tropical rainforest, destroy/clear the rainforest.'),
  'landfill': VocabUsage('Most household waste still ends up in landfill sites.', '', 'Sebagian besar sampah rumah tangga masih berakhir di tempat pembuangan sampah.', '', 'Kata benda. Kolokasi: landfill site, end up in landfill, send waste to landfill.', 'Noun. Collocations: landfill site, end up in landfill, send waste to landfill.'),
  'litter': VocabUsage('Heavy fines should be imposed on people who drop litter in parks.', '', 'Denda berat harus dikenakan pada orang yang membuang sampah sembarangan di taman.', '', 'Kata benda tak terhitung / kata kerja. Kolokasi: drop litter, pick up litter. Beda: rubbish = sampah umum.', 'Uncountable noun / verb. Collocations: drop litter, pick up litter. Rubbish = waste in general.'),
  'smog': VocabUsage('Thick smog forced schools in the capital to close for several days.', '', 'Kabut asap tebal memaksa sekolah-sekolah di ibu kota tutup selama beberapa hari.', '', 'Kata benda tak terhitung (smoke + fog). Kolokasi: thick smog, a blanket of smog.', 'Uncountable noun (smoke + fog). Collocations: thick smog, a blanket of smog.'),
  'exhaust fumes': VocabUsage('Exhaust fumes from heavy traffic are harmful to children\'s lungs.', '', 'Asap knalpot dari lalu lintas padat berbahaya bagi paru-paru anak-anak.', '', 'Frasa nomina jamak. Kolokasi: car/vehicle exhaust fumes, breathe in exhaust fumes.', 'Plural noun phrase. Collocations: car/vehicle exhaust fumes, breathe in exhaust fumes.'),
  'pesticide': VocabUsage('Excessive use of pesticides can contaminate rivers and harm bees.', '', 'Penggunaan pestisida berlebihan dapat mencemari sungai dan membahayakan lebah.', '', 'Kata benda. Kolokasi: spray/use pesticides, pesticide residue.', 'Noun. Collocations: spray/use pesticides, pesticide residue.'),
  'contamination': VocabUsage('The factory was closed after water contamination was detected nearby.', '', 'Pabrik itu ditutup setelah pencemaran air terdeteksi di sekitarnya.', '', 'Kata benda. Kolokasi: water/food contamination, risk of contamination. Verb: contaminate.', 'Noun. Collocations: water/food contamination, risk of contamination. Verb: contaminate.'),
  'scarcity': VocabUsage('Water scarcity could lead to conflict between neighbouring countries.', '', 'Kelangkaan air bisa memicu konflik antarnegara tetangga.', '', 'Kata benda. Kolokasi: water/food scarcity, scarcity of resources. Adj: scarce.', 'Noun. Collocations: water/food scarcity, scarcity of resources. Adj: scarce.'),
  'natural disaster': VocabUsage('Poor countries often struggle to recover after a major natural disaster.', '', 'Negara miskin sering kesulitan pulih setelah bencana alam besar.', '', 'Frasa nomina. Kolokasi: hit by a natural disaster, prone to natural disasters.', 'Noun phrase. Collocations: hit by a natural disaster, prone to natural disasters.'),
  'sea level': VocabUsage('Rising sea levels threaten low-lying islands in the Pacific.', '', 'Naiknya permukaan laut mengancam pulau-pulau dataran rendah di Pasifik.', '', 'Frasa nomina. Kolokasi: rising sea levels; above/below sea level (ketinggian).', 'Noun phrase. Collocations: rising sea levels; above/below sea level (altitude).'),
  'ozone layer': VocabUsage('International agreements helped to protect the ozone layer from harmful chemicals.', '', 'Perjanjian internasional membantu melindungi lapisan ozon dari bahan kimia berbahaya.', '', 'Frasa nomina dengan \'the\'. Kolokasi: damage to the ozone layer, a hole in the ozone layer.', 'Noun phrase with \'the\'. Collocations: damage to the ozone layer, a hole in the ozone layer.'),
  'wind farm': VocabUsage('Some residents oppose the new wind farm because of the noise.', '', 'Sebagian warga menentang ladang angin baru itu karena kebisingannya.', '', 'Frasa nomina. Kolokasi: build an offshore/onshore wind farm.', 'Noun phrase. Collocations: build an offshore/onshore wind farm.'),
  'solar panel': VocabUsage('Installing solar panels on rooftops can cut household energy bills.', '', 'Memasang panel surya di atap dapat memangkas tagihan listrik rumah tangga.', '', 'Frasa nomina. Kolokasi: install/fit solar panels, rooftop solar panels.', 'Noun phrase. Collocations: install/fit solar panels, rooftop solar panels.'),
  'single-use plastic': VocabUsage('Many cities have banned single-use plastic bags and straws.', '', 'Banyak kota telah melarang kantong dan sedotan plastik sekali pakai.', '', 'Frasa nomina/sifat. Kolokasi: ban/reduce single-use plastic(s), single-use plastic bags.', 'Noun phrase/adjective. Collocations: ban/reduce single-use plastic(s), single-use plastic bags.'),
  'eco-friendly': VocabUsage('Consumers are increasingly willing to pay more for eco-friendly products.', '', 'Konsumen makin bersedia membayar lebih untuk produk ramah lingkungan.', '', 'Kata sifat majemuk. Kolokasi: eco-friendly products/packaging/transport. Mirip: green, sustainable.', 'Compound adjective. Collocations: eco-friendly products/packaging/transport. Similar: green, sustainable.'),
  'curriculum': VocabUsage('Some argue that coding should be part of the school curriculum.', '', 'Sebagian orang berpendapat bahwa pemrograman harus menjadi bagian kurikulum sekolah.', '', 'Kata benda (jamak: curricula). Pola: on/in the curriculum. Beda: syllabus = isi satu mata pelajaran.', 'Noun (plural: curricula). Pattern: on/in the curriculum. Syllabus = content of one subject.'),
  'tuition': VocabUsage('Rising tuition fees prevent many talented students from attending university.', '', 'Biaya kuliah yang terus naik menghalangi banyak siswa berbakat untuk masuk universitas.', '', 'Kata benda. Kolokasi: tuition fees. Juga \'pengajaran/les\' (private tuition).', 'Noun. Collocation: tuition fees. Also \'teaching\' (private tuition).'),
  'literacy': VocabUsage('Improving adult literacy is a priority in many developing countries.', '', 'Meningkatkan kemampuan baca-tulis orang dewasa menjadi prioritas di banyak negara berkembang.', '', 'Kata benda. Kolokasi: literacy rate, digital/financial literacy. Adj: literate.', 'Noun. Collocations: literacy rate, digital/financial literacy. Adj: literate.'),
  'graduate': VocabUsage('Many graduates struggle to find jobs that match their qualifications.', '', 'Banyak lulusan kesulitan mencari pekerjaan yang sesuai dengan kualifikasinya.', '', 'Kata benda/kerja. Verb: graduate from university. Kolokasi: recent graduate, graduate job.', 'Noun/verb. Verb: graduate from university. Collocations: recent graduate, graduate job.'),
  'scholarship': VocabUsage('She won a full scholarship to study engineering abroad.', '', 'Ia memperoleh beasiswa penuh untuk kuliah teknik di luar negeri.', '', 'Kata benda. Kolokasi: win/award/apply for a scholarship, full scholarship.', 'Noun. Collocations: win/award/apply for a scholarship, full scholarship.'),
  'compulsory': VocabUsage('In some countries, military service is compulsory for young men.', '', 'Di beberapa negara, wajib militer diberlakukan bagi pemuda.', '', 'Kata sifat. Kolokasi: compulsory education/subject. Mirip: mandatory; lawan: optional, voluntary.', 'Adjective. Collocations: compulsory education/subject. Similar: mandatory; opposite: optional, voluntary.'),
  'discipline': VocabUsage('Teachers find it harder to maintain discipline in large classes.', '', 'Guru merasa lebih sulit menjaga disiplin di kelas yang besar.', '', 'Kata benda/kerja. Kolokasi: maintain/lack discipline, self-discipline. Juga \'cabang ilmu\'.', 'Noun/verb. Collocations: maintain/lack discipline, self-discipline. Also \'field of study\'.'),
  'tertiary education': VocabUsage('Access to tertiary education should not depend on family income.', '', 'Akses ke pendidikan tinggi tidak seharusnya bergantung pada penghasilan keluarga.', '', 'Frasa nomina formal. Urutan: primary, secondary, tertiary education. Mirip: higher education.', 'Formal noun phrase. Sequence: primary, secondary, tertiary education. Similar: higher education.'),
  'distance learning': VocabUsage('Distance learning allows people in remote areas to earn a degree.', '', 'Pembelajaran jarak jauh memungkinkan orang di daerah terpencil meraih gelar.', '', 'Frasa nomina tak terhitung. Mirip: online learning, e-learning. Kolokasi: distance learning course.', 'Uncountable noun phrase. Similar: online learning, e-learning. Collocation: distance learning course.'),
  'syllabus': VocabUsage('The teacher handed out the syllabus on the first day of the course.', '', 'Guru membagikan silabus pada hari pertama kursus.', '', 'Kata benda (jamak: syllabuses/syllabi). Pola: on the syllabus. Beda: curriculum = keseluruhan program.', 'Noun (plural: syllabuses/syllabi). Pattern: on the syllabus. Curriculum = the whole programme.'),
  'tutor': VocabUsage('Wealthy parents often hire private tutors to help their children pass exams.', '', 'Orang tua kaya sering menyewa guru les privat agar anaknya lulus ujian.', '', 'Kata benda/kerja. Kolokasi: private tutor, hire a tutor. Nomina: tutoring; adj: tutorial.', 'Noun/verb. Collocations: private tutor, hire a tutor. Noun: tutoring; adj: tutorial.'),
  'dropout': VocabUsage('Poverty is one of the main reasons for the high dropout rate.', '', 'Kemiskinan adalah salah satu alasan utama tingginya angka putus sekolah.', '', 'Kata benda. Kolokasi: dropout rate, school dropout. Verb: drop out (of school).', 'Noun. Collocations: dropout rate, school dropout. Verb: drop out (of school).'),
  'rote learning': VocabUsage('Critics say rote learning does not develop students\' problem-solving skills.', '', 'Para kritikus mengatakan belajar hafalan tidak mengembangkan kemampuan memecahkan masalah siswa.', '', 'Frasa nomina, bernada negatif di esai. Lawan: active/critical learning. Juga: learn by rote.', 'Noun phrase, negative in essays. Contrast: active/critical learning. Also: learn by rote.'),
  'extracurricular': VocabUsage('Extracurricular activities help students develop teamwork and leadership skills.', '', 'Kegiatan ekstrakurikuler membantu siswa mengembangkan kerja sama tim dan kepemimpinan.', '', 'Kata sifat. Kolokasi: extracurricular activities/clubs. Lawan konteks: academic subjects.', 'Adjective. Collocations: extracurricular activities/clubs. Contrast: academic subjects.'),
  'vocational': VocabUsage('Vocational training can prepare young people for well-paid technical jobs.', '', 'Pelatihan kejuruan dapat menyiapkan anak muda untuk pekerjaan teknis bergaji baik.', '', 'Kata sifat. Kolokasi: vocational training/school/course/skills. Lawan: academic.', 'Adjective. Collocations: vocational training/school/course/skills. Contrast: academic.'),
  'boarding school': VocabUsage('Sending young children to boarding school may affect family relationships.', '', 'Menyekolahkan anak kecil di sekolah berasrama bisa memengaruhi hubungan keluarga.', '', 'Frasa nomina. Pola: go to/attend boarding school. Mirip: pesantren.', 'Noun phrase. Pattern: go to/attend boarding school. Contrast: day school.'),
  'kindergarten': VocabUsage('Children usually start kindergarten at the age of four or five.', '', 'Anak-anak biasanya mulai masuk taman kanak-kanak pada usia empat atau lima tahun.', '', 'Kata benda. Pola: go to/start kindergarten, in kindergarten. Mirip (UK): nursery school.', 'Noun. Pattern: go to/start kindergarten, in kindergarten. Similar (UK): nursery school.'),
  'undergraduate': VocabUsage('Most undergraduates take part-time jobs to cover their living costs.', '', 'Kebanyakan mahasiswa S1 bekerja paruh waktu untuk menutup biaya hidup.', '', 'Kata benda/sifat. Kolokasi: undergraduate degree/course. Lawan: postgraduate.', 'Noun/adjective. Collocations: undergraduate degree/course. Contrast: postgraduate.'),
  'plagiarism': VocabUsage('Universities use special software to detect plagiarism in student essays.', '', 'Universitas menggunakan perangkat lunak khusus untuk mendeteksi plagiarisme dalam esai mahasiswa.', '', 'Kata benda. Kolokasi: detect/commit/accuse sb of plagiarism. Verb: plagiarize.', 'Noun. Collocations: detect/commit/accuse sb of plagiarism. Verb: plagiarize.'),
  'critical thinking': VocabUsage('Schools should place more emphasis on critical thinking than memorization.', '', 'Sekolah seharusnya lebih menekankan berpikir kritis daripada hafalan.', '', 'Frasa nomina tak terhitung. Kolokasi: develop/encourage critical thinking (skills).', 'Uncountable noun phrase. Collocations: develop/encourage critical thinking (skills).'),
  'homeschooling': VocabUsage('Homeschooling gives parents more control over what their children learn.', '', 'Sekolah di rumah memberi orang tua kendali lebih besar atas apa yang dipelajari anaknya.', '', 'Kata benda tak terhitung. Verb: homeschool a child. Mirip: home education.', 'Uncountable noun. Verb: homeschool a child. Similar: home education.'),
  'gap year': VocabUsage('Taking a gap year can help young people become more independent.', '', 'Mengambil tahun jeda sebelum kuliah dapat membantu anak muda menjadi lebih mandiri.', '', 'Frasa nomina. Kolokasi: take a gap year, during a gap year.', 'Noun phrase. Collocations: take a gap year, during a gap year.'),
  'peer pressure': VocabUsage('Teenagers often start smoking because of peer pressure.', '', 'Remaja sering mulai merokok karena tekanan teman sebaya.', '', 'Frasa nomina tak terhitung. Kolokasi: give in to/resist peer pressure, under peer pressure.', 'Uncountable noun phrase. Collocations: give in to/resist peer pressure, under peer pressure.'),
  'truancy': VocabUsage('The school introduced fines for parents to reduce truancy.', '', 'Sekolah itu memberlakukan denda bagi orang tua untuk mengurangi kebiasaan bolos sekolah.', '', 'Kata benda tak terhitung. Pelaku: truant; idiom: play truant (membolos).', 'Uncountable noun. Person: truant; idiom: play truant.'),
  'illiterate': VocabUsage('A significant proportion of the rural population is still illiterate.', '', 'Sebagian cukup besar penduduk pedesaan masih buta huruf.', '', 'Kata sifat. Lawan: literate. Nomina: illiteracy. Kiasan: computer illiterate (gaptek).', 'Adjective. Opposite: literate. Noun: illiteracy. Figurative: computer illiterate.'),
  'obesity': VocabUsage('Childhood obesity has risen sharply as diets have become less healthy.', '', 'Obesitas pada anak meningkat tajam seiring pola makan yang makin tidak sehat.', '', 'Kata benda tak terhitung. Kolokasi: childhood obesity, obesity rate, tackle obesity. Adj: obese.', 'Uncountable noun. Collocations: childhood obesity, obesity rate, tackle obesity. Adj: obese.'),
  'nutrition': VocabUsage('Good nutrition in early childhood is essential for brain development.', '', 'Gizi yang baik pada masa kanak-kanak awal sangat penting bagi perkembangan otak.', '', 'Kata benda tak terhitung. Kolokasi: good/poor nutrition. Adj: nutritious (bergizi), nutritional.', 'Uncountable noun. Collocations: good/poor nutrition. Adj: nutritious, nutritional.'),
  'epidemic': VocabUsage('Health officials warned of a growing epidemic of diabetes in urban areas.', '', 'Pejabat kesehatan memperingatkan wabah diabetes yang terus meluas di daerah perkotaan.', '', 'Kata benda. Juga kiasan untuk masalah sosial yang meluas. Beda: pandemic = skala global.', 'Noun. Also figurative for a widespread social problem. Pandemic = global scale.'),
  'sedentary': VocabUsage('A sedentary lifestyle increases the risk of heart disease.', '', 'Gaya hidup kurang gerak meningkatkan risiko penyakit jantung.', '', 'Kata sifat. Kolokasi: sedentary lifestyle/job/work. Lawan: active.', 'Adjective. Collocations: sedentary lifestyle/job/work. Opposite: active.'),
  'well-being': VocabUsage('Green spaces in cities can improve residents\' mental well-being.', '', 'Ruang hijau di kota dapat meningkatkan kesejahteraan mental warganya.', '', 'Kata benda tak terhitung. Kolokasi: physical/mental/emotional well-being, sense of well-being.', 'Uncountable noun. Collocations: physical/mental/emotional well-being, sense of well-being.'),
  'diagnose': VocabUsage('Doctors can now diagnose many diseases with a simple blood test.', '', 'Dokter kini dapat mendiagnosis banyak penyakit dengan tes darah sederhana.', '', 'Kata kerja. Pola: diagnose sth; be diagnosed with sth (pasien). Nomina: diagnosis.', 'Verb. Pattern: diagnose sth; be diagnosed with sth (patient). Noun: diagnosis.'),
  'prevention': VocabUsage('Governments should spend more on prevention rather than treatment.', '', 'Pemerintah sebaiknya lebih banyak berbelanja untuk pencegahan daripada pengobatan.', '', 'Kata benda. Pola: prevention of sth. Peribahasa: prevention is better than cure. Verb: prevent.', 'Noun. Pattern: prevention of sth. Saying: prevention is better than cure. Verb: prevent.'),
  'mental health': VocabUsage('Employers are paying more attention to the mental health of their staff.', '', 'Para pemberi kerja makin memperhatikan kesehatan mental karyawannya.', '', 'Frasa nomina tak terhitung. Kolokasi: mental health problems/issues/services.', 'Uncountable noun phrase. Collocations: mental health problems/issues/services.'),
  'life expectancy': VocabUsage('Life expectancy has increased thanks to better healthcare and sanitation.', '', 'Angka harapan hidup meningkat berkat layanan kesehatan dan sanitasi yang lebih baik.', '', 'Frasa nomina. Kolokasi: average life expectancy, life expectancy rises/falls.', 'Noun phrase. Collocations: average life expectancy, life expectancy rises/falls.'),
  'junk food': VocabUsage('Advertising junk food to children should be strictly controlled.', '', 'Iklan makanan tidak sehat untuk anak-anak harus diawasi ketat.', '', 'Frasa nomina tak terhitung. Kolokasi: eat/ban junk food. Mirip: fast food (tidak selalu sama).', 'Uncountable noun phrase. Collocations: eat/ban junk food. Similar: fast food (not always the same).'),
  'balanced diet': VocabUsage('A balanced diet includes fruit, vegetables, protein and whole grains.', '', 'Pola makan seimbang mencakup buah, sayur, protein, dan biji-bijian utuh.', '', 'Frasa nomina. Kolokasi: eat/follow/maintain a balanced diet.', 'Noun phrase. Collocations: eat/follow/maintain a balanced diet.'),
  'addiction': VocabUsage('Smartphone addiction is becoming a concern among teenagers.', '', 'Kecanduan ponsel pintar mulai menjadi kekhawatiran di kalangan remaja.', '', 'Kata benda. Pola: addiction to sth. Adj: addicted (to), addictive.', 'Noun. Pattern: addiction to sth. Adj: addicted (to), addictive.'),
  'fitness': VocabUsage('Regular exercise improves both physical fitness and mood.', '', 'Olahraga teratur meningkatkan kebugaran fisik sekaligus suasana hati.', '', 'Kata benda tak terhitung. Kolokasi: physical fitness, fitness level, fitness centre. Adj: fit.', 'Uncountable noun. Collocations: physical fitness, fitness level, fitness centre. Adj: fit.'),
  'insomnia': VocabUsage('Stress at work is a common cause of insomnia among adults.', '', 'Stres di tempat kerja adalah penyebab umum susah tidur pada orang dewasa.', '', 'Kata benda tak terhitung. Kolokasi: suffer from insomnia. Mirip: sleeplessness.', 'Uncountable noun. Collocation: suffer from insomnia. Similar: sleeplessness.'),
  'anxiety': VocabUsage('Exam pressure causes high levels of anxiety among secondary students.', '', 'Tekanan ujian menimbulkan tingkat kecemasan yang tinggi pada siswa sekolah menengah.', '', 'Kata benda. Pola: anxiety about sth. Adj: anxious. Lebih formal daripada worry.', 'Noun. Pattern: anxiety about sth. Adj: anxious. More formal than worry.'),
  'chronic': VocabUsage('Chronic diseases such as diabetes require long-term treatment.', '', 'Penyakit kronis seperti diabetes memerlukan pengobatan jangka panjang.', '', 'Kata sifat. Kolokasi: chronic disease/pain/illness; juga kiasan: chronic shortage. Lawan: acute.', 'Adjective. Collocations: chronic disease/pain/illness; also chronic shortage. Opposite: acute.'),
  'vaccination': VocabUsage('Vaccination programmes have almost eliminated several deadly diseases.', '', 'Program vaksinasi hampir memberantas beberapa penyakit mematikan.', '', 'Kata benda. Kolokasi: vaccination programme/campaign. Verb: vaccinate sb against sth.', 'Noun. Collocations: vaccination programme/campaign. Verb: vaccinate sb against sth.'),
  'healthcare': VocabUsage('Free healthcare should be available to every citizen.', '', 'Layanan kesehatan gratis seharusnya tersedia bagi setiap warga negara.', '', 'Kata benda tak terhitung. Kolokasi: healthcare system/workers/costs, access to healthcare.', 'Uncountable noun. Collocations: healthcare system/workers/costs, access to healthcare.'),
  'symptom': VocabUsage('Fever and a dry cough are common symptoms of the flu.', '', 'Demam dan batuk kering adalah gejala umum flu.', '', 'Kata benda. Kolokasi: show/develop symptoms, symptoms of sth. Juga kiasan: a symptom of a problem.', 'Noun. Collocations: show/develop symptoms, symptoms of sth. Also figurative: a symptom of a problem.'),
  'side effect': VocabUsage('Patients should be informed about the possible side effects of the medicine.', '', 'Pasien perlu diberi tahu tentang kemungkinan efek samping obat itu.', '', 'Frasa nomina, biasanya jamak. Kolokasi: possible/serious side effects, side effects of sth.', 'Noun phrase, usually plural. Collocations: possible/serious side effects, side effects of sth.'),
  'malnutrition': VocabUsage('Malnutrition remains a serious problem in some rural communities.', '', 'Gizi buruk masih menjadi masalah serius di beberapa komunitas pedesaan.', '', 'Kata benda tak terhitung. Kolokasi: suffer from malnutrition, child malnutrition. Adj: malnourished.', 'Uncountable noun. Collocations: suffer from malnutrition, child malnutrition. Adj: malnourished.'),
  'hygiene': VocabUsage('Good hygiene, such as washing hands, prevents the spread of infection.', '', 'Kebersihan yang baik, seperti mencuci tangan, mencegah penyebaran infeksi.', '', 'Kata benda tak terhitung. Kolokasi: personal/food hygiene, hygiene standards. Adj: hygienic.', 'Uncountable noun. Collocations: personal/food hygiene, hygiene standards. Adj: hygienic.'),
  'overweight': VocabUsage('Nearly a third of adults in the city are overweight.', '', 'Hampir sepertiga orang dewasa di kota itu kelebihan berat badan.', '', 'Kata sifat. Lebih halus daripada fat; obese = jauh lebih berat. Lawan: underweight.', 'Adjective. Softer than fat; obese = much heavier. Opposite: underweight.'),
  'workout': VocabUsage('A thirty-minute workout three times a week can improve your health.', '', 'Latihan fisik tiga puluh menit tiga kali seminggu dapat meningkatkan kesehatan.', '', 'Kata benda. Verb frasa: work out (berolahraga). Kolokasi: do a workout, daily workout.', 'Noun. Phrasal verb: work out (exercise). Collocations: do a workout, daily workout.'),
  'check-up': VocabUsage('Adults over forty should have a regular medical check-up.', '', 'Orang dewasa di atas empat puluh tahun sebaiknya rutin menjalani pemeriksaan kesehatan.', '', 'Kata benda. Kolokasi: have/go for a check-up, annual/regular check-up. Verb: check up on sb.', 'Noun. Collocations: have/go for a check-up, annual/regular check-up. Verb: check up on sb.'),
  'burnout': VocabUsage('Long working hours are leading to burnout among young doctors.', '', 'Jam kerja yang panjang menyebabkan kelelahan kerja di kalangan dokter muda.', '', 'Kata benda. Kolokasi: suffer from burnout, risk of burnout. Adj: burned/burnt out.', 'Noun. Collocations: suffer from burnout, risk of burnout. Adj: burned/burnt out.'),
  'privacy': VocabUsage('Social media companies collect data in ways that threaten users\' privacy.', '', 'Perusahaan media sosial mengumpulkan data dengan cara yang mengancam privasi pengguna.', '', 'Kata benda tak terhitung. Kolokasi: invasion of privacy, protect/respect privacy, privacy policy.', 'Uncountable noun. Collocations: invasion of privacy, protect/respect privacy, privacy policy.'),
  'surveillance': VocabUsage('The increase in CCTV surveillance has raised concerns about civil liberties.', '', 'Meningkatnya pengawasan CCTV menimbulkan kekhawatiran tentang kebebasan sipil.', '', 'Kata benda tak terhitung. Kolokasi: under surveillance, surveillance cameras, mass surveillance.', 'Uncountable noun. Collocations: under surveillance, surveillance cameras, mass surveillance.'),
  'cyberbullying': VocabUsage('Schools need clear policies to deal with cyberbullying among students.', '', 'Sekolah memerlukan kebijakan yang jelas untuk menangani perundungan daring di antara siswa.', '', 'Kata benda tak terhitung. Kolokasi: victim of cyberbullying, tackle cyberbullying.', 'Uncountable noun. Collocations: victim of cyberbullying, tackle cyberbullying.'),
  'artificial': VocabUsage('Artificial intelligence is changing the way many industries operate.', '', 'Kecerdasan buatan sedang mengubah cara kerja banyak industri.', '', 'Kata sifat. Kolokasi: artificial intelligence, artificial sweeteners. Lawan: natural.', 'Adjective. Collocations: artificial intelligence, artificial sweeteners. Opposite: natural.'),
  'advertising': VocabUsage('Advertising aimed at children should be more strictly regulated.', '', 'Periklanan yang ditujukan kepada anak-anak harus diatur lebih ketat.', '', 'Kata benda tak terhitung (industri/kegiatan). Satu iklan: an advertisement/ad. Verb: advertise.', 'Uncountable noun (the activity). One item: an advertisement/ad. Verb: advertise.'),
  'censorship': VocabUsage('Strict censorship of the press limits public debate.', '', 'Penyensoran pers yang ketat membatasi perdebatan publik.', '', 'Kata benda tak terhitung. Kolokasi: internet/press censorship. Verb: censor.', 'Uncountable noun. Collocations: internet/press censorship. Verb: censor.'),
  'gadget': VocabUsage('Children today spend hours playing with electronic gadgets.', '', 'Anak-anak masa kini menghabiskan berjam-jam bermain dengan gawai elektronik.', '', 'Kata benda terhitung. Kolokasi: electronic/kitchen gadgets, the latest gadget.', 'Countable noun. Collocations: electronic/kitchen gadgets, the latest gadget.'),
  'screen time': VocabUsage('Experts recommend limiting screen time for children under five.', '', 'Para ahli menyarankan membatasi waktu di depan layar bagi anak di bawah lima tahun.', '', 'Frasa nomina tak terhitung. Kolokasi: limit/reduce screen time, daily screen time.', 'Uncountable noun phrase. Collocations: limit/reduce screen time, daily screen time.'),
  'breakthrough': VocabUsage('Scientists have made a major breakthrough in cancer research.', '', 'Para ilmuwan telah membuat terobosan besar dalam penelitian kanker.', '', 'Kata benda. Kolokasi: make/achieve a breakthrough, a breakthrough in sth.', 'Noun. Collocations: make/achieve a breakthrough, a breakthrough in sth.'),
  'cutting-edge': VocabUsage('The hospital uses cutting-edge technology to treat heart patients.', '', 'Rumah sakit itu memakai teknologi paling mutakhir untuk merawat pasien jantung.', '', 'Kata sifat majemuk (sebelum nomina). Juga nomina: at the cutting edge of sth.', 'Compound adjective (before a noun). Also noun: at the cutting edge of sth.'),
  'obsolete': VocabUsage('Many traditional jobs may become obsolete because of automation.', '', 'Banyak pekerjaan tradisional bisa menjadi usang karena otomatisasi.', '', 'Kata sifat. Pola: become/render sth obsolete. Mirip: outdated.', 'Adjective. Pattern: become/render sth obsolete. Similar: outdated.'),
  'e-commerce': VocabUsage('The growth of e-commerce has forced many small shops to close.', '', 'Pertumbuhan perdagangan elektronik telah memaksa banyak toko kecil tutup.', '', 'Kata benda tak terhitung. Kolokasi: e-commerce platform/site, the rise of e-commerce.', 'Uncountable noun. Collocations: e-commerce platform/site, the rise of e-commerce.'),
  'hacker': VocabUsage('Hackers stole the personal data of millions of customers.', '', 'Para peretas mencuri data pribadi jutaan pelanggan.', '', 'Kata benda. Verb: hack (into) a system. Kegiatan: hacking.', 'Noun. Verb: hack (into) a system. Activity: hacking.'),
  'misinformation': VocabUsage('Misinformation spreads quickly on social media during health crises.', '', 'Informasi keliru menyebar cepat di media sosial saat krisis kesehatan.', '', 'Kata benda tak terhitung. Beda: misinformation (tak sengaja) vs disinformation (sengaja).', 'Uncountable noun. Misinformation (accidental) vs disinformation (deliberate).'),
  'fake news': VocabUsage('Young people need to learn how to identify fake news online.', '', 'Anak muda perlu belajar cara mengenali berita palsu di internet.', '', 'Frasa nomina tak terhitung (tanpa \'a\'). Kolokasi: spread/identify fake news.', 'Uncountable noun phrase (no \'a\'). Collocations: spread/identify fake news.'),
  'influencer': VocabUsage('Many teenagers buy products recommended by social media influencers.', '', 'Banyak remaja membeli produk yang direkomendasikan oleh influencer media sosial.', '', 'Kata benda. Kolokasi: social media influencer, influencer marketing. Verb: influence.', 'Noun. Collocations: social media influencer, influencer marketing. Verb: influence.'),
  'cybercrime': VocabUsage('Banks invest heavily in security to protect customers from cybercrime.', '', 'Bank berinvestasi besar dalam keamanan untuk melindungi nasabah dari kejahatan siber.', '', 'Kata benda tak terhitung. Kolokasi: combat/tackle cybercrime, victim of cybercrime.', 'Uncountable noun. Collocations: combat/tackle cybercrime, victim of cybercrime.'),
  'piracy': VocabUsage('Online piracy costs the film industry billions of dollars every year.', '', 'Pembajakan daring merugikan industri film miliaran dolar setiap tahun.', '', 'Kata benda tak terhitung. Kolokasi: software/music/online piracy. Pelaku: pirate.', 'Uncountable noun. Collocations: software/music/online piracy. Person: pirate.'),
  'broadcast': VocabUsage('The final match will be broadcast live on national television.', '', 'Pertandingan final akan disiarkan langsung di televisi nasional.', '', 'Kata kerja tak beraturan: broadcast-broadcast-broadcast. Kolokasi: broadcast live; juga nomina.', 'Irregular verb: broadcast-broadcast-broadcast. Collocation: broadcast live; also a noun.'),
  'reporter': VocabUsage('The reporter interviewed several witnesses after the accident.', '', 'Wartawan itu mewawancarai beberapa saksi setelah kecelakaan.', '', 'Kata benda. Mirip: journalist (lebih umum). Verb: report on sth.', 'Noun. Similar: journalist (broader). Verb: report on sth.'),
  'headline': VocabUsage('The scandal made headlines in newspapers across the country.', '', 'Skandal itu menjadi berita utama di surat kabar seluruh negeri.', '', 'Kata benda. Kolokasi: make/hit the headlines, front-page headline.', 'Noun. Collocations: make/hit the headlines, front-page headline.'),
  'tabloid': VocabUsage('Tabloid newspapers often focus on celebrity gossip rather than serious news.', '', 'Koran gosip sering berfokus pada gosip selebritas alih-alih berita serius.', '', 'Kata benda/sifat. Kolokasi: tabloid press/newspaper. Lawan: broadsheet (koran serius).', 'Noun/adjective. Collocations: tabloid press/newspaper. Contrast: broadsheet (serious paper).'),
  'user-friendly': VocabUsage('The new banking app is simple and user-friendly, even for older people.', '', 'Aplikasi bank yang baru itu sederhana dan mudah dipakai, bahkan bagi orang lanjut usia.', '', 'Kata sifat majemuk. Kolokasi: user-friendly design/interface/software.', 'Compound adjective. Collocations: user-friendly design/interface/software.'),
  'addictive': VocabUsage('Social media apps are designed to be addictive.', '', 'Aplikasi media sosial dirancang agar bikin ketagihan.', '', 'Kata sifat (untuk benda). Beda: addicted (untuk orang): I am addicted to it. Nomina: addiction.', 'Adjective (for things). Addicted is for people: I am addicted to it. Noun: addiction.'),
  'remote working': VocabUsage('Remote working has reduced commuting time for millions of employees.', '', 'Kerja jarak jauh telah memangkas waktu perjalanan bagi jutaan karyawan.', '', 'Frasa nomina tak terhitung. Mirip: working from home, telecommuting. Verb: work remotely.', 'Uncountable noun phrase. Similar: working from home, telecommuting. Verb: work remotely.'),
  'crime': VocabUsage('Unemployment and poverty are often linked to higher levels of crime.', '', 'Pengangguran dan kemiskinan sering dikaitkan dengan tingkat kejahatan yang lebih tinggi.', '', 'Kata benda (terhitung/tak terhitung). Kolokasi: commit a crime, crime rate, violent crime.', 'Noun (countable/uncountable). Collocations: commit a crime, crime rate, violent crime.'),
  'punishment': VocabUsage('Some people believe that harsher punishment will reduce crime.', '', 'Sebagian orang percaya bahwa hukuman yang lebih berat akan mengurangi kejahatan.', '', 'Kata benda. Kolokasi: severe/harsh punishment, capital punishment. Verb: punish sb for sth.', 'Noun. Collocations: severe/harsh punishment, capital punishment. Verb: punish sb for sth.'),
  'government': VocabUsage('The government should invest more in public transport.', '', 'Pemerintah seharusnya berinvestasi lebih banyak pada transportasi umum.', '', 'Kata benda; the government bisa diikuti kata kerja tunggal/jamak (UK). Adj: governmental.', 'Noun; in UK English \'the government\' can take a singular or plural verb. Adj: governmental.'),
  'offender': VocabUsage('Young offenders should receive education rather than long prison sentences.', '', 'Pelaku pelanggaran muda seharusnya mendapat pendidikan, bukan hukuman penjara panjang.', '', 'Kata benda. Kolokasi: young/first-time/repeat offender. Verb: offend; nomina: offence.', 'Noun. Collocations: young/first-time/repeat offender. Verb: offend; noun: offence.'),
  'juvenile delinquency': VocabUsage('Lack of parental supervision is a major factor in juvenile delinquency.', '', 'Kurangnya pengawasan orang tua adalah faktor utama kenakalan remaja.', '', 'Frasa nomina formal, tak terhitung. Pelaku: juvenile delinquent. Mirip: youth crime.', 'Formal uncountable noun phrase. Person: juvenile delinquent. Similar: youth crime.'),
  'rehabilitation': VocabUsage('Prisons should focus on rehabilitation so that inmates can rejoin society.', '', 'Penjara seharusnya berfokus pada rehabilitasi agar narapidana dapat kembali ke masyarakat.', '', 'Kata benda. Kolokasi: rehabilitation programme/centre. Verb: rehabilitate. Kontras: punishment.', 'Noun. Collocations: rehabilitation programme/centre. Verb: rehabilitate. Contrast: punishment.'),
  'imprisonment': VocabUsage('He was sentenced to five years\' imprisonment for fraud.', '', 'Ia dijatuhi hukuman penjara lima tahun atas penipuan.', '', 'Kata benda tak terhitung. Kolokasi: life imprisonment, sentenced to imprisonment. Verb: imprison.', 'Uncountable noun. Collocations: life imprisonment, sentenced to imprisonment. Verb: imprison.'),
  'death penalty': VocabUsage('Opponents argue that the death penalty does not reduce violent crime.', '', 'Para penentang berpendapat bahwa hukuman mati tidak mengurangi kejahatan kekerasan.', '', 'Frasa nomina dengan \'the\'. Kolokasi: abolish/impose the death penalty. Mirip: capital punishment.', 'Noun phrase with \'the\'. Collocations: abolish/impose the death penalty. Similar: capital punishment.'),
  'deterrent': VocabUsage('Heavy fines can act as a deterrent to dangerous driving.', '', 'Denda berat dapat memberi efek jera terhadap cara mengemudi yang berbahaya.', '', 'Kata benda. Pola: act as / serve as a deterrent (to sth). Verb: deter sb from doing sth.', 'Noun. Pattern: act as / serve as a deterrent (to sth). Verb: deter sb from doing sth.'),
  'theft': VocabUsage('Car theft has fallen thanks to better security systems.', '', 'Pencurian mobil menurun berkat sistem keamanan yang lebih baik.', '', 'Kata benda. Kolokasi: car/identity theft. Pelaku: thief; verb: steal. Beda: robbery (dengan kekerasan).', 'Noun. Collocations: car/identity theft. Person: thief; verb: steal. Robbery involves force.'),
  'burglary': VocabUsage('Burglary rates tend to rise during the holiday season.', '', 'Angka pembobolan rumah cenderung naik selama musim liburan.', '', 'Kata benda. Pelaku: burglar; verb: burgle (UK)/burglarize (US). Khusus masuk bangunan.', 'Noun. Person: burglar; verb: burgle (UK)/burglarize (US). Specifically entering a building.'),
  'vandalism': VocabUsage('The council spent thousands repairing bus shelters damaged by vandalism.', '', 'Dewan kota menghabiskan ribuan untuk memperbaiki halte bus yang rusak akibat vandalisme.', '', 'Kata benda tak terhitung. Kolokasi: act of vandalism. Pelaku: vandal; verb: vandalize.', 'Uncountable noun. Collocation: act of vandalism. Person: vandal; verb: vandalize.'),
  'fraud': VocabUsage('Online banking fraud is becoming more sophisticated every year.', '', 'Penipuan perbankan daring makin canggih setiap tahun.', '', 'Kata benda. Kolokasi: commit fraud, tax/credit card fraud. Adj: fraudulent.', 'Noun. Collocations: commit fraud, tax/credit card fraud. Adj: fraudulent.'),
  'smuggling': VocabUsage('Stricter border controls are needed to stop drug smuggling.', '', 'Pengawasan perbatasan yang lebih ketat diperlukan untuk menghentikan penyelundupan narkoba.', '', 'Kata benda tak terhitung. Kolokasi: drug/people smuggling. Verb: smuggle; pelaku: smuggler.', 'Uncountable noun. Collocations: drug/people smuggling. Verb: smuggle; person: smuggler.'),
  'victim': VocabUsage('Victims of crime often need long-term emotional support.', '', 'Korban kejahatan sering membutuhkan dukungan emosional jangka panjang.', '', 'Kata benda. Pola: victim of sth; fall victim to sth.', 'Noun. Pattern: victim of sth; fall victim to sth.'),
  'witness': VocabUsage('The police are asking any witnesses to come forward.', '', 'Polisi meminta para saksi untuk melapor.', '', 'Kata benda/kerja. Kolokasi: eyewitness, witness a crime/an accident.', 'Noun/verb. Collocations: eyewitness, witness a crime/an accident.'),
  'lenient': VocabUsage('Many people feel the sentence was too lenient for such a serious crime.', '', 'Banyak orang merasa hukuman itu terlalu ringan untuk kejahatan seberat itu.', '', 'Kata sifat. Kolokasi: lenient sentence/punishment, be lenient with sb. Lawan: harsh, strict.', 'Adjective. Collocations: lenient sentence/punishment, be lenient with sb. Opposite: harsh, strict.'),
  'harsh': VocabUsage('Critics say harsh sentences do little to prevent crime.', '', 'Para kritikus mengatakan hukuman keras tidak banyak mencegah kejahatan.', '', 'Kata sifat. Kolokasi: harsh punishment/criticism/conditions. Lawan: lenient, mild.', 'Adjective. Collocations: harsh punishment/criticism/conditions. Opposite: lenient, mild.'),
  'trial': VocabUsage('The trial is expected to last several weeks.', '', 'Persidangan itu diperkirakan berlangsung beberapa minggu.', '', 'Kata benda. Kolokasi: on trial, stand trial, fair trial. Juga uji coba (clinical trial).', 'Noun. Collocations: on trial, stand trial, fair trial. Also a test (clinical trial).'),
  'guilty': VocabUsage('The jury found the defendant guilty of fraud.', '', 'Juri menyatakan terdakwa bersalah atas penipuan.', '', 'Kata sifat. Pola: guilty of sth; find sb guilty, plead guilty. Juga \'merasa bersalah\' (feel guilty).', 'Adjective. Pattern: guilty of sth; find sb guilty, plead guilty. Also feel guilty.'),
  'innocent': VocabUsage('Everyone is presumed innocent until proven guilty.', '', 'Setiap orang dianggap tidak bersalah sampai terbukti bersalah.', '', 'Kata sifat. Pola: innocent of a crime. Juga \'polos/tak berdosa\' (innocent people). Nomina: innocence.', 'Adjective. Pattern: innocent of a crime. Also \'harmless\' (innocent people). Noun: innocence.'),
  'corruption': VocabUsage('Corruption undermines public trust in the government.', '', 'Korupsi meruntuhkan kepercayaan publik terhadap pemerintah.', '', 'Kata benda tak terhitung. Kolokasi: fight/tackle corruption, widespread corruption. Adj: corrupt.', 'Uncountable noun. Collocations: fight/tackle corruption, widespread corruption. Adj: corrupt.'),
  'bribery': VocabUsage('The official was arrested on charges of bribery.', '', 'Pejabat itu ditangkap atas tuduhan penyuapan.', '', 'Kata benda tak terhitung. Satu suap: a bribe; verb: bribe sb (to do sth).', 'Uncountable noun. One payment: a bribe; verb: bribe sb (to do sth).'),
  'reoffend': VocabUsage('Prisoners who receive job training are less likely to reoffend.', '', 'Narapidana yang mendapat pelatihan kerja lebih kecil kemungkinannya mengulangi kejahatan.', '', 'Kata kerja intransitif. Kolokasi: likely to reoffend. Nomina: reoffending (rate).', 'Intransitive verb. Collocation: likely to reoffend. Noun: reoffending (rate).'),
  'unemployment': VocabUsage('Youth unemployment remains high in many parts of the country.', '', 'Pengangguran di kalangan anak muda masih tinggi di banyak wilayah negara itu.', '', 'Kata benda tak terhitung. Kolokasi: unemployment rate, youth unemployment. Adj: unemployed.', 'Uncountable noun. Collocations: unemployment rate, youth unemployment. Adj: unemployed.'),
  'career': VocabUsage('Many people change their career several times during their working lives.', '', 'Banyak orang berganti karier beberapa kali sepanjang masa kerjanya.', '', 'Kata benda. Kolokasi: pursue/build a career, career path/prospects. Beda: job = pekerjaan saat ini.', 'Noun. Collocations: pursue/build a career, career path/prospects. Job = your current position.'),
  'workforce': VocabUsage('Women now make up nearly half of the country\'s workforce.', '', 'Perempuan kini mencakup hampir separuh tenaga kerja negara itu.', '', 'Kata benda. Kolokasi: skilled workforce, enter/join the workforce.', 'Noun. Collocations: skilled workforce, enter/join the workforce.'),
  'pension': VocabUsage('An ageing population puts pressure on the state pension system.', '', 'Populasi yang menua membebani sistem pensiun negara.', '', 'Kata benda. Kolokasi: state pension, pension scheme, retire on a pension. Pensiunan: pensioner.', 'Noun. Collocations: state pension, pension scheme, retire on a pension. Person: pensioner.'),
  'job satisfaction': VocabUsage('Job satisfaction is often more important to employees than salary.', '', 'Kepuasan kerja sering lebih penting bagi karyawan daripada gaji.', '', 'Frasa nomina tak terhitung. Kolokasi: high/low job satisfaction, improve job satisfaction.', 'Uncountable noun phrase. Collocations: high/low job satisfaction, improve job satisfaction.'),
  'work-life balance': VocabUsage('Flexible hours help employees achieve a better work-life balance.', '', 'Jam kerja fleksibel membantu karyawan mencapai keseimbangan kerja dan hidup yang lebih baik.', '', 'Frasa nomina. Kolokasi: achieve/maintain a healthy work-life balance.', 'Noun phrase. Collocations: achieve/maintain a healthy work-life balance.'),
  'employer': VocabUsage('Employers are looking for graduates with strong communication skills.', '', 'Para pemberi kerja mencari lulusan dengan kemampuan komunikasi yang kuat.', '', 'Kata benda. Pasangan: employer (pemberi kerja) vs employee (karyawan). Verb: employ.', 'Noun. Pair: employer (hires) vs employee (is hired). Verb: employ.'),
  'self-employed': VocabUsage('Self-employed workers often have no paid holidays or sick leave.', '', 'Pekerja wiraswasta sering tidak mendapat cuti berbayar maupun cuti sakit.', '', 'Kata sifat majemuk. Pola: be self-employed. Nomina: self-employment.', 'Compound adjective. Pattern: be self-employed. Noun: self-employment.'),
  'freelance': VocabUsage('More young people are choosing freelance work instead of permanent jobs.', '', 'Makin banyak anak muda memilih bekerja lepas daripada pekerjaan tetap.', '', 'Kata sifat/kerja/adverb: freelance work, work freelance. Orangnya: freelancer.', 'Adjective/verb/adverb: freelance work, work freelance. Person: freelancer.'),
  'entrepreneur': VocabUsage('Young entrepreneurs need easier access to loans to start businesses.', '', 'Pengusaha muda membutuhkan akses pinjaman yang lebih mudah untuk memulai usaha.', '', 'Kata benda. Adj: entrepreneurial; nomina: entrepreneurship (kewirausahaan).', 'Noun. Adj: entrepreneurial; noun: entrepreneurship.'),
  'cost of living': VocabUsage('The rising cost of living is forcing families to cut back on spending.', '', 'Biaya hidup yang terus naik memaksa keluarga mengurangi pengeluaran.', '', 'Frasa nomina dengan \'the\'. Kolokasi: the rising/high cost of living, cost-of-living crisis.', 'Noun phrase with \'the\'. Collocations: the rising/high cost of living, cost-of-living crisis.'),
  'living standards': VocabUsage('Economic growth has raised living standards for millions of people.', '', 'Pertumbuhan ekonomi telah menaikkan taraf hidup jutaan orang.', '', 'Frasa nomina jamak. Kolokasi: raise/improve living standards. Mirip: standard of living.', 'Plural noun phrase. Collocations: raise/improve living standards. Similar: standard of living.'),
  'wealth': VocabUsage('The gap in wealth between rich and poor continues to grow.', '', 'Kesenjangan kekayaan antara si kaya dan si miskin terus melebar.', '', 'Kata benda tak terhitung. Kolokasi: distribution of wealth, create wealth. Adj: wealthy.', 'Uncountable noun. Collocations: distribution of wealth, create wealth. Adj: wealthy.'),
  'affluent': VocabUsage('Affluent neighbourhoods usually have better schools and services.', '', 'Lingkungan yang makmur biasanya memiliki sekolah dan layanan yang lebih baik.', '', 'Kata sifat formal. Kolokasi: affluent areas/families/societies. Nomina: affluence. Mirip: wealthy.', 'Formal adjective. Collocations: affluent areas/families/societies. Noun: affluence. Similar: wealthy.'),
  'prosperity': VocabUsage('Free trade has brought prosperity to many coastal regions.', '', 'Perdagangan bebas telah membawa kemakmuran bagi banyak wilayah pesisir.', '', 'Kata benda tak terhitung. Kolokasi: economic prosperity, bring prosperity. Adj: prosperous.', 'Uncountable noun. Collocations: economic prosperity, bring prosperity. Adj: prosperous.'),
  'recession': VocabUsage('Thousands of businesses closed during the recession.', '', 'Ribuan usaha tutup selama masa resesi.', '', 'Kata benda. Kolokasi: go into/enter a recession, economic recession. Lebih parah: depression.', 'Noun. Collocations: go into/enter a recession, economic recession. Worse: depression.'),
  'taxpayer': VocabUsage('Public projects funded by taxpayers should be managed transparently.', '', 'Proyek publik yang didanai wajib pajak harus dikelola secara transparan.', '', 'Kata benda. Kolokasi: taxpayers\' money, at the taxpayer\'s expense.', 'Noun. Collocations: taxpayers\' money, at the taxpayer\'s expense.'),
  'brain drain': VocabUsage('Low salaries have caused a brain drain of doctors to richer countries.', '', 'Gaji rendah telah menyebabkan eksodus tenaga ahli, yaitu dokter, ke negara yang lebih kaya.', '', 'Frasa nomina. Pola: a brain drain from A to B. Lawan: brain gain.', 'Noun phrase. Pattern: a brain drain from A to B. Opposite: brain gain.'),
  'blue-collar': VocabUsage('Automation threatens many blue-collar jobs in manufacturing.', '', 'Otomatisasi mengancam banyak pekerjaan kasar di sektor manufaktur.', '', 'Kata sifat majemuk. Kolokasi: blue-collar workers/jobs. Lawan: white-collar.', 'Compound adjective. Collocations: blue-collar workers/jobs. Opposite: white-collar.'),
  'white-collar': VocabUsage('White-collar workers were more likely to work from home during the pandemic.', '', 'Pekerja kantoran lebih mungkin bekerja dari rumah selama pandemi.', '', 'Kata sifat majemuk. Kolokasi: white-collar jobs/workers/crime. Lawan: blue-collar.', 'Compound adjective. Collocations: white-collar jobs/workers/crime. Opposite: blue-collar.'),
  'workaholic': VocabUsage('Being a workaholic can damage both your health and your relationships.', '', 'Menjadi gila kerja dapat merusak kesehatan dan hubunganmu.', '', 'Kata benda (work + -aholic, dari alcoholic). Biasanya bernada negatif.', 'Noun (work + -aholic, from alcoholic). Usually negative.'),
  'materialism': VocabUsage('Some argue that advertising encourages materialism among young people.', '', 'Sebagian orang berpendapat bahwa iklan mendorong materialisme di kalangan anak muda.', '', 'Kata benda tak terhitung. Adj: materialistic. Lawan nilai: spirituality, minimalism.', 'Uncountable noun. Adj: materialistic. Contrasting values: spirituality, minimalism.'),
  'redundancy': VocabUsage('The factory announced two hundred redundancies after sales fell.', '', 'Pabrik itu mengumumkan dua ratus pemutusan hubungan kerja setelah penjualan merosot.', '', 'Kata benda (UK). Kolokasi: make sb redundant, redundancy pay. Mirip (US): layoff.', 'Noun (UK). Collocations: make sb redundant, redundancy pay. Similar (US): layoff.'),
  'urban': VocabUsage('Urban areas offer more job opportunities but higher living costs.', '', 'Daerah perkotaan menawarkan lebih banyak peluang kerja tetapi biaya hidup lebih tinggi.', '', 'Kata sifat (sebelum nomina). Kolokasi: urban areas/planning/sprawl. Lawan: rural.', 'Adjective (before a noun). Collocations: urban areas/planning/sprawl. Opposite: rural.'),
  'rural': VocabUsage('Many young people leave rural areas to find work in cities.', '', 'Banyak anak muda meninggalkan daerah pedesaan untuk mencari kerja di kota.', '', 'Kata sifat (sebelum nomina). Kolokasi: rural areas/communities/life. Lawan: urban.', 'Adjective (before a noun). Collocations: rural areas/communities/life. Opposite: urban.'),
  'population': VocabUsage('The world\'s population is expected to reach ten billion by 2060.', '', 'Populasi dunia diperkirakan mencapai sepuluh miliar pada tahun 2060.', '', 'Kata benda. Kolokasi: growing/ageing population, population growth/density.', 'Noun. Collocations: growing/ageing population, population growth/density.'),
  'urbanization': VocabUsage('Rapid urbanization has led to traffic congestion and housing shortages.', '', 'Urbanisasi yang pesat telah menyebabkan kemacetan dan kekurangan perumahan.', '', 'Kata benda tak terhitung. Kolokasi: rapid urbanization. Ejaan UK: urbanisation.', 'Uncountable noun. Collocation: rapid urbanization. UK spelling: urbanisation.'),
  'skyscraper': VocabUsage('The city skyline is dominated by modern skyscrapers.', '', 'Cakrawala kota itu didominasi oleh gedung pencakar langit modern.', '', 'Kata benda terhitung. Kolokasi: build a skyscraper, glass skyscrapers. Mirip: high-rise.', 'Countable noun. Collocations: build a skyscraper, glass skyscrapers. Similar: high-rise.'),
  'high-rise': VocabUsage('Many families in big cities now live in high-rise apartment blocks.', '', 'Banyak keluarga di kota besar kini tinggal di blok apartemen bertingkat tinggi.', '', 'Adjektiva/nomina. Kolokasi: high-rise building/apartment/block. Lawan: low-rise.', 'Adjective/noun. Collocations: high-rise building/apartment/block. Opposite: low-rise.'),
  'suburb': VocabUsage('Many young couples move to the suburbs to find bigger and cheaper homes.', '', 'Banyak pasangan muda pindah ke pinggiran kota untuk mencari rumah yang lebih besar dan murah.', '', 'Nomina. Pola: live in the suburbs (sering jamak). Adjektiva: suburban.', 'Noun. Pattern: live in the suburbs (often plural). Adjective: suburban.'),
  'outskirts': VocabUsage('The new factory was built on the outskirts of the city.', '', 'Pabrik baru itu dibangun di daerah pinggiran kota.', '', 'Nomina jamak. Pola tetap: on the outskirts of + kota. Lebih menekankan \'tepi\' dibanding suburb.', 'Plural noun. Fixed pattern: on the outskirts of + town. Stresses the edge more than suburb.'),
  'slum': VocabUsage('Millions of people in developing countries still live in overcrowded slums.', '', 'Jutaan orang di negara berkembang masih tinggal di permukiman kumuh yang padat.', '', 'Nomina terhitung. Kolokasi: urban slums, slum area, live in a slum.', 'Countable noun. Collocations: urban slums, slum area, live in a slum.'),
  'homelessness': VocabUsage('Rising rents are one of the main causes of homelessness in big cities.', '', 'Kenaikan harga sewa adalah salah satu penyebab utama tunawisma di kota besar.', '', 'Nomina tak terhitung (fenomena). Orangnya: the homeless / homeless people. Kolokasi: tackle homelessness.', 'Uncountable noun (the issue). People: the homeless. Collocation: tackle homelessness.'),
  'affordable housing': VocabUsage('The government should invest more in affordable housing for low-income families.', '', 'Pemerintah seharusnya berinvestasi lebih banyak pada rumah terjangkau bagi keluarga berpenghasilan rendah.', '', 'Frasa nomina tak terhitung. Kolokasi: provide/build affordable housing; shortage of affordable housing.', 'Uncountable noun phrase. Collocations: provide/build affordable housing; a shortage of affordable housing.'),
  'overcrowding': VocabUsage('Overcrowding on public transport makes the daily commute stressful.', '', 'Kepadatan berlebih di transportasi umum membuat perjalanan harian ke kantor penuh stres.', '', 'Nomina tak terhitung. Adjektiva: overcrowded (an overcrowded city). Pola: overcrowding in/on + tempat.', 'Uncountable noun. Adjective: overcrowded. Pattern: overcrowding in/on + place.'),
  'urban sprawl': VocabUsage('Urban sprawl has destroyed much of the farmland around the capital.', '', 'Perluasan kota yang tak terkendali telah merusak banyak lahan pertanian di sekitar ibu kota.', '', 'Frasa nomina tak terhitung. Kolokasi: control/limit urban sprawl. Bernuansa negatif.', 'Uncountable noun phrase. Collocations: control/limit urban sprawl. Negative tone.'),
  'green space': VocabUsage('Access to green space can improve the mental health of city residents.', '', 'Akses ke ruang terbuka hijau dapat meningkatkan kesehatan mental warga kota.', '', 'Nomina (bisa tak terhitung/jamak: green spaces). Kolokasi: access to green space, create green spaces.', 'Noun (uncountable or plural green spaces). Collocations: access to green space, create green spaces.'),
  'amenities': VocabUsage('The new housing estate lacks basic amenities such as shops and clinics.', '', 'Kompleks perumahan baru itu tidak memiliki fasilitas umum dasar seperti toko dan klinik.', '', 'Nomina jamak. Kolokasi: basic/local amenities, lack amenities. Contohnya toko, taman, klinik.', 'Plural noun. Collocations: basic/local amenities, lack amenities. E.g. shops, parks, clinics.'),
  'neighbourhood': VocabUsage('I grew up in a quiet neighbourhood where everyone knew each other.', '', 'Saya tumbuh di lingkungan tempat tinggal yang tenang di mana semua orang saling kenal.', '', 'Nomina. Ejaan Inggris-UK; AS: neighborhood. Kolokasi: a safe/quiet neighbourhood, in the neighbourhood.', 'Noun. British spelling; US: neighborhood. Collocations: a safe/quiet neighbourhood, in the neighbourhood.'),
  'landlord': VocabUsage('Our landlord agreed to repair the broken heater before winter.', '', 'Pemilik kontrakan kami setuju memperbaiki pemanas yang rusak sebelum musim dingin.', '', 'Nomina. Lawan: tenant (penyewa). Untuk perempuan kadang landlady.', 'Noun. Opposite: tenant. A woman may be called landlady.'),
  'rent': VocabUsage('The rent for a one-bedroom flat in the city centre has doubled.', '', 'Sewa untuk flat satu kamar di pusat kota telah naik dua kali lipat.', '', 'Nomina/verba. Kolokasi: pay the rent, rent rises; verba: rent a flat (menyewa).', 'Noun/verb. Collocations: pay the rent, rent rises; verb: rent a flat.'),
  'noise pollution': VocabUsage('Residents near the airport often complain about noise pollution at night.', '', 'Warga di dekat bandara sering mengeluhkan polusi suara pada malam hari.', '', 'Frasa nomina tak terhitung. Kolokasi: reduce noise pollution; sumber: traffic, aircraft, construction.', 'Uncountable noun phrase. Collocation: reduce noise pollution; sources: traffic, aircraft, construction.'),
  'countryside': VocabUsage('Many retired people prefer the peace and fresh air of the countryside.', '', 'Banyak pensiunan lebih menyukai ketenangan dan udara segar daerah pedesaan.', '', 'Nomina tak terhitung, biasanya dengan the: in the countryside. Beda: village = satu desa.', 'Uncountable noun, usually with the: in the countryside. Village = a single settlement.'),
  'congestion': VocabUsage('Building more roads does not always reduce traffic congestion in the long term.', '', 'Membangun lebih banyak jalan tidak selalu mengurangi kemacetan lalu lintas dalam jangka panjang.', '', 'Nomina tak terhitung. Kolokasi: traffic congestion, ease/reduce congestion. Adjektiva: congested.', 'Uncountable noun. Collocations: traffic congestion, ease/reduce congestion. Adjective: congested.'),
  'commute': VocabUsage('Many employees commute more than an hour each way to get to work.', '', 'Banyak karyawan menempuh perjalanan pulang-pergi kerja lebih dari satu jam sekali jalan.', '', 'Verba/nomina. Pola: commute to work/from + tempat; a long daily commute. Pelakunya: commuter.', 'Verb/noun. Pattern: commute to work/from + place; a long daily commute. Person: commuter.'),
  'pedestrian': VocabUsage('The city centre was closed to cars to make it safer for pedestrians.', '', 'Pusat kota ditutup untuk mobil agar lebih aman bagi pejalan kaki.', '', 'Nomina/adjektiva. Kolokasi: pedestrian crossing, pedestrian zone, pedestrian safety.', 'Noun/adjective. Collocations: pedestrian crossing, pedestrian zone, pedestrian safety.'),
  'rush hour': VocabUsage('Trains are extremely crowded during the morning rush hour.', '', 'Kereta sangat penuh selama jam sibuk pagi hari.', '', 'Frasa nomina. Pola: during/in (the) rush hour; morning/evening rush hour; rush-hour traffic.', 'Noun phrase. Pattern: during/in (the) rush hour; morning/evening rush hour; rush-hour traffic.'),
  'carpool': VocabUsage('Colleagues who live nearby can carpool to cut fuel costs and emissions.', '', 'Rekan kerja yang tinggal berdekatan bisa nebeng bersama untuk menghemat bensin dan emisi.', '', 'Verba/nomina. Pola: carpool to work; join a carpool. Istilah UK: car-sharing.', 'Verb/noun. Pattern: carpool to work; join a carpool. UK term: car-sharing.'),
  'toll road': VocabUsage('Drivers can save time by taking the toll road to the airport.', '', 'Pengemudi bisa menghemat waktu dengan lewat jalan tol ke bandara.', '', 'Frasa nomina. Kolokasi: take/use the toll road; pay a toll (bayar tarif tol).', 'Noun phrase. Collocations: take/use the toll road; pay a toll.'),
  'bike lane': VocabUsage('Adding more bike lanes would encourage people to cycle to work.', '', 'Menambah jalur sepeda akan mendorong orang untuk bersepeda ke kantor.', '', 'Frasa nomina. Sinonim UK: cycle lane. Kolokasi: build/add bike lanes, ride in the bike lane.', 'Noun phrase. UK synonym: cycle lane. Collocations: build/add bike lanes, ride in the bike lane.'),
  'speed limit': VocabUsage('Lowering the speed limit near schools has reduced the number of accidents.', '', 'Menurunkan batas kecepatan di dekat sekolah telah mengurangi jumlah kecelakaan.', '', 'Frasa nomina. Kolokasi: exceed/break the speed limit, lower/raise the speed limit.', 'Noun phrase. Collocations: exceed/break the speed limit, lower/raise the speed limit.'),
  'subway': VocabUsage('The subway is the fastest way to travel across the city during peak hours.', '', 'Kereta bawah tanah adalah cara tercepat untuk melintasi kota pada jam sibuk.', '', 'Nomina (Inggris-AS). UK: the underground/the tube; juga metro. Pola: take the subway, by subway.', 'Noun (American). UK: the underground/the tube; also metro. Pattern: take the subway, by subway.'),
  'high-speed rail': VocabUsage('High-speed rail could replace many short domestic flights in the future.', '', 'Kereta cepat dapat menggantikan banyak penerbangan domestik jarak pendek di masa depan.', '', 'Frasa nomina tak terhitung. Kolokasi: high-speed rail network/line; invest in high-speed rail.', 'Uncountable noun phrase. Collocations: high-speed rail network/line; invest in high-speed rail.'),
  'fare': VocabUsage('Bus fares have risen sharply, so fewer people are using public transport.', '', 'Ongkos bus naik tajam, sehingga makin sedikit orang memakai transportasi umum.', '', 'Nomina untuk tarif perjalanan (bus, taksi, pesawat). Beda: fee = biaya layanan; fair = adil.', 'Noun for travel prices (bus, taxi, flight). Compare: fee = service charge; fair = just.'),
  'electric car': VocabUsage('Governments offer tax incentives to encourage people to buy electric cars.', '', 'Pemerintah menawarkan insentif pajak untuk mendorong orang membeli mobil listrik.', '', 'Frasa nomina. Sinonim: electric vehicle (EV). Kolokasi: charge an electric car, switch to electric cars.', 'Noun phrase. Synonym: electric vehicle (EV). Collocations: charge an electric car, switch to electric cars.'),
  'drunk driving': VocabUsage('Stricter penalties are needed to stop drunk driving on our roads.', '', 'Hukuman yang lebih berat diperlukan untuk menghentikan mengemudi dalam keadaan mabuk di jalan kita.', '', 'Frasa nomina tak terhitung. Sinonim UK: drink-driving. Kolokasi: penalties for drunk driving.', 'Uncountable noun phrase. UK synonym: drink-driving. Collocation: penalties for drunk driving.'),
  'motorist': VocabUsage('Motorists are being urged to avoid the city centre this weekend.', '', 'Para pengendara mobil diimbau untuk menghindari pusat kota akhir pekan ini.', '', 'Nomina, gaya berita/formal. Lebih formal daripada driver; khusus pengemudi mobil pribadi.', 'Noun, news/formal style. More formal than driver; refers to car drivers.'),
  'road safety': VocabUsage('Schools should teach children about road safety from an early age.', '', 'Sekolah seharusnya mengajarkan anak-anak tentang keselamatan jalan sejak usia dini.', '', 'Frasa nomina tak terhitung. Kolokasi: improve road safety, road safety campaign.', 'Uncountable noun phrase. Collocations: improve road safety, road safety campaign.'),
  'tourism': VocabUsage('Tourism brings jobs to the region, but it can also damage the environment.', '', 'Pariwisata membawa lapangan kerja ke daerah itu, tetapi juga dapat merusak lingkungan.', '', 'Nomina tak terhitung. Kolokasi: boost tourism, the tourism industry. Orangnya: tourist.', 'Uncountable noun. Collocations: boost tourism, the tourism industry. Person: tourist.'),
  'leisure': VocabUsage('People today have less leisure time than their parents did.', '', 'Orang zaman sekarang memiliki lebih sedikit waktu luang dibanding orang tua mereka.', '', 'Nomina tak terhitung. Kolokasi: leisure time/activities, at your leisure (kapan pun sempat).', 'Uncountable noun. Collocations: leisure time/activities, at your leisure (whenever convenient).'),
  'landmark': VocabUsage('The Eiffel Tower is the most famous landmark in Paris.', '', 'Menara Eiffel adalah bangunan ikonik paling terkenal di Paris.', '', 'Nomina. Kolokasi: a famous/historic landmark. Juga kiasan: a landmark decision (keputusan bersejarah).', 'Noun. Collocations: a famous/historic landmark. Also figurative: a landmark decision.'),
  'sightseeing': VocabUsage('We spent the whole afternoon sightseeing in the old part of town.', '', 'Kami menghabiskan sepanjang sore jalan-jalan melihat tempat wisata di kota tua.', '', 'Nomina tak terhitung. Pola: go sightseeing, spend time sightseeing; sightseeing tour.', 'Uncountable noun. Pattern: go sightseeing, spend time sightseeing; sightseeing tour.'),
  'souvenir': VocabUsage('She bought a small wooden statue as a souvenir of her trip to Bali.', '', 'Dia membeli patung kayu kecil sebagai oleh-oleh dari perjalanannya ke Bali.', '', 'Nomina. Pola: a souvenir of/from + tempat; souvenir shop. Biasanya untuk diri sendiri sebagai kenangan.', 'Noun. Pattern: a souvenir of/from + place; souvenir shop. Usually kept as a reminder.'),
  'destination': VocabUsage('Japan has become a popular destination for young travellers.', '', 'Jepang telah menjadi tujuan wisata populer bagi pelancong muda.', '', 'Nomina. Kolokasi: a popular/holiday/tourist destination; reach your destination.', 'Noun. Collocations: a popular/holiday/tourist destination; reach your destination.'),
  'backpacker': VocabUsage('Cheap hostels in the old town are full of backpackers in summer.', '', 'Hostel murah di kota tua penuh dengan pelancong ransel saat musim panas.', '', 'Nomina. Verba: go backpacking. Identik dengan perjalanan hemat dan menginap di hostel.', 'Noun. Verb: go backpacking. Linked to budget travel and hostels.'),
  'package holiday': VocabUsage('A package holiday includes flights, hotel and meals for one fixed price.', '', 'Paket liburan mencakup tiket pesawat, hotel, dan makan dengan satu harga tetap.', '', 'Frasa nomina (UK). AS: package tour. Kolokasi: book/go on a package holiday.', 'Noun phrase (UK). US: package tour. Collocations: book/go on a package holiday.'),
  'mass tourism': VocabUsage('Mass tourism has put enormous pressure on popular beaches and old cities.', '', 'Pariwisata massal telah memberi tekanan besar pada pantai populer dan kota tua.', '', 'Frasa nomina tak terhitung, sering bernuansa negatif. Kontras: ecotourism, sustainable tourism.', 'Uncountable noun phrase, often negative. Contrast: ecotourism, sustainable tourism.'),
  'ecotourism': VocabUsage('Ecotourism can help protect rainforests by giving local people an income.', '', 'Ekowisata dapat membantu melindungi hutan hujan dengan memberi penghasilan bagi warga lokal.', '', 'Nomina tak terhitung. Kolokasi: promote ecotourism. Bentuk lain: eco-friendly, eco-tourist.', 'Uncountable noun. Collocation: promote ecotourism. Related: eco-friendly, eco-tourist.'),
  'tourist trap': VocabUsage('The restaurant near the castle was a tourist trap with terrible food.', '', 'Restoran dekat kastel itu adalah tempat wisata mahal dengan makanan yang buruk.', '', 'Frasa nomina informal, bernuansa negatif: mahal, ramai, kualitas rendah.', 'Informal noun phrase, negative: overpriced, crowded, poor quality.'),
  'off the beaten track': VocabUsage('We stayed in a small village off the beaten track, far from the crowds.', '', 'Kami menginap di desa kecil yang jauh dari keramaian wisata.', '', 'Idiom (adjektiva/adverbia). AS juga: off the beaten path. Pola: go/travel off the beaten track.', 'Idiom (adj/adv). US also: off the beaten path. Pattern: go/travel off the beaten track.'),
  'jet lag': VocabUsage('It took me three days to recover from jet lag after flying to New York.', '', 'Saya butuh tiga hari untuk pulih dari mabuk perbedaan waktu setelah terbang ke New York.', '', 'Nomina tak terhitung. Kolokasi: suffer from/get over jet lag. Adjektiva: jet-lagged.', 'Uncountable noun. Collocations: suffer from/get over jet lag. Adjective: jet-lagged.'),
  'hospitality': VocabUsage('We were impressed by the warm hospitality of the local people.', '', 'Kami terkesan dengan keramahan warga setempat.', '', 'Nomina tak terhitung. Kolokasi: warm hospitality; the hospitality industry (perhotelan). Adj: hospitable.', 'Uncountable noun. Collocations: warm hospitality; the hospitality industry. Adj: hospitable.'),
  'resort': VocabUsage('The beach resort offers swimming pools, spas and several restaurants.', '', 'Tempat peristirahatan di pantai itu menawarkan kolam renang, spa, dan beberapa restoran.', '', 'Nomina. Kolokasi: beach/ski/holiday resort. Idiom beda arti: as a last resort (pilihan terakhir).', 'Noun. Collocations: beach/ski/holiday resort. Different idiom: as a last resort.'),
  'excursion': VocabUsage('The tour includes a day excursion to the ancient temples.', '', 'Tur itu mencakup tamasya sehari ke kuil-kuil kuno.', '', 'Nomina, agak formal. Pola: an excursion to + tempat; go on an excursion. Mirip: day trip.', 'Noun, fairly formal. Pattern: an excursion to + place; go on an excursion. Similar: day trip.'),
  'cruise': VocabUsage('My grandparents went on a two-week cruise around the Mediterranean.', '', 'Kakek-nenek saya mengikuti pelayaran wisata dua minggu mengelilingi Laut Tengah.', '', 'Nomina/verba. Pola: go on a cruise; cruise ship. Verba: cruise around/along.', 'Noun/verb. Pattern: go on a cruise; cruise ship. Verb: cruise around/along.'),
  'breathtaking': VocabUsage('From the top of the mountain, the view was absolutely breathtaking.', '', 'Dari puncak gunung, pemandangannya benar-benar menakjubkan.', '', 'Adjektiva ekstrem: pakai absolutely, bukan very. Kolokasi: breathtaking view/scenery.', 'Extreme adjective: use absolutely, not very. Collocations: breathtaking view/scenery.'),
  'exotic': VocabUsage('The market sells exotic fruits that most visitors have never tasted.', '', 'Pasar itu menjual buah-buahan eksotis yang belum pernah dicicipi kebanyakan pengunjung.', '', 'Adjektiva. Kolokasi: exotic fruit/animals/destination. Bernuansa menarik karena asing.', 'Adjective. Collocations: exotic fruit/animals/destination. Suggests appealing foreignness.'),
  'poverty': VocabUsage('Education is one of the most effective ways to escape poverty.', '', 'Pendidikan adalah salah satu cara paling efektif untuk keluar dari kemiskinan.', '', 'Nomina tak terhitung. Kolokasi: live in poverty, reduce/eradicate poverty, the poverty line.', 'Uncountable noun. Collocations: live in poverty, reduce/eradicate poverty, the poverty line.'),
  'inequality': VocabUsage('The gap between rich and poor has led to growing inequality in society.', '', 'Jurang antara kaya dan miskin telah menyebabkan ketimpangan yang makin besar di masyarakat.', '', 'Nomina. Kolokasi: income/gender inequality, reduce inequality. Adjektiva: unequal.', 'Noun. Collocations: income/gender inequality, reduce inequality. Adjective: unequal.'),
  'charity': VocabUsage('She donates part of her salary to a children\'s charity every month.', '', 'Dia menyumbangkan sebagian gajinya ke badan amal anak setiap bulan.', '', 'Nomina. Pola: give/donate to charity (tak terhitung); a charity (lembaga). Adj: charitable.', 'Noun. Pattern: give/donate to charity (uncountable); a charity (organisation). Adj: charitable.'),
  'responsibility': VocabUsage('Parents have a responsibility to teach their children good values.', '', 'Orang tua punya tanggung jawab untuk mengajarkan nilai-nilai baik kepada anak.', '', 'Nomina. Pola: have a responsibility to + V / for + N; take responsibility for. Adj: responsible.', 'Noun. Pattern: have a responsibility to + V / for + N; take responsibility for. Adj: responsible.'),
  'independence': VocabUsage('Living away from home helps students develop independence.', '', 'Tinggal jauh dari rumah membantu mahasiswa mengembangkan kemandirian.', '', 'Nomina tak terhitung. Pola: independence from + N; gain independence. Adj: independent (of).', 'Uncountable noun. Pattern: independence from + N; gain independence. Adj: independent (of).'),
  'stereotype': VocabUsage('Advertising often reinforces gender stereotypes about men and women.', '', 'Iklan sering memperkuat stereotip gender tentang laki-laki dan perempuan.', '', 'Nomina/verba. Kolokasi: reinforce/challenge a stereotype; gender stereotypes. Adj: stereotypical.', 'Noun/verb. Collocations: reinforce/challenge a stereotype; gender stereotypes. Adj: stereotypical.'),
  'upbringing': VocabUsage('A strict upbringing can make children more disciplined but less creative.', '', 'Pola asuh yang ketat dapat membuat anak lebih disiplin tetapi kurang kreatif.', '', 'Nomina tunggal. Kolokasi: a strict/happy upbringing. Verba terkait: bring up a child.', 'Singular noun. Collocations: a strict/happy upbringing. Related verb: bring up a child.'),
  'nuclear family': VocabUsage('The nuclear family has become the most common household type in cities.', '', 'Keluarga inti telah menjadi tipe rumah tangga paling umum di perkotaan.', '', 'Frasa nomina. Lawan: extended family. Sering dipakai dalam esai tentang perubahan keluarga.', 'Noun phrase. Opposite: extended family. Common in essays on changing families.'),
  'extended family': VocabUsage('In many Asian cultures, the extended family often lives under one roof.', '', 'Di banyak budaya Asia, keluarga besar sering tinggal di bawah satu atap.', '', 'Frasa nomina. Mencakup kakek-nenek, paman, bibi, sepupu. Lawan: nuclear family.', 'Noun phrase. Includes grandparents, uncles, aunts, cousins. Opposite: nuclear family.'),
  'sibling': VocabUsage('Children with siblings often learn to share and cooperate earlier.', '', 'Anak yang punya saudara kandung sering belajar berbagi dan bekerja sama lebih awal.', '', 'Nomina formal/netral gender untuk brother/sister. Kolokasi: older/younger sibling, sibling rivalry.', 'Formal, gender-neutral noun for brother/sister. Collocations: older/younger sibling, sibling rivalry.'),
  'single parent': VocabUsage('Single parents often struggle to balance work and childcare.', '', 'Orang tua tunggal sering kesulitan menyeimbangkan pekerjaan dan pengasuhan anak.', '', 'Frasa nomina. Kolokasi: single-parent family/household (pakai tanda hubung sebagai adjektiva).', 'Noun phrase. Collocation: single-parent family/household (hyphenated as adjective).'),
  'breadwinner': VocabUsage('In the past, the father was usually the only breadwinner in the family.', '', 'Dulu, ayah biasanya menjadi satu-satunya pencari nafkah dalam keluarga.', '', 'Nomina. Kolokasi: the main/sole breadwinner. Sering dipakai saat membahas peran gender.', 'Noun. Collocations: the main/sole breadwinner. Common in discussions of gender roles.'),
  'household chores': VocabUsage('Both partners should share household chores such as cooking and cleaning.', '', 'Kedua pasangan sebaiknya berbagi pekerjaan rumah tangga seperti memasak dan bersih-bersih.', '', 'Frasa nomina jamak. Kolokasi: do/share household chores. Sinonim: housework (tak terhitung).', 'Plural noun phrase. Collocations: do/share household chores. Synonym: housework (uncountable).'),
  'the elderly': VocabUsage('The government must provide better healthcare for the elderly.', '', 'Pemerintah harus menyediakan layanan kesehatan yang lebih baik bagi lansia.', '', 'Nomina kolektif (the + adj), kata kerja jamak. Lebih sopan dari the old; alternatif: older people.', 'Collective noun (the + adj), plural verb. Politer than the old; alternative: older people.'),
  'nursing home': VocabUsage('Some families feel guilty about sending their parents to a nursing home.', '', 'Sebagian keluarga merasa bersalah menitipkan orang tua mereka ke panti jompo.', '', 'Frasa nomina. Sinonim: care home (UK). Pola: live in / move into a nursing home.', 'Noun phrase. Synonym: care home (UK). Pattern: live in / move into a nursing home.'),
  'role model': VocabUsage('Famous athletes should behave well because they are role models for young people.', '', 'Atlet terkenal harus berperilaku baik karena mereka adalah panutan bagi anak muda.', '', 'Frasa nomina. Pola: a role model for + orang; a positive role model.', 'Noun phrase. Pattern: a role model for + people; a positive role model.'),
  'childcare': VocabUsage('The high cost of childcare prevents many mothers from returning to work.', '', 'Mahalnya biaya pengasuhan anak menghalangi banyak ibu untuk kembali bekerja.', '', 'Nomina tak terhitung. Kolokasi: childcare costs/facilities, affordable childcare.', 'Uncountable noun. Collocations: childcare costs/facilities, affordable childcare.'),
  'adolescence': VocabUsage('Adolescence is a period of rapid physical and emotional change.', '', 'Masa remaja adalah periode perubahan fisik dan emosional yang cepat.', '', 'Nomina tak terhitung (formal). Pola: during adolescence. Orangnya: adolescent; informal: teenager.', 'Uncountable noun (formal). Pattern: during adolescence. Person: adolescent; informal: teenager.'),
  'parenting': VocabUsage('Good parenting involves setting clear rules and showing love.', '', 'Cara mendidik anak yang baik melibatkan aturan yang jelas dan kasih sayang.', '', 'Nomina tak terhitung. Kolokasi: parenting skills/style, good/bad parenting.', 'Uncountable noun. Collocations: parenting skills/style, good/bad parenting.'),
  'spoilt': VocabUsage('Children who always get what they want may become spoilt.', '', 'Anak yang selalu mendapatkan apa yang diinginkan bisa menjadi manja.', '', 'Adjektiva (UK; AS: spoiled). Pola: a spoilt child; become spoilt. Verba: spoil a child.', 'Adjective (UK; US: spoiled). Pattern: a spoilt child; become spoilt. Verb: spoil a child.'),
  'obedient': VocabUsage('Traditional schools expected pupils to be quiet and obedient.', '', 'Sekolah tradisional mengharapkan murid untuk tenang dan patuh.', '', 'Adjektiva. Pola: obedient to + orang. Nomina: obedience; verba: obey. Lawan: disobedient.', 'Adjective. Pattern: obedient to + person. Noun: obedience; verb: obey. Opposite: disobedient.'),
  'divorce': VocabUsage('The divorce rate has risen steadily over the past fifty years.', '', 'Tingkat perceraian terus naik selama lima puluh tahun terakhir.', '', 'Nomina/verba. Kolokasi: divorce rate, get a divorce, get divorced. Verba transitif: divorce someone.', 'Noun/verb. Collocations: divorce rate, get a divorce, get divorced. Transitive: divorce someone.'),
  'heritage': VocabUsage('Old buildings are an important part of a nation\'s cultural heritage.', '', 'Bangunan tua adalah bagian penting dari warisan budaya suatu bangsa.', '', 'Nomina tak terhitung. Kolokasi: cultural/national heritage, heritage site, preserve heritage.', 'Uncountable noun. Collocations: cultural/national heritage, heritage site, preserve heritage.'),
  'art gallery': VocabUsage('Entry to the national art gallery should be free for all citizens.', '', 'Masuk ke galeri seni nasional seharusnya gratis bagi semua warga.', '', 'Frasa nomina. Beda: museum (benda sejarah/ilmu) vs art gallery (karya seni).', 'Noun phrase. Compare: museum (history/science objects) vs art gallery (artworks).'),
  'masterpiece': VocabUsage('The Mona Lisa is considered a masterpiece of Renaissance art.', '', 'Mona Lisa dianggap sebagai mahakarya seni Renaisans.', '', 'Nomina. Pola: a masterpiece of + bidang; considered a masterpiece.', 'Noun. Pattern: a masterpiece of + field; considered a masterpiece.'),
  'sculpture': VocabUsage('A huge bronze sculpture stands in the middle of the square.', '', 'Sebuah patung perunggu besar berdiri di tengah alun-alun.', '', 'Nomina (terhitung: karya; tak terhitung: seni pahat). Pembuatnya: sculptor.', 'Noun (countable: a work; uncountable: the art). Maker: sculptor.'),
  'handicraft': VocabUsage('Tourists can buy local handicrafts directly from village artisans.', '', 'Wisatawan dapat membeli kerajinan tangan lokal langsung dari perajin desa.', '', 'Nomina, sering jamak. Kolokasi: traditional/local handicrafts. Sinonim: crafts.', 'Noun, often plural. Collocations: traditional/local handicrafts. Synonym: crafts.'),
  'folk music': VocabUsage('Young people are losing interest in the folk music of their region.', '', 'Anak muda mulai kehilangan minat pada musik rakyat daerah mereka.', '', 'Frasa nomina tak terhitung. Kolokasi: traditional folk music; folk song, folk dance.', 'Uncountable noun phrase. Collocations: traditional folk music; folk song, folk dance.'),
  'festival': VocabUsage('The town holds a colourful festival every year to celebrate the harvest.', '', 'Kota itu mengadakan festival meriah setiap tahun untuk merayakan panen.', '', 'Nomina. Kolokasi: hold/celebrate a festival; music/film festival.', 'Noun. Collocations: hold/celebrate a festival; music/film festival.'),
  'costume': VocabUsage('Dancers wore traditional costumes during the opening ceremony.', '', 'Para penari mengenakan pakaian adat selama upacara pembukaan.', '', 'Nomina. Kolokasi: traditional/national costume. Beda: custom (adat) vs costume (pakaian).', 'Noun. Collocations: traditional/national costume. Don\'t confuse with custom (tradition).'),
  'custom': VocabUsage('It is a local custom to remove your shoes before entering a home.', '', 'Melepas sepatu sebelum masuk rumah adalah adat istiadat setempat.', '', 'Nomina. Pola: it is a custom to + V; local customs. Beda: customs (bea cukai) dan costume.', 'Noun. Pattern: it is a custom to + V; local customs. Compare: customs (border), costume.'),
  'cuisine': VocabUsage('Indonesian cuisine is famous for its rich use of spices.', '', 'Masakan khas Indonesia terkenal karena penggunaan rempah yang kaya.', '', 'Nomina, lebih formal dari food. Kolokasi: local/Italian cuisine, traditional cuisine.', 'Noun, more formal than food. Collocations: local/Italian cuisine, traditional cuisine.'),
  'monument': VocabUsage('A monument was built to honour the soldiers who died in the war.', '', 'Sebuah monumen dibangun untuk menghormati para prajurit yang gugur dalam perang.', '', 'Nomina. Pola: a monument to + orang/peristiwa. Adj: monumental (sangat besar/penting).', 'Noun. Pattern: a monument to + person/event. Adj: monumental (huge/important).'),
  'architecture': VocabUsage('The city is known for its mix of colonial and modern architecture.', '', 'Kota itu dikenal dengan perpaduan arsitektur kolonial dan modern.', '', 'Nomina tak terhitung. Kolokasi: modern/traditional architecture. Orangnya: architect.', 'Uncountable noun. Collocations: modern/traditional architecture. Person: architect.'),
  'indigenous': VocabUsage('Indigenous communities have the right to protect their land and language.', '', 'Masyarakat pribumi berhak melindungi tanah dan bahasa mereka.', '', 'Adjektiva formal. Pola: indigenous to + tempat; indigenous people/species.', 'Formal adjective. Pattern: indigenous to + place; indigenous people/species.'),
  'dialect': VocabUsage('My grandmother speaks a dialect that younger people find hard to understand.', '', 'Nenek saya berbicara dengan dialek yang sulit dipahami orang muda.', '', 'Nomina. Pola: speak a dialect; regional/local dialect. Beda: accent hanya soal pelafalan.', 'Noun. Pattern: speak a dialect; regional/local dialect. Accent refers only to pronunciation.'),
  'mother tongue': VocabUsage('Children learn best when they are first taught in their mother tongue.', '', 'Anak belajar paling baik ketika pertama kali diajar dalam bahasa ibu mereka.', '', 'Frasa nomina. Sinonim: first language, native language.', 'Noun phrase. Synonyms: first language, native language.'),
  'bilingual': VocabUsage('Growing up bilingual can give children a clear advantage in the job market.', '', 'Tumbuh dwibahasa dapat memberi anak keunggulan nyata di dunia kerja.', '', 'Adjektiva. Kolokasi: bilingual education/children. Bandingkan: monolingual, multilingual.', 'Adjective. Collocations: bilingual education/children. Compare: monolingual, multilingual.'),
  'theatre': VocabUsage('Government funding helps local theatres keep ticket prices low.', '', 'Dana pemerintah membantu teater lokal menjaga harga tiket tetap murah.', '', 'Nomina. Ejaan UK; AS: theater. Pola: go to the theatre; movie theater (AS) = bioskop.', 'Noun. UK spelling; US: theater. Pattern: go to the theatre; movie theater (US) = cinema.'),
  'playwright': VocabUsage('Shakespeare is probably the most famous playwright in the English language.', '', 'Shakespeare mungkin penulis naskah drama paling terkenal dalam bahasa Inggris.', '', 'Nomina. Ejaan: -wright (pembuat), bukan -write. Karyanya: a play.', 'Noun. Spelled -wright (maker), not -write. Their work: a play.'),
  'novelist': VocabUsage('The novelist spent ten years writing her first book.', '', 'Novelis itu menghabiskan sepuluh tahun menulis buku pertamanya.', '', 'Nomina. Kolokasi: a best-selling/award-winning novelist. Karyanya: a novel.', 'Noun. Collocations: a best-selling/award-winning novelist. Their work: a novel.'),
  'orchestra': VocabUsage('The city orchestra performs free concerts in the park every summer.', '', 'Orkestra kota mengadakan konser gratis di taman setiap musim panas.', '', 'Nomina kolektif. Kolokasi: symphony orchestra; play in an orchestra. Pemimpin: conductor.', 'Collective noun. Collocations: symphony orchestra; play in an orchestra. Leader: conductor.'),
  'athlete': VocabUsage('Professional athletes train for several hours every day.', '', 'Atlet profesional berlatih beberapa jam setiap hari.', '', 'Nomina. Kolokasi: professional/Olympic athlete. Adj: athletic (atletis).', 'Noun. Collocations: professional/Olympic athlete. Adj: athletic.'),
  'spectator': VocabUsage('Thousands of spectators filled the stadium for the final match.', '', 'Ribuan penonton memenuhi stadion untuk pertandingan final.', '', 'Nomina, khusus penonton acara langsung (olahraga). Beda: audience (konser/teater), viewer (TV).', 'Noun for live events (sport). Compare: audience (concert/theatre), viewer (TV).'),
  'amateur': VocabUsage('Most players in the local football league are amateurs with full-time jobs.', '', 'Sebagian besar pemain di liga sepak bola lokal adalah amatir yang punya pekerjaan tetap.', '', 'Nomina/adjektiva. Lawan: professional. Kolokasi: amateur athlete/photographer.', 'Noun/adjective. Opposite: professional. Collocations: amateur athlete/photographer.'),
  'tournament': VocabUsage('Our school team won the regional basketball tournament last year.', '', 'Tim sekolah kami memenangkan turnamen basket tingkat daerah tahun lalu.', '', 'Nomina. Kolokasi: win/host/enter a tournament; tennis/chess tournament.', 'Noun. Collocations: win/host/enter a tournament; tennis/chess tournament.'),
  'championship': VocabUsage('The team needs one more victory to win the championship.', '', 'Tim itu butuh satu kemenangan lagi untuk memenangkan kejuaraan.', '', 'Nomina. Kolokasi: win the championship, world championship. Pemenangnya: champion.', 'Noun. Collocations: win the championship, world championship. Winner: champion.'),
  'referee': VocabUsage('The referee showed the player a red card for a dangerous tackle.', '', 'Wasit memberi pemain itu kartu merah karena tekel yang berbahaya.', '', 'Nomina/verba. Untuk sepak bola, basket, tinju. Tenis/kriket: umpire.', 'Noun/verb. Used in football, basketball, boxing. Tennis/cricket: umpire.'),
  'doping': VocabUsage('Athletes caught doping should be banned from competition for life.', '', 'Atlet yang ketahuan doping seharusnya dilarang bertanding seumur hidup.', '', 'Nomina tak terhitung. Kolokasi: doping scandal, test for doping, be caught doping.', 'Uncountable noun. Collocations: doping scandal, test for doping, be caught doping.'),
  'sportsmanship': VocabUsage('Shaking hands after the game is a sign of good sportsmanship.', '', 'Berjabat tangan setelah pertandingan adalah tanda sportivitas yang baik.', '', 'Nomina tak terhitung. Kolokasi: good sportsmanship, show sportsmanship. Adj: sporting.', 'Uncountable noun. Collocations: good sportsmanship, show sportsmanship. Adj: sporting.'),
  'stamina': VocabUsage('Long-distance runners need a great deal of stamina.', '', 'Pelari jarak jauh membutuhkan stamina yang sangat besar.', '', 'Nomina tak terhitung. Kolokasi: build up/improve stamina, lack stamina.', 'Uncountable noun. Collocations: build up/improve stamina, lack stamina.'),
  'extreme sports': VocabUsage('Extreme sports such as bungee jumping attract young people seeking thrills.', '', 'Olahraga ekstrem seperti bungee jumping menarik anak muda yang mencari sensasi.', '', 'Frasa nomina jamak. Kolokasi: take part in extreme sports. Sering dibahas soal risiko vs manfaat.', 'Plural noun phrase. Collocation: take part in extreme sports. Often discussed as risk vs benefit.'),
  'coach': VocabUsage('A good coach can motivate players to perform at their best.', '', 'Pelatih yang baik dapat memotivasi pemain untuk tampil maksimal.', '', 'Nomina/verba. Pola: coach a team. Arti lain: coach = bus antarkota (UK).', 'Noun/verb. Pattern: coach a team. Other meaning: coach = long-distance bus (UK).'),
  'trophy': VocabUsage('The captain lifted the trophy as the fans cheered loudly.', '', 'Kapten mengangkat piala sementara para penggemar bersorak keras.', '', 'Nomina. Kolokasi: win/lift/hold the trophy. Jamak: trophies.', 'Noun. Collocations: win/lift/hold the trophy. Plural: trophies.'),
  'team spirit': VocabUsage('Group projects at school help children develop team spirit.', '', 'Proyek kelompok di sekolah membantu anak mengembangkan semangat tim.', '', 'Frasa nomina tak terhitung. Kolokasi: build/develop team spirit, a strong team spirit.', 'Uncountable noun phrase. Collocations: build/develop team spirit, a strong team spirit.'),
  'fast food': VocabUsage('Eating too much fast food is a major cause of obesity among teenagers.', '', 'Terlalu banyak makan makanan cepat saji adalah penyebab utama obesitas pada remaja.', '', 'Frasa nomina tak terhitung. Kolokasi: fast food restaurant/chain; junk food lebih negatif.', 'Uncountable noun phrase. Collocations: fast food restaurant/chain; junk food is more negative.'),
  'takeaway': VocabUsage('After a long day at work, many people order a takeaway instead of cooking.', '', 'Setelah seharian bekerja, banyak orang memesan makanan bungkus alih-alih memasak.', '', 'Nomina (UK). AS: takeout. Pola: order/get a takeaway; takeaway coffee.', 'Noun (UK). US: takeout. Pattern: order/get a takeaway; takeaway coffee.'),
  'home-cooked': VocabUsage('Nothing tastes better than a home-cooked meal shared with family.', '', 'Tidak ada yang lebih enak daripada masakan rumahan yang dinikmati bersama keluarga.', '', 'Adjektiva (bertanda hubung), sebelum nomina: home-cooked meal/food.', 'Hyphenated adjective, before a noun: home-cooked meal/food.'),
  'vegetarian': VocabUsage('More restaurants now offer dishes for vegetarians on their menus.', '', 'Makin banyak restoran kini menawarkan hidangan untuk vegetarian di menunya.', '', 'Nomina/adjektiva. Pola: be/become a vegetarian; vegetarian diet. Masih boleh telur/susu.', 'Noun/adjective. Pattern: be/become a vegetarian; vegetarian diet. May still eat eggs/dairy.'),
  'vegan': VocabUsage('She became a vegan after learning about the impact of farming on animals.', '', 'Dia menjadi vegan setelah mengetahui dampak peternakan terhadap hewan.', '', 'Nomina/adjektiva. Lebih ketat dari vegetarian: tanpa telur, susu, madu. Pola: go vegan.', 'Noun/adjective. Stricter than vegetarian: no eggs, dairy, honey. Pattern: go vegan.'),
  'preservative': VocabUsage('Processed foods often contain preservatives to make them last longer.', '', 'Makanan olahan sering mengandung pengawet agar lebih tahan lama.', '', 'Nomina. Kolokasi: contain preservatives, free from preservatives. Verba: preserve.', 'Noun. Collocations: contain preservatives, free from preservatives. Verb: preserve.'),
  'calorie': VocabUsage('Sugary drinks contain a lot of calories but very few nutrients.', '', 'Minuman manis mengandung banyak kalori tetapi sangat sedikit nutrisi.', '', 'Nomina terhitung. Kolokasi: burn calories, high-calorie/low-calorie food, count calories.', 'Countable noun. Collocations: burn calories, high-/low-calorie food, count calories.'),
  'staple food': VocabUsage('Rice is the staple food for more than half of the world\'s population.', '', 'Nasi adalah makanan pokok bagi lebih dari separuh penduduk dunia.', '', 'Frasa nomina. Pola: X is the staple food of/for + kelompok. Juga: a staple diet.', 'Noun phrase. Pattern: X is the staple food of/for + group. Also: a staple diet.'),
  'genetically modified': VocabUsage('Some consumers refuse to buy genetically modified crops.', '', 'Sebagian konsumen menolak membeli tanaman hasil rekayasa genetik.', '', 'Adjektiva, singkatan GM/GMO. Kolokasi: genetically modified food/crops/organisms.', 'Adjective, abbreviated GM/GMO. Collocations: genetically modified food/crops/organisms.'),
  'famine': VocabUsage('Years of drought caused a terrible famine in the region.', '', 'Kekeringan bertahun-tahun menyebabkan bencana kelaparan dahsyat di wilayah itu.', '', 'Nomina. Lebih parah dari hunger (lapar umum). Kolokasi: severe famine, famine relief.', 'Noun. Stronger than hunger. Collocations: severe famine, famine relief.'),
  'organic': VocabUsage('Organic vegetables are usually more expensive than conventional ones.', '', 'Sayuran organik biasanya lebih mahal daripada sayuran biasa.', '', 'Adjektiva. Kolokasi: organic food/farming/produce. Lawan: conventional, chemically treated.', 'Adjective. Collocations: organic food/farming/produce. Opposite: conventional.'),
  'nutritious': VocabUsage('Schools should provide nutritious lunches to help students concentrate.', '', 'Sekolah seharusnya menyediakan makan siang bergizi agar siswa bisa berkonsentrasi.', '', 'Adjektiva. Kolokasi: nutritious meal/food/diet. Nomina: nutrition, nutrient.', 'Adjective. Collocations: nutritious meal/food/diet. Nouns: nutrition, nutrient.'),
  'eating habits': VocabUsage('Busy lifestyles have changed the eating habits of young professionals.', '', 'Gaya hidup sibuk telah mengubah kebiasaan makan para profesional muda.', '', 'Frasa nomina jamak. Kolokasi: healthy/unhealthy eating habits, change your eating habits.', 'Plural noun phrase. Collocations: healthy/unhealthy eating habits, change your eating habits.'),
  'street food': VocabUsage('Street food is cheap, tasty and an important part of local culture.', '', 'Jajanan kaki lima murah, enak, dan merupakan bagian penting budaya lokal.', '', 'Frasa nomina tak terhitung. Kolokasi: street food vendor/stall/market.', 'Uncountable noun phrase. Collocations: street food vendor/stall/market.'),
  'multinational': VocabUsage('Multinational companies create jobs but may also exploit cheap labour.', '', 'Perusahaan multinasional menciptakan lapangan kerja tetapi juga bisa mengeksploitasi buruh murah.', '', 'Adjektiva/nomina. Kolokasi: multinational company/corporation; a multinational (= perusahaannya).', 'Adjective/noun. Collocations: multinational company/corporation; a multinational (the firm).'),
  'free trade': VocabUsage('Free trade agreements have made imported goods cheaper for consumers.', '', 'Perjanjian perdagangan bebas telah membuat barang impor lebih murah bagi konsumen.', '', 'Frasa nomina tak terhitung. Kolokasi: free trade agreement/zone. Lawan: protectionism.', 'Uncountable noun phrase. Collocations: free trade agreement/zone. Opposite: protectionism.'),
  'westernization': VocabUsage('Some argue that westernization threatens traditional values in Asia.', '', 'Sebagian orang berpendapat bahwa pembaratan mengancam nilai-nilai tradisional di Asia.', '', 'Nomina tak terhitung. Ejaan UK juga westernisation. Verba: westernize.', 'Uncountable noun. UK spelling also westernisation. Verb: westernize.'),
  'developing country': VocabUsage('Many developing countries depend heavily on agriculture and exports.', '', 'Banyak negara berkembang sangat bergantung pada pertanian dan ekspor.', '', 'Frasa nomina. Lawan: developed country. Lebih sopan dari poor country.', 'Noun phrase. Opposite: developed country. Politer than poor country.'),
  'developed country': VocabUsage('Developed countries produce far more carbon emissions per person.', '', 'Negara maju menghasilkan emisi karbon per orang yang jauh lebih banyak.', '', 'Frasa nomina. Sinonim: industrialised nation. Lawan: developing country.', 'Noun phrase. Synonym: industrialised nation. Opposite: developing country.'),
  'foreign aid': VocabUsage('Foreign aid should be used to build schools and hospitals.', '', 'Bantuan luar negeri seharusnya digunakan untuk membangun sekolah dan rumah sakit.', '', 'Frasa nomina tak terhitung. Kolokasi: give/receive foreign aid; depend on foreign aid.', 'Uncountable noun phrase. Collocations: give/receive foreign aid; depend on foreign aid.'),
  'expatriate': VocabUsage('Many expatriates in Singapore work in finance and technology.', '', 'Banyak ekspatriat di Singapura bekerja di bidang keuangan dan teknologi.', '', 'Nomina, sering disingkat expat. Biasanya pekerja profesional yang tinggal di luar negeri.', 'Noun, often shortened to expat. Usually a professional living abroad.'),
  'sweatshop': VocabUsage('Some clothing brands have been criticised for using sweatshops overseas.', '', 'Beberapa merek pakaian dikritik karena memakai pabrik upah rendah di luar negeri.', '', 'Nomina bernuansa negatif. Kolokasi: sweatshop labour/conditions.', 'Negative noun. Collocations: sweatshop labour/conditions.'),
  'fair trade': VocabUsage('Buying fair trade coffee helps farmers earn a decent living.', '', 'Membeli kopi berlabel perdagangan adil membantu petani mendapat penghidupan layak.', '', 'Frasa nomina/adjektiva. Kolokasi: fair trade products/coffee. Beda: free trade (tanpa tarif).', 'Noun/adjective phrase. Collocations: fair trade products/coffee. Compare: free trade.'),
  'worldwide': VocabUsage('The company now has more than five thousand stores worldwide.', '', 'Perusahaan itu kini memiliki lebih dari lima ribu toko di seluruh dunia.', '', 'Adjektiva/adverbia. Pola: sell worldwide (adv); a worldwide problem (adj).', 'Adjective/adverb. Pattern: sell worldwide (adv); a worldwide problem (adj).'),
  'peak': VocabUsage('Sales reached a peak of two million units in 2015.', '', 'Penjualan mencapai puncak dua juta unit pada tahun 2015.', '', 'Nomina/verba untuk grafik. Pola: reach a peak of + angka; peak at + angka.', 'Noun/verb for graphs. Pattern: reach a peak of + number; peak at + number.'),
  'plummet': VocabUsage('Coal consumption plummeted after the government introduced new regulations.', '', 'Konsumsi batu bara anjlok setelah pemerintah memberlakukan aturan baru.', '', 'Verba intransitif, lebih kuat dari fall/drop. Pola: plummet to/by + angka.', 'Intransitive verb, stronger than fall/drop. Pattern: plummet to/by + number.'),
  'steady': VocabUsage('There was a steady increase in the number of online shoppers.', '', 'Terjadi peningkatan yang stabil pada jumlah pembeli daring.', '', 'Adjektiva untuk grafik. Kolokasi: a steady rise/increase/decline. Adverbia: steadily.', 'Adjective for graphs. Collocations: a steady rise/increase/decline. Adverb: steadily.'),
  'gradual': VocabUsage('The chart shows a gradual decline in newspaper sales over ten years.', '', 'Grafik itu menunjukkan penurunan bertahap penjualan koran selama sepuluh tahun.', '', 'Adjektiva. Kolokasi: a gradual increase/decline/change. Adverbia: gradually.', 'Adjective. Collocations: a gradual increase/decline/change. Adverb: gradually.'),
  'surge': VocabUsage('Demand for face masks surged during the first months of the pandemic.', '', 'Permintaan masker melonjak selama bulan-bulan pertama pandemi.', '', 'Verba/nomina. Pola: surge to + angka; a surge in + N (a surge in demand).', 'Verb/noun. Pattern: surge to + number; a surge in + N (a surge in demand).'),
  'soar': VocabUsage('House prices soared to record levels in the capital last year.', '', 'Harga rumah meroket ke tingkat rekor di ibu kota tahun lalu.', '', 'Verba intransitif, kenaikan sangat besar. Pola: soar to + angka. Lawan: plummet.', 'Intransitive verb, very large rise. Pattern: soar to + number. Opposite: plummet.'),
  'dip': VocabUsage('Visitor numbers dipped slightly in March before rising again.', '', 'Jumlah pengunjung turun sedikit pada bulan Maret sebelum naik lagi.', '', 'Verba/nomina, penurunan kecil sementara. Pola: dip slightly; a slight dip in + N.', 'Verb/noun, small temporary fall. Pattern: dip slightly; a slight dip in + N.'),
  'level off': VocabUsage('After years of growth, the unemployment rate levelled off at around 5%.', '', 'Setelah bertahun-tahun naik, tingkat pengangguran mendatar di sekitar 5%.', '', 'Verba frasal intransitif. Pola: level off at + angka. UK: levelled; AS: leveled.', 'Intransitive phrasal verb. Pattern: level off at + number. UK: levelled; US: leveled.'),
  'plateau': VocabUsage('Smartphone sales reached a plateau after several years of rapid growth.', '', 'Penjualan ponsel pintar memasuki masa stagnan setelah beberapa tahun tumbuh pesat.', '', 'Nomina/verba. Pola: reach a plateau; plateau at + angka. Jamak: plateaus/plateaux.', 'Noun/verb. Pattern: reach a plateau; plateau at + number. Plural: plateaus/plateaux.'),
  'slump': VocabUsage('Car sales slumped during the economic crisis.', '', 'Penjualan mobil merosot tajam selama krisis ekonomi.', '', 'Verba/nomina. Pola: slump to + angka; a slump in sales. Juga: economic slump (resesi).', 'Verb/noun. Pattern: slump to + number; a slump in sales. Also: economic slump.'),
  'bottom out': VocabUsage('The housing market finally bottomed out in 2012 and began to recover.', '', 'Pasar perumahan akhirnya mencapai titik terendah pada 2012 lalu mulai pulih.', '', 'Verba frasal intransitif, sering diikuti rebound/recover. Pola: bottom out at + angka.', 'Intransitive phrasal verb, often followed by recovery. Pattern: bottom out at + number.'),
  'rebound': VocabUsage('Tourist numbers rebounded quickly after travel restrictions were lifted.', '', 'Jumlah wisatawan naik kembali dengan cepat setelah pembatasan perjalanan dicabut.', '', 'Verba/nomina. Pola: rebound to + angka; a strong rebound in + N.', 'Verb/noun. Pattern: rebound to + number; a strong rebound in + N.'),
  'halve': VocabUsage('The number of smokers halved between 1990 and 2020.', '', 'Jumlah perokok berkurang separuh antara tahun 1990 dan 2020.', '', 'Verba (transitif/intransitif). Bentuk: halved, halving. Nomina terkait: half.', 'Verb (transitive/intransitive). Forms: halved, halving. Related noun: half.'),
  'double': VocabUsage('The population of the city doubled in less than twenty years.', '', 'Penduduk kota itu naik dua kali lipat dalam waktu kurang dari dua puluh tahun.', '', 'Verba/adjektiva. Pola: double in size/number; double from X to Y. Bandingkan: triple.', 'Verb/adjective. Pattern: double in size/number; double from X to Y. Compare: triple.'),
  'outnumber': VocabUsage('In this university, female students now outnumber male students.', '', 'Di universitas ini, jumlah mahasiswi kini melebihi jumlah mahasiswa.', '', 'Verba transitif. Pola: A outnumber(s) B (by + angka). Tanpa than.', 'Transitive verb. Pattern: A outnumber(s) B (by + number). No than.'),
  'overtake': VocabUsage('In 2010, online sales overtook in-store sales for the first time.', '', 'Pada 2010, penjualan daring menyalip penjualan di toko untuk pertama kalinya.', '', 'Verba tak beraturan: overtake-overtook-overtaken. Di grafik: satu garis melewati garis lain.', 'Irregular verb: overtake-overtook-overtaken. In graphs: one line passes another.'),
  'sharp': VocabUsage('There was a sharp rise in energy prices in the final quarter.', '', 'Terjadi kenaikan tajam harga energi pada kuartal terakhir.', '', 'Adjektiva grafik. Kolokasi: a sharp rise/fall/drop. Adverbia: sharply.', 'Graph adjective. Collocations: a sharp rise/fall/drop. Adverb: sharply.'),
  'slight': VocabUsage('The graph shows only a slight increase in rainfall over the decade.', '', 'Grafik itu hanya menunjukkan sedikit kenaikan curah hujan selama satu dekade.', '', 'Adjektiva. Kolokasi: a slight rise/fall/change. Adverbia: slightly. Lawan: significant.', 'Adjective. Collocations: a slight rise/fall/change. Adverb: slightly. Opposite: significant.'),
  'steep': VocabUsage('The steep decline in birth rates worries many governments.', '', 'Penurunan curam angka kelahiran mengkhawatirkan banyak pemerintah.', '', 'Adjektiva. Kolokasi: a steep rise/decline/increase. Juga: steep price (mahal sekali).', 'Adjective. Collocations: a steep rise/decline/increase. Also: steep price (very high).'),
  'marginal': VocabUsage('There was only a marginal difference between the two groups\' scores.', '', 'Hanya ada perbedaan yang sangat kecil antara nilai kedua kelompok.', '', 'Adjektiva. Kolokasi: a marginal increase/difference. Adverbia: marginally.', 'Adjective. Collocations: a marginal increase/difference. Adverb: marginally.'),
  'substantial': VocabUsage('The new policy led to a substantial reduction in road accidents.', '', 'Kebijakan baru itu menyebabkan penurunan yang cukup besar pada kecelakaan jalan.', '', 'Adjektiva formal. Kolokasi: a substantial increase/amount/reduction. Adverbia: substantially.', 'Formal adjective. Collocations: a substantial increase/amount/reduction. Adverb: substantially.'),
  'erratic': VocabUsage('Oil prices were erratic throughout the period shown in the chart.', '', 'Harga minyak naik turun tak menentu sepanjang periode yang ditampilkan grafik.', '', 'Adjektiva. Kolokasi: erratic fluctuations/behaviour. Sinonim: fluctuating, irregular.', 'Adjective. Collocations: erratic fluctuations/behaviour. Synonyms: fluctuating, irregular.'),
  'steadily': VocabUsage('The number of electric cars on the road has risen steadily since 2015.', '', 'Jumlah mobil listrik di jalan naik secara stabil sejak 2015.', '', 'Adverbia, setelah verba: rise/grow/decline steadily. Adjektiva: steady.', 'Adverb, after a verb: rise/grow/decline steadily. Adjective: steady.'),
  'respectively': VocabUsage('Sales in France and Spain were 20% and 15% respectively.', '', 'Penjualan di Prancis dan Spanyol masing-masing secara berurutan sebesar 20% dan 15%.', '', 'Adverbia, biasanya di akhir kalimat; urutan angka mengikuti urutan nomina sebelumnya.', 'Adverb, usually at the end; the figures match the order of the nouns given.'),
  'the lowest point': VocabUsage('Unemployment fell to the lowest point in thirty years in 2019.', '', 'Pengangguran turun ke titik terendah dalam tiga puluh tahun pada 2019.', '', 'Frasa nomina. Pola: fall to / hit the lowest point; lawan: the highest point / a peak.', 'Noun phrase. Pattern: fall to / hit the lowest point; opposite: the highest point / a peak.'),
  'roughly': VocabUsage('Roughly half of the respondents said they exercise every week.', '', 'Kurang lebih separuh responden mengatakan mereka berolahraga setiap minggu.', '', 'Adverbia sebelum angka. Sinonim: approximately (formal), about, around.', 'Adverb before numbers. Synonyms: approximately (formal), about, around.'),
  'nearly': VocabUsage('Nearly 70% of households now have access to the internet.', '', 'Hampir 70% rumah tangga kini memiliki akses internet.', '', 'Adverbia: sedikit di bawah angka. Sinonim: almost. Beda: roughly bisa di atas/bawah.', 'Adverb: just below a figure. Synonym: almost. Roughly may be above or below.'),
  'a quarter': VocabUsage('A quarter of the students surveyed preferred online classes.', '', 'Seperempat mahasiswa yang disurvei lebih menyukai kelas daring.', '', 'Frasa pecahan (25%). Pola: a quarter of + N; three quarters (75%).', 'Fraction phrase (25%). Pattern: a quarter of + N; three quarters (75%).'),
  'moreover': VocabUsage('Public transport reduces pollution. Moreover, it eases traffic congestion.', '', 'Transportasi umum mengurangi polusi. Lagi pula, itu juga mengurangi kemacetan.', '', 'Penghubung formal di awal kalimat + koma, untuk menambah poin. Sinonim: furthermore, in addition.', 'Formal linker at the start of a sentence + comma, adds a point. Synonyms: furthermore, in addition.'),
  'however': VocabUsage('Online learning is flexible. However, it requires strong self-discipline.', '', 'Belajar daring itu fleksibel. Namun, hal itu membutuhkan disiplin diri yang kuat.', '', 'Penghubung kontras di awal kalimat + koma. Jangan menyambung dua klausa hanya dengan koma.', 'Contrast linker at the start of a sentence + comma. Don\'t join two clauses with just a comma.'),
  'therefore': VocabUsage('The city\'s population is growing rapidly; therefore, more housing is needed.', '', 'Penduduk kota bertambah pesat; oleh karena itu, dibutuhkan lebih banyak perumahan.', '', 'Penghubung akibat, formal. Pola: ; therefore, / . Therefore, Sinonim: thus, consequently.', 'Formal result linker. Pattern: ; therefore, / . Therefore, Synonyms: thus, consequently.'),
  'argue': VocabUsage('Some people argue that university education should be free for everyone.', '', 'Sebagian orang berpendapat bahwa pendidikan universitas harus gratis untuk semua orang.', '', 'Verba. Pola: argue that + klausa; argue for/against + N. Nomina: argument.', 'Verb. Pattern: argue that + clause; argue for/against + N. Noun: argument.'),
  'drawback': VocabUsage('The main drawback of living in the city is the high cost of housing.', '', 'Kekurangan utama tinggal di kota adalah mahalnya biaya perumahan.', '', 'Nomina. Pola: the drawback of + N/V-ing; a major drawback. Sinonim: disadvantage.', 'Noun. Pattern: the drawback of + N/V-ing; a major drawback. Synonym: disadvantage.'),
  'on the whole': VocabUsage('On the whole, the benefits of tourism outweigh its disadvantages.', '', 'Pada umumnya, manfaat pariwisata lebih besar daripada kerugiannya.', '', 'Frasa penghubung untuk generalisasi, biasanya di awal kalimat + koma. Sinonim: overall, generally.', 'Linking phrase for generalising, usually sentence-initial + comma. Synonyms: overall, generally.'),
  'to some extent': VocabUsage('I agree with this view to some extent, but not completely.', '', 'Saya setuju dengan pandangan ini sampai batas tertentu, tetapi tidak sepenuhnya.', '', 'Frasa pembatas sikap: agree to some extent. Variasi: to a certain extent, to a large extent.', 'Hedging phrase: agree to some extent. Variants: to a certain extent, to a large extent.'),
  'it could be argued that': VocabUsage('It could be argued that social media has made people lonelier.', '', 'Bisa dikatakan bahwa media sosial telah membuat orang lebih kesepian.', '', 'Frasa pembuka impersonal untuk mengajukan pendapat secara hati-hati; diikuti klausa lengkap.', 'Impersonal opener to present a view cautiously; followed by a full clause.'),
  'by and large': VocabUsage('By and large, young people adapt to new technology more quickly.', '', 'Secara garis besar, anak muda beradaptasi dengan teknologi baru lebih cepat.', '', 'Idiom penghubung, agak informal; biasanya di awal kalimat + koma. Sinonim: on the whole.', 'Idiomatic linker, slightly informal; usually sentence-initial + comma. Synonym: on the whole.'),
  'all things considered': VocabUsage('All things considered, working from home has more advantages than disadvantages.', '', 'Setelah menimbang semuanya, bekerja dari rumah lebih banyak keuntungannya daripada kerugiannya.', '', 'Frasa penutup/kesimpulan, di awal kalimat + koma. Cocok untuk paragraf kesimpulan esai.', 'Concluding phrase, sentence-initial + comma. Suits an essay\'s conclusion.'),
  'admittedly': VocabUsage('Admittedly, electric cars are expensive, but their running costs are low.', '', 'Harus diakui, mobil listrik mahal, tetapi biaya operasionalnya rendah.', '', 'Adverbia untuk mengakui poin lawan sebelum membantah; sering diikuti but/however.', 'Adverb conceding the other side before countering; often followed by but/however.'),
  'arguably': VocabUsage('Climate change is arguably the greatest challenge of our time.', '', 'Perubahan iklim bisa dibilang merupakan tantangan terbesar di zaman kita.', '', 'Adverbia untuk klaim yang bisa dipertahankan; sering sebelum superlatif: arguably the best.', 'Adverb for a defensible claim; often before superlatives: arguably the best.'),
  'undoubtedly': VocabUsage('The internet has undoubtedly changed the way we communicate.', '', 'Internet tidak diragukan lagi telah mengubah cara kita berkomunikasi.', '', 'Adverbia penegas, biasanya sebelum verba utama atau di awal kalimat. Sinonim: certainly.', 'Emphatic adverb, before the main verb or at the start. Synonym: certainly.'),
  'thus': VocabUsage('Fewer cars are on the road; thus, air quality has improved.', '', 'Mobil di jalan makin sedikit; dengan demikian, kualitas udara membaik.', '', 'Adverbia formal untuk akibat. Pola: ; thus, / thus + V-ing (thus reducing costs).', 'Formal result adverb. Pattern: ; thus, / thus + V-ing (thus reducing costs).'),
  'meanwhile': VocabUsage('Car ownership rose sharply; meanwhile, bus use declined steadily.', '', 'Kepemilikan mobil naik tajam; sementara itu, penggunaan bus terus menurun.', '', 'Adverbia penghubung untuk dua hal yang terjadi bersamaan atau kontras, + koma.', 'Linking adverb for simultaneous or contrasting events, + comma.'),
  'besides': VocabUsage('Cycling is cheap. Besides, it keeps you fit and healthy.', '', 'Bersepeda itu murah. Selain itu juga, bersepeda membuatmu bugar dan sehat.', '', 'Adverbia (+ koma) untuk menambah alasan; preposisi: besides + N/V-ing. Beda: beside = di samping.', 'Adverb (+ comma) adding a reason; preposition: besides + N/V-ing. Beside = next to.'),
  'on the other hand': VocabUsage('Cities offer more jobs. On the other hand, living costs are much higher.', '', 'Kota menawarkan lebih banyak pekerjaan. Di sisi lain, biaya hidup jauh lebih tinggi.', '', 'Penghubung kontras antara dua sisi; idealnya didahului on the one hand. Di awal kalimat + koma.', 'Contrast linker between two sides; ideally after on the one hand. Sentence-initial + comma.'),
  'in the long run': VocabUsage('Investing in renewable energy will save money in the long run.', '', 'Berinvestasi pada energi terbarukan akan menghemat uang dalam jangka panjang.', '', 'Frasa adverbia, biasanya di akhir/awal kalimat. Lawan: in the short run/term.', 'Adverbial phrase, at the end or start. Opposite: in the short run/term.'),
  'in the short term': VocabUsage('Raising taxes may reduce demand in the short term.', '', 'Menaikkan pajak bisa mengurangi permintaan dalam jangka pendek.', '', 'Frasa adverbia. Lawan: in the long term. Adjektiva: short-term (short-term benefits).', 'Adverbial phrase. Opposite: in the long term. Adjective: short-term (short-term benefits).'),
  'owing to': VocabUsage('The flight was cancelled owing to bad weather.', '', 'Penerbangan itu dibatalkan karena cuaca buruk.', '', 'Preposisi formal + nomina/V-ing (bukan klausa). Sinonim: due to, because of.', 'Formal preposition + noun/V-ing (not a clause). Synonyms: due to, because of.'),
  'in terms of': VocabUsage('In terms of cost, public transport is far better than driving.', '', 'Dari segi biaya, transportasi umum jauh lebih baik daripada menyetir.', '', 'Frasa preposisi + nomina untuk menyebut aspek yang dibahas. Sinonim: regarding.', 'Prepositional phrase + noun naming the aspect discussed. Synonym: regarding.'),
  'in other words': VocabUsage('Prices doubled in five years. In other words, they rose by 100%.', '', 'Harga naik dua kali lipat dalam lima tahun. Dengan kata lain, harga naik 100%.', '', 'Penghubung untuk menjelaskan ulang dengan lebih sederhana, + koma. Sinonim: that is to say.', 'Linker to rephrase more simply, + comma. Synonym: that is to say.'),
  'to sum up': VocabUsage('To sum up, both government and individuals must act to protect the environment.', '', 'Singkatnya, pemerintah dan individu sama-sama harus bertindak untuk melindungi lingkungan.', '', 'Frasa pembuka kesimpulan + koma. Sinonim: in conclusion, to summarise.', 'Opener for a conclusion + comma. Synonyms: in conclusion, to summarise.'),
  'first and foremost': VocabUsage('First and foremost, schools must ensure that children are safe.', '', 'Pertama dan terutama, sekolah harus memastikan anak-anak aman.', '', 'Frasa penekan untuk poin paling penting, di awal kalimat + koma.', 'Emphatic phrase for the most important point, sentence-initial + comma.'),
  'it is widely believed that': VocabUsage('It is widely believed that regular exercise reduces stress.', '', 'Banyak orang percaya bahwa olahraga teratur mengurangi stres.', '', 'Pembuka impersonal formal + klausa. Variasi: it is commonly/generally believed that.', 'Formal impersonal opener + clause. Variants: it is commonly/generally believed that.'),
  'there is no doubt that': VocabUsage('There is no doubt that technology has improved healthcare.', '', 'Tak diragukan bahwa teknologi telah meningkatkan layanan kesehatan.', '', 'Frasa penegas + klausa. Sinonim: undoubtedly, certainly. Pakai hanya untuk klaim yang kuat.', 'Emphatic phrase + clause. Synonyms: undoubtedly, certainly. Use only for strong claims.'),
  'it goes without saying': VocabUsage('It goes without saying that children need love and attention.', '', 'Sudah jelas bahwa anak-anak membutuhkan kasih sayang dan perhatian.', '', 'Idiom, biasanya diikuti that + klausa. Agak informal untuk esai; alternatif: clearly.', 'Idiom, usually followed by that + clause. Slightly informal; alternative: clearly.'),
  'in my view': VocabUsage('In my view, governments should spend more on public health.', '', 'Menurut saya, pemerintah seharusnya membelanjakan lebih banyak untuk kesehatan masyarakat.', '', 'Frasa opini di awal kalimat + koma. Sinonim: in my opinion, from my perspective.', 'Opinion phrase, sentence-initial + comma. Synonyms: in my opinion, from my perspective.'),
  'to a large degree': VocabUsage('Success in life depends to a large degree on hard work.', '', 'Kesuksesan dalam hidup sebagian besar bergantung pada kerja keras.', '', 'Frasa adverbia penakar. Sinonim: largely, to a great extent. Lawan: to a small degree.', 'Adverbial phrase of degree. Synonyms: largely, to a great extent. Opposite: to a small degree.'),
  'not to mention': VocabUsage('Cars cause pollution, not to mention the danger they pose to pedestrians.', '', 'Mobil menyebabkan polusi, belum lagi bahaya yang ditimbulkannya bagi pejalan kaki.', '', 'Frasa penambah poin yang lebih kuat; diikuti nomina/V-ing, biasanya setelah koma.', 'Adds an extra, stronger point; followed by noun/V-ing, usually after a comma.'),
  'even though': VocabUsage('Even though the city is expensive, many graduates still move there.', '', 'Meskipun kota itu mahal, banyak lulusan tetap pindah ke sana.', '', 'Konjungsi + klausa, lebih tegas dari although. Jangan diikuti but di klausa berikutnya.', 'Conjunction + clause, stronger than although. Don\'t add but in the next clause.'),
  'as long as': VocabUsage('You can borrow my laptop as long as you return it by Friday.', '', 'Kamu boleh meminjam laptopku asalkan dikembalikan paling lambat hari Jumat.', '', 'Konjungsi syarat + klausa (present tense untuk masa depan). Sinonim: provided that.', 'Conditional conjunction + clause (present for future). Synonym: provided that.'),
  'apart from': VocabUsage('Apart from the high cost, the course was excellent.', '', 'Selain biayanya yang mahal, kursus itu sangat bagus.', '', 'Preposisi + nomina/V-ing. Bisa berarti \'kecuali\' atau \'selain (juga)\'. Sinonim: except for, besides.', 'Preposition + noun/V-ing. Means \'except\' or \'in addition to\'. Synonyms: except for, besides.'),
  'headquarters': VocabUsage('The company\'s headquarters will move to Jakarta next year.', '', 'Kantor pusat perusahaan akan pindah ke Jakarta tahun depan.', '', 'Nomina berakhiran -s, bisa tunggal/jamak (kata kerja is/are). Singkatan: HQ.', 'Noun ending in -s, used as singular or plural. Abbreviation: HQ.'),
  'branch': VocabUsage('The bank is opening a new branch in the shopping district.', '', 'Bank itu membuka cabang baru di kawasan pertokoan.', '', 'Nomina. Kolokasi: open/close a branch, branch office/manager. Lawan: headquarters.', 'Noun. Collocations: open/close a branch, branch office/manager. Opposite: headquarters.'),
  'department': VocabUsage('Please send your expense reports to the accounting department.', '', 'Silakan kirim laporan pengeluaran Anda ke departemen akuntansi.', '', 'Nomina. Kolokasi: sales/HR/accounting department, department head. Singkatan: dept.', 'Noun. Collocations: sales/HR/accounting department, department head. Abbreviation: dept.'),
  'reception': VocabUsage('Visitors must sign in at reception before going upstairs.', '', 'Tamu harus mendaftar di meja resepsionis sebelum naik ke atas.', '', 'Nomina. Pola: at reception (tanpa the di UK); reception desk. Petugasnya: receptionist.', 'Noun. Pattern: at reception (no the in UK); reception desk. Staff: receptionist.'),
  'extension': VocabUsage('You can reach me directly at extension 214.', '', 'Anda bisa menghubungi saya langsung di nomor ekstensi 214.', '', 'Nomina. Pola: at/on extension + nomor; singkatan ext. Arti lain: perpanjangan (deadline extension).', 'Noun. Pattern: at/on extension + number; abbreviated ext. Also: deadline extension.'),
  'voicemail': VocabUsage('I left a voicemail for the client, but she hasn\'t called back yet.', '', 'Saya meninggalkan pesan suara untuk klien itu, tetapi dia belum menelepon balik.', '', 'Nomina. Kolokasi: leave a voicemail, check your voicemail, go to voicemail.', 'Noun. Collocations: leave a voicemail, check your voicemail, go to voicemail.'),
  'directory': VocabUsage('You can find every employee\'s phone number in the staff directory.', '', 'Anda dapat menemukan nomor telepon setiap karyawan di direktori staf.', '', 'Nomina. Kolokasi: staff/company/phone directory. Di komputer: folder.', 'Noun. Collocations: staff/company/phone directory. In computing: a folder.'),
  'memo': VocabUsage('The manager sent a memo to all staff about the new parking rules.', '', 'Manajer mengirim memo kepada semua staf tentang aturan parkir yang baru.', '', 'Nomina (dari memorandum). Pola: send/circulate a memo to + orang; a memo about/on + topik.', 'Noun (from memorandum). Pattern: send/circulate a memo to + people; a memo about + topic.'),
  'cubicle': VocabUsage('Each employee works in a small cubicle with a desk and computer.', '', 'Setiap karyawan bekerja di bilik kerja kecil dengan meja dan komputer.', '', 'Nomina. Pola: work in a cubicle. Kontras: open-plan office, private office.', 'Noun. Pattern: work in a cubicle. Contrast: open-plan office, private office.'),
  'stationery': VocabUsage('Please order more stationery, including pens, folders and paper.', '', 'Tolong pesan alat tulis kantor lagi, termasuk pulpen, map, dan kertas.', '', 'Nomina tak terhitung (tanpa -s). Beda ejaan: stationary = diam/tidak bergerak.', 'Uncountable noun (no -s). Don\'t confuse with stationary = not moving.'),
  'filing cabinet': VocabUsage('All signed contracts are kept in the locked filing cabinet.', '', 'Semua kontrak yang sudah ditandatangani disimpan di lemari arsip yang terkunci.', '', 'Frasa nomina. AS juga file cabinet. Verba terkait: file documents (mengarsipkan).', 'Noun phrase. US also file cabinet. Related verb: file documents.'),
  'bulletin board': VocabUsage('The training schedule has been posted on the bulletin board.', '', 'Jadwal pelatihan sudah ditempel di papan pengumuman.', '', 'Frasa nomina (AS). UK: noticeboard. Pola: post/pin something on the bulletin board.', 'Noun phrase (US). UK: noticeboard. Pattern: post/pin something on the bulletin board.'),
  'whiteboard': VocabUsage('The team leader wrote the project timeline on the whiteboard.', '', 'Ketua tim menulis linimasa proyek di papan tulis putih.', '', 'Nomina. Pola: write on the whiteboard; whiteboard marker. Juga untuk papan virtual di rapat daring.', 'Noun. Pattern: write on the whiteboard; whiteboard marker. Also virtual boards in online meetings.'),
  'envelope': VocabUsage('Please put the invoice in an envelope and send it to the client.', '', 'Tolong masukkan faktur ke dalam amplop dan kirim ke klien.', '', 'Nomina. Kolokasi: seal/address an envelope; a stamped envelope.', 'Noun. Collocations: seal/address an envelope; a stamped envelope.'),
  'letterhead': VocabUsage('Official letters must be printed on company letterhead.', '', 'Surat resmi harus dicetak di atas kop surat perusahaan.', '', 'Nomina. Pola: on company letterhead. Biasanya memuat logo, alamat, dan kontak.', 'Noun. Pattern: on company letterhead. Usually shows logo, address and contacts.'),
  'fax machine': VocabUsage('Few offices still use a fax machine to send documents.', '', 'Sedikit kantor yang masih memakai mesin faks untuk mengirim dokumen.', '', 'Frasa nomina. Verba: fax a document to + orang; nomina: send a fax.', 'Noun phrase. Verb: fax a document to + person; noun: send a fax.'),
  'shredder': VocabUsage('Confidential documents should be destroyed in the shredder.', '', 'Dokumen rahasia harus dihancurkan di mesin penghancur kertas.', '', 'Nomina. Verba: shred documents. Sering muncul bersama confidential.', 'Noun. Verb: shred documents. Often appears with confidential.'),
  'paperwork': VocabUsage('New employees must complete a lot of paperwork on their first day.', '', 'Karyawan baru harus menyelesaikan banyak urusan administrasi di hari pertama.', '', 'Nomina tak terhitung (bukan paperworks). Kolokasi: complete/fill out/do the paperwork.', 'Uncountable noun (not paperworks). Collocations: complete/fill out/do the paperwork.'),
  'clerical': VocabUsage('The position involves clerical tasks such as filing and data entry.', '', 'Posisi itu mencakup tugas tata usaha seperti pengarsipan dan entri data.', '', 'Adjektiva. Kolokasi: clerical work/staff/error. Orangnya: clerk.', 'Adjective. Collocations: clerical work/staff/error. Person: clerk.'),
  'secretary': VocabUsage('Please contact my secretary to schedule a meeting.', '', 'Silakan hubungi sekretaris saya untuk menjadwalkan rapat.', '', 'Nomina. Istilah modern: administrative/executive assistant. Arti lain: menteri (AS: Secretary of State).', 'Noun. Modern term: administrative/executive assistant. Also a minister (US Secretary of State).'),
  'workstation': VocabUsage('Each workstation is equipped with two monitors and a phone.', '', 'Setiap meja kerja dilengkapi dengan dua monitor dan satu telepon.', '', 'Nomina. Kolokasi: set up/clean your workstation. Lebih luas dari desk (termasuk komputer).', 'Noun. Collocations: set up/clean your workstation. Broader than desk (includes the computer).'),
  'break room': VocabUsage('Free coffee and snacks are available in the break room.', '', 'Kopi dan camilan gratis tersedia di ruang istirahat.', '', 'Frasa nomina (AS). UK: staff room. Pola: in the break room.', 'Noun phrase (US). UK: staff room. Pattern: in the break room.'),
  'boardroom': VocabUsage('The directors are meeting in the boardroom on the top floor.', '', 'Para direktur sedang rapat di ruang rapat direksi di lantai paling atas.', '', 'Nomina. Pola: in the boardroom. Terkait: board of directors, board meeting.', 'Noun. Pattern: in the boardroom. Related: board of directors, board meeting.'),
  'lobby': VocabUsage('A visitor is waiting for you in the lobby.', '', 'Seorang tamu sedang menunggu Anda di lobi.', '', 'Nomina. Pola: in the lobby; hotel lobby. Sebagai verba: lobby for = melobi.', 'Noun. Pattern: in the lobby; hotel lobby. As a verb: lobby for = campaign.'),
  'elevator': VocabUsage('The elevator is out of service, so please use the stairs.', '', 'Lift sedang tidak berfungsi, jadi silakan gunakan tangga.', '', 'Nomina (AS). UK: lift. Pola: take the elevator to + lantai.', 'Noun (US). UK: lift. Pattern: take the elevator to + floor.'),
  'stairway': VocabUsage('The emergency stairway is located at the end of the corridor.', '', 'Tangga darurat terletak di ujung koridor.', '', 'Nomina. Sinonim: staircase, stairs. Kolokasi: emergency stairway.', 'Noun. Synonyms: staircase, stairs. Collocation: emergency stairway.'),
  'corridor': VocabUsage('The meeting room is the second door on the left down the corridor.', '', 'Ruang rapat adalah pintu kedua di sebelah kiri di sepanjang koridor.', '', 'Nomina. Pola: down/along the corridor. Sinonim AS: hallway.', 'Noun. Pattern: down/along the corridor. US synonym: hallway.'),
  'parking lot': VocabUsage('Employees should park in the parking lot behind the building.', '', 'Karyawan sebaiknya parkir di tempat parkir di belakang gedung.', '', 'Frasa nomina (AS). UK: car park. Pola: in the parking lot.', 'Noun phrase (US). UK: car park. Pattern: in the parking lot.'),
  'premises': VocabUsage('Smoking is not permitted anywhere on the premises.', '', 'Merokok tidak diizinkan di mana pun di lingkungan gedung.', '', 'Nomina jamak. Pola: on the premises, off the premises. Formal; sering di papan aturan.', 'Plural noun. Pattern: on/off the premises. Formal; common on signs and rules.'),
  'floor plan': VocabUsage('The architect showed us the floor plan of the new office.', '', 'Arsitek itu menunjukkan denah lantai kantor baru kepada kami.', '', 'Frasa nomina. Kolokasi: open floor plan (ruang terbuka tanpa sekat).', 'Noun phrase. Collocation: open floor plan (no partitions).'),
  'binder': VocabUsage('All the training materials are kept in a blue binder.', '', 'Semua materi pelatihan disimpan di map ring berwarna biru.', '', 'Nomina. Kolokasi: ring binder, a binder of documents. UK juga: ring file/folder.', 'Noun. Collocations: ring binder, a binder of documents. UK also: ring file/folder.'),
  'notepad': VocabUsage('He always keeps a notepad on his desk to write down ideas.', '', 'Dia selalu menaruh buku catatan kecil di mejanya untuk mencatat ide.', '', 'Nomina. Pola: write on/in a notepad. Juga nama aplikasi catatan di komputer.', 'Noun. Pattern: write on/in a notepad. Also a computer note-taking app.'),
  'sticky note': VocabUsage('She stuck a sticky note on my monitor to remind me of the meeting.', '', 'Dia menempelkan kertas tempel di monitorku untuk mengingatkan soal rapat.', '', 'Frasa nomina. Sinonim: Post-it (merek). Pola: stick a sticky note on + benda.', 'Noun phrase. Synonym: Post-it (brand). Pattern: stick a sticky note on + object.'),
  'toner': VocabUsage('The printer is running low on toner, so please order a new one.', '', 'Toner printer hampir habis, jadi tolong pesan yang baru.', '', 'Nomina tak terhitung/terhitung. Kolokasi: replace the toner, run low on toner, toner cartridge.', 'Uncountable/countable noun. Collocations: replace the toner, run low on toner, toner cartridge.'),
  'cartridge': VocabUsage('I need to replace the ink cartridge before printing the report.', '', 'Saya perlu mengganti kartrid tinta sebelum mencetak laporan.', '', 'Nomina. Kolokasi: ink/toner cartridge, replace a cartridge.', 'Noun. Collocations: ink/toner cartridge, replace a cartridge.'),
  'jammed': VocabUsage('The photocopier is jammed again, so I can\'t make copies.', '', 'Mesin fotokopi macet lagi, jadi saya tidak bisa memfotokopi.', '', 'Adjektiva/partisip. Pola: the printer is jammed; paper jam (nomina). Juga: jammed with = penuh sesak.', 'Adjective/participle. Pattern: the printer is jammed; paper jam (noun). Also: jammed with = packed.'),
  'out of order': VocabUsage('The vending machine on the second floor is out of order.', '', 'Mesin penjual otomatis di lantai dua rusak.', '', 'Frasa adjektiva untuk mesin umum (lift, mesin, telepon). Sinonim: broken, not working.', 'Adjective phrase for public machines (lifts, phones). Synonyms: broken, not working.'),
  'janitor': VocabUsage('The janitor cleans the offices every evening after staff leave.', '', 'Petugas kebersihan membersihkan kantor setiap sore setelah staf pulang.', '', 'Nomina (AS). UK: caretaker/cleaner. Sinonim formal: custodian.', 'Noun (US). UK: caretaker/cleaner. Formal synonym: custodian.'),
  'mailroom': VocabUsage('Packages for employees are delivered to the mailroom first.', '', 'Paket untuk karyawan dikirim ke ruang surat terlebih dahulu.', '', 'Nomina. Pola: in/to the mailroom. UK juga: post room.', 'Noun. Pattern: in/to the mailroom. UK also: post room.'),
  'stamp': VocabUsage('Don\'t forget to put a stamp on the envelope before mailing it.', '', 'Jangan lupa menempelkan perangko di amplop sebelum mengirimnya.', '', 'Nomina/verba. Pola: put a stamp on + N. Arti lain: stempel/cap (rubber stamp).', 'Noun/verb. Pattern: put a stamp on + N. Other meaning: rubber stamp.'),
  'proofread': VocabUsage('Please proofread the proposal carefully before sending it to the client.', '', 'Tolong koreksi naskah proposal itu dengan teliti sebelum dikirim ke klien.', '', 'Verba tak beraturan (proofread-proofread-proofread). Orangnya: proofreader. Fokus pada salah ketik/ejaan.', 'Irregular verb (same in all forms). Person: proofreader. Focuses on typos/spelling.'),
  'archive': VocabUsage('Old financial records are stored in the company archive.', '', 'Catatan keuangan lama disimpan di arsip perusahaan.', '', 'Nomina/verba. Pola: in the archive(s); archive emails/files (mengarsipkan).', 'Noun/verb. Pattern: in the archive(s); archive emails/files.'),
  'air conditioning': VocabUsage('The air conditioning in the meeting room isn\'t working properly.', '', 'Pendingin ruangan di ruang rapat tidak berfungsi dengan baik.', '', 'Nomina tak terhitung (sistemnya). Alatnya: air conditioner. Singkatan: AC/A/C.', 'Uncountable noun (the system). The unit: air conditioner. Abbreviation: AC.'),
  'cafeteria': VocabUsage('Lunch is served in the staff cafeteria from noon to 2 p.m.', '', 'Makan siang disajikan di kantin staf mulai pukul 12 hingga 2 siang.', '', 'Nomina. Kolokasi: staff/company cafeteria. Sistem swalayan; UK juga canteen.', 'Noun. Collocations: staff/company cafeteria. Self-service; UK also canteen.'),
  'vending machine': VocabUsage('You can buy drinks from the vending machine near the elevators.', '', 'Anda bisa membeli minuman dari mesin penjual otomatis di dekat lift.', '', 'Frasa nomina. Pola: buy something from a vending machine.', 'Noun phrase. Pattern: buy something from a vending machine.'),
  'handbook': VocabUsage('All company policies are explained in the employee handbook.', '', 'Semua kebijakan perusahaan dijelaskan di buku pegangan karyawan.', '', 'Nomina. Kolokasi: employee/staff handbook. Sinonim: manual, guide.', 'Noun. Collocations: employee/staff handbook. Synonyms: manual, guide.'),
  'announcement': VocabUsage('The CEO will make an important announcement at this afternoon\'s meeting.', '', 'CEO akan menyampaikan pengumuman penting pada rapat sore ini.', '', 'Nomina. Kolokasi: make an announcement (bukan do). Verba: announce.', 'Noun. Collocation: make an announcement (not do). Verb: announce.'),
  'newsletter': VocabUsage('Our monthly newsletter keeps employees informed about company news.', '', 'Buletin bulanan kami memberi kabar terbaru tentang perusahaan kepada karyawan.', '', 'Nomina. Kolokasi: monthly/weekly newsletter; subscribe to a newsletter.', 'Noun. Collocations: monthly/weekly newsletter; subscribe to a newsletter.'),
  'confidential': VocabUsage('This information is strictly confidential and must not be shared.', '', 'Informasi ini sangat rahasia dan tidak boleh dibagikan.', '', 'Adjektiva. Kolokasi: strictly confidential, confidential documents. Nomina: confidentiality.', 'Adjective. Collocations: strictly confidential, confidential documents. Noun: confidentiality.'),
  'urgent': VocabUsage('Please reply as soon as possible because the matter is urgent.', '', 'Mohon segera balas karena masalah ini mendesak.', '', 'Adjektiva. Kolokasi: urgent matter/request; it is urgent that + klausa. Nomina: urgency.', 'Adjective. Collocations: urgent matter/request; it is urgent that + clause. Noun: urgency.'),
  'approve': VocabUsage('The manager must approve all expenses over five hundred dollars.', '', 'Manajer harus menyetujui semua pengeluaran di atas lima ratus dolar.', '', 'Verba. Transitif: approve a budget/request; approve of = setuju secara moral. Nomina: approval.', 'Verb. Transitive: approve a budget/request; approve of = think well of. Noun: approval.'),
  'permit': VocabUsage('You need a building permit before starting any construction work.', '', 'Anda memerlukan izin mendirikan bangunan sebelum memulai pekerjaan konstruksi.', '', 'Nomina (dokumen): work/parking permit; apply for a permit. Sebagai verba (izinkan) tekanan di suku kedua.', 'Noun (document): work/parking permit; apply for a permit. As a verb, stress shifts to the second syllable.'),
  'workflow': VocabUsage('The new software has made our workflow much more efficient.', '', 'Perangkat lunak baru telah membuat alur kerja kami jauh lebih efisien.', '', 'Nomina. Kolokasi: improve/streamline the workflow, workflow management.', 'Noun. Collocations: improve/streamline the workflow, workflow management.'),
  'bottleneck': VocabUsage('Slow approval from the finance team is the main bottleneck in the process.', '', 'Persetujuan yang lambat dari tim keuangan adalah hambatan utama dalam proses itu.', '', 'Nomina. Pola: a bottleneck in + proses; cause/remove a bottleneck.', 'Noun. Pattern: a bottleneck in + process; cause/remove a bottleneck.'),
  'backlog': VocabUsage('We hired two temporary staff to clear the backlog of orders.', '', 'Kami merekrut dua staf sementara untuk menyelesaikan tumpukan pesanan yang tertunda.', '', 'Nomina. Pola: a backlog of + N; clear/reduce the backlog.', 'Noun. Pattern: a backlog of + N; clear/reduce the backlog.'),
  'progress': VocabUsage('The team leader reports on the project\'s progress every Monday.', '', 'Ketua tim melaporkan kemajuan proyek setiap hari Senin.', '', 'Nomina tak terhitung (bukan a progress). Kolokasi: make progress, progress report, in progress.', 'Uncountable noun (not a progress). Collocations: make progress, progress report, in progress.'),
  'milestone': VocabUsage('Launching the mobile app was an important milestone for the company.', '', 'Peluncuran aplikasi seluler adalah tonggak pencapaian penting bagi perusahaan.', '', 'Nomina. Kolokasi: reach/achieve a milestone; a major/key milestone.', 'Noun. Collocations: reach/achieve a milestone; a major/key milestone.'),
  'business hours': VocabUsage('Our customer service team is available during normal business hours.', '', 'Tim layanan pelanggan kami siap membantu selama jam kerja kantor biasa.', '', 'Frasa nomina jamak. Pola: during/outside business hours. Sinonim: office hours, opening hours.', 'Plural noun phrase. Pattern: during/outside business hours. Synonyms: office hours, opening hours.'),
  'weekday': VocabUsage('The office is open from 8 a.m. to 5 p.m. on weekdays.', '', 'Kantor buka mulai pukul 8 pagi hingga 5 sore pada hari kerja.', '', 'Nomina. Pola: on weekdays; weekday mornings. Lawan: weekend.', 'Noun. Pattern: on weekdays; weekday mornings. Opposite: weekend.'),
  'workload': VocabUsage('My workload has increased since two colleagues left the department.', '', 'Beban kerja saya bertambah sejak dua rekan keluar dari departemen.', '', 'Nomina. Kolokasi: a heavy/light workload, manage/reduce the workload.', 'Noun. Collocations: a heavy/light workload, manage/reduce the workload.'),
  'coworker': VocabUsage('I often have lunch with my coworkers in the cafeteria.', '', 'Saya sering makan siang bersama rekan sekantor di kantin.', '', 'Nomina, juga co-worker. Sinonim: colleague (lebih formal).', 'Noun, also co-worker. Synonym: colleague (more formal).'),
  'fill out': VocabUsage('Please fill out the registration form and return it to reception.', '', 'Silakan isi formulir pendaftaran dan kembalikan ke resepsionis.', '', 'Phrasal verb: fill out + form/application. Di Inggris Britania sering \'fill in\'.', 'Phrasal verb: fill out + form/application. British English often uses \'fill in\'.'),
  'hand in': VocabUsage('All employees must hand in their expense reports by Friday.', '', 'Semua karyawan harus menyerahkan laporan pengeluaran paling lambat Jumat.', '', 'Phrasal verb: hand in + report/assignment/resignation. Mirip \'submit\' tapi lebih santai.', 'Phrasal verb: hand in + report/assignment/resignation. Like \'submit\' but less formal.'),
  'board of directors': VocabUsage('The board of directors approved the new budget at its annual meeting.', '', 'Dewan direksi menyetujui anggaran baru dalam rapat tahunannya.', '', 'Frasa benda; dianggap satu kelompok. Kolokasi: the board approved/meets; sit on the board.', 'Noun phrase for one body. Collocations: the board approved/meets; sit on the board.'),
  'chairperson': VocabUsage('The chairperson opened the meeting by reviewing the agenda.', '', 'Ketua membuka rapat dengan meninjau agenda.', '', 'Kata benda netral gender untuk \'chairman/chairwoman\'; sering disingkat \'chair\'.', 'Gender-neutral noun for chairman/chairwoman; often shortened to \'chair\'.'),
  'executive': VocabUsage('Several senior executives will attend the product launch next week.', '', 'Beberapa eksekutif senior akan menghadiri peluncuran produk minggu depan.', '', 'Kata benda; juga adjektiva: executive office/decision. Pola: chief executive officer (CEO).', 'Noun; also adjective: executive office/decision. Pattern: chief executive officer (CEO).'),
  'supervisor': VocabUsage('Report any safety problems to your supervisor immediately.', '', 'Laporkan masalah keselamatan apa pun kepada atasan Anda segera.', '', 'Kata benda; verba: supervise. Pola: report to a supervisor; shift supervisor.', 'Noun; verb: supervise. Patterns: report to a supervisor; shift supervisor.'),
  'personnel': VocabUsage('Only authorized personnel are allowed to enter the server room.', '', 'Hanya staf berwenang yang boleh memasuki ruang server.', '', 'Kata benda jamak (pakai \'are\'). Jangan tertukar dengan \'personal\' (pribadi).', 'Plural noun (takes \'are\'). Don\'t confuse with \'personal\' (private).'),
  'shareholder': VocabUsage('The company pays dividends to its shareholders twice a year.', '', 'Perusahaan membayar dividen kepada pemegang sahamnya dua kali setahun.', '', 'Kata benda; sinonim AS: stockholder. Kolokasi: shareholder meeting, major shareholder.', 'Noun; US synonym: stockholder. Collocations: shareholder meeting, major shareholder.'),
  'stakeholder': VocabUsage('We consulted all stakeholders before changing the delivery schedule.', '', 'Kami berkonsultasi dengan semua pemangku kepentingan sebelum mengubah jadwal pengiriman.', '', 'Kata benda; lebih luas dari shareholder: karyawan, pelanggan, pemasok, dll. ikut terhitung.', 'Noun; broader than shareholder: staff, customers, suppliers, etc. are included.'),
  'subsidiary': VocabUsage('The firm opened a subsidiary in Singapore to serve Asian clients.', '', 'Firma itu membuka anak perusahaan di Singapura untuk melayani klien Asia.', '', 'Kata benda; lawan: parent company. Pola: a subsidiary of [company].', 'Noun; opposite: parent company. Pattern: a subsidiary of [company].'),
  'merger': VocabUsage('The merger between the two banks was completed last month.', '', 'Penggabungan kedua bank itu selesai bulan lalu.', '', 'Kata benda dari verba \'merge\'. Sering dipasangkan: mergers and acquisitions (M&A).', 'Noun from \'merge\'. Common pair: mergers and acquisitions (M&A).'),
  'firm': VocabUsage('She works as a consultant for a large accounting firm.', '', 'Ia bekerja sebagai konsultan di sebuah firma akuntansi besar.', '', 'Kata benda untuk perusahaan jasa: law/accounting/consulting firm. Sebagai adjektiva = kokoh.', 'Noun for service companies: law/accounting/consulting firm. As adjective = solid.'),
  'enterprise': VocabUsage('The software is designed for small and medium-sized enterprises.', '', 'Perangkat lunak itu dirancang untuk usaha kecil dan menengah.', '', 'Kata benda formal; kolokasi: small and medium-sized enterprises (SMEs), state enterprise.', 'Formal noun; collocations: small and medium-sized enterprises (SMEs), state enterprise.'),
  'joint venture': VocabUsage('The two companies formed a joint venture to build the new factory.', '', 'Kedua perusahaan membentuk usaha patungan untuk membangun pabrik baru.', '', 'Frasa benda; kolokasi: form/enter into a joint venture with [company].', 'Noun phrase; collocations: form/enter into a joint venture with [company].'),
  'downsize': VocabUsage('The company had to downsize after losing its biggest client.', '', 'Perusahaan harus mengurangi jumlah karyawan setelah kehilangan klien terbesarnya.', '', 'Verba (intransitif/transitif); nomina: downsizing. Lebih halus daripada \'lay off\'.', 'Verb (with or without object); noun: downsizing. Softer than \'lay off\'.'),
  'streamline': VocabUsage('We need to streamline the approval process to save time.', '', 'Kita perlu merampingkan proses persetujuan untuk menghemat waktu.', '', 'Verba: streamline + process/procedure/operations. Adjektiva: streamlined.', 'Verb: streamline + process/procedure/operations. Adjective: streamlined.'),
  'in charge of': VocabUsage('Mr. Lee is in charge of the marketing department.', '', 'Pak Lee bertanggung jawab atas departemen pemasaran.', '', 'Frasa: be in charge of + noun/-ing. Pola lain: put someone in charge of.', 'Phrase: be in charge of + noun/-ing. Also: put someone in charge of.'),
  'report to': VocabUsage('All sales staff report to the regional manager.', '', 'Semua staf penjualan melapor kepada manajer regional.', '', 'Verba frasa: report to + atasan (menunjukkan hierarki). Beda dengan \'report on\' = melaporkan hal.', 'Phrasal verb: report to + boss (shows hierarchy). \'Report on\' means describe a topic.'),
  'take over': VocabUsage('A new manager will take over the project next month.', '', 'Manajer baru akan mengambil alih proyek itu bulan depan.', '', 'Phrasal verb: take over + tugas/perusahaan. Nomina: takeover (pengambilalihan).', 'Phrasal verb: take over + role/company. Noun: takeover.'),
  'oversee': VocabUsage('She oversees the daily operations of the warehouse.', '', 'Ia mengawasi operasional harian gudang.', '', 'Verba tak beraturan: oversee-oversaw-overseen. Kolokasi: oversee operations/a project.', 'Irregular verb: oversee-oversaw-overseen. Collocations: oversee operations/a project.'),
  'delegate': VocabUsage('Good managers know how to delegate tasks to their team.', '', 'Manajer yang baik tahu cara mendelegasikan tugas kepada timnya.', '', 'Verba: delegate + task + to + orang. Sebagai nomina = utusan; nomina proses: delegation.', 'Verb: delegate + task + to + person. As noun = representative; process noun: delegation.'),
  'understaffed': VocabUsage('The clinic is understaffed, so patients often wait for hours.', '', 'Klinik itu kekurangan staf, jadi pasien sering menunggu berjam-jam.', '', 'Adjektiva; sinonim: short-staffed. Lawan: overstaffed.', 'Adjective; synonym: short-staffed. Opposite: overstaffed.'),
  'minutes': VocabUsage('Could you take the minutes at today\'s meeting?', '', 'Bisakah kamu membuat notulen rapat hari ini?', '', 'Selalu jamak dalam arti ini. Kolokasi: take/keep the minutes; approve the minutes.', 'Always plural in this sense. Collocations: take/keep the minutes; approve the minutes.'),
  'appointment': VocabUsage('I have an appointment with the client at two o\'clock.', '', 'Saya ada janji temu dengan klien pukul dua.', '', 'Kata benda: make/book/cancel an appointment with. Beda: \'meeting\' untuk rapat kelompok.', 'Noun: make/book/cancel an appointment with. \'Meeting\' is used for group discussions.'),
  'postpone': VocabUsage('The conference has been postponed until next spring.', '', 'Konferensi itu ditunda hingga musim semi mendatang.', '', 'Verba: postpone + noun/-ing + until/to. Beda: \'cancel\' = membatalkan sama sekali.', 'Verb: postpone + noun/-ing + until/to. \'Cancel\' means call off entirely.'),
  'attendee': VocabUsage('Each attendee will receive a name badge at the entrance.', '', 'Setiap peserta akan menerima tanda nama di pintu masuk.', '', 'Kata benda dari \'attend\' (tanpa \'to\'). Akhiran -ee = orang yang menerima/melakukan.', 'Noun from \'attend\' (no \'to\'). Suffix -ee marks the person involved.'),
  'seminar': VocabUsage('The company held a seminar on workplace safety for new staff.', '', 'Perusahaan mengadakan seminar tentang keselamatan kerja untuk staf baru.', '', 'Kata benda: hold/attend a seminar on + topik.', 'Noun: hold/attend a seminar on + topic.'),
  'webinar': VocabUsage('Over five hundred people registered for yesterday\'s marketing webinar.', '', 'Lebih dari lima ratus orang mendaftar webinar pemasaran kemarin.', '', 'Kata benda (web + seminar). Kolokasi: host/join/register for a webinar.', 'Noun (web + seminar). Collocations: host/join/register for a webinar.'),
  'adjourn': VocabUsage('The chair adjourned the meeting until Thursday morning.', '', 'Ketua menutup rapat untuk sementara hingga Kamis pagi.', '', 'Verba formal: adjourn + meeting + until. Bisa pasif: The meeting was adjourned.', 'Formal verb: adjourn + meeting + until. Often passive: The meeting was adjourned.'),
  'brainstorm': VocabUsage('Let\'s brainstorm some ideas for the holiday campaign.', '', 'Mari kita curah pendapat beberapa ide untuk kampanye liburan.', '', 'Verba & nomina: brainstorm ideas; hold a brainstorming session.', 'Verb and noun: brainstorm ideas; hold a brainstorming session.'),
  'consensus': VocabUsage('After a long discussion, the team finally reached a consensus.', '', 'Setelah diskusi panjang, tim akhirnya mencapai kesepakatan bersama.', '', 'Kata benda: reach/build a consensus on. Hindari \'general consensus of opinion\' (berlebihan).', 'Noun: reach/build a consensus on. Avoid \'consensus of opinion\' (redundant).'),
  'vote': VocabUsage('Members will vote on the proposal at the end of the meeting.', '', 'Para anggota akan memberi suara atas proposal itu di akhir rapat.', '', 'Verba & nomina: vote on/for/against; take a vote; cast a vote.', 'Verb and noun: vote on/for/against; take a vote; cast a vote.'),
  'motion': VocabUsage('The motion to increase the training budget was passed unanimously.', '', 'Usul untuk menaikkan anggaran pelatihan disetujui dengan suara bulat.', '', 'Kata benda rapat formal: propose/second/pass/reject a motion.', 'Formal meeting noun: propose/second/pass/reject a motion.'),
  'handout': VocabUsage('Please read the handout before we start the presentation.', '', 'Silakan baca bahan bagikan sebelum kita mulai presentasi.', '', 'Kata benda dari \'hand out\' (membagikan). Kolokasi: distribute/give out handouts.', 'Noun from \'hand out\' (distribute). Collocations: distribute/give out handouts.'),
  'keynote speech': VocabUsage('The CEO will deliver the keynote speech at the conference.', '', 'CEO akan menyampaikan pidato utama di konferensi.', '', 'Frasa benda: give/deliver a keynote speech. Pembicaranya: keynote speaker.', 'Noun phrase: give/deliver a keynote speech. The person: keynote speaker.'),
  'speaker': VocabUsage('Our guest speaker has twenty years of experience in retail.', '', 'Pembicara tamu kita memiliki pengalaman dua puluh tahun di bidang ritel.', '', 'Kata benda; kolokasi: guest/keynote speaker. Juga berarti pengeras suara.', 'Noun; collocations: guest/keynote speaker. Also means loudspeaker.'),
  'take notes': VocabUsage('Remember to take notes during the training session.', '', 'Ingat untuk mencatat selama sesi pelatihan.', '', 'Frasa verba: take notes on + topik. Bentuk lain: make a note of (mencatat satu hal).', 'Verb phrase: take notes on + topic. Also: make a note of (note one thing).'),
  'follow up': VocabUsage('I will follow up with the supplier about the late delivery.', '', 'Saya akan menindaklanjuti pemasok soal pengiriman yang terlambat.', '', 'Phrasal verb: follow up on + hal / with + orang. Nomina/adj: follow-up (pakai tanda hubung).', 'Phrasal verb: follow up on + issue / with + person. Noun/adj: follow-up (hyphenated).'),
  'touch base': VocabUsage('Let\'s touch base on Monday to discuss the next steps.', '', 'Mari kita berkabar singkat hari Senin untuk membahas langkah berikutnya.', '', 'Idiom kantor informal: touch base with + orang. Untuk kontak singkat, bukan rapat panjang.', 'Informal office idiom: touch base with + person. For brief contact, not long meetings.'),
  'get back to': VocabUsage('I\'ll get back to you with the figures by tomorrow afternoon.', '', 'Saya akan menghubungi Anda kembali dengan angka-angkanya paling lambat besok sore.', '', 'Phrasal verb: get back to + orang (+ with/on + hal). Umum di email dan telepon.', 'Phrasal verb: get back to + person (+ with/on + matter). Common in emails and calls.'),
  'run late': VocabUsage('Sorry, the previous meeting is running late, so I\'ll join soon.', '', 'Maaf, rapat sebelumnya terlambat dari jadwal, jadi saya akan segera bergabung.', '', 'Frasa verba, biasanya bentuk progresif: be running late. Subjek bisa orang atau acara.', 'Verb phrase, usually progressive: be running late. Subject can be a person or event.'),
  'ahead of time': VocabUsage('Please send your slides ahead of time so we can test them.', '', 'Tolong kirim slide Anda lebih awal agar kami bisa mengujinya.', '', 'Frasa keterangan; sinonim: in advance, beforehand. Biasanya di akhir kalimat.', 'Adverbial phrase; synonyms: in advance, beforehand. Usually at the end of a clause.'),
  'in advance': VocabUsage('Tickets must be booked at least two weeks in advance.', '', 'Tiket harus dipesan setidaknya dua minggu sebelumnya.', '', 'Frasa keterangan: [waktu] in advance; in advance of + noun. Juga: thank you in advance.', 'Adverbial: [time] in advance; in advance of + noun. Also: thank you in advance.'),
  'convenient': VocabUsage('Would Tuesday at ten be convenient for you?', '', 'Apakah Selasa pukul sepuluh cocok untuk Anda?', '', 'Adjektiva: convenient for + orang. Subjeknya waktu/tempat, bukan orang (\'I am convenient\' salah).', 'Adjective: convenient for + person. Subject is a time/place, not a person.'),
  'in person': VocabUsage('The manager prefers to interview candidates in person.', '', 'Manajer lebih suka mewawancarai kandidat secara langsung.', '', 'Frasa keterangan; lawan: online/by phone. Adjektiva: an in-person meeting.', 'Adverbial; opposite: online/by phone. Adjective: an in-person meeting.'),
  'tentative': VocabUsage('We have a tentative date for the launch, but it may change.', '', 'Kami sudah punya tanggal sementara untuk peluncuran, tapi bisa berubah.', '', 'Adjektiva: tentative plan/date/agreement. Adverbia: tentatively scheduled.', 'Adjective: tentative plan/date/agreement. Adverb: tentatively scheduled.'),
  'rehearsal': VocabUsage('There will be a full rehearsal the day before the ceremony.', '', 'Akan ada gladi lengkap sehari sebelum upacara.', '', 'Kata benda dari \'rehearse\'. Kolokasi: dress/final rehearsal.', 'Noun from \'rehearse\'. Collocations: dress/final rehearsal.'),
  'go over': VocabUsage('Let\'s go over the contract once more before we sign it.', '', 'Mari kita periksa ulang kontraknya sekali lagi sebelum menandatanganinya.', '', 'Phrasal verb: go over + dokumen/rincian. Sinonim formal: review.', 'Phrasal verb: go over + document/details. Formal synonym: review.'),
  'point out': VocabUsage('The auditor pointed out several errors in the report.', '', 'Auditor menunjukkan beberapa kesalahan dalam laporan itu.', '', 'Phrasal verb: point out + noun / point out that + klausa. Untuk menyoroti fakta/masalah.', 'Phrasal verb: point out + noun / that + clause. Used to highlight facts or problems.'),
  'come up with': VocabUsage('The team came up with a creative solution to the problem.', '', 'Tim itu mencetuskan solusi kreatif untuk masalah tersebut.', '', 'Phrasal verb 3 kata: come up with + idea/plan/solution. Tidak bisa dipisah.', 'Three-word phrasal verb: come up with + idea/plan/solution. Inseparable.'),
  'go ahead': VocabUsage('If the budget is approved, we can go ahead with the project.', '', 'Jika anggaran disetujui, kita bisa melanjutkan proyek itu.', '', 'Phrasal verb: go ahead with + rencana. Nomina: get the go-ahead (mendapat izin).', 'Phrasal verb: go ahead with + plan. Noun: get the go-ahead (permission).'),
  'take place': VocabUsage('The annual meeting will take place in the main hall.', '', 'Rapat tahunan akan berlangsung di aula utama.', '', 'Frasa verba intransitif, tidak bisa pasif. Subjek: event/meeting. Sinonim: be held.', 'Intransitive, never passive. Subject: event/meeting. Synonym: be held.'),
  'look forward to': VocabUsage('We look forward to working with you on this project.', '', 'Kami menantikan kerja sama dengan Anda dalam proyek ini.', '', 'Diikuti noun atau -ing (bukan to + verba dasar): look forward to hearing from you.', 'Followed by a noun or -ing, not base verb: look forward to hearing from you.'),
  'feasible': VocabUsage('The engineers think the plan is technically feasible.', '', 'Para insinyur menilai rencana itu layak secara teknis.', '', 'Adjektiva: technically/economically feasible. Nomina: feasibility study.', 'Adjective: technically/economically feasible. Noun: feasibility study.'),
  'proposal': VocabUsage('Please submit your proposal to the committee by the end of May.', '', 'Silakan serahkan proposal Anda kepada komite paling lambat akhir Mei.', '', 'Kata benda: submit/reject/approve a proposal; proposal for + hal. Verba: propose.', 'Noun: submit/reject/approve a proposal; proposal for + thing. Verb: propose.'),
  'applicant': VocabUsage('Each applicant must provide two references from previous employers.', '', 'Setiap pelamar harus menyertakan dua referensi dari pemberi kerja sebelumnya.', '', 'Kata benda dari \'apply for\'. Pola: applicant for + position/job.', 'Noun from \'apply for\'. Pattern: applicant for + position/job.'),
  'résumé': VocabUsage('Please attach your résumé when you apply online.', '', 'Silakan lampirkan riwayat hidup Anda saat melamar secara daring.', '', 'Kata benda (AS), sering ditulis resume. Di Inggris: CV. Kolokasi: send/update your résumé.', 'Noun (US), often spelled resume. British: CV. Collocations: send/update your résumé.'),
  'recruit': VocabUsage('The hotel plans to recruit thirty new staff before the holidays.', '', 'Hotel itu berencana merekrut tiga puluh staf baru sebelum musim liburan.', '', 'Verba & nomina (a new recruit = pegawai baru). Nomina proses: recruitment.', 'Verb and noun (a new recruit). Process noun: recruitment.'),
  'hire': VocabUsage('We decided to hire an experienced designer for the project.', '', 'Kami memutuskan mempekerjakan desainer berpengalaman untuk proyek itu.', '', 'Verba: hire + orang. Nomina: a new hire. Di Inggris \'hire\' juga = menyewa (hire a car).', 'Verb: hire + person. Noun: a new hire. In British English also = rent (hire a car).'),
  'resign': VocabUsage('He resigned from his position to start his own business.', '', 'Ia mengundurkan diri dari jabatannya untuk memulai usaha sendiri.', '', 'Verba: resign from/as + jabatan. Nomina: resignation (letter of resignation).', 'Verb: resign from/as + post. Noun: resignation (letter of resignation).'),
  'probation': VocabUsage('New employees are on probation for the first three months.', '', 'Karyawan baru menjalani masa percobaan selama tiga bulan pertama.', '', 'Kata benda: be on probation; probation period / probationary period.', 'Noun: be on probation; probation period / probationary period.'),
  'performance': VocabUsage('Your bonus depends on your performance during the year.', '', 'Bonus Anda bergantung pada kinerja Anda selama setahun.', '', 'Kata benda: job/sales performance; performance review. Verba: perform well/poorly.', 'Noun: job/sales performance; performance review. Verb: perform well/poorly.'),
  'payroll': VocabUsage('The new assistant was added to the payroll last week.', '', 'Asisten baru itu dimasukkan ke daftar gaji minggu lalu.', '', 'Kata benda: on the payroll; payroll department/system. Juga = total biaya gaji.', 'Noun: on the payroll; payroll department/system. Also = total wage cost.'),
  'vacancy': VocabUsage('There is a vacancy for a receptionist at our downtown branch.', '', 'Ada lowongan untuk resepsionis di cabang kami di pusat kota.', '', 'Kata benda: a vacancy for + posisi; fill a vacancy. Juga = kamar kosong (hotel).', 'Noun: a vacancy for + post; fill a vacancy. Also = free room (hotel).'),
  'candidate': VocabUsage('We interviewed five candidates for the sales manager position.', '', 'Kami mewawancarai lima kandidat untuk posisi manajer penjualan.', '', 'Kata benda: candidate for + posisi; ideal/suitable candidate.', 'Noun: candidate for + position; ideal/suitable candidate.'),
  'qualification': VocabUsage('A degree in finance is the main qualification for this job.', '', 'Gelar di bidang keuangan adalah kualifikasi utama untuk pekerjaan ini.', '', 'Kata benda, sering jamak. Kolokasi: have/meet the qualifications. Adj: qualified.', 'Noun, often plural. Collocations: have/meet the qualifications. Adj: qualified.'),
  'credentials': VocabUsage('The consultant showed us her professional credentials before the meeting.', '', 'Konsultan itu menunjukkan bukti kualifikasi profesionalnya sebelum rapat.', '', 'Kata benda jamak: impressive/academic credentials. Juga = data login (username/password).', 'Plural noun: impressive/academic credentials. Also = login details.'),
  'reference letter': VocabUsage('My former manager agreed to write a reference letter for me.', '', 'Mantan manajer saya setuju menulis surat rekomendasi untuk saya.', '', 'Frasa benda: write a reference letter for + orang. Sinonim: letter of recommendation.', 'Noun phrase: write a reference letter for + person. Synonym: letter of recommendation.'),
  'cover letter': VocabUsage('A strong cover letter explains why you want the job.', '', 'Surat lamaran yang kuat menjelaskan mengapa Anda menginginkan pekerjaan itu.', '', 'Frasa benda; dikirim bersama résumé/CV. Inggris Britania: covering letter.', 'Noun phrase sent with a résumé/CV. British: covering letter.'),
  'experienced': VocabUsage('We are looking for an experienced accountant to lead the team.', '', 'Kami mencari akuntan berpengalaman untuk memimpin tim.', '', 'Adjektiva: experienced in + bidang/-ing. Lawan: inexperienced.', 'Adjective: experienced in + field/-ing. Opposite: inexperienced.'),
  'full-time': VocabUsage('She accepted a full-time position at the head office.', '', 'Ia menerima posisi penuh waktu di kantor pusat.', '', 'Adjektiva (full-time job) dan adverbia (work full-time). Pakai tanda hubung.', 'Adjective (full-time job) and adverb (work full-time). Hyphenated.'),
  'part-time': VocabUsage('Many students take part-time jobs to pay for their studies.', '', 'Banyak mahasiswa mengambil pekerjaan paruh waktu untuk membiayai kuliah.', '', 'Adjektiva/adverbia: part-time job; work part-time. Lawan: full-time.', 'Adjective/adverb: part-time job; work part-time. Opposite: full-time.'),
  'permanent': VocabUsage('After one year, he was offered a permanent contract.', '', 'Setelah satu tahun, ia ditawari kontrak tetap.', '', 'Adjektiva: permanent contract/position/staff. Lawan: temporary.', 'Adjective: permanent contract/position/staff. Opposite: temporary.'),
  'employment': VocabUsage('The factory provides employment for over two thousand local residents.', '', 'Pabrik itu menyediakan lapangan kerja bagi lebih dari dua ribu warga setempat.', '', 'Kata benda tak terhitung: full-time employment; employment contract. Lawan: unemployment.', 'Uncountable noun: full-time employment; employment contract. Opposite: unemployment.'),
  'workplace': VocabUsage('The company is working to create a safer workplace for everyone.', '', 'Perusahaan sedang berupaya menciptakan tempat kerja yang lebih aman bagi semua orang.', '', 'Kata benda: in the workplace; workplace safety/culture.', 'Noun: in the workplace; workplace safety/culture.'),
  'onboarding': VocabUsage('Our onboarding program helps new hires learn the company systems.', '', 'Program penerimaan karyawan baru kami membantu mereka mempelajari sistem perusahaan.', '', 'Kata benda (dari \'onboard\'). Kolokasi: onboarding process/program/session.', 'Noun (from \'onboard\'). Collocations: onboarding process/program/session.'),
  'trainee': VocabUsage('Each trainee is assigned to a different department every month.', '', 'Setiap peserta pelatihan ditempatkan di departemen berbeda setiap bulan.', '', 'Kata benda (-ee = yang dilatih); pelatihnya: trainer. Kolokasi: management trainee.', 'Noun (-ee = person trained); the teacher is a trainer. Collocation: management trainee.'),
  'mentor': VocabUsage('A senior engineer acts as a mentor to new team members.', '', 'Seorang insinyur senior bertindak sebagai mentor bagi anggota tim baru.', '', 'Kata benda & verba (mentor someone). Orang yang dibimbing: mentee.', 'Noun and verb (mentor someone). The person guided: mentee.'),
  'appraisal': VocabUsage('Staff have their annual appraisal with their manager every December.', '', 'Staf menjalani penilaian kinerja tahunan dengan manajer setiap Desember.', '', 'Kata benda: annual/performance appraisal. Juga = penaksiran nilai (property appraisal).', 'Noun: annual/performance appraisal. Also = valuation (property appraisal).'),
  'raise': VocabUsage('She asked her boss for a raise after the successful project.', '', 'Ia meminta kenaikan gaji kepada atasannya setelah proyek yang sukses.', '', 'Kata benda (AS): ask for/get a raise. Inggris Britania: pay rise.', 'Noun (US): ask for/get a raise. British: pay rise.'),
  'bonus': VocabUsage('All staff received a year-end bonus for meeting the sales target.', '', 'Semua staf menerima bonus akhir tahun karena mencapai target penjualan.', '', 'Kata benda: year-end/performance bonus; receive/pay a bonus.', 'Noun: year-end/performance bonus; receive/pay a bonus.'),
  'pay slip': VocabUsage('Check your pay slip to see how much tax was deducted.', '', 'Periksa slip gaji Anda untuk melihat berapa pajak yang dipotong.', '', 'Frasa benda (Inggris Britania); AS: pay stub. Berisi gaji kotor, potongan, gaji bersih.', 'Noun phrase (British); US: pay stub. Shows gross pay, deductions and net pay.'),
  'payday': VocabUsage('Payday is on the twenty-fifth of every month.', '', 'Hari gajian jatuh pada tanggal dua puluh lima setiap bulan.', '', 'Kata benda, ditulis satu kata. Pola: on payday; payday is on + tanggal.', 'Noun, written as one word. Pattern: on payday; payday is on + date.'),
  'dismiss': VocabUsage('The employee was dismissed for repeatedly breaking safety rules.', '', 'Karyawan itu diberhentikan karena berulang kali melanggar aturan keselamatan.', '', 'Verba formal (sering pasif): be dismissed for + alasan. Nomina: dismissal. Informal: fire.', 'Formal verb, often passive: be dismissed for + reason. Noun: dismissal. Informal: fire.'),
  'lay off': VocabUsage('The factory laid off two hundred workers due to falling orders.', '', 'Pabrik itu mem-PHK dua ratus pekerja karena pesanan menurun.', '', 'Phrasal verb: lay off + pekerja (karena kondisi bisnis, bukan kesalahan). Nomina: layoff.', 'Phrasal verb: lay off + workers (business reasons, not misconduct). Noun: layoff.'),
  'retire': VocabUsage('My father plans to retire when he turns sixty.', '', 'Ayah saya berencana pensiun saat berusia enam puluh tahun.', '', 'Verba intransitif: retire from + pekerjaan. Nomina: retirement; adj: retired.', 'Intransitive verb: retire from + job. Noun: retirement; adj: retired.'),
  'shortlist': VocabUsage('Only six applicants made it onto the shortlist.', '', 'Hanya enam pelamar yang masuk daftar pendek kandidat.', '', 'Nomina & verba: be shortlisted for + posisi; draw up a shortlist.', 'Noun and verb: be shortlisted for + post; draw up a shortlist.'),
  'turn down': VocabUsage('She turned down the job offer because the salary was too low.', '', 'Ia menolak tawaran kerja itu karena gajinya terlalu rendah.', '', 'Phrasal verb: turn down + offer/request/invitation. Lebih santai dari \'decline/reject\'.', 'Phrasal verb: turn down + offer/request/invitation. Less formal than decline/reject.'),
  'step down': VocabUsage('The CEO will step down at the end of the year.', '', 'CEO akan mundur dari jabatannya pada akhir tahun.', '', 'Phrasal verb: step down as/from + jabatan. Mirip resign, khusus posisi tinggi.', 'Phrasal verb: step down as/from + post. Like resign, for senior roles.'),
  'morale': VocabUsage('Staff morale improved after the new flexible hours were introduced.', '', 'Semangat kerja staf meningkat setelah jam kerja fleksibel diberlakukan.', '', 'Kata benda: boost/raise/low morale. Jangan tertukar dengan \'moral\' (moral/etika).', 'Noun: boost/raise/low morale. Don\'t confuse with \'moral\' (ethics).'),
  'dedicated': VocabUsage('The project succeeded thanks to a small but dedicated team.', '', 'Proyek itu berhasil berkat tim kecil yang berdedikasi.', '', 'Adjektiva: dedicated to + noun/-ing. Juga = khusus (a dedicated server).', 'Adjective: dedicated to + noun/-ing. Also = reserved for one use (a dedicated server).'),
  'diligent': VocabUsage('He is a diligent worker who always checks the details.', '', 'Ia pekerja rajin yang selalu memeriksa detail.', '', 'Adjektiva formal: diligent worker/student. Nomina: diligence; adv: diligently.', 'Formal adjective: diligent worker/student. Noun: diligence; adverb: diligently.'),
  'punctual': VocabUsage('Please be punctual, as the meeting will start exactly at nine.', '', 'Harap tepat waktu, karena rapat akan dimulai tepat pukul sembilan.', '', 'Adjektiva untuk orang/pembayaran: be punctual for + acara. Nomina: punctuality.', 'Adjective for people/payments: be punctual for + event. Noun: punctuality.'),
  'competent': VocabUsage('We need a competent engineer to manage the installation.', '', 'Kami membutuhkan insinyur yang cakap untuk mengelola instalasi.', '', 'Adjektiva: competent at/in + bidang. Nomina: competence. Lawan: incompetent.', 'Adjective: competent at/in + field. Noun: competence. Opposite: incompetent.'),
  'leadership': VocabUsage('The company offers leadership training for new managers.', '', 'Perusahaan menawarkan pelatihan kepemimpinan untuk manajer baru.', '', 'Kata benda tak terhitung: leadership skills/qualities; under the leadership of.', 'Uncountable noun: leadership skills/qualities; under the leadership of.'),
  'collaborate': VocabUsage('Our designers collaborate closely with the engineering team.', '', 'Para desainer kami bekerja sama erat dengan tim teknik.', '', 'Verba: collaborate with + orang / on + proyek. Nomina: collaboration.', 'Verb: collaborate with + person / on + project. Noun: collaboration.'),
  'remote work': VocabUsage('Remote work allows employees to save time on commuting.', '', 'Kerja jarak jauh memungkinkan karyawan menghemat waktu perjalanan.', '', 'Frasa benda tak terhitung. Verba: work remotely. Sinonim: working from home (WFH).', 'Uncountable noun phrase. Verb: work remotely. Synonym: working from home (WFH).'),
  'day off': VocabUsage('I\'m taking a day off on Friday to visit my parents.', '', 'Saya mengambil hari libur kerja hari Jumat untuk mengunjungi orang tua.', '', 'Frasa benda; jamak: days off. Pola: take/have a day off.', 'Noun phrase; plural: days off. Pattern: take/have a day off.'),
  'sick leave': VocabUsage('He has been on sick leave since last Wednesday.', '', 'Ia sedang cuti sakit sejak Rabu lalu.', '', 'Frasa benda tak terhitung: be on / take sick leave. Sering butuh surat dokter.', 'Uncountable noun phrase: be on / take sick leave. Often needs a doctor\'s note.'),
  'maternity leave': VocabUsage('She will return to work after six months of maternity leave.', '', 'Ia akan kembali bekerja setelah enam bulan cuti melahirkan.', '', 'Frasa benda: be on / go on maternity leave. Untuk ayah: paternity leave.', 'Noun phrase: be on / go on maternity leave. For fathers: paternity leave.'),
  'vacation': VocabUsage('The manager is on vacation until the end of the month.', '', 'Manajer sedang liburan hingga akhir bulan.', '', 'Kata benda (AS): be on/go on vacation. Inggris Britania: holiday.', 'Noun (US): be on/go on vacation. British: holiday.'),
  'time sheet': VocabUsage('Submit your time sheet every Friday so overtime can be calculated.', '', 'Serahkan lembar jam kerja Anda setiap Jumat agar lembur bisa dihitung.', '', 'Frasa benda (juga ditulis timesheet): fill in/submit a time sheet.', 'Noun phrase (also timesheet): fill in/submit a time sheet.'),
  'dress code': VocabUsage('The office dress code is business casual from Monday to Thursday.', '', 'Aturan berpakaian kantor adalah kasual bisnis dari Senin sampai Kamis.', '', 'Frasa benda: follow/enforce a dress code; strict/relaxed dress code.', 'Noun phrase: follow/enforce a dress code; strict/relaxed dress code.'),
  'badge': VocabUsage('Visitors must wear a badge at all times inside the building.', '', 'Tamu harus memakai tanda pengenal setiap saat di dalam gedung.', '', 'Kata benda: wear a name/ID/security badge. Bisa juga lencana penghargaan.', 'Noun: wear a name/ID/security badge. Can also mean an award pin.'),
  'out of the office': VocabUsage('I will be out of the office until Monday with limited email access.', '', 'Saya tidak berada di kantor hingga Senin dengan akses email terbatas.', '', 'Frasa: be out of the office. Umum di balasan otomatis email (out-of-office reply).', 'Phrase: be out of the office. Common in auto-replies (out-of-office reply).'),
  'fill in for': VocabUsage('Can you fill in for Maria while she is at the conference?', '', 'Bisakah kamu menggantikan Maria sementara ia di konferensi?', '', 'Phrasal verb 3 kata: fill in for + orang. Sinonim: cover for, stand in for.', 'Three-word phrasal verb: fill in for + person. Synonyms: cover for, stand in for.'),
  'severance pay': VocabUsage('Workers who lose their jobs will receive severance pay.', '', 'Pekerja yang kehilangan pekerjaan akan menerima pesangon.', '', 'Frasa benda tak terhitung; juga \'severance package\'. Biasanya dihitung per tahun masa kerja.', 'Uncountable noun phrase; also \'severance package\'. Often based on years of service.'),
  'grievance': VocabUsage('Employees can file a grievance with the human resources department.', '', 'Karyawan dapat mengajukan pengaduan ke departemen SDM.', '', 'Kata benda formal: file/raise a grievance; grievance procedure.', 'Formal noun: file/raise a grievance; grievance procedure.'),
  'duties': VocabUsage('Your duties include answering calls and updating the database.', '', 'Tugas-tugas Anda meliputi menjawab telepon dan memperbarui basis data.', '', 'Bentuk jamak \'duty\': carry out/perform duties. Bentuk tunggal juga = bea (customs duty).', 'Plural of \'duty\': carry out/perform duties. Singular also = tax (customs duty).'),
  'perks': VocabUsage('Free lunches and a gym membership are some of the job\'s perks.', '', 'Makan siang gratis dan keanggotaan gym adalah beberapa fasilitas tambahan pekerjaan itu.', '', 'Kata benda jamak informal (dari perquisite). Pola: perks of the job.', 'Informal plural noun (from perquisite). Pattern: perks of the job.'),
  'reward': VocabUsage('The company rewards employees who suggest money-saving ideas.', '', 'Perusahaan memberi imbalan kepada karyawan yang mengusulkan ide penghematan.', '', 'Nomina & verba: reward someone for + -ing; a reward for + hal. Adj: rewarding (memuaskan).', 'Noun and verb: reward someone for + -ing; a reward for. Adj: rewarding (satisfying).'),
  'on duty': VocabUsage('A security guard is on duty at the entrance all night.', '', 'Seorang satpam sedang bertugas di pintu masuk sepanjang malam.', '', 'Frasa: be on duty; lawan: off duty. Umum untuk satpam, perawat, polisi.', 'Phrase: be on duty; opposite: off duty. Common for guards, nurses, police.'),
  'proficient': VocabUsage('Applicants must be proficient in English and Spanish.', '', 'Pelamar harus mahir berbahasa Inggris dan Spanyol.', '', 'Adjektiva: proficient in/at + bidang. Nomina: proficiency (language proficiency).', 'Adjective: proficient in/at + field. Noun: proficiency (language proficiency).'),
  'certificate': VocabUsage('Participants will receive a certificate after completing the course.', '', 'Peserta akan menerima sertifikat setelah menyelesaikan kursus.', '', 'Kata benda: certificate of + hal (completion/origin); issue a certificate.', 'Noun: certificate of + thing (completion/origin); issue a certificate.'),
  'invoice': VocabUsage('We will send you an invoice once the goods have been delivered.', '', 'Kami akan mengirimkan faktur setelah barang dikirim.', '', 'Nomina & verba: send/issue/pay an invoice; invoice a client.', 'Noun and verb: send/issue/pay an invoice; invoice a client.'),
  'turnover': VocabUsage('The company\'s annual turnover rose by fifteen percent last year.', '', 'Omzet tahunan perusahaan naik lima belas persen tahun lalu.', '', 'Kata benda; juga berarti tingkat pergantian karyawan (staff turnover). Lihat konteks.', 'Noun; also means rate of staff leaving (staff turnover). Check context.'),
  'quarterly': VocabUsage('The finance team publishes a quarterly report on sales.', '', 'Tim keuangan menerbitkan laporan per kuartal tentang penjualan.', '', 'Adjektiva & adverbia: quarterly report/meeting; paid quarterly.', 'Adjective and adverb: quarterly report/meeting; paid quarterly.'),
  'fiscal': VocabUsage('The new tax rules apply from the start of the next fiscal year.', '', 'Aturan pajak baru berlaku sejak awal tahun fiskal berikutnya.', '', 'Adjektiva: fiscal year/policy. Terkait anggaran/pajak pemerintah atau perusahaan.', 'Adjective: fiscal year/policy. Relates to government or company budgets and tax.'),
  'audit': VocabUsage('An external firm will audit our accounts next month.', '', 'Firma eksternal akan mengaudit pembukuan kami bulan depan.', '', 'Nomina & verba: carry out an audit; audit the accounts. Orangnya: auditor.', 'Noun and verb: carry out an audit; audit the accounts. Person: auditor.'),
  'deduct': VocabUsage('The cost of the uniform will be deducted from your first salary.', '', 'Biaya seragam akan dipotong dari gaji pertama Anda.', '', 'Verba: deduct + jumlah + from. Nomina: deduction; tax-deductible.', 'Verb: deduct + amount + from. Noun: deduction; tax-deductible.'),
  'expenditure': VocabUsage('The company reduced its expenditure on travel this year.', '', 'Perusahaan mengurangi pengeluaran untuk perjalanan tahun ini.', '', 'Kata benda formal: expenditure on + hal; capital/public expenditure.', 'Formal noun: expenditure on + thing; capital/public expenditure.'),
  'reimburse': VocabUsage('The company will reimburse you for any travel expenses.', '', 'Perusahaan akan mengganti biaya perjalanan Anda.', '', 'Verba: reimburse + orang + for + biaya. Nomina: reimbursement.', 'Verb: reimburse + person + for + cost. Noun: reimbursement.'),
  'accountant': VocabUsage('Our accountant prepares the financial statements every quarter.', '', 'Akuntan kami menyiapkan laporan keuangan setiap kuartal.', '', 'Kata benda; bidangnya: accounting/accountancy. Kolokasi: chartered/certified accountant.', 'Noun; the field: accounting/accountancy. Collocations: chartered/certified accountant.'),
  'accounts payable': VocabUsage('Accounts payable increased because several supplier bills are still unpaid.', '', 'Utang usaha meningkat karena beberapa tagihan pemasok masih belum dibayar.', '', 'Frasa benda akuntansi (singkatan AP); juga nama bagian yang membayar tagihan. Lawan: receivable.', 'Accounting noun phrase (AP); also the team that pays bills. Opposite: receivable.'),
  'accounts receivable': VocabUsage('The team is working to collect overdue accounts receivable.', '', 'Tim sedang berupaya menagih piutang usaha yang lewat jatuh tempo.', '', 'Frasa benda akuntansi (singkatan AR): uang yang belum dibayar pelanggan. Lawan: payable.', 'Accounting noun phrase (AR): money customers still owe. Opposite: payable.'),
  'balance sheet': VocabUsage('The balance sheet shows the company\'s assets and liabilities.', '', 'Neraca menunjukkan aset dan kewajiban perusahaan.', '', 'Frasa benda: on the balance sheet. Beda: income statement (laporan laba rugi).', 'Noun phrase: on the balance sheet. Compare: income statement (profit and loss).'),
  'asset': VocabUsage('Skilled employees are the company\'s most valuable asset.', '', 'Karyawan terampil adalah aset paling berharga perusahaan.', '', 'Kata benda terhitung: fixed/current assets; an asset to + tim. Lawan: liability.', 'Countable noun: fixed/current assets; an asset to + team. Opposite: liability.'),
  'liability': VocabUsage('The firm\'s liabilities now exceed its total assets.', '', 'Kewajiban firma itu kini melebihi total asetnya.', '', 'Kata benda; juga = tanggung jawab hukum (liability for damage). Adj: liable.', 'Noun; also = legal responsibility (liability for damage). Adj: liable.'),
  'bookkeeping': VocabUsage('She handles the bookkeeping for several small businesses.', '', 'Ia menangani pembukuan untuk beberapa usaha kecil.', '', 'Kata benda tak terhitung; orangnya: bookkeeper. Lebih teknis/harian daripada accounting.', 'Uncountable noun; person: bookkeeper. More routine than accounting.'),
  'spreadsheet': VocabUsage('I entered all the sales figures into a spreadsheet.', '', 'Saya memasukkan semua angka penjualan ke dalam lembar kerja.', '', 'Kata benda: in/into a spreadsheet; create/update a spreadsheet.', 'Noun: in/into a spreadsheet; create/update a spreadsheet.'),
  'tax return': VocabUsage('You must file your tax return before the end of March.', '', 'Anda harus melaporkan SPT pajak sebelum akhir Maret.', '', 'Frasa benda: file/submit a tax return. Bukan \'pengembalian pajak\' (itu tax refund).', 'Noun phrase: file/submit a tax return. Not a tax refund.'),
  'overdue': VocabUsage('This invoice is thirty days overdue, so please pay it immediately.', '', 'Faktur ini sudah lewat jatuh tempo tiga puluh hari, jadi harap segera dibayar.', '', 'Adjektiva: overdue payment/bill/book; [jumlah hari] overdue.', 'Adjective: overdue payment/bill/book; [number of days] overdue.'),
  'outstanding': VocabUsage('There is still an outstanding balance of two hundred dollars.', '', 'Masih ada saldo yang belum dibayar sebesar dua ratus dolar.', '', 'Adjektiva: outstanding balance/debt/invoice. Arti lain: luar biasa (outstanding work).', 'Adjective: outstanding balance/debt/invoice. Other sense: excellent (outstanding work).'),
  'due date': VocabUsage('The due date for this payment is the fifteenth of June.', '', 'Tanggal jatuh tempo pembayaran ini adalah lima belas Juni.', '', 'Frasa benda: due date for + hal; pay before the due date. Adj: be due on + tanggal.', 'Noun phrase: due date for + item; pay before the due date. Adj: be due on + date.'),
  'installment': VocabUsage('You can pay for the laptop in twelve monthly installments.', '', 'Anda bisa membayar laptop itu dengan dua belas cicilan bulanan.', '', 'Kata benda: pay in installments; monthly installment. Ejaan Britania: instalment.', 'Noun: pay in installments; monthly installment. British spelling: instalment.'),
  'down payment': VocabUsage('They made a down payment of ten percent on the new office.', '', 'Mereka membayar uang muka sepuluh persen untuk kantor baru itu.', '', 'Frasa benda: make/put a down payment on + barang besar (rumah, mobil).', 'Noun phrase: make/put a down payment on + big purchase (house, car).'),
  'petty cash': VocabUsage('Small office expenses like coffee are paid from petty cash.', '', 'Pengeluaran kantor kecil seperti kopi dibayar dari kas kecil.', '', 'Frasa benda tak terhitung: petty cash fund/box; pay from petty cash.', 'Uncountable noun phrase: petty cash fund/box; pay from petty cash.'),
  'cash flow': VocabUsage('Late payments from customers caused serious cash flow problems.', '', 'Pembayaran terlambat dari pelanggan menyebabkan masalah arus kas yang serius.', '', 'Frasa benda: positive/negative cash flow; cash flow problems/statement.', 'Noun phrase: positive/negative cash flow; cash flow problems/statement.'),
  'break even': VocabUsage('The new store is expected to break even within two years.', '', 'Toko baru itu diperkirakan balik modal dalam dua tahun.', '', 'Frasa verba intransitif. Nomina/adj: break-even point (titik impas).', 'Intransitive verb phrase. Noun/adj: break-even point.'),
  'bankrupt': VocabUsage('The airline went bankrupt after years of heavy losses.', '', 'Maskapai itu bangkrut setelah bertahun-tahun merugi besar.', '', 'Adjektiva: go/be declared bankrupt. Nomina: bankruptcy (file for bankruptcy).', 'Adjective: go/be declared bankrupt. Noun: bankruptcy (file for bankruptcy).'),
  'profitable': VocabUsage('The online store became profitable in its second year.', '', 'Toko daring itu mulai menguntungkan pada tahun keduanya.', '', 'Adjektiva: highly profitable; become profitable. Nomina: profit, profitability.', 'Adjective: highly profitable; become profitable. Nouns: profit, profitability.'),
  'deficit': VocabUsage('The department ended the year with a small budget deficit.', '', 'Departemen itu menutup tahun dengan defisit anggaran kecil.', '', 'Kata benda: budget/trade deficit; run a deficit. Lawan: surplus.', 'Noun: budget/trade deficit; run a deficit. Opposite: surplus.'),
  'surplus': VocabUsage('The company used its cash surplus to pay off old debts.', '', 'Perusahaan memakai kelebihan kasnya untuk melunasi utang lama.', '', 'Kata benda & adjektiva: budget/trade surplus; surplus stock. Lawan: deficit.', 'Noun and adjective: budget/trade surplus; surplus stock. Opposite: deficit.'),
  'earnings': VocabUsage('Quarterly earnings were higher than analysts had expected.', '', 'Pendapatan kuartalan lebih tinggi daripada perkiraan para analis.', '', 'Kata benda jamak: annual/quarterly earnings; earnings report. Verba: earn.', 'Plural noun: annual/quarterly earnings; earnings report. Verb: earn.'),
  'net profit': VocabUsage('After taxes, the firm reported a net profit of two million dollars.', '', 'Setelah pajak, firma itu melaporkan laba bersih dua juta dolar.', '', 'Frasa benda; lawan: gross profit (laba kotor). Pola: a net profit of + jumlah.', 'Noun phrase; compare gross profit. Pattern: a net profit of + amount.'),
  'overhead': VocabUsage('Moving to a smaller office helped us reduce overhead.', '', 'Pindah ke kantor yang lebih kecil membantu kami mengurangi biaya operasional tetap.', '', 'Kata benda (AS tunggal, Britania sering \'overheads\'): reduce/cut overhead; overhead costs.', 'Noun (US singular, British often \'overheads\'): reduce/cut overhead; overhead costs.'),
  'stock market': VocabUsage('Investors are worried about the falling stock market.', '', 'Para investor khawatir dengan pasar saham yang sedang turun.', '', 'Frasa benda: on the stock market; stock market crash. Sinonim: stock exchange.', 'Noun phrase: on the stock market; stock market crash. Similar: stock exchange.'),
  'share': VocabUsage('She bought one thousand shares in the technology company.', '', 'Ia membeli seribu lembar saham di perusahaan teknologi itu.', '', 'Kata benda terhitung: shares in + perusahaan; share price. Sinonim AS: stock.', 'Countable noun: shares in + company; share price. US synonym: stock.'),
  'broker': VocabUsage('He asked his broker to sell the shares before the price fell.', '', 'Ia meminta makelarnya menjual saham itu sebelum harganya turun.', '', 'Kata benda: stock/insurance/real estate broker. Verba: broker a deal (memperantarai).', 'Noun: stock/insurance/real estate broker. Verb: broker a deal.'),
  'write off': VocabUsage('The bank decided to write off the unpaid loan.', '', 'Bank memutuskan menghapusbukukan pinjaman yang tak terbayar itu.', '', 'Phrasal verb: write off + debt/loss. Nomina: a write-off (pakai tanda hubung).', 'Phrasal verb: write off + debt/loss. Noun: a write-off (hyphenated).'),
  'billing': VocabUsage('Please contact our billing department if you have questions about charges.', '', 'Silakan hubungi bagian penagihan kami jika ada pertanyaan tentang biaya.', '', 'Kata benda: billing department/address/cycle. Verba: bill a customer.', 'Noun: billing department/address/cycle. Verb: bill a customer.'),
  'year-end': VocabUsage('All departments must submit their reports before the year-end closing.', '', 'Semua departemen harus menyerahkan laporan sebelum penutupan akhir tahun buku.', '', 'Nomina & adjektiva: year-end bonus/report/closing; at year-end.', 'Noun and adjective: year-end bonus/report/closing; at year-end.'),
  'cost-effective': VocabUsage('Video calls are a cost-effective alternative to business trips.', '', 'Panggilan video adalah alternatif hemat biaya untuk perjalanan dinas.', '', 'Adjektiva majemuk: cost-effective solution/way. Bentuk lain: cost-efficient.', 'Compound adjective: cost-effective solution/way. Similar: cost-efficient.'),
  'payment': VocabUsage('We accept payment by credit card or bank transfer.', '', 'Kami menerima pembayaran dengan kartu kredit atau transfer bank.', '', 'Kata benda: make a payment; payment for + barang; payment by + metode.', 'Noun: make a payment; payment for + item; payment by + method.'),
  'surcharge': VocabUsage('A ten percent surcharge applies to orders placed on public holidays.', '', 'Biaya tambahan sepuluh persen berlaku untuk pesanan pada hari libur nasional.', '', 'Kata benda: a surcharge on + barang/layanan; fuel surcharge. Biasanya wajib, bukan pilihan.', 'Noun: a surcharge on + goods/service; fuel surcharge. Usually mandatory.'),
  'rebate': VocabUsage('Customers who buy before June will receive a fifty-dollar rebate.', '', 'Pelanggan yang membeli sebelum Juni akan menerima potongan harga kembali lima puluh dolar.', '', 'Kata benda: a rebate on + barang; tax rebate. Beda dengan discount: dibayar balik setelah beli.', 'Noun: a rebate on + item; tax rebate. Unlike a discount, it is paid back after buying.'),
  'overcharge': VocabUsage('The hotel overcharged us for the room, so we asked for a refund.', '', 'Hotel menagih kami berlebih untuk kamar, jadi kami meminta pengembalian dana.', '', 'Verba: overcharge + orang + for + barang. Lawan: undercharge.', 'Verb: overcharge + person + for + item. Opposite: undercharge.'),
  'affordable': VocabUsage('The company offers affordable housing for its overseas staff.', '', 'Perusahaan menyediakan perumahan terjangkau bagi staf luar negerinya.', '', 'Adjektiva: affordable price/housing. Verba: can afford + noun/to + verba.', 'Adjective: affordable price/housing. Verb: can afford + noun/to + verb.'),
  'cut back': VocabUsage('We need to cut back on printing costs this quarter.', '', 'Kita perlu mengurangi biaya cetak kuartal ini.', '', 'Phrasal verb: cut back on + hal. Nomina: cutbacks (pemotongan anggaran).', 'Phrasal verb: cut back on + thing. Noun: cutbacks (budget cuts).'),
  'set aside': VocabUsage('The company sets aside part of its profits for emergencies.', '', 'Perusahaan menyisihkan sebagian labanya untuk keadaan darurat.', '', 'Phrasal verb: set aside + uang/waktu + for + tujuan.', 'Phrasal verb: set aside + money/time + for + purpose.'),
  'expense account': VocabUsage('Client dinners can be charged to your expense account.', '', 'Makan malam dengan klien dapat dibebankan ke rekening biaya dinas Anda.', '', 'Frasa benda: charge something to an expense account; on an expense account.', 'Noun phrase: charge something to an expense account; on an expense account.'),
  'deposit': VocabUsage('A deposit of twenty percent is required to confirm the booking.', '', 'Uang muka dua puluh persen diperlukan untuk mengonfirmasi pemesanan.', '', 'Nomina & verba: pay/leave a deposit; deposit money into an account.', 'Noun and verb: pay/leave a deposit; deposit money into an account.'),
  'teller': VocabUsage('The teller helped me open a new account in ten minutes.', '', 'Teller membantu saya membuka rekening baru dalam sepuluh menit.', '', 'Kata benda: bank teller. Mesinnya: automated teller machine (ATM).', 'Noun: bank teller. The machine: automated teller machine (ATM).'),
  'ATM': VocabUsage('There is an ATM in the lobby if you need to withdraw cash.', '', 'Ada ATM di lobi jika Anda perlu menarik uang tunai.', '', 'Singkatan automated teller machine; pakai artikel \'an\' (dibaca ei-ti-em). Britania: cash machine.', 'Short for automated teller machine; use \'an\'. British: cash machine.'),
  'checking account': VocabUsage('My salary is paid directly into my checking account.', '', 'Gaji saya dibayarkan langsung ke rekening giro saya.', '', 'Frasa benda (AS); Britania: current account. Untuk transaksi harian.', 'Noun phrase (US); British: current account. For daily transactions.'),
  'savings account': VocabUsage('She opened a savings account to save for a new car.', '', 'Ia membuka rekening tabungan untuk menabung membeli mobil baru.', '', 'Frasa benda: open a savings account; put money into a savings account.', 'Noun phrase: open a savings account; put money into a savings account.'),
  'withdrawal': VocabUsage('The daily withdrawal limit at this ATM is five hundred dollars.', '', 'Batas penarikan uang harian di ATM ini adalah lima ratus dolar.', '', 'Kata benda dari \'withdraw\': make a withdrawal; withdrawal limit. Lawan: deposit.', 'Noun from \'withdraw\': make a withdrawal; withdrawal limit. Opposite: deposit.'),
  'mortgage': VocabUsage('They took out a thirty-year mortgage to buy their first home.', '', 'Mereka mengambil KPR tiga puluh tahun untuk membeli rumah pertama.', '', 'Kata benda: take out/pay off a mortgage; mortgage payment. Huruf t tidak dibaca.', 'Noun: take out/pay off a mortgage; mortgage payment. The t is silent.'),
  'interest rate': VocabUsage('The central bank raised the interest rate to control inflation.', '', 'Bank sentral menaikkan suku bunga untuk mengendalikan inflasi.', '', 'Frasa benda: raise/cut/lower interest rates; a low interest rate.', 'Noun phrase: raise/cut/lower interest rates; a low interest rate.'),
  'exchange rate': VocabUsage('The exchange rate affects how much our imported parts cost.', '', 'Kurs memengaruhi berapa harga suku cadang impor kami.', '', 'Frasa benda: the exchange rate between/for + mata uang; favorable exchange rate.', 'Noun phrase: the exchange rate between/for + currencies; favorable exchange rate.'),
  'balance': VocabUsage('You can check your account balance using the mobile app.', '', 'Anda dapat memeriksa saldo rekening melalui aplikasi seluler.', '', 'Kata benda: account/remaining balance; check your balance. Arti lain: keseimbangan.', 'Noun: account/remaining balance; check your balance. Other sense: equilibrium.'),
  'debit card': VocabUsage('You can pay with a debit card at most shops in the city.', '', 'Anda bisa membayar dengan kartu debit di sebagian besar toko di kota.', '', 'Frasa benda: pay by/with a debit card. Beda: credit card memakai pinjaman bank.', 'Noun phrase: pay by/with a debit card. A credit card uses borrowed money instead.'),
  'collateral': VocabUsage('The bank asked for the factory building as collateral for the loan.', '', 'Bank meminta gedung pabrik sebagai agunan untuk pinjaman itu.', '', 'Kata benda tak terhitung: as collateral for + loan; put up collateral.', 'Uncountable noun: as collateral for + loan; put up collateral.'),
  'borrow': VocabUsage('The company borrowed money from the bank to expand its factory.', '', 'Perusahaan meminjam uang dari bank untuk memperluas pabriknya.', '', 'Verba: borrow + barang + from + orang (menerima). Jangan tertukar dengan \'lend\' (memberi).', 'Verb: borrow + thing + from + person (receive). Don\'t confuse with \'lend\' (give).'),
  'lend': VocabUsage('Banks are less willing to lend money to new businesses.', '', 'Bank kurang bersedia meminjamkan uang kepada usaha baru.', '', 'Verba tak beraturan: lend-lent-lent. Pola: lend + orang + barang / lend + barang + to + orang.', 'Irregular: lend-lent-lent. Pattern: lend someone something / lend something to someone.'),
  'online banking': VocabUsage('Online banking lets customers pay bills at any time.', '', 'Perbankan daring memungkinkan nasabah membayar tagihan kapan saja.', '', 'Frasa benda tak terhitung; sinonim: internet banking. Kolokasi: use/log in to online banking.', 'Uncountable noun phrase; synonym: internet banking. Collocations: use/log in to online banking.'),
  'transaction': VocabUsage('Every transaction is recorded in the company\'s accounting system.', '', 'Setiap transaksi dicatat dalam sistem akuntansi perusahaan.', '', 'Kata benda: make/complete a transaction; transaction fee. Verba: transact.', 'Noun: make/complete a transaction; transaction fee. Verb: transact.'),
  'bank statement': VocabUsage('Please attach your last three bank statements to the loan application.', '', 'Silakan lampirkan rekening koran tiga bulan terakhir Anda pada permohonan pinjaman.', '', 'Frasa benda: monthly bank statement; request/print a bank statement.', 'Noun phrase: monthly bank statement; request/print a bank statement.'),
  'launch': VocabUsage('The company will launch its new smartphone in September.', '', 'Perusahaan akan meluncurkan ponsel pintar barunya pada bulan September.', '', 'Verba & nomina: launch a product/campaign; the product launch.', 'Verb and noun: launch a product/campaign; the product launch.'),
  'campaign': VocabUsage('Our advertising campaign increased online sales by thirty percent.', '', 'Kampanye iklan kami meningkatkan penjualan daring sebesar tiga puluh persen.', '', 'Kata benda: advertising/marketing campaign; launch/run a campaign.', 'Noun: advertising/marketing campaign; launch/run a campaign.'),
  'competitor': VocabUsage('Our main competitor has just lowered its prices.', '', 'Pesaing utama kami baru saja menurunkan harganya.', '', 'Kata benda: main/major competitor. Verba: compete with; adj: competitive.', 'Noun: main/major competitor. Verb: compete with; adj: competitive.'),
  'forecast': VocabUsage('The sales forecast for next year looks very positive.', '', 'Prakiraan penjualan untuk tahun depan terlihat sangat positif.', '', 'Nomina & verba (forecast-forecast-forecast): sales/weather forecast; forecast growth.', 'Noun and verb (forecast-forecast-forecast): sales/weather forecast; forecast growth.'),
  'growth': VocabUsage('The region has seen strong economic growth over the past decade.', '', 'Kawasan itu mengalami pertumbuhan ekonomi yang kuat selama satu dekade terakhir.', '', 'Kata benda tak terhitung: rapid/steady growth; growth in + bidang. Verba: grow.', 'Uncountable noun: rapid/steady growth; growth in + area. Verb: grow.'),
  'brochure': VocabUsage('You can find more details about our services in this brochure.', '', 'Anda bisa menemukan detail lebih lanjut tentang layanan kami di brosur ini.', '', 'Kata benda: travel/company brochure; in the brochure. Mirip: leaflet, pamphlet.', 'Noun: travel/company brochure; in the brochure. Similar: leaflet, pamphlet.'),
  'voucher': VocabUsage('Each customer receives a voucher for ten percent off the next purchase.', '', 'Setiap pelanggan menerima voucher potongan sepuluh persen untuk pembelian berikutnya.', '', 'Kata benda: gift/discount voucher; a voucher for + nilai/barang; redeem a voucher.', 'Noun: gift/discount voucher; a voucher for + value/item; redeem a voucher.'),
  'advertisement': VocabUsage('We placed an advertisement in the local newspaper for the job.', '', 'Kami memasang iklan di koran lokal untuk lowongan itu.', '', 'Kata benda formal; singkatan: ad, advert. Kolokasi: place/run an advertisement.', 'Formal noun; short forms: ad, advert. Collocations: place/run an advertisement.'),
  'commercial': VocabUsage('The company paid a famous actor to appear in its TV commercial.', '', 'Perusahaan membayar aktor terkenal untuk tampil dalam iklan TV-nya.', '', 'Kata benda (iklan TV/radio). Sebagai adjektiva = komersial (commercial use).', 'Noun (TV/radio ad). As adjective = for business (commercial use).'),
  'billboard': VocabUsage('A huge billboard advertising the new car stands near the highway.', '', 'Papan reklame besar yang mengiklankan mobil baru berdiri di dekat jalan tol.', '', 'Kata benda (AS); Britania: hoarding. Kolokasi: put up a billboard.', 'Noun (US); British: hoarding. Collocation: put up a billboard.'),
  'endorse': VocabUsage('Several famous athletes endorse the company\'s sports drinks.', '', 'Beberapa atlet terkenal mendukung minuman olahraga perusahaan itu.', '', 'Verba: endorse + product/candidate/plan. Nomina: endorsement (celebrity endorsement).', 'Verb: endorse + product/candidate/plan. Noun: endorsement (celebrity endorsement).'),
  'sponsor': VocabUsage('A local bank agreed to sponsor the charity marathon.', '', 'Sebuah bank lokal setuju menjadi sponsor maraton amal itu.', '', 'Verba & nomina: sponsor an event; main sponsor. Nomina proses: sponsorship.', 'Verb and noun: sponsor an event; main sponsor. Process noun: sponsorship.'),
  'clientele': VocabUsage('The boutique has a wealthy clientele from all over the city.', '', 'Butik itu memiliki para pelanggan kaya dari seluruh kota.', '', 'Kata benda kolektif formal (tanpa -s). Kolokasi: loyal/wealthy clientele.', 'Formal collective noun (no -s). Collocations: loyal/wealthy clientele.'),
  'loyalty program': VocabUsage('Members of our loyalty program earn points with every purchase.', '', 'Anggota program loyalitas kami mendapat poin setiap kali berbelanja.', '', 'Frasa benda: join a loyalty program; loyalty card/points. Britania: loyalty scheme.', 'Noun phrase: join a loyalty program; loyalty card/points. British: loyalty scheme.'),
  'word of mouth': VocabUsage('Most of our new customers hear about us by word of mouth.', '', 'Sebagian besar pelanggan baru kami mengenal kami dari mulut ke mulut.', '', 'Frasa benda: by/through word of mouth; word-of-mouth marketing (adjektiva bertanda hubung).', 'Noun phrase: by/through word of mouth; word-of-mouth marketing (hyphenated adjective).'),
  'market share': VocabUsage('The company aims to increase its market share in Asia.', '', 'Perusahaan bertujuan meningkatkan pangsa pasarnya di Asia.', '', 'Frasa benda: gain/lose/increase market share; a market share of + persen.', 'Noun phrase: gain/lose/increase market share; a market share of + percent.'),
  'sales rep': VocabUsage('A sales rep will visit your office to demonstrate the product.', '', 'Seorang wiraniaga akan mengunjungi kantor Anda untuk memperagakan produk.', '', 'Singkatan informal sales representative. Sinonim: salesperson.', 'Informal short form of sales representative. Synonym: salesperson.'),
  'pitch': VocabUsage('She gave a convincing pitch to the potential investors.', '', 'Ia memberikan presentasi penjualan yang meyakinkan kepada calon investor.', '', 'Nomina & verba: make/give a pitch; pitch an idea to + orang. Lihat: sales pitch.', 'Noun and verb: make/give a pitch; pitch an idea to + person. See: sales pitch.'),
  'persuade': VocabUsage('The sales team persuaded the client to sign a two-year contract.', '', 'Tim penjualan membujuk klien untuk menandatangani kontrak dua tahun.', '', 'Verba: persuade + orang + to + verba. Nomina: persuasion; adj: persuasive.', 'Verb: persuade + person + to + verb. Noun: persuasion; adj: persuasive.'),
  'bargain': VocabUsage('At that price, the printer is a real bargain.', '', 'Dengan harga segitu, printer itu benar-benar barang murah.', '', 'Kata benda: a real bargain; bargain price. Sebagai verba = menawar (bargain with/over).', 'Noun: a real bargain; bargain price. As verb = haggle (bargain with/over).'),
  'markup': VocabUsage('The store adds a forty percent markup to most imported goods.', '', 'Toko itu menambahkan kenaikan harga jual empat puluh persen pada sebagian besar barang impor.', '', 'Kata benda: a markup of + persen; add a markup. Verba: mark up (menaikkan harga).', 'Noun: a markup of + percent; add a markup. Verb: mark up.'),
  'clearance sale': VocabUsage('The shop is having a clearance sale before it moves to a new location.', '', 'Toko itu mengadakan obral cuci gudang sebelum pindah ke lokasi baru.', '', 'Frasa benda: have/hold a clearance sale. Bertujuan menghabiskan stok lama.', 'Noun phrase: have/hold a clearance sale. Aimed at clearing old stock.'),
  'on sale': VocabUsage('These winter coats are on sale for half price this week.', '', 'Mantel musim dingin ini sedang diskon setengah harga minggu ini.', '', 'Frasa: be on sale (AS = diskon). Hati-hati: \'for sale\' = dijual (bukan diskon).', 'Phrase: be on sale (US = discounted). Note: \'for sale\' = available to buy.'),
  'free of charge': VocabUsage('Delivery is free of charge for orders over fifty dollars.', '', 'Pengiriman gratis untuk pesanan di atas lima puluh dolar.', '', 'Frasa formal; sinonim: free, at no cost. Umum di iklan dan syarat layanan.', 'Formal phrase; synonyms: free, at no cost. Common in ads and terms.'),
  'complimentary': VocabUsage('Guests receive a complimentary breakfast during their stay.', '', 'Tamu mendapat sarapan cuma-cuma selama menginap.', '', 'Adjektiva: complimentary drink/ticket. Beda ejaan: complementary = saling melengkapi.', 'Adjective: complimentary drink/ticket. Different from complementary (matching).'),
  'free trial': VocabUsage('Sign up today for a thirty-day free trial of our software.', '', 'Daftar hari ini untuk uji coba gratis tiga puluh hari perangkat lunak kami.', '', 'Frasa benda: a [durasi] free trial; start/cancel a free trial.', 'Noun phrase: a [length] free trial; start/cancel a free trial.'),
  'feedback': VocabUsage('We welcome your feedback on our new website design.', '', 'Kami menyambut umpan balik Anda tentang desain situs web baru kami.', '', 'Kata benda tak terhitung (bukan \'feedbacks\'): give/get feedback on + hal.', 'Uncountable noun (not \'feedbacks\'): give/get feedback on + thing.'),
  'questionnaire': VocabUsage('Please complete the short questionnaire at the end of the course.', '', 'Silakan isi kuesioner singkat di akhir kursus.', '', 'Kata benda: complete/fill out a questionnaire. Mirip: survey.', 'Noun: complete/fill out a questionnaire. Similar: survey.'),
  'best seller': VocabUsage('This blender has been our best seller for three years.', '', 'Blender ini menjadi barang terlaris kami selama tiga tahun.', '', 'Frasa benda (juga bestseller). Adj: best-selling product/author.', 'Noun phrase (also bestseller). Adj: best-selling product/author.'),
  'in demand': VocabUsage('Data analysts are highly in demand in the job market.', '', 'Analis data sangat banyak dicari di pasar kerja.', '', 'Frasa: be (highly/in great) demand. Nomina: demand for + barang.', 'Phrase: be (highly/in great) demand. Noun: demand for + product.'),
  'merchandise': VocabUsage('All merchandise must be paid for at the front counter.', '', 'Semua barang dagangan harus dibayar di konter depan.', '', 'Kata benda tak terhitung (tanpa -s). Juga = merchandise resmi (merch) band/klub.', 'Uncountable noun (no -s). Also official goods (merch) of a band/club.'),
  'showroom': VocabUsage('Customers can test the new models in our showroom.', '', 'Pelanggan bisa mencoba model-model baru di ruang pamer kami.', '', 'Kata benda: car/furniture showroom; in the showroom.', 'Noun: car/furniture showroom; in the showroom.'),
  'trade show': VocabUsage('We will display our latest products at the trade show in Berlin.', '', 'Kami akan memamerkan produk terbaru kami di pameran dagang di Berlin.', '', 'Frasa benda: attend/exhibit at a trade show. Sinonim: trade fair, expo.', 'Noun phrase: attend/exhibit at a trade show. Synonyms: trade fair, expo.'),
  'booth': VocabUsage('Please visit our booth at the exhibition to see a demonstration.', '', 'Silakan kunjungi stan kami di pameran untuk melihat demonstrasi.', '', 'Kata benda: set up/visit a booth; at booth number 12. Juga: phone/ticket booth.', 'Noun: set up/visit a booth; at booth number 12. Also: phone/ticket booth.'),
  'catalog': VocabUsage('Our new spring catalog is available online and in stores.', '', 'Katalog musim semi kami yang baru tersedia daring dan di toko.', '', 'Kata benda (AS); Britania: catalogue. Kolokasi: product catalog; in the catalog.', 'Noun (US); British: catalogue. Collocations: product catalog; in the catalog.'),
  'price list': VocabUsage('Could you send me your latest price list by email?', '', 'Bisakah Anda mengirimkan daftar harga terbaru melalui email?', '', 'Frasa benda: latest/updated price list; on the price list.', 'Noun phrase: latest/updated price list; on the price list.'),
  'price tag': VocabUsage('The price tag on this jacket says forty dollars.', '', 'Label harga pada jaket ini menyebutkan empat puluh dolar.', '', 'Frasa benda; kiasan: a high price tag = biaya mahal (proyek, rencana).', 'Noun phrase; figurative: a high price tag = big cost (of a project).'),
  'retailer': VocabUsage('The retailer plans to open twenty new stores next year.', '', 'Pengecer itu berencana membuka dua puluh toko baru tahun depan.', '', 'Kata benda; terkait: retail (industri), wholesaler (grosir). Kolokasi: online retailer.', 'Noun; related: retail (sector), wholesaler. Collocation: online retailer.'),
  'franchise': VocabUsage('He bought a coffee shop franchise in a busy shopping mall.', '', 'Ia membeli waralaba kedai kopi di mal yang ramai.', '', 'Kata benda: buy/own a franchise; franchise fee. Pemilik: franchisee; pemberi: franchisor.', 'Noun: buy/own a franchise; franchise fee. Owner: franchisee; brand: franchisor.'),
  'commerce': VocabUsage('The government wants to support the growth of electronic commerce.', '', 'Pemerintah ingin mendukung pertumbuhan perniagaan elektronik.', '', 'Kata benda tak terhitung: e-commerce; chamber of commerce. Adj: commercial.', 'Uncountable noun: e-commerce; chamber of commerce. Adj: commercial.'),
  'checkout': VocabUsage('There was a long line at the checkout this morning.', '', 'Ada antrean panjang di tempat bayar pagi ini.', '', 'Kata benda: at the checkout; online checkout. Verba: check out (juga = keluar hotel).', 'Noun: at the checkout; online checkout. Verb: check out (also leave a hotel).'),
  'cashier': VocabUsage('Please give your receipt to the cashier if you want a refund.', '', 'Berikan struk Anda kepada kasir jika Anda ingin pengembalian uang.', '', 'Kata benda untuk orang (bukan tempat). Kolokasi: cashier\'s desk; pay the cashier.', 'Noun for the person (not the place). Collocations: cashier\'s desk; pay the cashier.'),
  'stocktaking': VocabUsage('The store will close early on Sunday for stocktaking.', '', 'Toko akan tutup lebih awal hari Minggu untuk stok opname.', '', 'Kata benda tak terhitung (Britania). Verba: take stock; AS: inventory count.', 'Uncountable noun (British). Verb: take stock; US: inventory count.'),
  'vendor': VocabUsage('We are looking for a new vendor to supply office furniture.', '', 'Kami sedang mencari vendor baru untuk memasok perabot kantor.', '', 'Kata benda: approved/software vendor. Juga pedagang kaki lima (street vendor).', 'Noun: approved/software vendor. Also a street seller (street vendor).'),
  'inventory': VocabUsage('We need to reduce our inventory before the new models arrive.', '', 'Kita perlu mengurangi persediaan barang sebelum model baru datang.', '', 'Kata benda: keep/manage inventory; take inventory (menghitung stok). Sinonim: stock.', 'Noun: keep/manage inventory; take inventory (count stock). Synonym: stock.'),
  'procurement': VocabUsage('All purchases above one thousand dollars must go through procurement.', '', 'Semua pembelian di atas seribu dolar harus melalui bagian pengadaan.', '', 'Kata benda formal (dari procure); juga nama bagian. Kolokasi: procurement process/officer.', 'Formal noun (from procure); also a department. Collocations: procurement process/officer.'),
  'negotiate': VocabUsage('We negotiated a lower price with the supplier.', '', 'Kami bernegosiasi harga yang lebih rendah dengan pemasok.', '', 'Verba: negotiate + deal/price + with + pihak. Nomina: negotiation.', 'Verb: negotiate + deal/price + with + party. Noun: negotiation.'),
  'order form': VocabUsage('Fill out the order form and send it to the sales department.', '', 'Isi formulir pesanan dan kirimkan ke bagian penjualan.', '', 'Frasa benda: fill out/complete an order form; online order form.', 'Noun phrase: fill out/complete an order form; online order form.'),
  'place an order': VocabUsage('I would like to place an order for fifty boxes of paper.', '', 'Saya ingin memesan lima puluh kotak kertas.', '', 'Frasa verba formal: place an order for + barang + with + pemasok.', 'Formal verb phrase: place an order for + goods + with + supplier.'),
  'backorder': VocabUsage('The printer you requested is on backorder until next week.', '', 'Printer yang Anda minta berstatus pesanan tertunda hingga minggu depan.', '', 'Nomina & verba: be on backorder; the item is backordered.', 'Noun and verb: be on backorder; the item is backordered.'),
  'out of stock': VocabUsage('I\'m sorry, that size is currently out of stock.', '', 'Maaf, ukuran itu saat ini stok habis.', '', 'Frasa: be/go out of stock. Lawan: in stock. Mirip: sold out.', 'Phrase: be/go out of stock. Opposite: in stock. Similar: sold out.'),
  'in stock': VocabUsage('We have all the items you ordered in stock.', '', 'Kami punya semua barang yang Anda pesan di gudang.', '', 'Frasa: be in stock / have something in stock. Lawan: out of stock.', 'Phrase: be in stock / have something in stock. Opposite: out of stock.'),
  'restock': VocabUsage('The staff restock the shelves every night after closing.', '', 'Staf mengisi ulang stok rak setiap malam setelah tutup.', '', 'Verba: restock + shelves/store/item. Awalan re- = melakukan lagi.', 'Verb: restock + shelves/store/item. Prefix re- = again.'),
  'run out of': VocabUsage('We have run out of printer paper, so I\'ll order more.', '', 'Kita kehabisan kertas printer, jadi saya akan memesan lagi.', '', 'Phrasal verb 3 kata: run out of + barang. Tanpa objek: supplies ran out.', 'Three-word phrasal verb: run out of + item. Without object: supplies ran out.'),
  'bid': VocabUsage('Three construction companies submitted bids for the project.', '', 'Tiga perusahaan konstruksi mengajukan penawaran untuk proyek itu.', '', 'Nomina & verba: submit/make a bid for; bid for/on a contract. Lelang: highest bid.', 'Noun and verb: submit/make a bid for; bid for/on a contract. Auction: highest bid.'),
  'terms and conditions': VocabUsage('Please read the terms and conditions before you sign up.', '', 'Silakan baca syarat dan ketentuan sebelum Anda mendaftar.', '', 'Frasa benda jamak: accept/agree to the terms and conditions; singkat: T&Cs.', 'Plural noun phrase: accept/agree to the terms and conditions; short: T&Cs.'),
  'fine print': VocabUsage('Always read the fine print before signing a contract.', '', 'Selalu baca ketentuan kecil sebelum menandatangani kontrak.', '', 'Frasa benda: read the fine print; in the fine print. Britania: small print.', 'Noun phrase: read the fine print; in the fine print. British: small print.'),
  'binding': VocabUsage('Once signed, the agreement is legally binding on both parties.', '', 'Setelah ditandatangani, perjanjian itu mengikat secara hukum bagi kedua pihak.', '', 'Adjektiva: legally binding; binding on + pihak; binding contract/agreement.', 'Adjective: legally binding; binding on + party; binding contract/agreement.'),
  'agreement': VocabUsage('The two firms signed an agreement to share research costs.', '', 'Kedua firma menandatangani perjanjian untuk berbagi biaya riset.', '', 'Kata benda: sign/reach an agreement; in agreement with. Verba: agree.', 'Noun: sign/reach an agreement; in agreement with. Verb: agree.'),
  'sign up': VocabUsage('Over two hundred employees signed up for the health program.', '', 'Lebih dari dua ratus karyawan mendaftar program kesehatan itu.', '', 'Phrasal verb: sign up for + kegiatan/layanan. Nomina: sign-up (pakai tanda hubung).', 'Phrasal verb: sign up for + activity/service. Noun: sign-up (hyphenated).'),
  'unit price': VocabUsage('The unit price falls when you order more than five hundred items.', '', 'Harga satuan turun jika Anda memesan lebih dari lima ratus barang.', '', 'Frasa benda: the unit price of + barang. Total = unit price x quantity.', 'Noun phrase: the unit price of + item. Total = unit price x quantity.'),
  'prepaid': VocabUsage('Prepaid phone cards are sold at most convenience stores.', '', 'Kartu telepon prabayar dijual di sebagian besar minimarket.', '', 'Adjektiva: prepaid card/plan/envelope. Lawan: postpaid (pascabayar).', 'Adjective: prepaid card/plan/envelope. Opposite: postpaid.'),
  'cash on delivery': VocabUsage('Customers can choose cash on delivery when ordering online.', '', 'Pelanggan dapat memilih bayar di tempat saat memesan daring.', '', 'Frasa benda (singkatan COD): pay cash on delivery; offer cash on delivery.', 'Noun phrase (COD): pay cash on delivery; offer cash on delivery.'),
  'compromise': VocabUsage('After hours of talks, both sides agreed to a compromise.', '', 'Setelah berjam-jam berunding, kedua pihak menyepakati kompromi.', '', 'Nomina & verba: reach a compromise; compromise on + hal. Juga = membahayakan (compromise security).', 'Noun and verb: reach a compromise; compromise on + issue. Also = endanger (compromise security).'),
  'subscription': VocabUsage('The annual subscription includes free access to all online courses.', '', 'Langganan tahunan mencakup akses gratis ke semua kursus daring.', '', 'Kata benda: subscription to + layanan; cancel/renew a subscription. Verba: subscribe to.', 'Noun: subscription to + service; cancel/renew a subscription. Verb: subscribe to.'),
  'renewal': VocabUsage('Your contract is due for renewal at the end of this month.', '', 'Kontrak Anda akan diperpanjang pada akhir bulan ini.', '', 'Kata benda dari \'renew\': contract/license renewal; due for renewal.', 'Noun from \'renew\': contract/license renewal; due for renewal.'),
  'expire': VocabUsage('Your passport expires next month, so please renew it soon.', '', 'Paspor Anda habis masa berlakunya bulan depan, jadi segera perpanjang.', '', 'Verba intransitif: contract/card/visa expires. Nomina: expiry/expiration date.', 'Intransitive verb: contract/card/visa expires. Noun: expiry/expiration date.'),
  'compliance': VocabUsage('All suppliers must be in compliance with our safety standards.', '', 'Semua pemasok harus mematuhi standar keselamatan kami.', '', 'Kata benda: in compliance with + aturan; compliance officer. Verba: comply with.', 'Noun: in compliance with + rules; compliance officer. Verb: comply with.'),
  'eligible': VocabUsage('Full-time employees are eligible for the health insurance plan.', '', 'Karyawan penuh waktu memenuhi syarat untuk program asuransi kesehatan.', '', 'Adjektiva: eligible for + noun / eligible to + verba. Nomina: eligibility.', 'Adjective: eligible for + noun / eligible to + verb. Noun: eligibility.'),
  'lawyer': VocabUsage('The company asked its lawyer to review the contract.', '', 'Perusahaan meminta pengacaranya meninjau kontrak itu.', '', 'Kata benda umum; sinonim AS: attorney. Kolokasi: hire/consult a lawyer.', 'General noun; US synonym: attorney. Collocations: hire/consult a lawyer.'),
  'lawsuit': VocabUsage('The customer filed a lawsuit against the manufacturer.', '', 'Pelanggan itu mengajukan gugatan hukum terhadap produsen.', '', 'Kata benda: file/bring a lawsuit against; settle a lawsuit. Verba: sue.', 'Noun: file/bring a lawsuit against; settle a lawsuit. Verb: sue.'),
  'dispute': VocabUsage('The dispute over the payment was settled without going to court.', '', 'Perselisihan soal pembayaran itu diselesaikan tanpa ke pengadilan.', '', 'Nomina & verba: a dispute over/about; settle/resolve a dispute; dispute a bill.', 'Noun and verb: a dispute over/about; settle/resolve a dispute; dispute a bill.'),
  'penalty': VocabUsage('The supplier must pay a penalty if the goods arrive after the deadline.', '', 'Pemasok harus membayar denda jika barang tiba setelah tenggat.', '', 'Kata benda. Kolokasi: pay a penalty, late penalty, penalty for + kesalahan. Lebih formal dari \'fine\'.', 'Noun. Collocations: pay a penalty, late penalty, penalty for + offense. More formal than \'fine\'.'),
  'trademark': VocabUsage('The company registered its logo as a trademark to protect the brand.', '', 'Perusahaan mendaftarkan logonya sebagai merek dagang untuk melindungi mereknya.', '', 'Kata benda. Kolokasi: register a trademark, trademark infringement (pelanggaran merek).', 'Noun. Collocations: register a trademark, trademark infringement.'),
  'deliver': VocabUsage('We can deliver the order to your office by Friday afternoon.', '', 'Kami bisa mengirimkan pesanan ke kantor Anda paling lambat Jumat sore.', '', 'Kata kerja. Pola: deliver + barang + to + tempat. Kata benda: delivery. Juga: deliver a speech.', 'Verb. Pattern: deliver + item + to + place. Noun: delivery. Also: deliver a speech.'),
  'courier': VocabUsage('Please send the signed contract by courier so it arrives tomorrow.', '', 'Tolong kirim kontrak yang sudah ditandatangani lewat kurir supaya tiba besok.', '', 'Kata benda. Pola: send by courier, courier service, courier company.', 'Noun. Patterns: send by courier, courier service, courier company.'),
  'fragile': VocabUsage('The box contains glassware, so please mark it as fragile.', '', 'Kotak ini berisi barang pecah belah, jadi tolong tandai sebagai mudah pecah.', '', 'Kata sifat. Sering tertulis di label paket: FRAGILE, handle with care.', 'Adjective. Often printed on parcel labels: FRAGILE, handle with care.'),
  'logistics': VocabUsage('Our logistics team plans the routes for all outgoing shipments.', '', 'Tim logistik kami merencanakan rute untuk semua kiriman keluar.', '', 'Kata benda (bentuk -s, kata kerjanya tunggal/jamak). Kolokasi: logistics company, logistics manager.', 'Noun (ends in -s, may take singular or plural verb). Collocations: logistics company, logistics manager.'),
  'consignment': VocabUsage('The first consignment of office chairs arrived at the warehouse this morning.', '', 'Kiriman pertama kursi kantor tiba di gudang pagi ini.', '', 'Kata benda. Pola: a consignment of + barang. Juga: on consignment (titip jual).', 'Noun. Pattern: a consignment of + goods. Also: on consignment (sold on behalf of the owner).'),
  'turnaround time': VocabUsage('The printing shop offers a turnaround time of two business days.', '', 'Percetakan itu menawarkan waktu penyelesaian dua hari kerja.', '', 'Frasa benda. Pola: a turnaround time of + durasi; quick/fast turnaround time.', 'Noun phrase. Pattern: a turnaround time of + duration; quick/fast turnaround time.'),
  'shipping': VocabUsage('Shipping is free for orders over fifty dollars.', '', 'Pengiriman gratis untuk pesanan di atas lima puluh dolar.', '', 'Kata benda. Kolokasi: free shipping, shipping cost/fee, shipping address. Kata kerja: ship.', 'Noun. Collocations: free shipping, shipping cost/fee, shipping address. Verb: ship.'),
  'freight': VocabUsage('The freight was transported by rail to reduce costs.', '', 'Muatan barang itu diangkut dengan kereta untuk menekan biaya.', '', 'Kata benda tak terhitung. Kolokasi: freight charges, air freight, freight train.', 'Uncountable noun. Collocations: freight charges, air freight, freight train.'),
  'cargo': VocabUsage('The ship was carrying cargo worth over two million dollars.', '', 'Kapal itu membawa kargo senilai lebih dari dua juta dolar.', '', 'Kata benda. Kolokasi: cargo ship, cargo hold, load/unload cargo. Mirip \'freight\'.', 'Noun. Collocations: cargo ship, cargo hold, load/unload cargo. Similar to \'freight\'.'),
  'tracking number': VocabUsage('You can check your parcel online using the tracking number in the email.', '', 'Anda bisa mengecek paket secara daring memakai nomor resi di email.', '', 'Frasa benda. Pola: enter/use the tracking number; track a package.', 'Noun phrase. Pattern: enter/use the tracking number; track a package.'),
  'parcel': VocabUsage('A parcel was left at the reception desk for you this morning.', '', 'Ada paket yang ditinggalkan di meja resepsionis untuk Anda pagi ini.', '', 'Kata benda (Inggris Britania); Amerika lebih sering \'package\'. Kolokasi: send/receive a parcel.', 'Noun (British); American English prefers \'package\'. Collocations: send/receive a parcel.'),
  'dispatch': VocabUsage('The items will be dispatched from our warehouse within 24 hours.', '', 'Barang akan dikirim dari gudang kami dalam 24 jam.', '', 'Kata kerja, sering pasif: be dispatched. Juga kata benda: dispatch date. Lebih formal dari \'send\'.', 'Verb, often passive: be dispatched. Also a noun: dispatch date. More formal than \'send\'.'),
  'recipient': VocabUsage('Please write the recipient\'s full name and address clearly.', '', 'Tolong tulis nama lengkap dan alamat penerima dengan jelas.', '', 'Kata benda. Kolokasi: recipient of + sesuatu (award, email). Lawan: sender.', 'Noun. Collocations: recipient of + something (award, email). Opposite: sender.'),
  'sender': VocabUsage('If the address is wrong, the package will be returned to the sender.', '', 'Jika alamatnya salah, paket akan dikembalikan ke pengirim.', '', 'Kata benda. Ungkapan umum: return to sender. Lawan: recipient.', 'Noun. Common phrase: return to sender. Opposite: recipient.'),
  'customs': VocabUsage('The shipment was held at customs for three days.', '', 'Kiriman itu tertahan di bea cukai selama tiga hari.', '', 'Kata benda (selalu -s untuk arti ini). Pola: go through/clear customs, customs declaration.', 'Noun (always with -s in this sense). Patterns: go through/clear customs, customs declaration.'),
  'duty-free': VocabUsage('Passengers can buy duty-free perfume at the airport shops.', '', 'Penumpang bisa membeli parfum bebas bea di toko bandara.', '', 'Kata sifat/keterangan. Kolokasi: duty-free shop, duty-free allowance.', 'Adjective/adverb. Collocations: duty-free shop, duty-free allowance.'),
  'tariff': VocabUsage('The government raised the tariff on imported steel last year.', '', 'Pemerintah menaikkan tarif bea atas baja impor tahun lalu.', '', 'Kata benda. Pola: a tariff on + barang; impose/raise/lift tariffs.', 'Noun. Pattern: a tariff on + goods; impose/raise/lift tariffs.'),
  'container': VocabUsage('Each container is checked before it is loaded onto the ship.', '', 'Setiap peti kemas diperiksa sebelum dimuat ke kapal.', '', 'Kata benda. Kolokasi: shipping container, container ship/port. Juga berarti wadah umum.', 'Noun. Collocations: shipping container, container ship/port. Also means any holder.'),
  'pallet': VocabUsage('The workers stacked the boxes neatly on a wooden pallet.', '', 'Para pekerja menumpuk kotak-kotak dengan rapi di atas palet kayu.', '', 'Kata benda. Pola: on a pallet, stack/load pallets. Jangan tertukar dengan \'palette\' (palet cat).', 'Noun. Patterns: on a pallet, stack/load pallets. Don\'t confuse with \'palette\' (paint).'),
  'forklift': VocabUsage('Only trained staff are allowed to drive the forklift in the warehouse.', '', 'Hanya staf terlatih yang boleh mengemudikan forklift di gudang.', '', 'Kata benda. Kolokasi: drive/operate a forklift, forklift driver/operator.', 'Noun. Collocations: drive/operate a forklift, forklift driver/operator.'),
  'loading dock': VocabUsage('The delivery truck is waiting at the loading dock behind the building.', '', 'Truk pengiriman sedang menunggu di dermaga bongkar muat di belakang gedung.', '', 'Frasa benda. Pola: at the loading dock. Sering muncul di soal foto TOEIC.', 'Noun phrase. Pattern: at the loading dock. Common in TOEIC photo questions.'),
  'unload': VocabUsage('It took the team two hours to unload the truck.', '', 'Tim butuh dua jam untuk membongkar muatan truk itu.', '', 'Kata kerja. Pola: unload + kendaraan/barang. Lawan: load.', 'Verb. Pattern: unload + vehicle/goods. Opposite: load.'),
  'delayed': VocabUsage('Our shipment has been delayed because of bad weather at the port.', '', 'Kiriman kami tertunda karena cuaca buruk di pelabuhan.', '', 'Kata sifat/participle. Pola: be delayed by/because of + sebab. Kata dasar: delay.', 'Adjective/participle. Pattern: be delayed by/because of + cause. Base: delay.'),
  'expedite': VocabUsage('Could you expedite my order? I need it before the conference.', '', 'Bisakah Anda mempercepat pesanan saya? Saya butuh sebelum konferensi.', '', 'Kata kerja formal. Kolokasi: expedite an order/process/shipment. Sinonim santai: speed up.', 'Formal verb. Collocations: expedite an order/process/shipment. Informal synonym: speed up.'),
  'express delivery': VocabUsage('For an extra fee, we offer express delivery within one day.', '', 'Dengan biaya tambahan, kami menawarkan pengiriman kilat dalam satu hari.', '', 'Frasa benda. Pola: by express delivery, choose express delivery. Lawan: standard delivery.', 'Noun phrase. Patterns: by express delivery, choose express delivery. Opposite: standard delivery.'),
  'overnight': VocabUsage('If you order before 5 p.m., we will ship it overnight.', '', 'Jika Anda memesan sebelum pukul 5 sore, kami akan mengirimnya agar tiba besok.', '', 'Kata keterangan/sifat. Kolokasi: ship overnight, overnight delivery. Juga: stay overnight (menginap).', 'Adverb/adjective. Collocations: ship overnight, overnight delivery. Also: stay overnight.'),
  'postage': VocabUsage('The postage for this envelope is included in the price.', '', 'Ongkos pos untuk amplop ini sudah termasuk dalam harga.', '', 'Kata benda tak terhitung. Kolokasi: postage paid, postage and handling.', 'Uncountable noun. Collocations: postage paid, postage and handling.'),
  'fleet': VocabUsage('The company plans to add twenty electric vans to its fleet.', '', 'Perusahaan berencana menambah dua puluh van listrik ke armadanya.', '', 'Kata benda kolektif. Pola: a fleet of + kendaraan (trucks, vehicles, aircraft).', 'Collective noun. Pattern: a fleet of + vehicles (trucks, cars, aircraft).'),
  'carrier': VocabUsage('We use a different carrier for international shipments.', '', 'Kami memakai perusahaan angkutan yang berbeda untuk kiriman internasional.', '', 'Kata benda. Bisa berarti perusahaan pengangkut barang atau maskapai (air carrier).', 'Noun. Can mean a shipping company or an airline (air carrier).'),
  'bill of lading': VocabUsage('The captain signed the bill of lading before the ship left port.', '', 'Kapten menandatangani konosemen sebelum kapal meninggalkan pelabuhan.', '', 'Frasa benda (jamak: bills of lading). Dokumen resmi bukti penerimaan muatan oleh pengangkut.', 'Noun phrase (plural: bills of lading). Official document showing the carrier received the goods.'),
  'packing slip': VocabUsage('Check the items against the packing slip when the box arrives.', '', 'Cocokkan barang dengan daftar isi kiriman saat kotak tiba.', '', 'Frasa benda. Pola: check against the packing slip; included in/with the package.', 'Noun phrase. Patterns: check against the packing slip; included in/with the package.'),
  'bubble wrap': VocabUsage('Wrap each plate in bubble wrap before putting it in the box.', '', 'Bungkus setiap piring dengan plastik gelembung sebelum dimasukkan ke kotak.', '', 'Frasa benda tak terhitung. Pola: wrap something in bubble wrap.', 'Uncountable noun phrase. Pattern: wrap something in bubble wrap.'),
  'seal': VocabUsage('Do not accept the package if the seal is broken.', '', 'Jangan terima paketnya jika segelnya rusak.', '', 'Kata benda dan kerja. Pola: the seal is broken; seal an envelope/box (menyegel).', 'Noun and verb. Patterns: the seal is broken; seal an envelope/box.'),
  'storage': VocabUsage('We rent extra storage space for old files and equipment.', '', 'Kami menyewa ruang penyimpanan tambahan untuk arsip lama dan peralatan.', '', 'Kata benda tak terhitung. Kolokasi: storage space/room/unit, in storage. Kata kerja: store.', 'Uncountable noun. Collocations: storage space/room/unit, in storage. Verb: store.'),
  'supply chain': VocabUsage('The shortage of chips disrupted the entire supply chain.', '', 'Kelangkaan cip mengganggu seluruh rantai pasok.', '', 'Frasa benda. Kolokasi: disrupt the supply chain, supply chain management.', 'Noun phrase. Collocations: disrupt the supply chain, supply chain management.'),
  'stockroom': VocabUsage('Extra printer paper is kept in the stockroom on the second floor.', '', 'Kertas printer cadangan disimpan di gudang kecil di lantai dua.', '', 'Kata benda. Pola: in the stockroom. Mirip \'storeroom\'; lebih kecil dari \'warehouse\'.', 'Noun. Pattern: in the stockroom. Similar to \'storeroom\'; smaller than a \'warehouse\'.'),
  'door-to-door': VocabUsage('The moving company provides door-to-door service at a fixed price.', '', 'Perusahaan pindahan itu menyediakan layanan dari pintu ke pintu dengan harga tetap.', '', 'Kata sifat (pakai tanda hubung sebelum benda). Kolokasi: door-to-door delivery/service/sales.', 'Adjective (hyphenated before a noun). Collocations: door-to-door delivery/service/sales.'),
  'pick up': VocabUsage('I will pick up the samples from the supplier on my way to work.', '', 'Saya akan mengambil sampel dari pemasok dalam perjalanan ke kantor.', '', 'Phrasal verb terpisah: pick it up / pick up the box. Kata benda: pickup.', 'Separable phrasal verb: pick it up / pick up the box. Noun: pickup.'),
  'drop off': VocabUsage('You can drop off your documents at the front desk anytime.', '', 'Anda bisa mengantar dokumen ke meja depan kapan saja.', '', 'Phrasal verb terpisah: drop it off / drop off the keys. Lawan: pick up. Kata benda: drop-off.', 'Separable phrasal verb: drop it off / drop off the keys. Opposite: pick up. Noun: drop-off.'),
  'lost and found': VocabUsage('Someone handed in your umbrella to the lost and found.', '', 'Seseorang menyerahkan payung Anda ke bagian barang hilang dan temuan.', '', 'Frasa benda. Pola: check/go to the lost and found; hand something in to the lost and found.', 'Noun phrase. Patterns: check/go to the lost and found; hand something in to the lost and found.'),
  'install': VocabUsage('A technician will install the new air conditioner on Monday.', '', 'Seorang teknisi akan memasang AC baru pada hari Senin.', '', 'Kata kerja. Kolokasi: install software/equipment. Kata benda: installation.', 'Verb. Collocations: install software/equipment. Noun: installation.'),
  'operate': VocabUsage('Employees must complete safety training before they operate this machine.', '', 'Karyawan wajib menyelesaikan pelatihan keselamatan sebelum mengoperasikan mesin ini.', '', 'Kata kerja. Pola: operate + mesin; juga \'beroperasi\' (operate in Asia). Kata benda: operation, operator.', 'Verb. Pattern: operate + machine; also \'run a business\' (operate in Asia). Nouns: operation, operator.'),
  'productivity': VocabUsage('The new software has increased productivity by fifteen percent.', '', 'Perangkat lunak baru telah meningkatkan produktivitas sebesar lima belas persen.', '', 'Kata benda tak terhitung. Kolokasi: increase/boost/improve productivity. Sifat: productive.', 'Uncountable noun. Collocations: increase/boost/improve productivity. Adjective: productive.'),
  'defective': VocabUsage('Customers may return any defective product within thirty days.', '', 'Pelanggan boleh mengembalikan produk cacat apa pun dalam tiga puluh hari.', '', 'Kata sifat. Kolokasi: defective product/item/part. Kata benda: defect.', 'Adjective. Collocations: defective product/item/part. Noun: defect.'),
  'plant': VocabUsage('The company will open a new manufacturing plant in Vietnam next year.', '', 'Perusahaan akan membuka pabrik manufaktur baru di Vietnam tahun depan.', '', 'Kata benda. Kolokasi: manufacturing/power/assembly plant. Konteks bisnis, bukan \'tanaman\'.', 'Noun. Collocations: manufacturing/power/assembly plant. Business sense, not \'a growing plant\'.'),
  'manufacture': VocabUsage('This factory manufactures parts for several car companies.', '', 'Pabrik ini membuat suku cadang untuk beberapa perusahaan mobil.', '', 'Kata kerja dan benda. Kata turunan: manufacturer (produsen), manufacturing (industri manufaktur).', 'Verb and noun. Related: manufacturer (maker), manufacturing (the industry).'),
  'quality control': VocabUsage('Every product goes through quality control before it is packed.', '', 'Setiap produk melalui kendali mutu sebelum dikemas.', '', 'Frasa benda. Pola: go through / pass quality control; quality control team/inspector.', 'Noun phrase. Patterns: go through / pass quality control; quality control team/inspector.'),
  'breakdown': VocabUsage('A breakdown on the production line stopped work for two hours.', '', 'Kerusakan mesin di lini produksi menghentikan pekerjaan selama dua jam.', '', 'Kata benda. Kata kerja: break down (mogok). Juga: a breakdown of costs (rincian biaya).', 'Noun. Verb: break down. Also: a breakdown of costs (itemized list).'),
  'downtime': VocabUsage('We scheduled the system upgrade on Sunday to reduce downtime.', '', 'Kami menjadwalkan peningkatan sistem pada hari Minggu untuk mengurangi waktu henti.', '', 'Kata benda tak terhitung. Kolokasi: reduce/minimize downtime, unplanned downtime.', 'Uncountable noun. Collocations: reduce/minimize downtime, unplanned downtime.'),
  'batch': VocabUsage('The latest batch of samples failed the quality test.', '', 'Kelompok produksi sampel terbaru gagal dalam uji mutu.', '', 'Kata benda. Pola: a batch of + benda; in batches (bertahap per kelompok).', 'Noun. Pattern: a batch of + noun; in batches.'),
  'machinery': VocabUsage('The factory spent millions on new machinery last year.', '', 'Pabrik itu menghabiskan jutaan dolar untuk mesin-mesin baru tahun lalu.', '', 'Kata benda tak terhitung (tidak ada \'machineries\'). Bandingkan: a machine (terhitung).', 'Uncountable noun (no \'machineries\'). Compare: a machine (countable).'),
  'spare parts': VocabUsage('We keep spare parts in stock so repairs can be done quickly.', '', 'Kami menyimpan stok suku cadang agar perbaikan bisa dilakukan dengan cepat.', '', 'Frasa benda jamak. Kolokasi: order/keep spare parts, spare parts for + mesin.', 'Plural noun phrase. Collocations: order/keep spare parts, spare parts for + machine.'),
  'protective gear': VocabUsage('Visitors must wear protective gear when entering the factory floor.', '', 'Pengunjung wajib memakai alat pelindung diri saat memasuki area pabrik.', '', 'Frasa benda tak terhitung. Pola: wear protective gear. Mirip: safety equipment.', 'Uncountable noun phrase. Pattern: wear protective gear. Similar: safety equipment.'),
  'hazard': VocabUsage('Boxes left in the hallway are a fire hazard.', '', 'Kotak yang dibiarkan di lorong merupakan bahaya kebakaran.', '', 'Kata benda. Kolokasi: fire/safety/health hazard, pose a hazard. Sifat: hazardous.', 'Noun. Collocations: fire/safety/health hazard, pose a hazard. Adjective: hazardous.'),
  'precaution': VocabUsage('As a precaution, all employees should back up their files daily.', '', 'Sebagai tindakan pencegahan, semua karyawan sebaiknya mencadangkan berkas setiap hari.', '', 'Kata benda. Pola: as a precaution; take precautions against + risiko.', 'Noun. Patterns: as a precaution; take precautions against + risk.'),
  'recall': VocabUsage('The manufacturer announced a recall of 10,000 faulty heaters.', '', 'Produsen mengumumkan penarikan 10.000 pemanas yang rusak.', '', 'Kata benda dan kerja. Pola: a recall of + produk; recall a product. Arti lain: mengingat.', 'Noun and verb. Patterns: a recall of + product; recall a product. Other meaning: remember.'),
  'durable': VocabUsage('These office chairs are made of durable materials and last for years.', '', 'Kursi kantor ini terbuat dari bahan awet dan tahan bertahun-tahun.', '', 'Kata sifat. Kolokasi: durable material/goods/product. Kata benda: durability.', 'Adjective. Collocations: durable material/goods/product. Noun: durability.'),
  'carry out': VocabUsage('The engineers will carry out a full inspection next week.', '', 'Para insinyur akan melaksanakan inspeksi menyeluruh minggu depan.', '', 'Phrasal verb. Kolokasi: carry out a survey/test/plan/inspection. Lebih formal dari \'do\'.', 'Phrasal verb. Collocations: carry out a survey/test/plan/inspection. More formal than \'do\'.'),
  'put together': VocabUsage('It took us an hour to put together the new desks.', '', 'Kami butuh satu jam untuk merakit meja-meja baru itu.', '', 'Phrasal verb terpisah: put it together. Juga: put together a report/team (menyusun).', 'Separable phrasal verb: put it together. Also: put together a report/team.'),
  'shut down': VocabUsage('The plant will shut down for maintenance during the holidays.', '', 'Pabrik akan ditutup sementara untuk perawatan selama liburan.', '', 'Phrasal verb. Untuk mesin/komputer (mematikan) atau usaha (menutup). Kata benda: shutdown.', 'Phrasal verb. Used for machines/computers or businesses. Noun: shutdown.'),
  'reservation': VocabUsage('I would like to make a reservation for four people at seven o\'clock.', '', 'Saya ingin memesan tempat untuk empat orang pukul tujuh.', '', 'Kata benda. Pola: make/cancel/confirm a reservation; reservation for + jumlah/tanggal.', 'Noun. Patterns: make/cancel/confirm a reservation; reservation for + number/date.'),
  'itinerary': VocabUsage('The travel coordinator sent everyone a detailed itinerary for the trip.', '', 'Koordinator perjalanan mengirimi semua orang rencana perjalanan yang terperinci.', '', 'Kata benda. Kolokasi: a detailed/revised itinerary, plan an itinerary.', 'Noun. Collocations: a detailed/revised itinerary, plan an itinerary.'),
  'boarding pass': VocabUsage('Please have your boarding pass and passport ready at the gate.', '', 'Harap siapkan pas naik pesawat dan paspor Anda di gerbang.', '', 'Frasa benda. Pola: show/print your boarding pass; mobile boarding pass.', 'Noun phrase. Patterns: show/print your boarding pass; mobile boarding pass.'),
  'departure': VocabUsage('The departure of flight 302 has been moved to gate 12.', '', 'Keberangkatan penerbangan 302 telah dipindahkan ke gerbang 12.', '', 'Kata benda. Kolokasi: departure time/gate/lounge. Kata kerja: depart. Lawan: arrival.', 'Noun. Collocations: departure time/gate/lounge. Verb: depart. Opposite: arrival.'),
  'arrival': VocabUsage('Please contact the hotel shuttle upon arrival at the airport.', '', 'Silakan hubungi bus antar-jemput hotel setibanya di bandara.', '', 'Kata benda. Pola: upon/on arrival; arrival time/hall. Kata kerja: arrive (at/in).', 'Noun. Patterns: upon/on arrival; arrival time/hall. Verb: arrive (at/in).'),
  'layover': VocabUsage('I have a three-hour layover in Singapore before my flight to Tokyo.', '', 'Saya singgah tiga jam di Singapura sebelum penerbangan ke Tokyo.', '', 'Kata benda. Pola: a layover in + kota. Mirip \'stopover\' (biasanya lebih lama).', 'Noun. Pattern: a layover in + city. Similar to \'stopover\' (usually longer).'),
  'connecting flight': VocabUsage('If the first flight is late, I might miss my connecting flight.', '', 'Jika penerbangan pertama terlambat, saya bisa ketinggalan penerbangan lanjutan.', '', 'Frasa benda. Kolokasi: catch/miss a connecting flight.', 'Noun phrase. Collocations: catch/miss a connecting flight.'),
  'aisle seat': VocabUsage('I prefer an aisle seat on long flights so I can stretch my legs.', '', 'Saya lebih suka kursi lorong pada penerbangan jauh supaya bisa meluruskan kaki.', '', 'Frasa benda. \'Aisle\' dibaca /ail/ (s tidak dibaca). Lawan: window seat.', 'Noun phrase. \'Aisle\' is pronounced /ail/ (silent s). Opposite: window seat.'),
  'carry-on': VocabUsage('Each passenger may bring one carry-on bag into the cabin.', '', 'Setiap penumpang boleh membawa satu tas bagasi kabin ke dalam kabin.', '', 'Kata benda/sifat. Kolokasi: carry-on bag/luggage. Lawan: checked baggage.', 'Noun/adjective. Collocations: carry-on bag/luggage. Opposite: checked baggage.'),
  'baggage claim': VocabUsage('We waited at baggage claim for almost forty minutes.', '', 'Kami menunggu di tempat pengambilan bagasi hampir empat puluh menit.', '', 'Frasa benda. Pola: at baggage claim; baggage claim area/carousel.', 'Noun phrase. Patterns: at baggage claim; baggage claim area/carousel.'),
  'luggage': VocabUsage('Please do not leave your luggage unattended in the lobby.', '', 'Mohon jangan meninggalkan koper Anda tanpa pengawasan di lobi.', '', 'Kata benda tak terhitung: a piece of luggage (bukan \'luggages\'). Sinonim: baggage.', 'Uncountable noun: a piece of luggage (not \'luggages\'). Synonym: baggage.'),
  'check-in': VocabUsage('Online check-in opens 24 hours before the flight.', '', 'Lapor masuk daring dibuka 24 jam sebelum penerbangan.', '', 'Kata benda (pakai tanda hubung). Kata kerjanya \'check in\' tanpa tanda hubung: check in at the hotel.', 'Noun (hyphenated). The verb is \'check in\' without a hyphen: check in at the hotel.'),
  'round trip': VocabUsage('A round trip ticket to Bali is cheaper if you book early.', '', 'Tiket pulang pergi ke Bali lebih murah jika Anda memesan lebih awal.', '', 'Frasa benda/sifat (Amerika; Britania: return). Kolokasi: round trip ticket/fare.', 'Noun/adjective (US; UK: return). Collocations: round trip ticket/fare.'),
  'one-way': VocabUsage('She bought a one-way ticket because her return date was not fixed.', '', 'Dia membeli tiket sekali jalan karena tanggal pulangnya belum pasti.', '', 'Kata sifat. Kolokasi: one-way ticket/street. Lawan: round trip / return.', 'Adjective. Collocations: one-way ticket/street. Opposite: round trip / return.'),
  'passport': VocabUsage('Make sure your passport is valid for at least six months.', '', 'Pastikan paspor Anda berlaku setidaknya enam bulan.', '', 'Kata benda. Kolokasi: renew/apply for a passport, passport control, valid passport.', 'Noun. Collocations: renew/apply for a passport, passport control, valid passport.'),
  'flight attendant': VocabUsage('The flight attendant asked passengers to fasten their seat belts.', '', 'Pramugari meminta penumpang mengencangkan sabuk pengaman.', '', 'Frasa benda netral gender (pramugari/pramugara). Lebih umum dari \'stewardess\'.', 'Gender-neutral noun phrase. Preferred over \'stewardess\'.'),
  'booked up': VocabUsage('All the hotels near the venue are booked up for the weekend.', '', 'Semua hotel di dekat lokasi acara sudah penuh dipesan untuk akhir pekan.', '', 'Frasa sifat. Pola: be booked up (for + waktu). Sinonim: fully booked.', 'Adjective phrase. Pattern: be booked up (for + time). Synonym: fully booked.'),
  'room service': VocabUsage('He ordered a sandwich from room service after his late meeting.', '', 'Dia memesan roti lapis dari layanan kamar setelah rapat yang larut.', '', 'Frasa benda tak terhitung. Pola: order (something from) room service.', 'Uncountable noun phrase. Pattern: order (something from) room service.'),
  'concierge': VocabUsage('The concierge recommended a good seafood restaurant nearby.', '', 'Pramutamu hotel merekomendasikan restoran makanan laut yang enak di dekat sini.', '', 'Kata benda. Bisa orangnya atau mejanya: ask the concierge, at the concierge desk.', 'Noun. Can be the person or the desk: ask the concierge, at the concierge desk.'),
  'key card': VocabUsage('If your key card does not work, please go to the front desk.', '', 'Jika kartu kunci Anda tidak berfungsi, silakan ke meja depan.', '', 'Frasa benda. Kolokasi: swipe/insert a key card; key card access.', 'Noun phrase. Collocations: swipe/insert a key card; key card access.'),
  'wake-up call': VocabUsage('Could I have a wake-up call at six tomorrow morning?', '', 'Bisakah saya dibangunkan lewat telepon pukul enam besok pagi?', '', 'Frasa benda. Pola: request/get a wake-up call at + jam. Kiasan: peringatan keras.', 'Noun phrase. Pattern: request/get a wake-up call at + time. Figurative: a warning.'),
  'housekeeping': VocabUsage('Housekeeping will clean your room between ten and two.', '', 'Petugas tata graha akan membersihkan kamar Anda antara pukul sepuluh dan dua.', '', 'Kata benda tak terhitung; merujuk ke bagian/staf kebersihan hotel. Kolokasi: housekeeping staff.', 'Uncountable noun; refers to the hotel cleaning department. Collocation: housekeeping staff.'),
  'shuttle bus': VocabUsage('A free shuttle bus runs between the hotel and the airport every hour.', '', 'Bus antar-jemput gratis beroperasi antara hotel dan bandara setiap jam.', '', 'Frasa benda. Kolokasi: take the shuttle bus; airport shuttle; the shuttle runs every + waktu.', 'Noun phrase. Collocations: take the shuttle bus; airport shuttle; runs every + time.'),
  'car rental': VocabUsage('The company covers car rental costs for business trips.', '', 'Perusahaan menanggung biaya sewa mobil untuk perjalanan dinas.', '', 'Frasa benda. Kolokasi: car rental company/desk. Kata kerja: rent a car (Brit.: hire a car).', 'Noun phrase. Collocations: car rental company/desk. Verb: rent a car (UK: hire a car).'),
  'travel agency': VocabUsage('We booked the whole conference trip through a local travel agency.', '', 'Kami memesan seluruh perjalanan konferensi melalui biro perjalanan lokal.', '', 'Frasa benda. Pola: book through a travel agency. Orangnya: travel agent.', 'Noun phrase. Pattern: book through a travel agency. The person: travel agent.'),
  'per diem': VocabUsage('Employees receive a per diem of fifty dollars for meals while traveling.', '', 'Karyawan menerima uang harian dinas lima puluh dolar untuk makan selama perjalanan.', '', 'Frasa benda (Latin, \'per hari\'). Pola: a per diem of + jumlah; per diem allowance.', 'Noun phrase (Latin, \'per day\'). Pattern: a per diem of + amount; per diem allowance.'),
  'business class': VocabUsage('Senior managers are allowed to fly business class on long trips.', '', 'Manajer senior boleh terbang kelas bisnis untuk perjalanan jauh.', '', 'Frasa benda/keterangan. Pola: fly business class (tanpa \'in\'); business class seat.', 'Noun/adverb phrase. Pattern: fly business class (no \'in\'); business class seat.'),
  'upgrade': VocabUsage('The airline offered to upgrade us to business class for free.', '', 'Maskapai menawarkan untuk menaikkan kelas kami ke kelas bisnis secara gratis.', '', 'Kata kerja dan benda. Pola: upgrade (someone) to + kelas; get an upgrade.', 'Verb and noun. Pattern: upgrade (someone) to + class; get an upgrade.'),
  'no-show': VocabUsage('Hotels often charge a fee for a no-show without cancellation.', '', 'Hotel sering mengenakan biaya bagi tamu yang tidak datang tanpa pembatalan.', '', 'Kata benda (pakai tanda hubung). Bisa orangnya atau kejadiannya. Kolokasi: no-show fee.', 'Noun (hyphenated). Can mean the person or the event. Collocation: no-show fee.'),
  'traffic jam': VocabUsage('I\'m sorry I\'m late; I was stuck in a traffic jam on the highway.', '', 'Maaf saya terlambat; saya terjebak macet di jalan tol.', '', 'Frasa benda. Pola: be stuck in a traffic jam. Sinonim: heavy traffic.', 'Noun phrase. Pattern: be stuck in a traffic jam. Synonym: heavy traffic.'),
  'stop by': VocabUsage('Feel free to stop by my office if you have any questions.', '', 'Silakan mampir ke kantor saya jika ada pertanyaan.', '', 'Phrasal verb informal. Pola: stop by + tempat. Sinonim: drop by.', 'Informal phrasal verb. Pattern: stop by + place. Synonym: drop by.'),
  'venue': VocabUsage('The venue for this year\'s conference is a hotel near the beach.', '', 'Tempat acara konferensi tahun ini adalah sebuah hotel dekat pantai.', '', 'Kata benda. Pola: the venue for + acara; book/change the venue.', 'Noun. Pattern: the venue for + event; book/change the venue.'),
  'caterer': VocabUsage('We hired a caterer to provide lunch for two hundred guests.', '', 'Kami menyewa penyedia katering untuk menyediakan makan siang bagi dua ratus tamu.', '', 'Kata benda (orang/perusahaan). Kata kerja: cater (for). Kegiatannya: catering.', 'Noun (person/company). Verb: cater (for). The service: catering.'),
  'banquet': VocabUsage('The annual banquet will be held in the hotel\'s grand ballroom.', '', 'Jamuan makan tahunan akan diadakan di ruang dansa utama hotel.', '', 'Kata benda. Kolokasi: hold a banquet, banquet hall. Lebih formal dari \'dinner party\'.', 'Noun. Collocations: hold a banquet, banquet hall. More formal than \'dinner party\'.'),
  'buffet': VocabUsage('A buffet breakfast is included in the room rate.', '', 'Sarapan prasmanan sudah termasuk dalam tarif kamar.', '', 'Kata benda. Kolokasi: buffet breakfast/lunch, all-you-can-eat buffet. Dibaca /bu-fei/.', 'Noun. Collocations: buffet breakfast/lunch, all-you-can-eat buffet. Pronounced /bu-fay/.'),
  'appetizer': VocabUsage('We ordered a few appetizers to share before the main course.', '', 'Kami memesan beberapa hidangan pembuka untuk dibagi sebelum hidangan utama.', '', 'Kata benda (Amerika; Britania: starter). Pola: order an appetizer, as an appetizer.', 'Noun (US; UK: starter). Patterns: order an appetizer, as an appetizer.'),
  'main course': VocabUsage('For the main course, guests can choose fish or chicken.', '', 'Untuk hidangan utama, tamu bisa memilih ikan atau ayam.', '', 'Frasa benda. Pola: for the main course. Sinonim Amerika: entree.', 'Noun phrase. Pattern: for the main course. US synonym: entree.'),
  'dessert': VocabUsage('The dinner ended with coffee and a chocolate dessert.', '', 'Makan malam diakhiri dengan kopi dan hidangan penutup cokelat.', '', 'Kata benda. Pola: for dessert. Jangan tertukar dengan \'desert\' (gurun), satu s.', 'Noun. Pattern: for dessert. Don\'t confuse with \'desert\' (one s).'),
  'beverage': VocabUsage('Beverages are available at the back of the conference room.', '', 'Minuman tersedia di bagian belakang ruang konferensi.', '', 'Kata benda formal untuk \'drink\'. Kolokasi: food and beverage, hot/cold beverages.', 'Formal noun for \'drink\'. Collocations: food and beverage, hot/cold beverages.'),
  'menu': VocabUsage('The restaurant changes its lunch menu every season.', '', 'Restoran itu mengganti menu makan siangnya setiap musim.', '', 'Kata benda. Pola: on the menu (ada di menu); set menu, menu item.', 'Noun. Patterns: on the menu; set menu, menu item.'),
  'tip': VocabUsage('In this country, it is common to leave a tip of about ten percent.', '', 'Di negara ini, sudah biasa memberi uang tip sekitar sepuluh persen.', '', 'Kata benda dan kerja. Pola: leave/give a tip; tip the waiter. Arti lain: saran (a useful tip).', 'Noun and verb. Patterns: leave/give a tip; tip the waiter. Other meaning: advice.'),
  'waiter': VocabUsage('The waiter brought us the bill and a small dish of mints.', '', 'Pelayan restoran membawakan kami tagihan dan sepiring kecil permen mint.', '', 'Kata benda. Bentuk netral: server; perempuan: waitress. Kata kerja: wait tables.', 'Noun. Neutral form: server; female: waitress. Verb phrase: wait tables.'),
  'dine in': VocabUsage('Would you like to dine in or take your order to go?', '', 'Apakah Anda ingin makan di tempat atau pesanan dibawa pulang?', '', 'Phrasal verb. Lawan: take out / to go. Kata sifat: dine-in customers.', 'Phrasal verb. Opposite: take out / to go. Adjective: dine-in customers.'),
  'takeout': VocabUsage('We ordered takeout because the meeting ran late.', '', 'Kami memesan makanan bawa pulang karena rapatnya molor.', '', 'Kata benda (Amerika; Britania: takeaway). Pola: order/get takeout.', 'Noun (US; UK: takeaway). Patterns: order/get takeout.'),
  'gathering': VocabUsage('The team had a small gathering to celebrate the project\'s success.', '', 'Tim mengadakan acara kumpul-kumpul kecil untuk merayakan keberhasilan proyek.', '', 'Kata benda. Kolokasi: a social/family gathering, hold a gathering. Kata kerja: gather.', 'Noun. Collocations: a social/family gathering, hold a gathering. Verb: gather.'),
  'award ceremony': VocabUsage('She received the Employee of the Year prize at the award ceremony.', '', 'Dia menerima penghargaan Karyawan Terbaik Tahun Ini di upacara penghargaan.', '', 'Frasa benda. Pola: at the award ceremony; hold/attend an award ceremony.', 'Noun phrase. Patterns: at the award ceremony; hold/attend an award ceremony.'),
  'anniversary': VocabUsage('The company is celebrating its twentieth anniversary this month.', '', 'Perusahaan sedang merayakan hari jadinya yang kedua puluh bulan ini.', '', 'Kata benda. Pola: celebrate the + angka urutan + anniversary; wedding anniversary.', 'Noun. Pattern: celebrate the + ordinal + anniversary; wedding anniversary.'),
  'farewell party': VocabUsage('We are throwing a farewell party for Mr. Lee, who is retiring.', '', 'Kami mengadakan pesta perpisahan untuk Pak Lee yang akan pensiun.', '', 'Frasa benda. Kolokasi: throw/hold a farewell party for + orang.', 'Noun phrase. Collocations: throw/hold a farewell party for + person.'),
  'RSVP': VocabUsage('Please RSVP by March 10 so we can arrange the seating.', '', 'Mohon konfirmasi kehadiran paling lambat 10 Maret agar kami bisa mengatur tempat duduk.', '', 'Singkatan Prancis (répondez s\'il vous plaît). Dipakai sebagai kata kerja: RSVP by + tanggal.', 'French abbreviation (please reply). Used as a verb: RSVP by + date.'),
  'invitation': VocabUsage('Thank you for your invitation to the product launch.', '', 'Terima kasih atas undangan Anda ke peluncuran produk.', '', 'Kata benda. Pola: an invitation to + acara; accept/decline an invitation. Kata kerja: invite.', 'Noun. Pattern: an invitation to + event; accept/decline an invitation. Verb: invite.'),
  'guest list': VocabUsage('Please add the new clients to the guest list for Friday\'s dinner.', '', 'Tolong tambahkan klien baru ke daftar tamu untuk makan malam hari Jumat.', '', 'Frasa benda. Pola: on the guest list; add someone to the guest list.', 'Noun phrase. Patterns: on the guest list; add someone to the guest list.'),
  'host': VocabUsage('Our branch will host the regional sales meeting this year.', '', 'Cabang kami akan menjadi tuan rumah rapat penjualan regional tahun ini.', '', 'Kata benda dan kerja. Pola: host a meeting/event; be the host of. Juga: pembawa acara.', 'Noun and verb. Patterns: host a meeting/event; be the host of. Also: presenter.'),
  'organizer': VocabUsage('The organizers thanked all the volunteers at the end of the event.', '', 'Para penyelenggara berterima kasih kepada semua relawan di akhir acara.', '', 'Kata benda. Pola: the organizer of + acara. Kata kerja: organize (Brit.: organiser).', 'Noun. Pattern: the organizer of + event. Verb: organize (UK: organiser).'),
  'auditorium': VocabUsage('The keynote speech will take place in the main auditorium.', '', 'Pidato utama akan berlangsung di auditorium utama.', '', 'Kata benda. Pola: in the auditorium. Jamak: auditoriums.', 'Noun. Pattern: in the auditorium. Plural: auditoriums.'),
  'banner': VocabUsage('A large banner with the company logo hung above the entrance.', '', 'Sebuah spanduk besar dengan logo perusahaan tergantung di atas pintu masuk.', '', 'Kata benda. Kolokasi: hang/put up a banner. Juga: banner ad (iklan spanduk di web).', 'Noun. Collocations: hang/put up a banner. Also: banner ad (online).'),
  'refreshments': VocabUsage('Light refreshments will be served after the presentation.', '', 'Hidangan ringan akan disajikan setelah presentasi.', '', 'Kata benda jamak. Kolokasi: light refreshments, refreshments will be served/provided.', 'Plural noun. Collocations: light refreshments, refreshments will be served/provided.'),
  'toast': VocabUsage('The CEO raised his glass and proposed a toast to the new partners.', '', 'CEO mengangkat gelasnya dan mengajak bersulang untuk para mitra baru.', '', 'Kata benda dan kerja. Pola: propose/make a toast to + orang; toast the couple.', 'Noun and verb. Patterns: propose/make a toast to + person; toast the couple.'),
  'attendance': VocabUsage('Attendance at the safety training is required for all staff.', '', 'Kehadiran dalam pelatihan keselamatan wajib bagi seluruh staf.', '', 'Kata benda. Pola: attendance at + acara; high/low attendance. Kata kerja: attend.', 'Noun. Pattern: attendance at + event; high/low attendance. Verb: attend.'),
  'admission': VocabUsage('Admission to the trade fair is free for registered visitors.', '', 'Tiket masuk ke pameran dagang gratis bagi pengunjung terdaftar.', '', 'Kata benda. Pola: admission to + tempat; admission fee/ticket. Arti lain: pengakuan.', 'Noun. Pattern: admission to + place; admission fee/ticket. Other meaning: confession.'),
  'sold out': VocabUsage('Tickets for the opening concert were sold out within an hour.', '', 'Tiket konser pembukaan habis terjual dalam satu jam.', '', 'Frasa sifat. Pola: be sold out; a sold-out show (pakai tanda hubung sebelum benda).', 'Adjective phrase. Pattern: be sold out; a sold-out show (hyphenated before a noun).'),
  'raffle': VocabUsage('All guests can enter the raffle to win a weekend trip.', '', 'Semua tamu bisa ikut undian untuk memenangkan perjalanan akhir pekan.', '', 'Kata benda. Kolokasi: enter a raffle, raffle ticket/prize, hold a raffle.', 'Noun. Collocations: enter a raffle, raffle ticket/prize, hold a raffle.'),
  'usher': VocabUsage('An usher showed us to our seats in the front row.', '', 'Seorang pengantar tamu mengantar kami ke kursi di barisan depan.', '', 'Kata benda dan kerja. Pola: usher someone to/into + tempat.', 'Noun and verb. Pattern: usher someone to/into + place.'),
  'audience': VocabUsage('The audience asked many questions after the speech.', '', 'Penonton mengajukan banyak pertanyaan setelah pidato.', '', 'Kata benda kolektif. Kolokasi: a large/small audience, target audience.', 'Collective noun. Collocations: a large/small audience, target audience.'),
  'queue': VocabUsage('There was a long queue at the registration desk this morning.', '', 'Ada antrean panjang di meja registrasi pagi ini.', '', 'Kata benda/kerja (Britania; Amerika: line). Pola: in a queue, queue up for + sesuatu.', 'Noun/verb (UK; US: line). Patterns: in a queue, queue up for + something.'),
  'line up': VocabUsage('Visitors lined up outside the store before it opened.', '', 'Pengunjung mengantre di luar toko sebelum toko buka.', '', 'Phrasal verb. Pola: line up for + sesuatu. Juga: line up a speaker (mengatur/menyiapkan).', 'Phrasal verb. Pattern: line up for + something. Also: line up a speaker (arrange).'),
  'inquiry': VocabUsage('Thank you for your inquiry about our corporate rates.', '', 'Terima kasih atas pertanyaan Anda tentang tarif korporat kami.', '', 'Kata benda. Pola: an inquiry about/into + hal; make an inquiry. Kata kerja: inquire.', 'Noun. Pattern: an inquiry about/into + topic; make an inquiry. Verb: inquire.'),
  'complaint': VocabUsage('We received a complaint about the slow delivery service.', '', 'Kami menerima keluhan tentang layanan pengiriman yang lambat.', '', 'Kata benda. Pola: make/file a complaint about + hal. Kata kerja: complain (about).', 'Noun. Pattern: make/file a complaint about + issue. Verb: complain (about).'),
  'refund': VocabUsage('You will receive a full refund if the item is returned unused.', '', 'Anda akan menerima pengembalian uang penuh jika barang dikembalikan dalam keadaan belum dipakai.', '', 'Kata benda dan kerja. Kolokasi: full refund, request/issue a refund. Sifat: refundable.', 'Noun and verb. Collocations: full refund, request/issue a refund. Adjective: refundable.'),
  'warranty': VocabUsage('The laptop comes with a two-year warranty.', '', 'Laptop ini dilengkapi garansi dua tahun.', '', 'Kata benda. Pola: under warranty (masih bergaransi); a warranty on/for + produk.', 'Noun. Patterns: under warranty; a warranty on/for + product.'),
  'replacement': VocabUsage('We will send you a replacement for the damaged printer.', '', 'Kami akan mengirimkan pengganti untuk printer yang rusak.', '', 'Kata benda. Pola: a replacement for + benda/orang. Kata kerja: replace.', 'Noun. Pattern: a replacement for + item/person. Verb: replace.'),
  'cancel': VocabUsage('Due to the storm, we had to cancel the outdoor event.', '', 'Karena badai, kami terpaksa membatalkan acara luar ruangan.', '', 'Kata kerja. Kolokasi: cancel a meeting/order/flight. Kata benda: cancellation.', 'Verb. Collocations: cancel a meeting/order/flight. Noun: cancellation.'),
  'hotline': VocabUsage('Customers can call our hotline twenty-four hours a day.', '', 'Pelanggan bisa menghubungi layanan telepon kami dua puluh empat jam sehari.', '', 'Kata benda. Kolokasi: customer service hotline, call the hotline.', 'Noun. Collocations: customer service hotline, call the hotline.'),
  'representative': VocabUsage('A customer service representative will contact you shortly.', '', 'Seorang perwakilan layanan pelanggan akan segera menghubungi Anda.', '', 'Kata benda. Kolokasi: sales/customer service representative (sering disingkat \'rep\').', 'Noun. Collocations: sales/customer service representative (often \'rep\').'),
  'on hold': VocabUsage('I was on hold for twenty minutes before someone answered.', '', 'Saya menunggu di telepon selama dua puluh menit sebelum ada yang menjawab.', '', 'Frasa. Pola: be on hold; put someone on hold. Juga: proyek ditunda (the project is on hold).', 'Phrase. Patterns: be on hold; put someone on hold. Also: postponed (the project is on hold).'),
  'hang up': VocabUsage('Please don\'t hang up; I\'ll transfer you to the manager.', '', 'Mohon jangan tutup teleponnya; saya akan menyambungkan Anda ke manajer.', '', 'Phrasal verb. Pola: hang up (on someone) = menutup telepon secara tiba-tiba.', 'Phrasal verb. Pattern: hang up (on someone) = end a call abruptly.'),
  'call back': VocabUsage('Ms. Park is in a meeting, but she will call you back after lunch.', '', 'Bu Park sedang rapat, tetapi dia akan menelepon balik Anda setelah makan siang.', '', 'Phrasal verb terpisah: call someone back. Kata benda: callback.', 'Separable phrasal verb: call someone back. Noun: callback.'),
  'apologize': VocabUsage('We apologize for the delay in processing your order.', '', 'Kami meminta maaf atas keterlambatan pemrosesan pesanan Anda.', '', 'Kata kerja. Pola: apologize (to someone) for + benda/-ing. Kata benda: apology.', 'Verb. Pattern: apologize (to someone) for + noun/-ing. Noun: apology.'),
  'inconvenience': VocabUsage('We are sorry for any inconvenience this may cause.', '', 'Kami mohon maaf atas ketidaknyamanan yang mungkin ditimbulkan.', '', 'Kata benda. Ungkapan baku surat: sorry for any inconvenience. Sifat: inconvenient.', 'Noun. Standard letter phrase: sorry for any inconvenience. Adjective: inconvenient.'),
  'satisfaction': VocabUsage('Customer satisfaction has always been the highest priority for our team.', '', 'Kepuasan pelanggan selalu menjadi prioritas tertinggi bagi tim kami.', '', 'Kata benda. Kolokasi: customer/job satisfaction, satisfaction survey. Sifat: satisfied.', 'Noun. Collocations: customer/job satisfaction, satisfaction survey. Adjective: satisfied.'),
  'exchange': VocabUsage('You can exchange the shirt for a larger size within two weeks.', '', 'Anda bisa menukar kemeja itu dengan ukuran lebih besar dalam dua minggu.', '', 'Kata kerja dan benda. Pola: exchange A for B. Beda: refund = uang kembali.', 'Verb and noun. Pattern: exchange A for B. Compare: refund = money back.'),
  'courteous': VocabUsage('The hotel staff were courteous and very helpful.', '', 'Staf hotel itu sopan dan sangat membantu.', '', 'Kata sifat formal. Kolokasi: courteous staff/service. Kata benda: courtesy.', 'Formal adjective. Collocations: courteous staff/service. Noun: courtesy.'),
  'prompt': VocabUsage('Thank you for your prompt reply to my email.', '', 'Terima kasih atas balasan cepat Anda terhadap email saya.', '', 'Kata sifat. Kolokasi: prompt reply/response/payment. Keterangan: promptly (= tepat waktu).', 'Adjective. Collocations: prompt reply/response/payment. Adverb: promptly.'),
  'troubleshoot': VocabUsage('The IT team is trying to troubleshoot the network problem.', '', 'Tim IT sedang berusaha mengatasi masalah jaringan.', '', 'Kata kerja. Pola: troubleshoot + masalah/perangkat. Kata benda: troubleshooting.', 'Verb. Pattern: troubleshoot + problem/device. Noun: troubleshooting.'),
  'FAQ': VocabUsage('Most common questions are answered in the FAQ section of our website.', '', 'Sebagian besar pertanyaan umum dijawab di bagian FAQ situs web kami.', '', 'Singkatan: frequently asked questions. Kolokasi: FAQ page/section, check the FAQ.', 'Abbreviation: frequently asked questions. Collocations: FAQ page/section, check the FAQ.'),
  'membership': VocabUsage('Gym membership is free for all full-time employees.', '', 'Keanggotaan pusat kebugaran gratis bagi semua karyawan tetap.', '', 'Kata benda. Kolokasi: membership fee/card, renew a membership.', 'Noun. Collocations: membership fee/card, renew a membership.'),
  'toll-free': VocabUsage('For assistance, please call our toll-free number.', '', 'Untuk bantuan, silakan hubungi nomor bebas pulsa kami.', '', 'Kata sifat (pakai tanda hubung). Kolokasi: toll-free number/line.', 'Adjective (hyphenated). Collocations: toll-free number/line.'),
  'deal with': VocabUsage('Our support team deals with hundreds of requests every day.', '', 'Tim dukungan kami menangani ratusan permintaan setiap hari.', '', 'Phrasal verb tak terpisah. Pola: deal with + masalah/orang. Bentuk lampau: dealt with.', 'Inseparable phrasal verb. Pattern: deal with + problem/person. Past: dealt with.'),
  'look into': VocabUsage('I will look into the billing error and get back to you.', '', 'Saya akan menyelidiki kesalahan tagihan itu dan menghubungi Anda kembali.', '', 'Phrasal verb tak terpisah. Pola: look into + masalah/keluhan. Sinonim formal: investigate.', 'Inseparable phrasal verb. Pattern: look into + issue/complaint. Formal synonym: investigate.'),
  'password': VocabUsage('Please change your password every ninety days for security.', '', 'Silakan ganti kata sandi Anda setiap sembilan puluh hari demi keamanan.', '', 'Kata benda. Kolokasi: enter/change/reset a password, strong password.', 'Noun. Collocations: enter/change/reset a password, strong password.'),
  'log in': VocabUsage('You need to log in with your employee ID to access the system.', '', 'Anda perlu masuk akun dengan ID karyawan untuk mengakses sistem.', '', 'Phrasal verb. Pola: log in (to + sistem). Kata benda: login (tanpa spasi).', 'Phrasal verb. Pattern: log in (to + system). Noun: login (one word).'),
  'log out': VocabUsage('Always log out of your account when using a shared computer.', '', 'Selalu keluar dari akun Anda saat memakai komputer bersama.', '', 'Phrasal verb. Pola: log out of + akun. Lawan: log in. Kata benda: logout.', 'Phrasal verb. Pattern: log out of + account. Opposite: log in. Noun: logout.'),
  'username': VocabUsage('Your username is the first part of your company email address.', '', 'Nama pengguna Anda adalah bagian pertama alamat email kantor Anda.', '', 'Kata benda. Pola: enter your username and password.', 'Noun. Pattern: enter your username and password.'),
  'update': VocabUsage('Please update the software before the meeting starts.', '', 'Tolong perbarui perangkat lunaknya sebelum rapat dimulai.', '', 'Kata kerja dan benda. Kolokasi: update software/records; a software update. Sifat: updated.', 'Verb and noun. Collocations: update software/records; a software update. Adjective: updated.'),
  'download': VocabUsage('You can download the application form from our website.', '', 'Anda bisa mengunduh formulir pendaftaran dari situs web kami.', '', 'Kata kerja dan benda. Pola: download + file from + sumber. Lawan: upload.', 'Verb and noun. Pattern: download + file from + source. Opposite: upload.'),
  'upload': VocabUsage('Please upload your receipts to the expense system by Friday.', '', 'Tolong unggah kuitansi Anda ke sistem pengeluaran paling lambat Jumat.', '', 'Kata kerja dan benda. Pola: upload + file to + sistem. Lawan: download.', 'Verb and noun. Pattern: upload + file to + system. Opposite: download.'),
  'server': VocabUsage('The website was down because the server was overloaded.', '', 'Situs web tidak bisa diakses karena servernya kelebihan beban.', '', 'Kata benda. Kolokasi: the server is down, server room, mail server. Arti lain: pelayan.', 'Noun. Collocations: the server is down, server room, mail server. Other meaning: waiter.'),
  'backup': VocabUsage('Make a backup of all important files before the system upgrade.', '', 'Buat cadangan semua berkas penting sebelum peningkatan sistem.', '', 'Kata benda (satu kata). Kata kerjanya \'back up\' (dua kata): back up your files.', 'Noun (one word). The verb is \'back up\' (two words): back up your files.'),
  'tech support': VocabUsage('If your laptop won\'t start, contact tech support.', '', 'Jika laptop Anda tidak mau menyala, hubungi dukungan teknis.', '', 'Frasa benda tak terhitung (singkatan technical support). Pola: call/contact tech support.', 'Uncountable noun phrase (short for technical support). Pattern: call/contact tech support.'),
  'software': VocabUsage('The accounting department uses new software to manage invoices.', '', 'Bagian akuntansi memakai perangkat lunak baru untuk mengelola faktur.', '', 'Kata benda tak terhitung (bukan \'softwares\'). Hitung: a software program/package.', 'Uncountable noun (not \'softwares\'). Countable: a software program/package.'),
  'hardware': VocabUsage('The budget includes new hardware such as monitors and printers.', '', 'Anggaran mencakup perangkat keras baru seperti monitor dan printer.', '', 'Kata benda tak terhitung. Lawan: software. Juga: toko perkakas (hardware store).', 'Uncountable noun. Opposite: software. Also: tools shop (hardware store).'),
  'keyboard': VocabUsage('My keyboard stopped working, so I borrowed one from IT.', '', 'Papan ketik saya berhenti berfungsi, jadi saya meminjam satu dari bagian IT.', '', 'Kata benda. Kolokasi: wireless keyboard, keyboard shortcut.', 'Noun. Collocations: wireless keyboard, keyboard shortcut.'),
  'scanner': VocabUsage('Use the scanner on the third floor to make digital copies of the contracts.', '', 'Gunakan pemindai di lantai tiga untuk membuat salinan digital kontrak.', '', 'Kata benda. Kata kerja: scan (scan a document). Kolokasi: document scanner.', 'Noun. Verb: scan (scan a document). Collocation: document scanner.'),
  'inbox': VocabUsage('My inbox was full of messages after the holiday.', '', 'Kotak masuk saya penuh pesan setelah liburan.', '', 'Kata benda. Pola: in my inbox; check your inbox. Lawan: outbox / sent items.', 'Noun. Patterns: in my inbox; check your inbox. Opposite: outbox / sent items.'),
  'cc': VocabUsage('Please cc your manager on all emails to the client.', '', 'Tolong beri tembusan kepada manajer Anda di semua email ke klien.', '', 'Kata kerja/benda (dari carbon copy). Pola: cc someone on + email. Bentuk lampau: cc\'d.', 'Verb/noun (from carbon copy). Pattern: cc someone on + email. Past: cc\'d.'),
  'forward': VocabUsage('Could you forward me the schedule that Ms. Tan sent yesterday?', '', 'Bisakah Anda meneruskan kepada saya jadwal yang dikirim Bu Tan kemarin?', '', 'Kata kerja. Pola: forward + email to + orang; forward someone + email.', 'Verb. Patterns: forward + email to + person; forward someone + email.'),
  'reply': VocabUsage('Please reply to this email by the end of the day.', '', 'Mohon balas email ini paling lambat akhir hari.', '', 'Kata kerja dan benda. Pola: reply to + email/orang (wajib \'to\'). Bandingkan: answer + objek.', 'Verb and noun. Pattern: reply to + email/person (\'to\' needed). Compare: answer + object.'),
  'crash': VocabUsage('The program crashed and I lost my unsaved work.', '', 'Programnya mogok total dan pekerjaan saya yang belum disimpan hilang.', '', 'Kata kerja dan benda (tak berobjek untuk komputer). Kolokasi: system crash, the app crashed.', 'Verb and noun (intransitive for computers). Collocations: system crash, the app crashed.'),
  'reboot': VocabUsage('If the screen freezes, try to reboot the computer.', '', 'Jika layarnya macet, coba nyalakan ulang komputernya.', '', 'Kata kerja dan benda. Sinonim: restart. Pola: reboot the system/computer.', 'Verb and noun. Synonym: restart. Pattern: reboot the system/computer.'),
  'video call': VocabUsage('Let\'s have a quick video call to discuss the design.', '', 'Mari kita lakukan panggilan video singkat untuk membahas desainnya.', '', 'Frasa benda. Kolokasi: have/join/make a video call; on a video call.', 'Noun phrase. Collocations: have/join/make a video call; on a video call.'),
  'printout': VocabUsage('Bring a printout of the agenda to the meeting.', '', 'Bawalah hasil cetak agenda ke rapat.', '', 'Kata benda (satu kata). Pola: a printout of + dokumen. Kata kerja: print out.', 'Noun (one word). Pattern: a printout of + document. Verb: print out.'),
  'up to date': VocabUsage('Please keep the client contact list up to date.', '', 'Tolong jaga daftar kontak klien agar tetap terkini.', '', 'Frasa sifat. Pola: keep something up to date; sebelum benda pakai tanda hubung: up-to-date data.', 'Adjective phrase. Pattern: keep something up to date; before a noun: up-to-date data.'),
  'out of date': VocabUsage('The price list on the website is out of date.', '', 'Daftar harga di situs web sudah usang.', '', 'Frasa sifat. Lawan: up to date. Sebelum benda: out-of-date information.', 'Adjective phrase. Opposite: up to date. Before a noun: out-of-date information.'),
  'keep track of': VocabUsage('We use a spreadsheet to keep track of all our expenses.', '', 'Kami memakai lembar kerja untuk terus memantau semua pengeluaran.', '', 'Ungkapan. Pola: keep track of + benda. Lawan: lose track of (kehilangan jejak).', 'Expression. Pattern: keep track of + noun. Opposite: lose track of.'),
  'figure out': VocabUsage('It took me a while to figure out how the new system works.', '', 'Saya butuh waktu cukup lama untuk memahami cara kerja sistem baru.', '', 'Phrasal verb. Pola: figure out + how/what/why...; figure it out. Informal.', 'Phrasal verb. Pattern: figure out + how/what/why...; figure it out. Informal.'),
  'catch up': VocabUsage('I need to catch up on my emails after the business trip.', '', 'Saya perlu mengejar ketinggalan membaca email setelah perjalanan dinas.', '', 'Phrasal verb. Pola: catch up on + pekerjaan; catch up with + orang.', 'Phrasal verb. Patterns: catch up on + work; catch up with + person.'),
  'tenant': VocabUsage('The new tenant will move into the second-floor office next month.', '', 'Penyewa baru akan menempati kantor di lantai dua bulan depan.', '', 'Kata benda. Lawan: landlord (pemilik). Kolokasi: tenant agreement.', 'Noun. Opposite: landlord. Collocation: tenant agreement.'),
  'lease': VocabUsage('We signed a five-year lease for the new office.', '', 'Kami menandatangani kontrak sewa lima tahun untuk kantor baru.', '', 'Kata benda dan kerja. Pola: sign/renew a lease; lease + properti from/to + orang.', 'Noun and verb. Patterns: sign/renew a lease; lease + property from/to + person.'),
  'renovation': VocabUsage('The lobby is closed for renovation until next month.', '', 'Lobi ditutup untuk renovasi hingga bulan depan.', '', 'Kata benda. Pola: closed for renovation; under renovation. Kata kerja: renovate.', 'Noun. Patterns: closed for renovation; under renovation. Verb: renovate.'),
  'property': VocabUsage('The company owns several commercial properties in the city center.', '', 'Perusahaan itu memiliki beberapa properti komersial di pusat kota.', '', 'Kata benda. Kolokasi: commercial/residential property, property value. Arti lain: milik.', 'Noun. Collocations: commercial/residential property, property value. Other sense: belongings.'),
  'furnished': VocabUsage('The apartment is fully furnished, so you only need to bring clothes.', '', 'Apartemen itu sudah lengkap berperabot, jadi Anda hanya perlu membawa pakaian.', '', 'Kata sifat. Kolokasi: fully/partly furnished. Lawan: unfurnished. Kata benda: furniture.', 'Adjective. Collocations: fully/partly furnished. Opposite: unfurnished. Noun: furniture.'),
  'vacant': VocabUsage('There are two vacant offices on the fifth floor.', '', 'Ada dua kantor kosong di lantai lima.', '', 'Kata sifat. Kolokasi: vacant office/lot/position. Kata benda: vacancy (juga lowongan kerja).', 'Adjective. Collocations: vacant office/lot/position. Noun: vacancy (also a job opening).'),
  'realtor': VocabUsage('Our realtor found us a good office building near the station.', '', 'Agen properti kami menemukan gedung kantor yang bagus di dekat stasiun.', '', 'Kata benda (Amerika). Sinonim: real estate agent (Britania: estate agent).', 'Noun (US). Synonym: real estate agent (UK: estate agent).'),
  'floor space': VocabUsage('The new warehouse has twice the floor space of the old one.', '', 'Gudang baru memiliki luas lantai dua kali lipat dari gudang lama.', '', 'Frasa benda tak terhitung. Pola: X square meters of floor space.', 'Uncountable noun phrase. Pattern: X square meters of floor space.'),
  'office space': VocabUsage('The startup is looking for affordable office space downtown.', '', 'Perusahaan rintisan itu sedang mencari ruang kantor yang terjangkau di pusat kota.', '', 'Frasa benda tak terhitung. Kolokasi: rent/lease office space, shared office space.', 'Uncountable noun phrase. Collocations: rent/lease office space, shared office space.'),
  'move in': VocabUsage('The new employees will move in on the first of the month.', '', 'Karyawan baru akan mulai menempati ruangan pada tanggal satu bulan ini.', '', 'Phrasal verb. Pola: move in(to) + tempat. Lawan: move out. Kata benda: move-in date.', 'Phrasal verb. Pattern: move in(to) + place. Opposite: move out. Noun: move-in date.'),
  'move out': VocabUsage('Tenants must give one month\'s notice before they move out.', '', 'Penyewa harus memberi pemberitahuan satu bulan sebelum pindah keluar.', '', 'Phrasal verb. Pola: move out of + tempat. Lawan: move in.', 'Phrasal verb. Pattern: move out of + place. Opposite: move in.'),
  'neighborhood': VocabUsage('The hotel is located in a quiet neighborhood near the river.', '', 'Hotel itu terletak di lingkungan yang tenang dekat sungai.', '', 'Kata benda (Amerika; Britania: neighbourhood). Pola: in the neighborhood.', 'Noun (US; UK: neighbourhood). Pattern: in the neighborhood.'),
  'spacious': VocabUsage('The new meeting room is bright and spacious.', '', 'Ruang rapat baru itu terang dan luas.', '', 'Kata sifat untuk ruangan/bangunan. Sinonim: roomy. Lawan: cramped (sempit).', 'Adjective for rooms/buildings. Synonym: roomy. Opposite: cramped.'),
  'downtown': VocabUsage('Our main office is located downtown, near the central station.', '', 'Kantor pusat kami terletak di pusat kota, dekat stasiun pusat.', '', 'Kata keterangan/sifat (Amerika). Pola: go downtown (tanpa \'to\'); downtown area.', 'Adverb/adjective (US). Patterns: go downtown (no \'to\'); downtown area.'),
  'listing': VocabUsage('I saw a listing for a three-bedroom house on the agency\'s website.', '', 'Saya melihat iklan properti rumah tiga kamar di situs web agen itu.', '', 'Kata benda. Pola: a listing for + properti. Juga: daftar umum (job listings).', 'Noun. Pattern: a listing for + property. Also: any list (job listings).'),
  'blueprint': VocabUsage('The architect showed us the blueprint for the new factory.', '', 'Arsitek menunjukkan kepada kami cetak biru untuk pabrik baru.', '', 'Kata benda. Pola: a blueprint for + bangunan/rencana. Kiasan: rencana dasar.', 'Noun. Pattern: a blueprint for + building/plan. Figurative: a basic plan.'),
  'plumber': VocabUsage('We called a plumber to fix the leaking pipe in the kitchen.', '', 'Kami memanggil tukang ledeng untuk memperbaiki pipa bocor di dapur.', '', 'Kata benda; huruf b tidak dibaca (/plam-er/). Pekerjaannya: plumbing.', 'Noun; the b is silent (/plum-er/). The work: plumbing.'),
  'electrician': VocabUsage('An electrician is coming to check the wiring in the meeting room.', '', 'Seorang tukang listrik akan datang untuk memeriksa kabel di ruang rapat.', '', 'Kata benda. Kaitan: electric, electrical, electricity.', 'Noun. Related: electric, electrical, electricity.'),
  'leak': VocabUsage('There is a leak in the ceiling above the reception desk.', '', 'Ada kebocoran di plafon di atas meja resepsionis.', '', 'Kata benda dan kerja. Pola: a leak in + benda; the pipe is leaking. Juga: membocorkan informasi.', 'Noun and verb. Patterns: a leak in + object; the pipe is leaking. Also: leak information.'),
  'repair': VocabUsage('The elevator will be repaired over the weekend.', '', 'Lift akan diperbaiki selama akhir pekan.', '', 'Kata kerja dan benda. Pola: under repair; repair work. Sinonim: fix.', 'Verb and noun. Patterns: under repair; repair work. Synonym: fix.'),
  'remodel': VocabUsage('The restaurant plans to remodel its kitchen this summer.', '', 'Restoran itu berencana merombak dapurnya musim panas ini.', '', 'Kata kerja. Pola: remodel + ruangan/bangunan. Kata benda: remodeling. Mirip: renovate.', 'Verb. Pattern: remodel + room/building. Noun: remodeling. Similar: renovate.'),
  'refurbish': VocabUsage('The old warehouse was refurbished and turned into modern offices.', '', 'Gudang lama itu diperbarui dan diubah menjadi kantor modern.', '', 'Kata kerja, sering pasif. Kata benda: refurbishment. Juga untuk barang: refurbished laptop.', 'Verb, often passive. Noun: refurbishment. Also for goods: refurbished laptop.'),
  'downturn': VocabUsage('Many small firms closed during the economic downturn.', '', 'Banyak perusahaan kecil tutup selama kemerosotan ekonomi.', '', 'Kata benda. Kolokasi: economic downturn, a downturn in + sektor. Lawan: upturn.', 'Noun. Collocations: economic downturn, a downturn in + sector. Opposite: upturn.'),
  'outlook': VocabUsage('The outlook for next quarter\'s sales is positive.', '', 'Prospek penjualan kuartal depan positif.', '', 'Kata benda. Pola: the outlook for + hal; positive/gloomy outlook. Juga: pandangan hidup.', 'Noun. Pattern: the outlook for + topic; positive/gloomy outlook. Also: attitude.'),
